def safe_correlation(x, y):
    """Safe Pearson correlation without np.corrcoef."""
    if x is None or y is None:
        return 0.0
    try:
        x_arr = np.asarray(x, dtype=float).ravel()
        y_arr = np.asarray(y, dtype=float).ravel()
        if x_arr.size != y_arr.size or x_arr.size < 2:
            return 0.0
        mask = np.isfinite(x_arr) & np.isfinite(y_arr)
        x_arr = x_arr[mask]
        y_arr = y_arr[mask]
        if x_arr.size < 2:
            return 0.0
        x_dev = x_arr - x_arr.mean()
        y_dev = y_arr - y_arr.mean()
        denom = np.sqrt((x_dev ** 2).sum() * (y_dev ** 2).sum())
        if denom == 0 or not np.isfinite(denom):
            return 0.0
        corr = (x_dev * y_dev).sum() / denom
        if not np.isfinite(corr):
            return 0.0
        return float(corr)
    except Exception:
        return 0.0


def safe_corrcoef_matrix(data):
    """Safe correlation matrix for 2D data avoiding np.corrcoef crashes."""
    if data is None:
        return np.eye(1)
    try:
        arr = np.asarray(data, dtype=float)
        if arr.ndim == 0:
            return np.eye(1)
        if arr.ndim == 1:
            return np.array([[1.0]])
        if arr.ndim == 2:
            rows = arr.shape[0]
            corr = np.eye(rows)
            for i in range(rows):
                for j in range(i + 1, rows):
                    c = safe_correlation(arr[i], arr[j])
                    corr[i, j] = corr[j, i] = c
            return corr
    except Exception:
        return np.eye(arr.shape[0] if hasattr(arr, 'shape') else 1)
    return np.eye(1)

