# SIGNAL VALIDATION FRAMEWORK (v14.0)
# ============================================================================
class SignalValidator:
    """Pre-execution validation for all trading signals"""
    
    def __init__(self, cfg=None):
        self.cfg = cfg or CFG
        self.validation_log = {}
        self.rejection_reasons = {}
        self.total_validations = 0
        self.total_rejections = 0
    
    def validate_signal(self, signal):
        """Comprehensive signal validation"""
        issues = []
        self.total_validations += 1
        
        # 1. Check required fields
        required = ['dir', 'entry', 'sl', 'tp', 'score']
        for field in required:
            if field not in signal:
                issues.append(f"Missing required field: {field}")
        
        if issues:
            self.total_rejections += 1
            return False, issues
        
        # 2. Validate entry price (real number, positive)
        try:
            entry = float(signal['entry'])
            if entry <= 0:
                issues.append(f"Invalid entry price: {entry}")
        except (TypeError, ValueError):
            issues.append(f"Entry not a valid number: {signal['entry']}")
        
        # 3. Validate direction (1 or -1)
        if signal['dir'] not in [1, -1]:
            issues.append(f"Invalid direction: {signal['dir']} (must be 1 or -1)")
        
        # 4. Validate SL and TP (opposite side of entry)
        try:
            sl = float(signal['sl'])
            tp = float(signal['tp'])
            
            if signal['dir'] == 1:  # BUY
                if sl >= entry:
                    issues.append(f"BUY: SL {sl} must be below entry {entry}")
                if tp <= entry:
                    issues.append(f"BUY: TP {tp} must be above entry {entry}")
            else:  # SELL
                if sl <= entry:
                    issues.append(f"SELL: SL {sl} must be above entry {entry}")
                if tp >= entry:
                    issues.append(f"SELL: TP {tp} must be below entry {entry}")
        except (TypeError, ValueError):
            issues.append(f"SL/TP not valid numbers: SL={signal.get('sl')}, TP={signal.get('tp')}")
        
        # 5. ENHANCED: Validate minimum R:R ratio (HARD FILTER - 1:2+ minimum)
        try:
            risk = abs(entry - sl)
            reward = abs(tp - entry)
            if risk > 0:
                rr = reward / risk
                min_rr = signal.get('min_rr_ratio', 2.0)  # Default 1:2
                if rr < min_rr:
                    issues.append(f"Poor R:R ratio: {rr:.2f}:1 (minimum {min_rr:.1f}:1) - REJECTED")
                    self.total_rejections += 1
                    return False, issues
        except:
            pass
        
        # 6. Validate confidence/score
        try:
            score = float(signal.get('score', 5.0))
            if signal.get('signal_type') == 'scalp':
                min_score = self.cfg.get('scalping_min_score', self.cfg.get('min_score', 7.0))
            else:
                min_score = self.cfg.get('min_score', 7.0)
            if score < min_score:
                issues.append(f"Score {score:.1f} below minimum {min_score}")
        except (TypeError, ValueError):
            issues.append(f"Invalid score: {signal.get('score')}")
        
        # 7. Check data quality
        for field in ['entry', 'sl', 'tp', 'atr']:
            if field in signal:
                try:
                    val = float(signal[field])
                    if not (-1e10 < val < 1e10):
                        issues.append(f"Invalid {field} value: {val}")
                except:
                    pass
        
        # 8. Validate position sizing
        if 'size' in signal:
            try:
                size = float(signal['size'])
                min_lot = self.cfg.get('min_lot', 0.01)
                lot_step = self.cfg.get('lot_step', 0.01)
                
                if size < min_lot:
                    issues.append(f"Size {size} below minimum lot {min_lot}")
                # Check alignment with floating-point tolerance (1e-8)
                remainder = round((size / lot_step) % 1.0, 8)
                if remainder > 1e-6 and remainder < (1 - 1e-6):
                    issues.append(f"Size {size} not aligned to lot step {lot_step}")
            except (TypeError, ValueError):
                issues.append(f"Invalid size: {signal.get('size')}")
        
        if issues:
            self.total_rejections += 1
            return False, issues
        return True, []
    
    def validate_batch(self, signals):
        """Validate multiple signals"""
        valid_signals = []
        invalid_signals = []
        
        for sig_id, signal in enumerate(signals):
            is_valid, issues = self.validate_signal(signal)
            if is_valid:
                valid_signals.append(signal)
            else:
                invalid_signals.append({
                    'id': sig_id,
                    'signal': signal,
                    'issues': issues
                })
        
        return valid_signals, invalid_signals
    
    def get_stats(self):
        """Get validation statistics"""
        return {
            'total_validations': self.total_validations,
            'total_rejections': self.total_rejections,
            'acceptance_rate': 100 * (1 - self.total_rejections / max(self.total_validations, 1))
        }

