# ============================================================================
# STAGE-15: PER-SYMBOL STATE ISOLATION (manual symbol switching made safe)
# ============================================================================
# When you switch CONFIG["symbol"] between XAUUSDm and BTCUSDm, each symbol now
# gets its OWN database, state file and model files - so XAU trade stats, ML
# datasets, fingerprints and DRL experience never contaminate BTC (or vice
# versa). The LEGACY (unsuffixed) files are renamed once so the current
# symbol's history carries over; other symbols' files are never copied.
# Paths that are symbol-independent (news cache, charts) stay shared.
_STATE_SYM_TAG = str(CONFIG.get('symbol', 'XAUUSDm')).replace('/', '_').replace(' ', '')
_STATE_SUFFIXED_KEYS = [
    'db_path', 'state_file',
    'ml_regressor_path', 'ml_classifier_path',
    'lgbm_regressor_path', 'lgbm_classifier_path',
    'rf_model_path', 'rf_regressor_path', 'meta_model_path',
    'swing_scalp_model_path', 'drl_model_path',
]
for _sk in _STATE_SUFFIXED_KEYS:
    _legacy = CONFIG.get(_sk, '')
    if not (isinstance(_legacy, str) and _legacy):
        continue
    if _legacy.endswith(f'_{_STATE_SYM_TAG}'):
        continue  # already isolated
    _sroot, _sext = (_legacy.rsplit('.', 1) if '.' in _legacy else (_legacy, ''))
    _snew = f"{_sroot}_{_STATE_SYM_TAG}{('.' + _sext) if _sext else ''}"
    if not os.path.exists(_snew) and os.path.exists(_legacy):
        try:
            os.rename(_legacy, _snew)  # move: history carries over, no stale copy left behind
            print(f"[STATE] Migrated {_legacy} -> {_snew} (history carried over)")
        except Exception as _se:
            try:
                import shutil
                shutil.copy(_legacy, _snew)
                print(f"[STATE] Copied {_legacy} -> {_snew} (rename failed: {_se}; stale legacy kept)")
            except Exception as _se2:
                print(f"[STATE] Migration failed for {_legacy}: {_se2}")
    CONFIG[_sk] = _snew
print(f"[STATE] Isolated state for symbol: {_STATE_SYM_TAG}")

