class _SymbolSpecResolver:
    """Dict-compatible per-symbol spec lookup, resolved against CFG['symbol']
    at call time so the existing EXNESS['...'] references keep working and
    automatically pick up the right contract specs when the symbol changes."""
    def _spec(self):
        return SYMBOL_SPECS.get(CFG.get('symbol', 'XAUUSDm'), _DEFAULT_SPEC)
    def __getitem__(self, key):
        return self._spec()[key]
    def get(self, key, default=None):
        try:
            return self._spec()[key]
        except KeyError:
            return default
    def __contains__(self, key):
        return key in self._spec()
    def __repr__(self):
        return f"SymbolSpec({CFG.get('symbol', '?')}: {self._spec()})"

