def safe_float(x, default=0.0):
    """Safely convert to float, handling NaN and exceptions"""
    if isinstance(x, Exception):
        return default
    if x is None:
        return default
    if isinstance(x, float) and np.isnan(x):
        return default
    try:
        return float(x)
    except (ValueError, TypeError):
        return default

def setup_logging():
    """Configure logging with file and console handlers"""
    os.makedirs("logs", exist_ok=True)
    
    if sys.platform == "win32":
        try:
            sys.stdout.reconfigure(encoding='utf-8')
            sys.stderr.reconfigure(encoding='utf-8')
        except (AttributeError, OSError) as e:
            print(f"[WARN] Failed to reconfigure stdout/stderr encoding: {e}")
    
    log = logging.getLogger("SentinelV12_1")
    log.setLevel(logging.INFO)
    
    fh = RotatingFileHandler(
        "logs/bot_v12_1.log",
        maxBytes=5_000_000,
        backupCount=10,
        encoding='utf-8'
    )
    fh.setFormatter(logging.Formatter('%(asctime)s|%(levelname)s|%(message)s'))
    
    ch = logging.StreamHandler()
    ch.setFormatter(logging.Formatter('%(asctime)s|%(message)s'))
    
    log.addHandler(fh)
    log.addHandler(ch)
    
    simple_fh = logging.FileHandler("logs/simple_v12_1.log", mode='a', encoding='utf-8')
    simple_fh.setFormatter(logging.Formatter('%(asctime)s - %(message)s'))
    log.addHandler(simple_fh)
    
    return log

