class SessionDetectorV18:
    # STAGE-9: was shadowed by the later SessionDetector definition (name bound to the last def).
    # Kept verbatim as the SessionDetectorV18 base class; NOT deleted.
    """Detect trading sessions (Asian, European, US) with penalty/reward system for session-specific trading"""
    def __init__(self):
        self.session_names = ['ASIAN', 'EUROPEAN', 'US']
        self.sessions = {
            'ASIAN': {'start': 0, 'end': 8, 'multiplier': 0.8},  # 00:00-08:00 UTC (lower volatility)
            'EUROPEAN': {'start': 8, 'end': 16, 'multiplier': 1.2},  # 08:00-16:00 UTC (high volatility)
            'US': {'start': 13, 'end': 21, 'multiplier': 1.1}  # 13:00-21:00 UTC (overlapping, trending)
        }
        self.current_session = 'ASIAN'
        self.session_transitions = []
        
    def detect_current_session(self) -> str:
        """Detect current trading session based on UTC hour"""
        try:
            current_utc_hour = utc_now().hour
            if 0 <= current_utc_hour < 8:
                self.current_session = 'ASIAN'
            elif 8 <= current_utc_hour < 13:
                self.current_session = 'EUROPEAN'
            else:  # 13 <= current_utc_hour < 21
                self.current_session = 'US'
            return self.current_session
        except Exception as e:
            LOG.error(f"Session detection error: {e}")
            return 'ASIAN'
    
    def get_session_hours(self, session_name: str = None) -> Dict:
        """Get start/end hours for a session"""
        if session_name is None:
            session_name = self.current_session
        return self.sessions.get(session_name, {'start': 0, 'end': 24, 'multiplier': 1.0})
    
    def apply_session_multiplier(self, signal_strength: float, session_name: str = None) -> float:
        """Apply session-based multiplier to signal strength (penalty/reward)"""
        if session_name is None:
            session_name = self.current_session
        multiplier = self.sessions.get(session_name, {}).get('multiplier', 1.0)
        return signal_strength * multiplier
    
    def get_session_boundaries(self) -> Dict:
        """Get current session boundaries"""
        session_info = self.sessions[self.current_session]
        return {'start': session_info['start'], 'end': session_info['end'], 'multiplier': session_info['multiplier']}
    
    def is_major_session_overlap(self) -> bool:
        """Check if currently in session overlap (European + US: 13:00-16:00 UTC)"""
        current_hour = utc_now().hour
        return 13 <= current_hour < 16

# PHASE 5.2: LONG-TERM FORECASTER - 3-DAY ML PREDICTION ENGINE (MISSING CLASS NOW ADDED)
class LongTermForecaster:
    """3-day price move forecaster using multi-timeframe LSTM + Transformer ensemble"""
    def __init__(self, symbol: str = "XAUUSD", horizon_bars: int = 72):
        self.symbol = symbol
        self.horizon_bars = horizon_bars  # 72 = 3 days of hourly bars
        self.forecast_data = []
        self.model_lstm = LSTMSequenceModel(seq_length=48, num_features=4)
        self.model_transformer = TransformerEncoder(seq_length=48)
        self.is_trained = False
        self.last_forecast = {'move_pct': 0.0, 'direction': 'NEUTRAL', 'confidence': 0.0, 'timestamp': datetime.now()}
        self.forecast_history = []
        
    def aggregate_multiframe_features(self, bars_h4: List, bars_h1: List, bars_m15: List) -> Dict:
        """Aggregate features from multiple timeframes for 3-day prediction"""
        try:
            features_h4 = np.array([[b['close'], b['high'], b['low'], b['volume']] for b in bars_h4[-12:]]).flatten()  # Last 12 H4 bars = 2 days
            features_h1 = np.array([[b['close'], b['high'], b['low'], b['volume']] for b in bars_h1[-24:]]).flatten()  # Last 24 H1 bars = 1 day
            features_m15 = np.array([[b['close'], b['high'], b['low'], b['volume']] for b in bars_m15[-8:]]).flatten()  # Last 8 M15 bars = 2 hours
            
            aggregated = np.concatenate([features_h4, features_h1, features_m15])
            returns = np.diff(np.log([b['close'] for b in bars_h1[-24:]]))  # H1 returns
            volatility = np.std(returns) if len(returns) > 0 else 0.01
            
            return {
                'features': aggregated,
                'h4_features': features_h4,
                'h1_features': features_h1,
                'm15_features': features_m15,
                'volatility': volatility,
                'current_price': bars_h1[-1]['close'] if bars_h1 else 0.0
            }
        except Exception as e:
            LOG.error(f"Multiframe feature aggregation error: {e}")
            return {'features': np.zeros(240), 'volatility': 0.01, 'current_price': 0.0}
    
    def train_sequence_model(self, bars_h4: List, bars_h1: List, bars_m15: List, target_prices: List):
        """Train LSTM+Transformer ensemble on historical 3-day sequences"""
        try:
            if len(bars_h1) < 72:
                LOG("Insufficient data for 3-day training", "WARNING")
                return False
            
            # Generate sequences for training
            sequences, targets = [], []
            for i in range(len(bars_h1) - 72):
                seq_data = bars_h1[i:i+48]
                target_price = bars_h1[i+72]['close']
                move_pct = (target_price - seq_data[-1]['close']) / seq_data[-1]['close']
                
                features = np.array([[b['close'], b['high'], b['low'], b['volume']] for b in seq_data])
                sequences.append(features)
                targets.append(move_pct)
            
            if len(sequences) > 0:
                X = np.array(sequences)
                y = np.array(targets)
                self.model_lstm.X_train = X
                self.model_lstm.y_train = y
                self.model_lstm.fit(X, y)
                self.model_transformer.fit(X, y)
                self.is_trained = True
                LOG.info(f"LongTermForecaster trained on {len(sequences)} sequences")
                return True
            return False
        except Exception as e:
            LOG.error(f"Training error in LongTermForecaster: {e}")
            return False
    
    def predict_3day_move(self, bars_h4: List, bars_h1: List, bars_m15: List) -> Dict:
        """Predict 3-day price move using trained ensemble"""
        try:
            if len(bars_h1) < 48:
                return {'move_pct': 0.0, 'direction': 'NEUTRAL', 'confidence': 0.0, 'source': 'insufficient_data'}
            
            # Aggregate features
            agg = self.aggregate_multiframe_features(bars_h4, bars_h1, bars_m15)
            features = agg['features'].reshape(1, -1)
            
            # Get predictions from both models
            lstm_pred = self.model_lstm.predict(features[0][-48*4:].reshape(1, 48, 4)) if self.is_trained else 0.0
            transformer_pred = self.model_transformer.predict(features[0][-48*4:].reshape(1, 48, 4)) if self.is_trained else 0.0
            
            # Ensemble prediction (average)
            ensemble_move = (lstm_pred + transformer_pred) / 2.0
            confidence = min(abs(ensemble_move) * 2, 0.95)
            direction = 'UP' if ensemble_move > 0.005 else 'DOWN' if ensemble_move < -0.005 else 'NEUTRAL'
            
            forecast = {
                'move_pct': float(ensemble_move),
                'direction': direction,
                'confidence': float(confidence),
                'lstm_pred': float(lstm_pred),
                'transformer_pred': float(transformer_pred),
                'timestamp': datetime.now(),
                'current_price': agg['current_price'],
                'volatility': agg['volatility']
            }
            
            self.last_forecast = forecast
            self.forecast_history.append(forecast)
            return forecast
        except Exception as e:
            LOG.error(f"3-day prediction error: {e}")
            return {'move_pct': 0.0, 'direction': 'NEUTRAL', 'confidence': 0.0, 'error': str(e)}
    
    def generate_telegram_alerts(self, forecast: Dict, threshold: float = 0.02):
        """Generate Telegram alert for significant 3-day moves"""
        try:
            if abs(forecast['move_pct']) > threshold and forecast['confidence'] > 0.60:
                direction = "[UP]" if forecast['move_pct'] > 0 else "[DOWN]"
                alert_msg = f"3-DAY FORECAST: {direction} {abs(forecast['move_pct'])*100:.2f}% move predicted\n"
                alert_msg += f"Confidence: {forecast['confidence']*100:.1f}%\n"
                alert_msg += f"Current Price: ${forecast['current_price']:.2f}\n"
                alert_msg += f"Timestamp: {forecast['timestamp'].strftime('%Y-%m-%d %H:%M:%S')}"
                
                # Log and store alert (actual Telegram sending handled by main execution loop)
                LOG(alert_msg, "ALERT")
                return alert_msg
            return None
        except Exception as e:
            LOG.error(f"Telegram alert generation error: {e}")
            return None

