class VisualSuite:
    """
    Professional charting system with 3 integrated charts:
    
    Chart 1 (M15): Entry/Exit, ATR-SL bands, VWAP
    Chart 2 (H1/H4): FVG Zones, Higher Timeframe Trend
    Chart 3 (Dashboard): Equity Curve vs MA, Z-Score Oscillator, Retail Sentiment
    """
    def __init__(self):
        self.name = "VisualSuite"
        self.plotly_available = False
        try:
            import plotly.graph_objects as go
            self.go = go
            self.plotly_available = True
        except ImportError:
            LOG.warning("[VisualSuite] Plotly not available - charting disabled")
    
    def create_m15_chart(self, df: pd.DataFrame, entry: float, sl: float, tp: float, 
                        atr: float, vwap: float) -> Optional[str]:
        """
        Create M15 chart with:
        - Candlestick OHLC
        - ATR-based SL bands (green/red)
        - VWAP line
        - Entry/SL/TP levels
        """
        if not self.plotly_available or df is None or df.empty:
            return None
        
        try:
            fig = self.go.Figure()
            
            # Add candlesticks
            fig.add_trace(self.go.Candlestick(
                x=df.index,
                open=df['open'],
                high=df['high'],
                low=df['low'],
                close=df['close'],
                name='XAUUSD',
                increasing_line_color='#2ecc71',
                decreasing_line_color='#e74c3c'
            ))
            
            # Add VWAP
            if 'vwap' in df.columns:
                fig.add_trace(self.go.Scatter(
                    x=df.index,
                    y=df['vwap'],
                    name='VWAP',
                    line=dict(color='#3498db', width=2, dash='dash')
                ))
            
            # Add ATR bands
            if 'atr' in df.columns:
                atr_upper = df['close'] + (df['atr'] * 2)
                atr_lower = df['close'] - (df['atr'] * 2)
                
                fig.add_trace(self.go.Scatter(
                    x=df.index,
                    y=atr_upper,
                    name='ATR Upper',
                    line=dict(width=0),
                    showlegend=False
                ))
                
                fig.add_trace(self.go.Scatter(
                    x=df.index,
                    y=atr_lower,
                    name='ATR Band',
                    fill='tonexty',
                    line=dict(width=0),
                    fillcolor='rgba(52, 152, 219, 0.1)'
                ))
            
            # Add Entry/SL/TP levels
            current_time = df.index[-1]
            fig.add_hline(y=entry, line_dash="solid", line_color="#f39c12", annotation_text="Entry", annotation_position="right")
            fig.add_hline(y=sl, line_dash="dash", line_color="#e74c3c", annotation_text="SL", annotation_position="right")
            fig.add_hline(y=tp, line_dash="dash", line_color="#2ecc71", annotation_text="TP", annotation_position="right")
            
            fig.update_layout(
                title="M15: Entry/Exit + ATR-SL Bands + VWAP",
                template="plotly_dark",
                height=500,
                xaxis_title="Time",
                yaxis_title="Price (USD/oz)"
            )
            
            return fig.to_html()
        
        except Exception as e:
            LOG.warning(f"[VisualSuite] M15 chart generation failed: {e}")
            return None
    
    def create_fvg_chart(self, df: pd.DataFrame, fvgs: List[dict], trend: str) -> Optional[str]:
        """
        Create H1/H4 chart with:
        - Candlestick OHLC
        - FVG zones (box drawings)
        - Higher timeframe trend direction
        """
        if not self.plotly_available or df is None or df.empty:
            return None
        
        try:
            fig = self.go.Figure()
            
            # Add candlesticks
            fig.add_trace(self.go.Candlestick(
                x=df.index,
                open=df['open'],
                high=df['high'],
                low=df['low'],
                close=df['close'],
                name='XAUUSD'
            ))
            
            # Add FVG zones
            for fvg in fvgs[:5]:  # Limit to last 5 FVGs
                color = 'rgba(46, 204, 113, 0.2)' if fvg['type'] == 'BULLISH' else 'rgba(231, 76, 60, 0.2)'
                
                fig.add_shape(
                    type="rect",
                    x0=df.index[0],
                    x1=df.index[-1],
                    y0=fvg['bottom'],
                    y1=fvg['top'],
                    fillcolor=color,
                    line_width=0,
                    layer="below"
                )
            
            # Add trend annotation
            fig.add_annotation(
                text=f"Trend: {trend}",
                xref="paper", yref="paper",
                x=0.05, y=0.95,
                showarrow=False,
                bgcolor="rgba(0,0,0,0.7)",
                font=dict(color="white", size=14)
            )
            
            fig.update_layout(
                title="H1/H4: FVG Zones + Higher Timeframe Trend",
                template="plotly_dark",
                height=500,
                xaxis_title="Time",
                yaxis_title="Price (USD/oz)"
            )
            
            return fig.to_html()
        
        except Exception as e:
            LOG.warning(f"[VisualSuite] FVG chart generation failed: {e}")
            return None
    
    def create_dashboard_chart(self, equity_history: List[float], z_scores: List[float], 
                              equity_ma: float) -> Optional[str]:
        """
        Create Dashboard with:
        - Equity Curve vs 20-MA (green above, red below)
        - Z-Score Oscillator (overbought/oversold bands)
        - Retail Sentiment gauge
        """
        if not self.plotly_available or not equity_history:
            return None
        
        try:
            from plotly.subplots import make_subplots
            
            fig = make_subplots(rows=3, cols=1, subplot_titles=("Equity Curve", "Z-Score", "Signal Count"))
            
            # Row 1: Equity Curve
            equity_ma_line = [equity_ma] * len(equity_history)
            
            fig.add_trace(
                self.go.Scatter(x=list(range(len(equity_history))), y=equity_history, 
                               name='Equity', line=dict(color='#2ecc71')),
                row=1, col=1
            )
            
            fig.add_trace(
                self.go.Scatter(x=list(range(len(equity_history))), y=equity_ma_line, 
                               name='Equity MA', line=dict(color='#3498db', dash='dash')),
                row=1, col=1
            )
            
            # Row 2: Z-Score with bands
            if z_scores:
                fig.add_trace(
                    self.go.Scatter(x=list(range(len(z_scores))), y=z_scores, 
                                   name='Z-Score', line=dict(color='#9b59b6')),
                    row=2, col=1
                )
                
                # Add overbought/oversold bands
                fig.add_hline(y=2.5, line_dash="dash", line_color="red", row=2, col=1)
                fig.add_hline(y=-2.5, line_dash="dash", line_color="green", row=2, col=1)
            
            # Row 3: Signal count (placeholder)
            fig.add_annotation(text="Dashboard Ready", row=3, col=1)
            
            fig.update_layout(
                title="Dashboard: Equity, Z-Score, Sentiment",
                template="plotly_dark",
                height=1000,
                showlegend=True
            )
            
            return fig.to_html()
        
        except Exception as e:
            LOG.warning(f"[VisualSuite] Dashboard generation failed: {e}")
            return None


class EducationalChartGenerator:
    """
    v18.1 Educational Chart Generator
    Creates 3 professional, TradingView-style charts for signal visualization and learning
    
    Chart 1: Price Action Setup (candles + EMAs + entry/SL/TP zones)
    Chart 2: Smart Money Structure (order blocks, FVGs, support/resistance)
    Chart 3: Momentum & Confluence (RSI divergences, volume profile, zone clustering)
    
    Each chart sent separately as media group with 2-3 second interval for mobile readability
    """
    
    def __init__(self):
        self.mpl = None
        self.plt = None
        self.mpf = None
        self.colors = {
            'bullish': '#0f9d58',      # Green
            'bearish': '#db4437',      # Red
            'entry': '#1f2937',        # Dark slate
            'sl': '#ef4444',           # Red
            'tp': '#10b981',           # Green
            'zone': '#fbbf24',         # Amber
            'support': '#3b82f6',      # Blue
            'resistance': '#ef4444',   # Red
            'ob_bull': '#2563eb',      # Blue
            'ob_bear': '#b91c1c',      # Dark Red
            'fvg': '#0ea5e9',          # Sky
            'background': '#FFFFFF',   # Light
            'grid': '#E5E7EB',         # Light gray
            'text': '#111827'          # Dark
        }
        try:
            if not self.mpl:
                import matplotlib
                matplotlib.use('Agg')
                import matplotlib.pyplot as plt
                self.mpl = matplotlib
                self.plt = plt
            if not self.mpf:
                import mplfinance as mpf
                self.mpf = mpf
            LOG.info("[v18.1 EducationalChartGenerator] Matplotlib + mplfinance ready")
        except ImportError as e:
            LOG.warning(f"[v18.1 EducationalChartGenerator] Matplotlib unavailable: {e}")
    
    def create_3chart_education_package(self, df, signal_data: dict, zone_data: dict = None, macro_insight: dict = None, dfs: dict = None) -> List[bytes]:
        """
        Create educational charts for Telegram media group

        Args:
            df: DataFrame with OHLCV data
            signal_data: {dir, entry, sl, tp, score, strategy, etc}
            zone_data: {order_blocks, fvgs, support_levels, resistance_levels, etc}
            macro_insight: {macro_bias, dxy_correlation, volatility_regime}
            dfs: Optional dict of DataFrames by timeframe for multi-timeframe dashboard

        Returns:
            List of PNG bytes [chart1, chart2, chart3, chart4?]
        """
        if df is None or df.empty or not self.plt:
            LOG.warning("[v18.1] Chart generation skipped - no data or matplotlib unavailable")
            return []
        
        # Enrich zone_data from the dataframe if the incoming payload is sparse
        zone_data = zone_data or {}
        if not any(zone_data.get(k) for k in ['support_levels', 'resistance_levels', 'order_blocks', 'fvgs', 'zones']):
            extracted = ZONE_ANALYZER.analyze_all(df)
            zone_data.setdefault('support_levels', extracted.get('support_levels', []))
            zone_data.setdefault('resistance_levels', extracted.get('resistance_levels', []))
            zone_data.setdefault('order_blocks', extracted.get('order_blocks', []))
            zone_data.setdefault('fvgs', extracted.get('fvgs', []))
            zone_data.setdefault('zones', extracted.get('zones', []))
            zone_data.setdefault('liquidity_pools', extracted.get('liquidity_pools', []))
            zone_data.setdefault('msb', extracted.get('msb'))
        else:
            extracted = ZONE_ANALYZER.analyze_all(df)
            zone_data.setdefault('support_levels', extracted.get('support_levels', []))
            zone_data.setdefault('resistance_levels', extracted.get('resistance_levels', []))
            zone_data.setdefault('order_blocks', extracted.get('order_blocks', []))
            zone_data.setdefault('fvgs', extracted.get('fvgs', []))
            zone_data.setdefault('zones', extracted.get('zones', []))
            zone_data.setdefault('liquidity_pools', extracted.get('liquidity_pools', []))
            zone_data.setdefault('msb', extracted.get('msb'))

        try:
            charts = []
            
            # Chart 1: Price Action Setup
            chart1 = self._create_price_action_chart(df, signal_data, zone_data)
            if chart1:
                charts.append(chart1)
            
            # Chart 2: Smart Money Structure
            chart2 = self._create_smc_structure_chart(df, signal_data, zone_data)
            if chart2:
                charts.append(chart2)
            
            # Chart 3: Momentum & Confluence
            chart3 = self._create_momentum_chart(df, signal_data, zone_data, macro_insight)
            if chart3:
                charts.append(chart3)

            # Chart 4: Zone Reaction Dashboard
            chart4 = self._create_zone_reaction_dashboard(df, signal_data, zone_data, dfs)
            if chart4:
                charts.append(chart4)

            # Optional: Prepend TradingView-style light PNG for quick visual
            try:
                if CFG.get('use_tv_light_chart', True):
                    trades = signal_data.get('trades', []) if isinstance(signal_data, dict) else []
                    tv_png = generate_tv_light_chart(df, trades=trades,
                                                     width=CFG.get('chart_width', 1200),
                                                     height=CFG.get('chart_height', 700),
                                                     dpi=100,
                                                     wick_color=CFG.get('tv_wick_color', '#F23645'),
                                                     accent_color=CFG.get('tv_accent_color', '#F23645'))
                    if tv_png:
                        # Put TV-style chart first for quick review
                        charts.insert(0, tv_png)
            except Exception as e:
                LOG.debug(f"[v18.1] TV light chart generation skipped: {e}")
            
            LOG.info(f"[v18.1] Generated {len(charts)} educational charts")
            return charts
        except Exception as e:
            LOG.error(f"[v18.1] Chart package creation failed: {e}")
            return []
    
    def _create_price_action_chart(self, df, signal_data, zone_data) -> Optional[bytes]:
        """Chart 1: Clean price action with EMAs, entry/SL/TP levels"""
        try:
            import io
            from datetime import datetime as dt
            
            direction = signal_data.get('dir', 'BUY')
            entry = float(signal_data.get('entry', df['close'].iloc[-1]))
            sl = float(signal_data.get('sl', 0))
            tp = float(signal_data.get('tp', 0))
            score = signal_data.get('score', 0)
            strategy = signal_data.get('strategy', 'N/A')
            order_type = str(signal_data.get('order_type', 'limit')).upper()
            
            zone_data = zone_data or {}
            support_level = zone_data.get('support_levels', [None])[0]
            resistance_level = zone_data.get('resistance_levels', [None])[0]
            
            # Prepare data for mplfinance
            df_plot = df[['open', 'high', 'low', 'close', 'volume']].copy()
            
            # Add EMAs as secondary plots
            ema_plots = []
            if 'ema9' in df.columns:
                ema_plots.append(self.mpf.make_addplot(df['ema9'], color='#00FFFF', width=1.5, secondary_y=False))
            if 'ema21' in df.columns:
                ema_plots.append(self.mpf.make_addplot(df['ema21'], color='#FFD700', width=1.5, secondary_y=False))
            if 'ema50' in df.columns:
                ema_plots.append(self.mpf.make_addplot(df['ema50'], color='#FF6B6B', width=1.2, secondary_y=False))
            
            # Create figure
            fig, axes = self.plt.subplots(figsize=(14, 7), facecolor=self.colors['background'])
            ax = axes
            
            # Plot candlesticks manually for better control
            width = 0.6
            for i in range(len(df_plot)):
                o, h, l, c = df_plot.iloc[i][['open', 'high', 'low', 'close']]
                color = self.colors['bullish'] if c >= o else self.colors['bearish']
                
                # Wick
                ax.plot([i, i], [l, h], color=color, linewidth=0.8)
                # Body
                body_height = abs(c - o)
                body_bottom = min(o, c)
                ax.add_patch(self.mpl.patches.Rectangle((i - width/2, body_bottom), width, body_height, 
                                                         facecolor=color, edgecolor=color, linewidth=0.5))
            
            # Add EMAs
            if 'ema9' in df.columns:
                ax.plot(df['ema9'], color='#00FFFF', linewidth=1.5, label='EMA9', alpha=0.7)
            if 'ema21' in df.columns:
                ax.plot(df['ema21'], color='#FFD700', linewidth=1.5, label='EMA21', alpha=0.7)
            if 'ema50' in df.columns:
                ax.plot(df['ema50'], color='#FF6B6B', linewidth=1.2, label='EMA50', alpha=0.7)
            
            # Add entry/SL/TP zones as shaded regions
            last_idx = len(df_plot) - 1
            zone_height = max(df['high']) - min(df['low'])
            
            # Entry zone (light zone)
            ax.axhline(entry, color=self.colors['entry'], linewidth=2.5, linestyle='-', label=f'Entry {entry:.2f}', alpha=0.8)
            
            # SL zone (red strip)
            if sl > 0:
                ax.fill_between([last_idx-20, last_idx], sl - zone_height*0.01, sl + zone_height*0.01, 
                                color=self.colors['sl'], alpha=0.15, label=f'SL {sl:.2f}')
                ax.axhline(sl, color=self.colors['sl'], linewidth=1.5, linestyle='--', alpha=0.6)
            
            # TP zone (green strip)
            if tp > 0:
                ax.fill_between([last_idx-20, last_idx], tp - zone_height*0.01, tp + zone_height*0.01,
                                color=self.colors['tp'], alpha=0.15, label=f'TP {tp:.2f}')
                ax.axhline(tp, color=self.colors['tp'], linewidth=1.5, linestyle='--', alpha=0.6)
            
            # Support/Resistance if available
            if support_level:
                ax.axhline(support_level, color=self.colors['support'], linewidth=1.2, linestyle=':', alpha=0.5, label=f'Support {support_level:.2f}')
            if resistance_level:
                ax.axhline(resistance_level, color=self.colors['resistance'], linewidth=1.2, linestyle=':', alpha=0.5, label=f'Resistance {resistance_level:.2f}')

            # Draw detected zone levels and ranges
            for z in zone_data.get('zones', []):
                try:
                    if isinstance(z, dict):
                        if 'zone' in z and isinstance(z['zone'], (list, tuple)) and len(z['zone']) >= 2:
                            low, high = min(z['zone']), max(z['zone'])
                            color = self.colors['fvg'] if z.get('type') == 'fvg' else self.colors['zone']
                            ax.fill_between([0, last_idx], low, high, color=color, alpha=0.08)
                            ax.plot([0, last_idx], [low, low], color=color, linewidth=1.0, linestyle='--', alpha=0.4)
                            ax.plot([0, last_idx], [high, high], color=color, linewidth=1.0, linestyle='--', alpha=0.4)
                        elif 'level' in z and z['level'] is not None:
                            color = self.colors['fvg'] if z.get('type') == 'fvg' else self.colors['zone']
                            ax.axhline(z['level'], color=color, linewidth=1.0, linestyle='--', alpha=0.45)
                except Exception:
                    continue

            for ob in zone_data.get('order_blocks', []):
                try:
                    if isinstance(ob, dict) and 'zone' in ob and len(ob['zone']) >= 2:
                        low, high = min(ob['zone']), max(ob['zone'])
                        color = self.colors['ob_bull'] if ob.get('dir') == 'BUY' else self.colors['ob_bear']
                        ax.fill_between([0, last_idx], low, high, color=color, alpha=0.08)
                        ax.plot([0, last_idx], [low, low], color=color, linewidth=1.0, linestyle=':', alpha=0.35)
                        ax.plot([0, last_idx], [high, high], color=color, linewidth=1.0, linestyle=':', alpha=0.35)
                except Exception:
                    continue

            # Styling
            ax.set_facecolor(self.colors['background'])
            ax.grid(True, color=self.colors['grid'], alpha=0.7, linewidth=0.6)
            ax.spines['top'].set_visible(False)
            ax.spines['right'].set_visible(False)
            ax.spines['left'].set_color(self.colors['grid'])
            ax.spines['bottom'].set_color(self.colors['grid'])
            ax.set_ylabel('Price (USD/oz)', fontsize=11, color=self.colors['text'], weight='bold')
            ax.set_xlabel('Time', fontsize=11, color=self.colors['text'], weight='bold')
            
            # Title with key info
            rr_ratio = abs((tp - entry) / (entry - sl)) if sl > 0 and entry != sl else 0
            title = f"📊 {direction} SETUP | {strategy} | Score: {score:.1f}/15 | RR: {rr_ratio:.2f}:1 | {order_type}"
            ax.set_title(title, fontsize=13, color=self.colors['text'], weight='bold', pad=15)
            
            # Legend
            ax.legend(loc='upper left', fontsize=9, facecolor='#1a1a2e', edgecolor=self.colors['grid'], framealpha=0.9)
            ax.tick_params(colors=self.colors['text'], labelsize=9)
            
            # Convert to bytes
            buf = io.BytesIO()
            self.plt.tight_layout()
            self.plt.savefig(buf, format='png', dpi=100, facecolor=self.colors['background'], edgecolor='none')
            self.plt.close(fig)
            buf.seek(0)
            
            LOG.info(f"[v18.1] Chart 1 (Price Action) generated: {len(buf.getvalue())} bytes")
            return buf.getvalue()
            
        except Exception as e:
            LOG.error(f"[v18.1] Price action chart failed: {e}")
            return None
    
    def _create_smc_structure_chart(self, df, signal_data, zone_data) -> Optional[bytes]:
        """Chart 2: Smart Money Concepts - Order Blocks, FVGs, Support/Resistance, BOS"""
        try:
            import io
            
            zone_data = zone_data or {}
            df_plot = df[['open', 'high', 'low', 'close']].copy()
            
            fig, ax = self.plt.subplots(figsize=(14, 7), facecolor=self.colors['background'])
            
            # Plot candles
            width = 0.6
            for i in range(len(df_plot)):
                o, h, l, c = df_plot.iloc[i][['open', 'high', 'low', 'close']]
                color = self.colors['bullish'] if c >= o else self.colors['bearish']
                
                ax.plot([i, i], [l, h], color=color, linewidth=0.8)
                ax.add_patch(self.mpl.patches.Rectangle((i - width/2, min(o, c)), width, abs(c - o),
                                                         facecolor=color, edgecolor=color, linewidth=0.5))
            
            # Draw order blocks
            for ob in zone_data.get('order_blocks', []):
                try:
                    if isinstance(ob, dict):
                        direction = ob.get('direction', ob.get('dir', 'BUY'))
                        zone = ob.get('zone', [])
                        if len(zone) >= 2:
                            low, high = min(zone), max(zone)
                            color = self.colors['ob_bull'] if direction == 'BUY' else self.colors['ob_bear']
                            ax.fill_between([0, len(df_plot)], low, high, color=color, alpha=0.15, label=f"OB {direction}")
                            ax.plot([0, len(df_plot)], [low, low], color=color, linewidth=1.5, linestyle='--', alpha=0.4)
                            ax.plot([0, len(df_plot)], [high, high], color=color, linewidth=1.5, linestyle='--', alpha=0.4)
                except:
                    pass
            
            # Draw FVGs
            for fvg in zone_data.get('fvgs', []):
                try:
                    if isinstance(fvg, dict):
                        zone = fvg.get('zone', [])
                        if len(zone) >= 2:
                            low, high = min(zone), max(zone)
                            ax.fill_between([0, len(df_plot)], low, high, color=self.colors['fvg'], alpha=0.12, label='FVG')
                            ax.plot([0, len(df_plot)], [low, low], color=self.colors['fvg'], linewidth=1, linestyle=':', alpha=0.5)
                            ax.plot([0, len(df_plot)], [high, high], color=self.colors['fvg'], linewidth=1, linestyle=':', alpha=0.5)
                except:
                    pass
            
            # Draw support/resistance
            for sup in zone_data.get('support_levels', []):
                if sup:
                    ax.axhline(sup, color=self.colors['support'], linewidth=1.5, linestyle='-.', alpha=0.6, label=f'S {sup:.2f}')
            
            for res in zone_data.get('resistance_levels', []):
                if res:
                    ax.axhline(res, color=self.colors['resistance'], linewidth=1.5, linestyle='-.', alpha=0.6, label=f'R {res:.2f}')
            
            # Styling
            ax.set_facecolor(self.colors['background'])
            ax.grid(True, color=self.colors['grid'], alpha=0.7, linewidth=0.6)
            ax.spines['top'].set_visible(False)
            ax.spines['right'].set_visible(False)
            ax.spines['left'].set_color(self.colors['grid'])
            ax.spines['bottom'].set_color(self.colors['grid'])
            ax.set_ylabel('Price (USD/oz)', fontsize=11, color=self.colors['text'], weight='bold')
            ax.set_xlabel('Time', fontsize=11, color=self.colors['text'], weight='bold')
            ax.set_title('🎯 Smart Money Structure - Order Blocks & FVGs', fontsize=13, color=self.colors['text'], weight='bold', pad=15)
            
            # Legend
            handles, labels = ax.get_legend_handles_labels()
            by_label = dict(zip(labels, handles))
            ax.legend(by_label.values(), by_label.keys(), loc='upper left', fontsize=9, facecolor='#1a1a2e', edgecolor=self.colors['grid'])
            ax.tick_params(colors=self.colors['text'], labelsize=9)
            
            # Convert to bytes
            buf = io.BytesIO()
            self.plt.tight_layout()
            self.plt.savefig(buf, format='png', dpi=100, facecolor=self.colors['background'], edgecolor='none')
            self.plt.close(fig)
            buf.seek(0)
            
            LOG.info(f"[v18.1] Chart 2 (SMC Structure) generated: {len(buf.getvalue())} bytes")
            return buf.getvalue()
            
        except Exception as e:
            LOG.error(f"[v18.1] SMC structure chart failed: {e}")
            return None
    
    def _create_momentum_chart(self, df, signal_data, zone_data, macro_insight) -> Optional[bytes]:
        """Chart 3: Momentum & Confluence - RSI, zone clustering, volume profile POC"""
        try:
            import io
            
            fig, (ax1, ax2) = self.plt.subplots(2, 1, figsize=(14, 8), facecolor=self.colors['background'],
                                               gridspec_kw={'height_ratios': [3, 1]})
            
            # Top panel: Candles + RSI
            df_plot = df[['open', 'high', 'low', 'close']].copy()
            
            width = 0.6
            for i in range(len(df_plot)):
                o, h, l, c = df_plot.iloc[i][['open', 'high', 'low', 'close']]
                color = self.colors['bullish'] if c >= o else self.colors['bearish']
                ax1.plot([i, i], [l, h], color=color, linewidth=0.8)
                ax1.add_patch(self.mpl.patches.Rectangle((i - width/2, min(o, c)), width, abs(c - o),
                                                          facecolor=color, edgecolor=color, linewidth=0.5))
            
            # Plot RSI if available
            if 'rsi' in df.columns:
                ax1_twin = ax1.twinx()
                rsi = df['rsi']
                ax1_twin.plot(rsi, color='#9333EA', linewidth=2, label='RSI(14)', alpha=0.7)
                ax1_twin.fill_between(range(len(rsi)), 30, 70, color='gray', alpha=0.05)
                ax1_twin.axhline(70, color='#FF3333', linewidth=1, linestyle='--', alpha=0.3)
                ax1_twin.axhline(30, color='#33FF33', linewidth=1, linestyle='--', alpha=0.3)
                ax1_twin.set_ylabel('RSI', fontsize=10, color='#9333EA', weight='bold')
                ax1_twin.set_ylim([0, 100])
                ax1_twin.tick_params(axis='y', labelcolor='#9333EA')
            
            # Zone confluence visualization (count overlapping zones)
            zone_data = zone_data or {}
            all_zones = []
            all_zones.extend(zone_data.get('order_blocks', []))
            all_zones.extend(zone_data.get('fvgs', []))
            all_zones.extend(zone_data.get('support_levels', []))
            all_zones.extend(zone_data.get('resistance_levels', []))
            all_zones.extend(zone_data.get('zones', []))
            
            # Mark detected zones on the top chart
            for z in zone_data.get('zones', []):
                try:
                    if isinstance(z, dict) and 'zone' in z and isinstance(z['zone'], (list, tuple)) and len(z['zone']) >= 2:
                        low, high = min(z['zone']), max(z['zone'])
                        color = self.colors['zone'] if z.get('type') != 'fvg' else self.colors['fvg']
                        ax1.fill_between([0, len(df_plot)], low, high, color=color, alpha=0.06)
                    elif isinstance(z, dict) and z.get('level') is not None:
                        color = self.colors['zone'] if z.get('type') != 'fvg' else self.colors['fvg']
                        ax1.axhline(z['level'], color=color, linewidth=1.0, linestyle='--', alpha=0.3)
                except Exception:
                    continue

            # Mark confluence points text
            if len(all_zones) > 0:
                current_price = df['close'].iloc[-1]
                confluence_count = sum(1 for zone in all_zones if isinstance(zone, dict) or isinstance(zone, (int, float)))
                ax1.text(len(df_plot) - 5, df['high'].max() * 0.98, f'Confluence: {confluence_count} zones', 
                        fontsize=11, color='#1f2937', weight='bold', bbox=dict(boxstyle='round,pad=0.5', facecolor='#f8fafc', edgecolor='#cbd5e1'))
            
            ax1.set_facecolor(self.colors['background'])
            ax1.grid(True, color=self.colors['grid'], alpha=0.7, linewidth=0.6)
            ax1.spines['top'].set_visible(False)
            ax1.spines['right'].set_visible(False)
            ax1.spines['left'].set_color(self.colors['grid'])
            ax1.spines['bottom'].set_color(self.colors['grid'])
            ax1.set_ylabel('Price (USD/oz)', fontsize=11, color=self.colors['text'], weight='bold')
            
            # Bottom panel: Volume
            volume_colors = [self.colors['bullish'] if df['close'].iloc[i] >= df['open'].iloc[i] else self.colors['bearish']
                             for i in range(len(df))]
            ax2.bar(range(len(df)), df['volume'], color=volume_colors, alpha=0.35, width=0.8)
            macro_insight = macro_insight or {}
            title = f"📈 Momentum & Confluence | RSI + Volume | DXY: {macro_insight.get('dxy_correlation', 0):.3f}"
            ax1.set_title(title, fontsize=13, color=self.colors['text'], weight='bold', pad=15)
            
            ax1.tick_params(colors=self.colors['text'], labelsize=9)
            ax2.set_facecolor(self.colors['background'])
            ax2.spines['top'].set_visible(False)
            ax2.spines['right'].set_visible(False)
            ax2.spines['left'].set_color(self.colors['grid'])
            ax2.spines['bottom'].set_color(self.colors['grid'])
            ax2.set_ylabel('Volume', fontsize=10, color=self.colors['text'], weight='bold')
            ax2.set_xlabel('Time', fontsize=11, color=self.colors['text'], weight='bold')
            ax2.tick_params(colors=self.colors['text'], labelsize=9)
            ax2.grid(True, color=self.colors['grid'], alpha=0.7, linewidth=0.6)
            
            # Convert to bytes
            buf = io.BytesIO()
            self.plt.tight_layout()
            self.plt.savefig(buf, format='png', dpi=100, facecolor=self.colors['background'], edgecolor='none')
            self.plt.close(fig)
            buf.seek(0)
            
            LOG.info(f"[v18.1] Chart 3 (Momentum) generated: {len(buf.getvalue())} bytes")
            return buf.getvalue()
            
        except Exception as e:
            LOG.error(f"[v18.1] Momentum chart failed: {e}")
            return None

    def _create_zone_reaction_dashboard(self, df, signal_data, zone_data, dfs=None) -> Optional[bytes]:
        """Chart 4: Multi-timeframe zone reaction dashboard."""
        try:
            import io

            zone_reaction_summary = signal_data.get('zone_reaction_summary') or {}
            if not zone_reaction_summary and isinstance(dfs, dict):
                zone_reaction_summary = ZONE_ANALYZER.summarize_multi_tf_zone_reactions(dfs)

            if not zone_reaction_summary:
                LOG.info("[v18.1] No multi-timeframe zone reaction data available for dashboard")
                return None

            fig, ax = self.plt.subplots(figsize=(14, 7), facecolor=self.colors['background'])
            ax.set_facecolor(self.colors['background'])
            ax.axis('off')

            lines = [
                'ZONE REACTION DASHBOARD',
                f"Signal: {signal_data.get('dir', 'N/A')} | {signal_data.get('strategy', 'N/A').upper()} | TF: {signal_data.get('tf', 'N/A')}",
                '']

            for tf in sorted(zone_reaction_summary.keys(), key=lambda x: x):
                reactions = zone_reaction_summary[tf]
                if not reactions:
                    lines.append(f"{tf}: No reaction data")
                    continue
                for direction, reaction in reactions.items():
                    if not reaction:
                        continue
                    line = (
                        f"{tf} {direction}: {reaction['reaction_type'].replace('_', ' ').title()} "
                        f"@ {reaction['zone_level']:.2f} ({reaction['proximity_atr']:.2f} ATR)"
                    )
                    lines.append(line)
                lines.append('')

            # Add a summary block of confirmed holds vs breaks
            summary_counts = {'support': 0, 'resistance': 0, 'break': 0, 'other': 0}
            for reactions in zone_reaction_summary.values():
                for reaction in reactions.values():
                    if not reaction:
                        continue
                    if 'bounce' in reaction['reaction_type'] or 'test' in reaction['reaction_type']:
                        if reaction['direction'] == 'BUY':
                            summary_counts['support'] += 1
                        else:
                            summary_counts['resistance'] += 1
                    elif 'broke' in reaction['reaction_type']:
                        summary_counts['break'] += 1
                    else:
                        summary_counts['other'] += 1

            lines.extend([
                'SUMMARY:',
                f"Support hold/tests: {summary_counts['support']}",
                f"Resistance hold/tests: {summary_counts['resistance']}",
                f"Breakouts: {summary_counts['break']}",
                f"Other reactions: {summary_counts['other']}"
            ])

            ax.text(0.01, 0.99, '\n'.join(lines), color=self.colors['text'], fontsize=11,
                    fontfamily='monospace', va='top', ha='left', wrap=True)

            if zone_data.get('support_levels') or zone_data.get('resistance_levels'):
                stats = [
                    f"Support levels: {len(zone_data.get('support_levels', []))}",
                    f"Resistance levels: {len(zone_data.get('resistance_levels', []))}",
                    f"Order blocks: {len(zone_data.get('order_blocks', []))}",
                    f"FVGs: {len(zone_data.get('fvgs', []))}"
                ]
                ax.text(0.72, 0.75, '\n'.join(stats), color=self.colors['text'], fontsize=10,
                        fontfamily='monospace', va='top', ha='left', bbox=dict(facecolor='rgba(15,15,25,0.9)', edgecolor=self.colors['grid'], boxstyle='round,pad=0.5'))

            title = f"🧭 Zone Reaction Dashboard | {signal_data.get('dir', 'N/A')} | {signal_data.get('tf', 'N/A')}"
            ax.set_title(title, color=self.colors['text'], fontsize=14, pad=20)

            buf = io.BytesIO()
            self.plt.tight_layout()
            self.plt.savefig(buf, format='png', dpi=100, facecolor=self.colors['background'], edgecolor='none')
            self.plt.close(fig)
            buf.seek(0)

            LOG.info(f"[v18.1] Zone reaction dashboard generated: {len(buf.getvalue())} bytes")
            return buf.getvalue()

        except Exception as e:
            LOG.error(f"[v18.1] Zone reaction dashboard chart failed: {e}")
            return None


def generate_tv_light_chart(df, trades: list, width: int = 1200, height: int = 700, dpi: int = 100,
                            wick_color: str = '#F23645', accent_color: str = '#F23645') -> bytes:
    """
    Generate a clean TradingView-like light-mode chart PNG showing candles and trade markers.

    Args:
        df: pandas DataFrame indexed by datetime with columns ['open','high','low','close','volume']
        trades: list of dicts, each like { 'time': pd.Timestamp or index, 'price': float, 'side': 'BUY'|'SELL', 'size': float, 'label': str }
        width, height, dpi: image sizing
        wick_color: color for candle wicks and borders
        accent_color: color used for axes labels and markers

    Returns:
        PNG bytes (or None on failure)
    """
    try:
        import io
        import matplotlib
        matplotlib.use('Agg')
        import matplotlib.pyplot as plt
        from matplotlib.patches import Rectangle

        if df is None or getattr(df, 'empty', True):
            return None

        opens = df['open'].values
        highs = df['high'].values
        lows = df['low'].values
        closes = df['close'].values

        # TradingView light-mode style
        bg = '#FFFFFF'
        grid = '#E5E7EB'
        text = accent_color
        up_color = '#0f9d58'
        down_color = '#db4437'

        fig, ax = plt.subplots(figsize=(width / dpi, height / dpi), dpi=dpi)
        fig.patch.set_facecolor(bg)
        ax.set_facecolor(bg)

        # Draw wicks and bodies
        bar_width = 0.6
        for i in range(len(df)):
            o, h, l, c = opens[i], highs[i], lows[i], closes[i]
            color = up_color if c >= o else down_color

            # Wick
            ax.plot([i, i], [l, h], color=wick_color, linewidth=0.8, zorder=2)

            # Body
            lower = min(o, c)
            height_body = abs(c - o)
            if height_body == 0:
                height_body = (max(highs) - min(lows)) * 0.001
            rect = Rectangle((i - bar_width / 2, lower), bar_width, height_body,
                             facecolor=color, edgecolor=wick_color, linewidth=0.7, zorder=3)
            ax.add_patch(rect)

        # Minimal axes styling (TradingView-like light)
        ax.spines['top'].set_visible(False)
        ax.spines['right'].set_visible(False)
        ax.spines['left'].set_color(grid)
        ax.spines['bottom'].set_color(grid)
        ax.tick_params(colors=text, labelsize=9)
        ax.grid(True, color=grid, linewidth=0.6, alpha=0.9)

        # X-axis labels: subset to avoid crowding
        try:
            xticks_idx = list(range(0, len(df), max(1, len(df) // 6)))
            xticks = [df.index[i].strftime('%Y-%m-%d %H:%M') for i in xticks_idx]
            ax.set_xticks(xticks_idx)
            ax.set_xticklabels(xticks, color=text)
        except Exception:
            pass

        # Plot trade markers with explicit vertical offsets
        if trades:
            price_min, price_max = float(min(lows)), float(max(highs))
            price_range = max(1e-6, price_max - price_min)
            offset_amt = 0.02 * price_range

            for tr in trades:
                try:
                    t = tr.get('time')
                    if isinstance(t, (int, float)):
                        ix = int(t)
                    else:
                        if t in df.index:
                            ix = int(df.index.get_loc(t))
                        else:
                            ix = int(df.index.get_indexer([t], method='nearest')[0]) if hasattr(df.index, 'get_indexer') else None
                    if ix is None or ix < 0 or ix >= len(df):
                        continue

                    price = float(tr.get('price', df['close'].iloc[ix]))
                    side = str(tr.get('side', 'BUY')).upper()
                    size = tr.get('size')
                    label = tr.get('label') or ''

                    if side == 'BUY':
                        marker = '^'
                        y = price + offset_amt
                    else:
                        marker = 'v'
                        y = price - offset_amt

                    ax.scatter([ix], [y], marker=marker, s=80, color=accent_color, edgecolor='k', zorder=5)
                    text_offset = 1.5 * offset_amt if side == 'BUY' else -1.5 * offset_amt
                    ax.text(ix, y + text_offset, f"{label or side}{(f' {size}' if size else '')}",
                            fontsize=8, color=text, ha='center', va='bottom' if side == 'BUY' else 'top', zorder=6,
                            bbox=dict(boxstyle='round,pad=0.2', facecolor='#ffffff', edgecolor=grid, linewidth=0.5))
                except Exception:
                    continue

        ax.set_ylabel('Price', color=text)
        ax.set_xlabel('Time', color=text)
        plt.tight_layout()
        buf = io.BytesIO()
        fig.savefig(buf, format='png', dpi=dpi, facecolor=bg)
        plt.close(fig)
        buf.seek(0)
        return buf.getvalue()

    except Exception as e:
        LOG.error(f"[Chart] generate_tv_light_chart failed: {e}")
        return None


class DynamicPlotlyCharter:
    """
    Professional Plotly charting for signal visualization
    Generates high-fidelity dark-mode charts with Entry/SL/TP levels
    and dynamic Signal Insight table (Macro Bias, DXY Correlation, Volatility Regime)
    """
    def __init__(self):
        self.kaleido_available = False
        try:
            import plotly.graph_objects as go
            import plotly.io as pio
            self.go = go
            self.pio = pio
            # Check if kaleido is installed for PNG export
            try:
                import kaleido
                self.kaleido_available = True
                try:
                    pio.renderers.default = "kaleido"
                except Exception:
                    pass
                LOG.info("[v16.0] Plotly with kaleido available - PNG export enabled")
            except ImportError:
                self.kaleido_available = False
                LOG.warning("[v16.0] Plotly available but kaleido not found - PNG export disabled (install: pip install kaleido)")
        except ImportError:
            self.go = None
            self.pio = None
            LOG.warning("[v16.0] Plotly not installed - charting disabled (install: pip install plotly kaleido)")
    
    def create_signal_chart(self, df, signal_data: dict, macro_insight: dict = None, timeframe_label: str = None, chart_variant: str = 'primary') -> bytes:
        """
        Generate a TradingView-style LIGHT-MODE hero chart (STAGE-12) matching the
        reference screenshots: white background, TV candle colors, 4-EMA ribbon,
        volume subplot, dark LONG/SHORT info card (Units/Entry/SL/TP1-3/Macro/
        grade/Score), red STOP LOSS banner, dashed level lines and colored
        price boxes on the right ladder.

        Args:
            df: DataFrame with OHLCV data (needs ema9/ema21/ema50 if present)
            signal_data: Signal details (dir, entry, sl, tp, score, vol, grade...)
            macro_insight: {macro_bias, dxy_correlation, volatility_regime}
            timeframe_label: Optional timeframe label for chart title
            chart_variant: 'primary' or 'strategy' (title flavor only)

        Returns:
            PNG image bytes or None if charting unavailable
        """
        if not self.go or df is None or df.empty:
            return None

        try:
            from plotly.subplots import make_subplots

            direction = normalize_direction(signal_data.get('dir', 'BUY'))
            if direction not in ('BUY', 'SELL'):
                direction = 'BUY'
            is_long = direction == 'BUY'
            entry = float(signal_data.get('entry', df['close'].iloc[-1]))
            sl = float(signal_data.get('sl', 0) or 0)
            tp = float(signal_data.get('tp', 0) or 0)
            score = float(signal_data.get('score', 0) or 0)
            vol_units = float(signal_data.get('vol', signal_data.get('size', 0)) or 0)
            grade = str(signal_data.get('grade') or '').upper()
            timeframe_label = timeframe_label or signal_data.get('tf', 'N/A')
            symbol = signal_data.get('symbol', CFG.get('symbol', 'XAUUSD'))
            strategy_name = str(signal_data.get('strategy', 'unknown')).replace('_', ' ').upper()
            macro_bias = str((macro_insight or {}).get('macro_bias', 'NEUTRAL'))

            # Score scale: internal scores are 0-15; screenshots show a %
            score_pct = (score / 15.0 * 100.0) if score <= 15 else score

            # R-multiple TP ladder (matches Pine defaults: 1.5R / 3R / 4.5R)
            r_mult = abs(entry - sl) if sl > 0 else 0.0
            if r_mult > 0:
                sign = 1.0 if is_long else -1.0
                tp1 = entry + sign * 1.5 * r_mult
                tp2 = entry + sign * 3.0 * r_mult
                tp3 = entry + sign * 4.5 * r_mult
            else:
                tp1 = tp2 = tp3 = 0.0

            x_values = [pd.Timestamp(x).to_pydatetime() for x in df.index]
            last_index = x_values[-1]
            last_close = float(df['close'].iloc[-1])

            fig = make_subplots(
                rows=2, cols=1, shared_xaxes=True,
                row_heights=[0.84, 0.16], vertical_spacing=0.04,
                subplot_titles=(f"  {symbol}  |  {timeframe_label}", "")
            )

            # --- Price candles (TradingView light-mode colors) ---
            fig.add_trace(self.go.Candlestick(
                x=x_values, open=df['open'], high=df['high'], low=df['low'], close=df['close'],
                name='Price', increasing_line_color='#089981', increasing_fillcolor='#089981',
                decreasing_line_color='#F23645', decreasing_fillcolor='#F23645',
                showlegend=False
            ), row=1, col=1)

            # --- EMA ribbon: 9 magenta / 21 orange / 50 teal / 200 red ---
            ema_specs = [('ema9', '#9B59B6', 1.4), ('ema21', '#F39C12', 1.4), ('ema50', '#1ABC9C', 1.2)]
            for ema_col, color, width in ema_specs:
                if ema_col in df.columns:
                    fig.add_trace(self.go.Scatter(
                        x=x_values, y=df[ema_col], mode='lines',
                        line=dict(color=color, width=width), name=ema_col.upper(),
                        legendgroup='ema', showlegend=True
                    ), row=1, col=1)
            if len(df) >= 200 and 'close' in df.columns:
                ema200 = df['close'].ewm(span=200, adjust=False).mean()
                fig.add_trace(self.go.Scatter(
                    x=x_values, y=ema200, mode='lines',
                    line=dict(color='#E74C3C', width=1.2), name='EMA200',
                    legendgroup='ema', showlegend=True
                ), row=1, col=1)

            # --- Level lines across the price pane (row 1): SL red dashed,
            #     Entry green solid, TP blue dotted, TP1-3 faint dotted ---
            def _level_line(price, color, dash, width, layer='above'):
                fig.add_shape(
                    type='line', x0=x_values[0], x1=last_index, y0=price, y1=price,
                    xref='x', yref='y',
                    line=dict(color=color, width=width, dash=dash),
                    layer=layer
                )

            if sl > 0:
                _level_line(sl, '#F23645', 'dash', 1.4)
            _level_line(entry, '#089981', 'solid', 1.0)
            if tp > 0:
                _level_line(tp, '#3498DB', 'dot', 1.0)
            for lvl in (tp1, tp2, tp3):
                if lvl > 0:
                    _level_line(lvl, '#95A5A6', 'dot', 0.8, layer='below')

            # --- STOP LOSS banner (red rounded label, TV style) ---
            if sl > 0:
                fig.add_annotation(
                    x=last_index, y=sl, xref='x', yref='y',
                    text=' STOP LOSS &#10007; ',
                    showarrow=False, xanchor='left', yanchor='middle',
                    font=dict(color='#FFFFFF', size=12, family='Arial, sans-serif'),
                    bgcolor='#F23645', borderwidth=0, opacity=0.95
                )

            # --- LONG / SHORT info card (dark TV card, white text) ---
            macro_line = ('Macro Aligned' if (macro_bias == 'BULLISH') == is_long
                          else ('Macro Against' if macro_bias in ('BULLISH', 'BEARISH') else 'Macro Neutral'))
            card_lines = [
                f"Units: {vol_units:.2f}",
                f"Entry: {entry:.2f}",
                f"SL: {sl:.1f}" if sl > 0 else "SL: -",
            ]
            for lvl, lbl in ((tp1, 'TP1'), (tp2, 'TP2'), (tp3, 'TP3')):
                if lvl > 0:
                    card_lines.append(f"{lbl}: {lvl:.2f}")
            card_lines.append(macro_line)
            if grade:
                card_lines.append(f"[{grade} TIER]")
            card_lines.append(f"Score: {score_pct:.0f}%")
            card_bg = 'rgba(10, 45, 30, 0.92)' if is_long else 'rgba(52, 12, 18, 0.92)'
            dot_color = '#2ECC71' if is_long else '#F23645'
            fig.add_annotation(
                xref='paper', yref='paper', x=0.015, y=0.55,
                xanchor='left', yanchor='top', align='left',
                text=(f"<span style='color:{dot_color}'>&#9679;</span> "
                      f"<b>{'LONG' if is_long else 'SHORT'}</b><br>"
                      + '<br>'.join(card_lines)),
                showarrow=False,
                font=dict(color='#FFFFFF', size=12, family='Arial, sans-serif'),
                bgcolor=card_bg, bordercolor='rgba(255,255,255,0.25)', borderwidth=1
            )

            # --- Right-side price boxes (TV price ladder style) ---
            def _price_box(price, text, color):
                fig.add_annotation(
                    x=last_index, y=price, xref='x', yref='y',
                    text=f' {text} ', showarrow=False, xanchor='left', yanchor='middle',
                    font=dict(color='#FFFFFF', size=10, family='Arial, sans-serif'),
                    bgcolor=color, borderwidth=0, opacity=0.95
                )

            if sl > 0:
                _price_box(sl, f'SL {sl:.2f}', '#F23645')
            _price_box(entry, f'Entry {entry:.2f}', '#089981')
            if tp1 > 0:
                _price_box(tp1, f'TP1 {tp1:.2f}', '#2980B9')
            _price_box(last_close, f'{last_close:.2f}', '#111827')

            # --- Zone reactions (kept from v16, restyled for light mode) ---
            zone_reaction_summary = signal_data.get('zone_reaction_summary') or {}
            if zone_reaction_summary:
                reaction_lines = []
                for tf_name, reaction_map in zone_reaction_summary.items():
                    parts = []
                    for dir_key, reaction in reaction_map.items():
                        parts.append(f"{dir_key[:1]}:{reaction['reaction_type'].replace('_',' ')}")
                    if parts:
                        reaction_lines.append(f"{tf_name}: {' | '.join(parts)}")
                if reaction_lines:
                    fig.add_annotation(
                        xref='paper', yref='paper', x=0.01, y=0.99,
                        xanchor='left', yanchor='top', align='left',
                        text='<b>Zone Reactions</b><br>' + '<br>'.join(reaction_lines),
                        showarrow=False,
                        font=dict(color='#1F2937', size=10, family='Arial, sans-serif'),
                        bgcolor='rgba(255, 255, 255, 0.9)',
                        bordercolor='#D1D5DB', borderwidth=1
                    )

            # --- STRATEGY STUDY panel (STAGE-14): which strategy fired and why -
            #     the "details for studying" from the signal alert. Light card,
            #     right side, mirroring the screenshot's info-card concept. ---
            try:
                _strat = str(signal_data.get('strategy') or 'UNKNOWN').replace('_', ' ').title()
                _stype = str(signal_data.get('signal_type') or 'regular').replace('_', ' ').title()
                _otype = str(signal_data.get('order_type') or 'market').upper()
                _regime = str(signal_data.get('regime') or 'N/A')
                _session = str(signal_data.get('session') or 'N/A')
                _mtf = str(signal_data.get('mtf_signal_type') or 'INTRADAY')
                _align = float(signal_data.get('alignment_multiplier') or 1.0)
                _ml = signal_data.get('ml') or {}
                _ml_conf = _ml.get('conf', None)
                _ml_dir = _ml.get('dir_prob', None)
                _corr = signal_data.get('correlation', None)
                _reasons = [str(r) for r in (signal_data.get('reasons') or [])][-6:]

                study_lines = [
                    "<b>STRATEGY STUDY</b>",
                    f"Strategy: {_strat}",
                    f"Type: {_stype} | Order: {_otype}",
                    f"Regime: {_regime} | Session: {_session}",
                    f"MTF: {_mtf}" + (f" ({_align:.2f}x aligned)" if _align and _align != 1.0 else ""),
                ]
                if _ml_conf is not None:
                    study_lines.append(f"ML conf: {float(_ml_conf)*100:.0f}%" +
                                        (f" (dir prob {float(_ml_dir)*100:.0f}%)" if _ml_dir is not None else ""))
                if _corr is not None:
                    study_lines.append(f"DXY corr: {float(_corr):+.2f}")
                study_lines.append(f"Final score: {score_pct:.0f}% ({score:.1f}/15)")
                if grade:
                    study_lines.append(f"Grade: [{grade}]")
                if _reasons:
                    study_lines.append("<b>Confluence (latest):</b>")
                    study_lines += [f"&bull; {r}" for r in _reasons]

                fig.add_annotation(
                    xref='paper', yref='paper', x=0.995, y=0.60,
                    xanchor='right', yanchor='top', align='left',
                    text='<br>'.join(study_lines),
                    showarrow=False,
                    font=dict(color='#1F2937', size=11, family='Arial, sans-serif'),
                    bgcolor='rgba(248, 250, 252, 0.94)',
                    bordercolor='#D1D5DB', borderwidth=1
                )
            except Exception as _e:
                LOG.debug(f"[Chart] Strategy study panel error: {_e}")

            # --- Volume subplot (green/red by candle direction) ---
            if 'volume' in df.columns:
                vol_colors = ['#089981' if c >= o else '#F23645'
                              for o, c in zip(df['open'].values, df['close'].values)]
                fig.add_trace(self.go.Bar(
                    x=x_values, y=df['volume'], marker_color=vol_colors, opacity=0.45,
                    name='Volume', showlegend=False
                ), row=2, col=1)

            # --- Layout: TradingView light mode ---
            title_side = 'LONG' if is_long else 'SHORT'
            title_text = (f"{symbol}  |  {timeframe_label}  |  {title_side}  |  "
                          f"Score {score_pct:.0f}%  |  {strategy_name}")
            if chart_variant == 'strategy':
                title_text = f"{symbol}  |  {timeframe_label}  |  Strategy Overlay  |  {strategy_name}"

            fig.update_layout(
                title={'text': title_text, 'x': 0.01, 'xanchor': 'left',
                       'font': dict(size=15, color='#111827', family='Arial, sans-serif')},
                template='plotly_white',
                hovermode='x unified',
                height=760,
                width=1080,
                font=dict(family='Arial, sans-serif', size=12, color='#111827'),
                plot_bgcolor='#ffffff',
                paper_bgcolor='#ffffff',
                margin=dict(t=80, b=34, l=46, r=26),
                showlegend=True,
                legend=dict(orientation='h', yanchor='bottom', y=1.015, xanchor='right', x=1.0,
                            font=dict(size=10, color='#64748B'), bgcolor='rgba(255,255,255,0)')
            )
            fig.update_xaxes(showgrid=True, gridwidth=1, gridcolor='#E5E7EB', zeroline=False,
                             tickfont=dict(color='#64748B'))
            fig.update_xaxes(rangeslider_visible=False)
            fig.update_yaxes(showgrid=True, gridwidth=1, gridcolor='#E5E7EB', zeroline=False,
                             tickfont=dict(color='#64748B'), side='right',
                             tickformat=',.2f' if (last_close > 500) else ',.4f')
            fig.update_yaxes(showticklabels=False, row=2, col=1)

            def _dump_html_fallback():
                # STAGE-13: when no PNG engine works (e.g. plotly 6.0.1 +
                # kaleido 1.3.0 mismatch), dump a self-contained HTML so the
                # hero chart is still inspectable in state/charts/.
                try:
                    os.makedirs('state/charts', exist_ok=True)
                    html_path = f"state/charts/hero_{int(time.time())}.html"
                    fig.write_html(html_path, include_plotlyjs=True, full_html=True)
                    LOG.info(f"[v16.0] PNG unavailable - hero chart dumped to {html_path}")
                except Exception:
                    pass

            if self.kaleido_available:
                try:
                    png_bytes = fig.to_image(format='png', width=1080, height=760)
                    if png_bytes:
                        LOG.info(f"[v16.0] Hero chart generated: {len(png_bytes)} bytes")
                        return png_bytes
                    raise RuntimeError('empty png')
                except Exception as e:
                    try:
                        png_bytes = self.pio.to_image(fig, format='png', width=1080, height=760)
                        if png_bytes:
                            LOG.info(f"[v16.0] Hero chart generated via pio: {len(png_bytes)} bytes")
                            return png_bytes
                        raise RuntimeError('empty png')
                    except Exception as e2:
                        # Third fallback - kaleido 1.x direct API (works with
                        # plotly < 6.1.1 where the to_image bridge is broken).
                        try:
                            import kaleido
                            import tempfile
                            tmp = tempfile.NamedTemporaryFile(suffix='.png', delete=False)
                            tmp.close()
                            kaleido.write_fig(fig, file=tmp.name, width=1080, height=760)
                            with open(tmp.name, 'rb') as f:
                                png_bytes = f.read()
                            os.unlink(tmp.name)
                            if png_bytes:
                                LOG.info(f"[v16.0] Hero chart generated via kaleido API: {len(png_bytes)} bytes")
                                return png_bytes
                            raise RuntimeError('empty png')
                        except Exception as e3:
                            LOG.warning(f"[v16.0] PNG export failed: {e} / {e2} / {e3}")
                            _dump_html_fallback()

            return None
        except Exception as e:
            LOG.error(f"[v16.0] Chart creation failed: {e}")
            return None
    def create_signal_charts(self, dfs, signal_data: dict, macro_insight: dict = None, timeframes=None):
        """Generate multiple clean signal charts for the preferred timeframe and a strategy overlay."""
        if not self.go or dfs is None:
            return []

        timeframes = timeframes or ['M5', 'M15', 'H1', 'H4']
        preferred_tf = (signal_data or {}).get('tf')
        ordered_tfs = [preferred_tf] if preferred_tf in timeframes else []
        ordered_tfs += [tf for tf in timeframes if tf != preferred_tf]

        generated = []
        for idx, tf in enumerate(ordered_tfs[:3]):
            df = dfs.get(tf)
            if df is None or df.empty:
                continue

            chart_variant = 'primary' if idx == 0 else 'strategy'
            img = self.create_signal_chart(df, signal_data, macro_insight, timeframe_label=tf, chart_variant=chart_variant)
            if img:
                generated.append((tf, img))

        return generated
    
    def _create_signal_insight_table(self, signal_data: dict, macro_insight: dict = None) -> object:
        """Create Signal Insight table trace with macro bias, DXY correlation, volatility regime"""
        if not self.go:
            return None
        
        macro_insight = macro_insight or {}
        
        # Prepare table data
        header = ['Metric', 'Value']
        rows = [
            ['Signal Score', f"{signal_data.get('score', 0):.1f}/15"],
            ['Confluence', f"{signal_data.get('confluence_mult', 1.0):.2f}x"],
            ['Macro Bias', macro_insight.get('macro_bias', 'NEUTRAL')],
            ['DXY Correlation', f"{macro_insight.get('dxy_correlation', 0.0):.3f}"],
            ['Volatility Regime', macro_insight.get('volatility_regime', 'NORMAL')],
            ['ML Confidence', f"{signal_data.get('ml_conf', 0.5):.0%}"],
        ]
        
        return self.go.Table(
            header=dict(
                values=header,
                fill_color='#1a1a2e',
                align='left',
                font=dict(color='#00FF41', size=11)
            ),
            cells=dict(
                values=list(zip(*rows)),
                fill_color='#0f0f1e',
                align='left',
                font=dict(color='#FFFFFF', size=10),
                height=25
            ),
            name='Signal Insight'
        )


class CPIEconomicShockHandler:
    """
    v16.0 Dynamic CPI Shock Handler
    
    Monitors for CPI (Consumer Price Index) news events and implements
    dynamic risk lockdowns based on actual vs forecast deviations:
    
    - If Actual > Forecast + 0.2% (USD Bullish): Lock long positions for 120 min
    - If Actual < Forecast - 0.2% (USD Bearish): Lock short positions for 120 min
    - Release lock early when market recovers 50% of initial news move
    """
    def __init__(self):
        self.cpi_event_lock_long = None  # datetime when lock expires
        self.cpi_event_lock_short = None  # datetime when lock expires
        self.cpi_shock_baseline = {}  # Stores initial price at shock time {direction: price}
        self.cpi_shock_window_min = 120  # How long to lock after CPI shock
        self.cpi_deviation_threshold = 0.002  # 0.2% threshold
        self.recovery_threshold = 0.5  # Release when 50% recovery
        LOG.info("[v16.0] CPIEconomicShockHandler initialized")
    
    def check_cpi_event(self) -> dict:
        """
        Check if current time is within CPI event window
        
        Returns:
            {
                'is_cpi_time': bool,
                'actual': float (if available),
                'forecast': float (if available),
                'deviation': float,
                'impact': 'BULLISH' | 'BEARISH' | None
            }
        """
        # Check if news module available and near CPI time
        try:
            now = utc_now()
            
            # Determine if CPI event window (typically first Friday of month 13:30 UTC for US CPI)
            # For this example, check if we're in first Friday of month near 13:30 UTC
            is_first_friday = now.day <= 7 and now.weekday() == 4  # Friday
            is_cpi_hour = now.hour == 13 and now.minute >= 25  # 13:25-13:35 window
            
            if not (is_first_friday and is_cpi_hour):
                return {'is_cpi_time': False}
            
            # In production: would fetch actual vs forecast from news API
            # For now, return structure for integration
            return {
                'is_cpi_time': True,
                'actual': None,  # Would be fetched from news API
                'forecast': None,  # Would be fetched from news API
                'deviation': 0.0,
                'impact': None
            }
        except Exception as e:
            LOG.warning(f"[CPI] Event check failed: {e}")
            return {'is_cpi_time': False}
    
    def evaluate_cpi_shock(self, actual: float, forecast: float, current_price: float) -> str:
        """
        Evaluate CPI deviation and determine shock impact
        
        Args:
            actual: Actual CPI value
            forecast: Forecasted CPI value
            current_price: Current XAU/USD price at shock time
        
        Returns:
            'BULLISH' | 'BEARISH' | None
        """
        if actual is None or forecast is None:
            return None
        
        deviation = (actual - forecast) / abs(forecast) if forecast != 0 else 0
        
        LOG.info(f"[CPI] Actual={actual:.2f}, Forecast={forecast:.2f}, Deviation={deviation:.4f}")
        
        if deviation > self.cpi_deviation_threshold:
            # USD Bullish (strong CPI = higher rates expected = USD stronger = XAU weaker)
            LOG.warning(f"[CPI] BULLISH SHOCK: Actual beat forecast by {deviation*100:.2f}%")
            self.cpi_event_lock_long = utc_now() + timedelta(minutes=self.cpi_shock_window_min)
            self.cpi_shock_baseline['BUY'] = current_price
            return 'BULLISH'
        
        elif deviation < -self.cpi_deviation_threshold:
            # USD Bearish (weak CPI = lower rates expected = USD weaker = XAU stronger)
            LOG.warning(f"[CPI] BEARISH SHOCK: Actual missed forecast by {abs(deviation)*100:.2f}%")
            self.cpi_event_lock_short = utc_now() + timedelta(minutes=self.cpi_shock_window_min)
            self.cpi_shock_baseline['SELL'] = current_price
            return 'BEARISH'
        
        return None
    
    def is_long_locked(self, current_price: float = None) -> bool:
        """
        Check if long positions are locked due to CPI shock
        
        Returns True if:
        1. Lock period not expired, OR
        2. Market hasn't recovered 50% of initial move yet
        """
        if self.cpi_event_lock_long is None:
            return False
        
        # Check if lock period expired
        if utc_now() > self.cpi_event_lock_long:
            self.cpi_event_lock_long = None
            self.cpi_shock_baseline.pop('BUY', None)
            return False
        
        # Check recovery threshold (if we have price data)
        if current_price and 'BUY' in self.cpi_shock_baseline:
            baseline = self.cpi_shock_baseline['BUY']
            # For bullish shock (XAU dropped), check if it recovered 50%
            # If baseline was 2500, current is 2480, move was 20 points
            # Recovery is when it's back to 2490 (50% of 20)
            move = baseline - current_price  # Positive if dropped
            if move > 0 and current_price >= (baseline - move * self.recovery_threshold):
                LOG.info(f"[CPI] Long lock released: Market recovered 50% ({current_price:.2f} vs baseline {baseline:.2f})")
                self.cpi_event_lock_long = None
                self.cpi_shock_baseline.pop('BUY', None)
                return False
        
        return True
    
    def is_short_locked(self, current_price: float = None) -> bool:
        """
        Check if short positions are locked due to CPI shock
        
        Returns True if:
        1. Lock period not expired, OR
        2. Market hasn't recovered 50% of initial move yet
        """
        if self.cpi_event_lock_short is None:
            return False
        
        # Check if lock period expired
        if utc_now() > self.cpi_event_lock_short:
            self.cpi_event_lock_short = None
            self.cpi_shock_baseline.pop('SELL', None)
            return False
        
        # Check recovery threshold (if we have price data)
        if current_price and 'SELL' in self.cpi_shock_baseline:
            baseline = self.cpi_shock_baseline['SELL']
            # For bearish shock (XAU rallied), check if it recovered 50%
            move = current_price - baseline  # Positive if rallied
            if move > 0 and current_price <= (baseline + move * self.recovery_threshold):
                LOG.info(f"[CPI] Short lock released: Market recovered 50% ({current_price:.2f} vs baseline {baseline:.2f})")
                self.cpi_event_lock_short = None
                self.cpi_shock_baseline.pop('SELL', None)
                return False
        
        return True
    
    def lock_unknown_shock(self, current_price: float):
        """STAGE-8: conservative lock when a CPI/NFP event is detected inside the
        event window but actual-vs-forecast deviation is unavailable (the bot's
        news feed carries titles/times only). Lock BOTH directions for the full
        shock window instead of guessing a side."""
        self.cpi_event_lock_long = utc_now() + timedelta(minutes=self.cpi_shock_window_min)
        self.cpi_event_lock_short = utc_now() + timedelta(minutes=self.cpi_shock_window_min)
        self.cpi_shock_baseline['BUY'] = current_price
        self.cpi_shock_baseline['SELL'] = current_price
        LOG.warning(f"[CPI] Unknown-shock lock: both directions locked {self.cpi_shock_window_min}min (baseline {current_price:.2f})")


