# v18.1 LAYER 2: LIQUIDITY SENTINEL - FAIR VALUE GAPS (FVG)
# ============================================================
class LiquiditySentinelV18:
    # STAGE-9: was shadowed by the later LiquiditySentinel definition (name bound to the last def).
    # Kept verbatim as the LiquiditySentinelV18 base class; NOT deleted.
    """
    Detect Bullish FVGs (Support) and Bearish FVGs (Resistance).
    FVG = Imbalance > ATR * 0.3
    Reward price when it taps FVG.
    """
    def __init__(self):
        self.bullish_fvgs = deque(maxlen=50)  # Support zones
        self.bearish_fvgs = deque(maxlen=50)  # Resistance zones
        
    def detect_fvgs(self, high, low, close, atr, lookback=3):
        """
        Detect Fair Value Gaps using 3-bar pattern.
        Bullish FVG: low[i] > high[i-2] (Gap Up)
        Bearish FVG: high[i] < low[i-2] (Gap Down)
        """
        fvg_threshold = atr * CFG.get("fvg_atr_multiplier", 0.3)
        signals = []
        
        if len(high) < 3:
            return signals
        
        # Check for Bullish FVG (support zone)
        if low[-1] > high[-3] and (low[-1] - high[-3]) > fvg_threshold:
            bullish_fvg_zone = (high[-3], low[-1])
            self.bullish_fvgs.append({
                'zone': bullish_fvg_zone,
                'timestamp': datetime.now(),
                'atr': atr
            })
            signals.append(('BULLISH_FVG', bullish_fvg_zone))
        
        # Check for Bearish FVG (resistance zone)
        if high[-1] < low[-3] and (low[-3] - high[-1]) > fvg_threshold:
            bearish_fvg_zone = (high[-1], low[-3])
            self.bearish_fvgs.append({
                'zone': bearish_fvg_zone,
                'timestamp': datetime.now(),
                'atr': atr
            })
            signals.append(('BEARISH_FVG', bearish_fvg_zone))
        
        return signals
    
    def tap_fvg_reward(self, current_price, direction):
        """
        If price taps FVG zone, add reward for corresponding direction.
        BUY: If price taps Bullish FVG (support)
        SELL: If price taps Bearish FVG (resistance)
        """
        reward = 0.0
        
        # Check Bullish FVGs for BUY
        if direction == 'BUY':
            for fvg in self.bullish_fvgs:
                zone_low, zone_high = fvg['zone']
                if zone_low <= current_price <= zone_high:
                    reward += 3.0  # Reward for tapping support
        
        # Check Bearish FVGs for SELL
        elif direction == 'SELL':
            for fvg in self.bearish_fvgs:
                zone_low, zone_high = fvg['zone']
                if zone_low <= current_price <= zone_high:
                    reward += 3.0  # Reward for tapping resistance
        
        return reward

