# v18.1 LAYER 3: DYNAMIC NEWS STRADDLE
# ============================================================
class DynamicNewsStraddle:
    """
    5 mins before news, place BOTH Buy-Stop and Sell-Stop @ (Price +/- (ATR * 0.5)).
    Wait for breakout, exit the losing side.
    """
    def __init__(self):
        self.pending_straddles = {}
        self.news_schedule = {}
        
    def setup_straddle(self, current_price, atr, symbol, timeframe='H1'):
        """
        Setup straddle: Buy-Stop above and Sell-Stop below current price.
        """
        straddle_offset = atr * CFG.get("news_straddle_atr_mult", 0.5)
        
        buy_stop_price = current_price + straddle_offset
        sell_stop_price = current_price - straddle_offset
        
        straddle_id = hashlib.md5(f"{symbol}_{datetime.now().isoformat()}".encode()).hexdigest()[:8]
        
        self.pending_straddles[straddle_id] = {
            'symbol': symbol,
            'buy_stop': buy_stop_price,
            'sell_stop': sell_stop_price,
            'entry_price': current_price,
            'atr': atr,
            'created_at': datetime.now(),
            'status': 'PENDING'
        }
        
        LOG.info(f"[v18.1] News Straddle {straddle_id}: BUY-STOP={buy_stop_price:.2f}, SELL-STOP={sell_stop_price:.2f}")
        return straddle_id, buy_stop_price, sell_stop_price
    
    def check_straddle_fills(self, current_price):
        """
        Check if straddle limits are breached.
        Returns direction of breakout: 'BUY', 'SELL', or None
        """
        breakouts = []
        
        for straddle_id, straddle in list(self.pending_straddles.items()):
            if straddle['status'] != 'PENDING':
                continue
            
            if current_price >= straddle['buy_stop']:
                straddle['status'] = 'BUY_FILLED'
                breakouts.append(('BUY', straddle_id, straddle))
                LOG.info(f"[v18.1] Straddle {straddle_id} BUY filled at {current_price:.2f}")
            
            elif current_price <= straddle['sell_stop']:
                straddle['status'] = 'SELL_FILLED'
                breakouts.append(('SELL', straddle_id, straddle))
                LOG.info(f"[v18.1] Straddle {straddle_id} SELL filled at {current_price:.2f}")
        
        return breakouts

