class GhostCorrelationSentinel:
    """
    Monitor XAUUSD vs DXYm correlation:
    - Strong Inverse (< -0.8): Reward trend following
    - Toxic Positive (> -0.2): Penalty -5.0
    """
    def __init__(self, lookback=50):
        self.lookback = lookback
        self.xau_prices = deque(maxlen=lookback)
        self.dxy_prices = deque(maxlen=lookback)
        self.correlation_history = deque(maxlen=100)
        
    def update_prices(self, xau_price, dxy_price):
        """Update price history"""
        self.xau_prices.append(xau_price)
        self.dxy_prices.append(dxy_price)
    
    def calculate_correlation(self):
        """Calculate Pearson correlation between XAUUSD and DXYm"""
        if len(self.xau_prices) < 10 or len(self.dxy_prices) < 10:
            return 0.0
        
        xau_arr = np.array(list(self.xau_prices))
        dxy_arr = np.array(list(self.dxy_prices))
        
        corr = safe_correlation(xau_arr, dxy_arr)
        if np.isnan(corr):
            corr = 0.0
        
        self.correlation_history.append(corr)
        return corr
    
    def get_correlation_signal(self, corr, direction):
        """
        SYMMETRICAL LOGIC:
        - Strong Inverse (< -0.8): Reward trend (BUY if DXY down, SELL if DXY up)
        - Toxic Positive (> -0.2): Penalty -5.0 (Avoid trading)
        - Normal (-0.8 to -0.2): Neutral
        """
        extreme_inverse_threshold = CFG.get("correlation_extreme_inverse", -0.8)
        toxic_positive_threshold = CFG.get("correlation_toxic_positive", -0.2)
        
        if corr < extreme_inverse_threshold:
            # Strong inverse: Reward trend following
            return 5.0  # Reward
        elif corr > toxic_positive_threshold:
            # Toxic positive: Penalty
            return -5.0  # Penalty
        else:
            # Normal range
            return 0.0

