class FVGLiquidityMagnet:
    """
    Detect H1 Fair Value Gaps and place limit orders at FVG levels.
    
    BUY strategy:
    - Identify Bullish FVG (gap up: Low[i] > High[i-2])
    - If price approaching from above, place BUY_LIMIT at top of gap
    
    SELL strategy:
    - Identify Bearish FVG (gap down: High[i] < Low[i-2])
    - If price approaching from below, place SELL_LIMIT at bottom of gap
    """
    
    def __init__(self):
        self.name = "FVGLiquidityMagnet"
        self.last_h1_fvgs = []
        self.lookback = 50  # Scan last 50 H1 bars
        
    def detect_h1_fvgs(self, h1_df) -> list:
        """
        Detect H1 Fair Value Gaps.
        Returns list of {'type': 'BULLISH'|'BEARISH', 'level': float}
        """
        if h1_df is None or len(h1_df) < 3:
            return []
        
        fvgs = []
        high = h1_df['high'].values
        low = h1_df['low'].values
        atr = h1_df.get('atr', h1_df['close'].rolling(14).std()).iloc[-1]
        
        # Scan for FVGs (need at least 50 bars for meaningful detection)
        scan_len = min(len(h1_df), self.lookback)
        
        for i in range(2, scan_len):
            # Bullish FVG: Current Low > Previous-2 High
            if low[i] > high[i-2]:
                gap_size = low[i] - high[i-2]
                if gap_size > atr * 0.5:  # Significant gap
                    fvgs.append({
                        'type': 'BULLISH',
                        'level': high[i-2],  # Top of the gap (entry point)
                        'gap_size': gap_size,
                        'bar_index': i
                    })
            
            # Bearish FVG: Current High < Previous-2 Low
            if high[i] < low[i-2]:
                gap_size = low[i-2] - high[i]
                if gap_size > atr * 0.5:  # Significant gap
                    fvgs.append({
                        'type': 'BEARISH',
                        'level': low[i-2],  # Bottom of the gap (entry point)
                        'gap_size': gap_size,
                        'bar_index': i
                    })
        
        self.last_h1_fvgs = fvgs[-5:] if fvgs else []  # Keep last 5 for context
        return self.last_h1_fvgs
    
    def get_magnet_order(self, current_price: float, h1_df) -> dict or None:
        """
        Check if current price is approaching an FVG magnet.
        Returns order spec: {'type': 'BUY_LIMIT'|'SELL_LIMIT', 'price': float, 'fvg_type': str}
        """
        fvgs = self.detect_h1_fvgs(h1_df)
        if not fvgs:
            return None
        
        # Check most recent FVG
        latest_fvg = fvgs[-1]
        proximity_threshold = latest_fvg['gap_size'] * 0.5  # Half the gap size for approach detection
        
        if latest_fvg['type'] == 'BULLISH':
            # Bullish FVG: Price approaching FROM ABOVE
            # BUY_LIMIT should be at the TOP of the gap
            if current_price < latest_fvg['level'] + proximity_threshold and \
               current_price > latest_fvg['level']:
                return {
                    'type': 'BUY_LIMIT',
                    'price': latest_fvg['level'],
                    'fvg_type': 'BULLISH',
                    'gap_size': latest_fvg['gap_size']
                }
        
        elif latest_fvg['type'] == 'BEARISH':
            # Bearish FVG: Price approaching FROM BELOW
            # SELL_LIMIT should be at the BOTTOM of the gap
            if current_price > latest_fvg['level'] - proximity_threshold and \
               current_price < latest_fvg['level']:
                return {
                    'type': 'SELL_LIMIT',
                    'price': latest_fvg['level'],
                    'fvg_type': 'BEARISH',
                    'gap_size': latest_fvg['gap_size']
                }
        
        return None

