def normalize_direction(direction) -> str:
    """STAGE-6: Normalize trade direction to 'BUY' or 'SELL' (fail-closed).
    
    place_market/place_limit historically did `if direction == 'BUY': BUY else SELL`,
    so any unrecognized value ('buy', 'LONG', 1, 'sell ', None...) silently became
    a SELL. Now every order path normalizes first; unrecognized values return
    'UNKNOWN' and the caller refuses the order.
    """
    try:
        if isinstance(direction, str):
            d = direction.strip().upper()
            if d in ('BUY', 'LONG', 'B', '1', 'TRUE'):
                return 'BUY'
            if d in ('SELL', 'SHORT', 'S', '-1', 'FALSE'):
                return 'SELL'
        elif isinstance(direction, (int, float)) and not isinstance(direction, bool):
            if direction >= 1:
                return 'BUY'
            if direction <= -1:
                return 'SELL'
        elif isinstance(direction, bool):
            return 'BUY' if direction else 'SELL'
    except Exception:
        pass
    return 'UNKNOWN'

class MT5Connection:
    def __init__(self):
        self.connected = False
        self.circuit = CircuitBreaker()
        self.cache = TTLCache(100, 60)
        self.fetch_lock = threading.RLock()
        
        if not MT5_OK:
            LOG.error("[MT5] Library not installed. Install: pip install MetaTrader5")
            return

        self.connect()

    def connect(self, max_attempts=5):
        for attempt in range(max_attempts):
            try:
                LOG.info(f"[MT5] Attempt {attempt+1}/{max_attempts}")

                if not mt5.initialize():
                    err = mt5.last_error()
                    LOG.error(f"[MT5] Initialize failed: {err}")
                    time.sleep(2 ** attempt)
                    continue

                if not mt5.login(CFG["mt5_login"], CFG["mt5_password"], CFG["mt5_server"]):
                    err = mt5.last_error()
                    LOG.error(f"[MT5] Login failed: {err}")
                    LOG.error(f"[MT5] Check: login={CFG['mt5_login']}, server={CFG['mt5_server']}")
                    mt5.shutdown()
                    time.sleep(2 ** attempt)
                    continue

                if not mt5.symbol_select(CFG["symbol"], True):
                    LOG.error(f"[MT5] Main symbol {CFG['symbol']} not available")
                    mt5.shutdown()
                    time.sleep(2 ** attempt)
                    continue

                if CFG["correlation_symbol"]:
                    if mt5.symbol_select(CFG["correlation_symbol"], True):
                        LOG.info(f"[MT5] Correlation symbol {CFG['correlation_symbol']} selected")
                    else:
                        LOG.warning(f"[MT5] Correlation symbol {CFG['correlation_symbol']} not available")

                self.connected = True
                LOG.info(f"[MT5] Connected on attempt {attempt+1}")

                try:
                    TG.notify_status(f"MT5 Connected\nServer: {CFG['mt5_server']}\nSymbol: {CFG['symbol']}")
                except KeyboardInterrupt:
                    raise  # Re-raise keyboard interrupt
                except (OSError, RuntimeError) as e:
                    LOG.debug(f"Failed to notify Telegram of MT5 connection: {e}")
                except Exception as e:
                    LOG.warning(f"Unexpected error in Telegram notification: {type(e).__name__}: {e}")

                return True

            except Exception as e:
                LOG.error(f"[MT5] Exception: {e}")
                time.sleep(2 ** attempt)

        self.connected = False
        LOG.error(f"[MT5] Failed after {max_attempts} attempts")
        TG.notify_error(f"MT5 Failed - {max_attempts} attempts")
        return False

    def reconnect(self):
        if CFG["mode"] not in ['live', 'analysis']:
            return False

        self.connected = False
        try:
            mt5.shutdown()
        except (OSError, RuntimeError) as e:
            LOG.debug(f"MT5 shutdown raised exception (expected): {e}")
        except Exception as e:
            LOG.warning(f"Unexpected error shutting down MT5: {type(e).__name__}: {e}")
        LOG.warning("[MT5] Reconnecting with exponential backoff")
        return self.connect(max_attempts=5)

    def ensure_connection(self):
        if not MT5_OK:
            return False

        if CFG["mode"] not in ['live', 'analysis']:
            return self.connected

        if not self.connected:
            return self.reconnect()

        try:
            terminal = mt5.terminal_info()
            if terminal is None:
                return self.reconnect()
        except (OSError, RuntimeError) as e:
            LOG.warning(f"MT5 terminal check failed: {e}, reconnecting...")
            return self.reconnect()
        except Exception as e:
            LOG.error(f"Unexpected MT5 error: {type(e).__name__}: {e}")
            return self.reconnect()

        return True
    
    def fetch(self, symbol, tf, bars):
        cache_key = f"{symbol}:{tf}:{bars}"
        with self.fetch_lock:
            cached = self.cache.get(cache_key)
            if cached is not None:
                return cached

            result = self._fetch_impl(symbol, tf, bars)
            # CRITICAL: Only cache successful fetches, NOT None/empty results
            if result is not None and not result.empty:
                self.cache.set(cache_key, result)
            # If result is None/empty, do NOT cache it to avoid blocking future attempts
            return result
    
    def _fetch_impl(self, symbol, tf, bars):
        if not self.ensure_connection():
            LOG.error(f"[MT5] Connection check failed for {symbol}")
            return None
        
        try:
            tf_map = {
                'M1': mt5.TIMEFRAME_M1,
                'M5': mt5.TIMEFRAME_M5,
                'M15': mt5.TIMEFRAME_M15,
                'H1': mt5.TIMEFRAME_H1,
                'H4': mt5.TIMEFRAME_H4,
                'D1': mt5.TIMEFRAME_D1,
                'W1': mt5.TIMEFRAME_W1,
                'MN1': mt5.TIMEFRAME_MN1
            }
            
            if tf not in tf_map:
                LOG.error(f"[MT5] Unknown timeframe: {tf}")
                return None
            
            # Retry logic with exponential backoff for transient failures
            max_retries = 3
            for attempt in range(1, max_retries + 1):
                LOG.debug(f"[MT5._fetch_impl] Fetching {tf}: requesting {bars} bars for {symbol} (attempt {attempt}/{max_retries})")
                
                try:
                    with self.fetch_lock:
                        if not mt5.symbol_select(symbol, True):
                            last_err = mt5.last_error()
                            LOG.error(f"[MT5] Symbol select failed for {symbol}: {last_err}")
                            if attempt < max_retries:
                                time.sleep(0.5 * (2 ** (attempt - 1)))
                                continue
                            return None

                        # Check if circuit is OPEN and reset it for data fetch (data fetch is critical path)
                        if self.circuit.state == "open":
                            LOG.warning(f"[MT5._fetch_impl] Circuit breaker OPEN, resetting for critical data fetch")
                            self.circuit.reset()
                        
                        rates = self.circuit.call(
                            mt5.copy_rates_from_pos,
                            symbol,
                            tf_map[tf],
                            0,
                            bars
                        )
                    
                    if rates is None:
                        last_err = mt5.last_error()
                        LOG.error(f"[MT5] copy_rates_from_pos RETURNED NONE for {symbol} {tf}: {last_err} (attempt {attempt}/{max_retries})")
                        if attempt < max_retries:
                            time.sleep(0.5 * (2 ** (attempt - 1)))
                            continue
                        return None
                    
                    if len(rates) == 0:
                        LOG.error(f"[MT5] NO RATES returned for {symbol} {tf} (empty array, attempt {attempt}/{max_retries})")
                        if attempt < max_retries:
                            time.sleep(0.5 * (2 ** (attempt - 1)))
                            continue
                        return None
                    
                    # Success - convert to DataFrame
                    LOG.debug(f"[MT5] Got {len(rates)} rates on attempt {attempt}, converting to DataFrame...")
                    df = pd.DataFrame(rates)
                    df = df.rename(columns={'tick_volume': 'volume'})
                    df.index = pd.to_datetime(df['time'], unit='s', utc=True)
                    result = df[['open', 'high', 'low', 'close', 'volume', 'spread']]
                    LOG.debug(f"[MT5] Successfully fetched {len(result)} bars for {symbol} {tf}")
                    return result
                
                except Exception as circuit_err:
                    LOG.error(f"[MT5._fetch_impl] Circuit breaker or MT5 error for {symbol} {tf}: {type(circuit_err).__name__}: {circuit_err}")
                    if attempt < max_retries:
                        time.sleep(0.5 * (2 ** (attempt - 1)))
                        continue
            
            # All retries exhausted
            LOG.error(f"[MT5] All {max_retries} retry attempts exhausted for {symbol} {tf}")
            return None
            
        except Exception as e:
            LOG.error(f"[MT5] Fetch error for {symbol} {tf}: {type(e).__name__}: {e}")
            import traceback
            LOG.debug(traceback.format_exc())
            return None
    
    def fetch_range(self, symbol, tf, start, end):
        if not self.ensure_connection():
            return None
        
        try:
            tf_map = {'M15': mt5.TIMEFRAME_M15, 'H1': mt5.TIMEFRAME_H1, 'H4': mt5.TIMEFRAME_H4, 'D1': mt5.TIMEFRAME_D1, 'W1': mt5.TIMEFRAME_W1, 'MN1': mt5.TIMEFRAME_MN1}
            with self.fetch_lock:
                rates = mt5.copy_rates_range(
                    symbol,
                    tf_map.get(tf, mt5.TIMEFRAME_M15),
                    start,
                    end
                )
            
            # FIXED: Check if rates is None or empty properly
            if rates is None:
                return None
            
            # Check if it's a numpy array and has length
            if isinstance(rates, np.ndarray):
                if rates.size == 0:
                    return None
            elif len(rates) == 0:
                return None
            
            df = pd.DataFrame(rates)
            df.index = pd.to_datetime(df['time'], unit='s', utc=True)
            
            # FIX: Handle missing volume column properly
            # MT5 returns 'tick_volume' not 'volume'
            if 'tick_volume' in df.columns:
                df = df.rename(columns={'tick_volume': 'volume'})
            
            # Ensure all required columns exist
            required_cols = ['open', 'high', 'low', 'close', 'volume', 'spread']
            available_cols = [col for col in required_cols if col in df.columns]
            
            # If volume column doesn't exist, create it with default values
            if 'volume' not in df.columns:
                df['volume'] = 0
            
            return df[available_cols]
            
        except Exception as e:
            LOG.error(f"[MT5] Fetch range error: {e}")
            return None
    
    def get_fresh_tick(self, symbol=None):
        if not self.ensure_connection():
            return None
        
        if symbol is None:
            symbol = CFG["symbol"]
        
        try:
            tick = mt5.symbol_info_tick(symbol)
            if tick:
                spread = tick.ask - tick.bid
                STORE.log_spread(symbol, spread)
                
                return {
                    'bid': tick.bid,
                    'ask': tick.ask,
                    'mid': (tick.bid + tick.ask) / 2,
                    'spread': spread,
                    'time': tick.time
                }
        except Exception as e:
            LOG.warning(f"[MT5] Tick error for {symbol}: {e}")
        return None
    
    def current_price(self, symbol=None):
        tick = self.get_fresh_tick(symbol)
        return tick['mid'] if tick else None
    
    def get_spread(self, symbol=None):
        tick = self.get_fresh_tick(symbol)
        return tick['spread'] if tick else None
    
    def get_account_info(self):
        """Get current account information including balance and equity"""
        if CFG["mode"] != 'live' or not self.ensure_connection():
            return {
                'balance': CFG["account_balance"],
                'equity': CFG["account_balance"],
                'profit': 0.0,
                'margin': 0.0,
                'free_margin': CFG["account_balance"]
            }
        
        try:
            account_info = mt5.account_info()
            if account_info:
                return {
                    'balance': account_info.balance,
                    'equity': account_info.equity,
                    'profit': account_info.profit,
                    'margin': account_info.margin,
                    'free_margin': account_info.margin_free,
                    'margin_level': account_info.margin_level
                }
        except Exception as e:
            LOG.warning(f"[MT5] Account info error: {e}")
        
        return {
            'balance': CFG["account_balance"],
            'equity': CFG["account_balance"],
            'profit': 0.0,
            'margin': 0.0,
            'free_margin': CFG["account_balance"]
        }
    
    def get_current_balance(self):
        """Get current account balance"""
        account_info = self.get_account_info()
        return account_info['balance']
    
    def check_available_margin(self, proposed_lots, entry_price=None, symbol=None):
        """Check if sufficient margin available for proposed position size."""
        try:
            if symbol is None:
                symbol = CFG["symbol"]
            if entry_price is None:
                tick = self.get_fresh_tick(symbol)
                entry_price = tick['mid'] if tick else 0
            
            account_info = self.get_account_info()
            free_margin = account_info.get('free_margin', 0)
            balance = account_info.get('balance', 1)
            
            # Fixed: Use configured leverage (1:200 = 200), not margin_level percentage
            leverage = CFG.get("leverage", 200)  # Exness default is 1:200
            
            # Correct margin calculation:
            # Margin Required = (Lots * Contract Size * Entry Price) / Leverage
            position_value = proposed_lots * entry_price * EXNESS['contract_size']
            margin_required = position_value / max(1, leverage) if leverage > 0 else position_value
            
            # Add 5% buffer to margin requirement for safety
            margin_required_with_buffer = margin_required * 1.05
            
            available = margin_required_with_buffer < free_margin
            margin_level = (balance / margin_required * 100) if margin_required > 0 else 0
            
            result = {
                'available': available,
                'margin_required': float(margin_required),
                'margin_required_buffered': float(margin_required_with_buffer),
                'margin_free': float(free_margin),
                'margin_level': float(margin_level),
                'leverage': int(leverage),
                'position_value': float(position_value)
            }
            
            if not available:
                LOG.warning(f"[MARGIN] Insufficient: Required ${margin_required:.2f} (buffered: ${margin_required_with_buffer:.2f}), Free ${free_margin:.2f}")
            
            return result
            
        except Exception as e:
            LOG.error(f"[MARGIN] Check failed: {e}")
            return {'available': False, 'margin_required': 0, 'margin_free': 0, 'margin_level': 0, 'error': str(e)}
    
    def update_account_balance(self):
        """Update the config with current balance"""
        if CFG["mode"] == 'live' and self.ensure_connection():
            account_info = self.get_account_info()
            if account_info['balance'] > 0:
                CFG["account_balance"] = account_info['balance']
                LOG.info(f"[BALANCE] Updated to: ${account_info['balance']:.2f} (Equity: ${account_info['equity']:.2f})")
                return account_info['balance'], account_info['equity'], account_info['profit']
        return CFG["account_balance"], CFG["account_balance"], 0.0
    
    def get_all_account_positions(self):
        """Get ALL positions on the account (not just current symbol)"""
        if not self.ensure_connection():
            return []
        try:
            positions = mt5.positions_get() or []
            return positions
        except Exception as e:
            LOG.warning(f"[MT5] Error loading all positions: {e}")
            return []

    def _normalize_ticket(self, ticket):
        if ticket is None:
            return None
        if isinstance(ticket, int):
            return ticket
        try:
            return int(str(ticket).strip())
        except Exception:
            return ticket

    def get_symbol_positions(self, symbol=None):
        """Get positions for specific symbol"""
        if not self.ensure_connection():
            return []
        try:
            if symbol is None:
                symbol = CFG["symbol"]
            positions = mt5.positions_get(symbol=symbol) or []
            return positions
        except Exception as e:
            LOG.warning(f"[MT5] Error loading positions for {symbol}: {e}")
            return []
    
    def get_position_by_ticket(self, ticket):
        """Get specific position by ticket"""
        if not self.ensure_connection():
            return None
        ticket = self._normalize_ticket(ticket)
        try:
            positions = mt5.positions_get(ticket=ticket)
            if positions:
                return positions[0]
        except Exception as e:
            LOG.warning(f"[MT5] Error loading position {ticket}: {e}")

        # Fallback: search all positions manually by normalized ticket or string match
        try:
            positions = mt5.positions_get() or []
            for pos in positions:
                if self._normalize_ticket(getattr(pos, 'ticket', None)) == ticket:
                    return pos
                if str(getattr(pos, 'ticket', '')).strip() == str(ticket).strip():
                    return pos
        except Exception as e:
            LOG.warning(f"[MT5] Fallback position lookup failed for {ticket}: {e}")
        return None

    async def sync_positions(self, store):
        """Sync MT5 positions with local DB. FIX 1: Handle Exness ticket re-assignments (partial closures).
        
        Flow:
        1. Fetch all MT5 positions for symbol
        2. Track any manual positions not in DB
        3. For DB trades missing from MT5: search for matching position to adopt
        4. Only close trade if no matching position found
        """
        if CFG["mode"] != 'live' or not self.ensure_connection():
            return
        await asyncio.sleep(3)
        try:
            positions = mt5.positions_get(symbol=CFG["symbol"]) or []
            if not positions:
                LOG.debug(f"[SYNC] No symbol positions returned for {CFG['symbol']}; checking all account positions")
                positions = [p for p in (mt5.positions_get() or []) if getattr(p, 'symbol', None) == CFG['symbol']]
            pos_map = {p.ticket: p for p in positions}
            db_open = store.open_trades()
            db_tickets = {t.get('ticket') for t in db_open}

            # Step 1: Insert manual positions missing from DB
            for pos in positions:
                if pos.ticket not in db_tickets:
                    trade_data = {
                        'id': f"MAN{uuid.uuid4().hex[:8]}",
                        'sig_id': "MANUAL",
                        'ts': utc_now().isoformat(),
                        'dir': 'BUY' if pos.type == mt5.ORDER_TYPE_BUY else 'SELL',
                        'entry': pos.price_open,
                        'sl': pos.sl or 0.0,
                        'tp': pos.tp or 0.0,
                        'vol': pos.volume,
                        'init_vol': pos.volume,
                        'status': 'open',
                        'ticket': pos.ticket,
                        'correlation_used': 0,
                        'strategy': 'manual',
                        'max_duration_bars': None,
                        'entry_tf': CFG["timeframes"][0],
                        'trail_high': None,
                        'trail_low': None,
                        'trail_level': None
                    }
                    store.insert_trade(trade_data)
                    LOG.info(f"[SYNC] Manual position tracked: Ticket={pos.ticket}, Vol={pos.volume}, Entry={pos.price_open}")

            # Step 2: FIX 1 - Ticket Adoption for Exness Partial Closures
            for trade in db_open:
                ticket = trade.get('ticket')
                trade_id = trade.get('id')
                
                if ticket not in pos_map:
                    positions = mt5.positions_get(symbol=CFG["symbol"]) or []
                    pos_map = {p.ticket: p for p in positions}
                    if ticket in pos_map:
                        continue

                    # Additional safety: check direct ticket lookup before declaring the trade closed.
                    live_pos = self.get_position_by_ticket(ticket)
                    if live_pos is not None:
                        LOG.debug(f"[SYNC] Trade ticket {ticket} still active in MT5 by direct lookup")
                        continue

                    # DB trade ticket not in MT5 - search for matching position
                    trade_dir = 'BUY' if trade['dir'] == 'BUY' else 'SELL'
                    trade_vol = abs(trade.get('vol', trade.get('init_vol', 0.0)))
                    trade_entry = float(trade.get('entry', 0.0))
                    
                    # Search untracked positions: same direction + volume + entry price similarity
                    matching_pos = None
                    for pos in positions:
                        if pos.ticket in db_tickets:
                            continue
                        pos_type = 'BUY' if pos.type == mt5.ORDER_TYPE_BUY else 'SELL'
                        if pos_type != trade_dir:
                            continue

                        vol_diff_pct = abs(pos.volume - trade_vol) / max(trade_vol, 1e-6) * 100
                        price_diff = abs(pos.price_open - trade_entry)
                        price_threshold = max(0.01, abs(trade_entry) * 0.002)

                        if vol_diff_pct < 5 and price_diff <= price_threshold:
                            matching_pos = pos
                            LOG.debug(f"[SYNC] Found matching position: old_ticket={ticket}, new_ticket={pos.ticket}, vol_diff={vol_diff_pct:.1f}%, price_diff={price_diff:.4f}")
                            break

                    if matching_pos:
                        # Ticket adoption: adopt the new ticket instead of closing
                        store.update_trade_ticket(trade_id, matching_pos.ticket)
                        LOG.warning(f"[SYNC] ✓ TICKET ADOPTION: {ticket} → {matching_pos.ticket} (Trade ID={trade_id}) | Exness partial close recovered")
                    else:
                        # No matching live position found - assume trade closed in MT5
                        current = self.current_price()
                        if current:
                            pnl = (current - trade['entry']) if trade['dir'] == 'BUY' else (trade['entry'] - current)
                            r = pnl / max(1e-6, abs(trade['entry'] - trade.get('sl', 0.0)))
                            store.close_trade(trade_id, current, pnl, r)
                            LOG.info(f"[SYNC] Trade closed (ticket {ticket} not in MT5): PnL=${pnl:.2f}, R={r:.2f}x")
        except Exception as e:
            LOG.warning(f"[SYNC] Position sync failed: {e}")
    
    def place_market(self, direction, sl, tp, vol):
        if CFG["mode"] != 'live' or not self.ensure_connection():
            return random.randint(100000, 999999)
        
        try:
            # STAGE-6: direction normalization - never let a malformed direction
            # (e.g. lowercase/None) silently become a SELL order
            direction = normalize_direction(direction)
            if direction not in ('BUY', 'SELL'):
                LOG.error(f"[ORDER] place_market: unrecognized direction, order REFUSED (fail-closed)")
                return 0
            # --- v15.0 Slippage Protection: Check health status ---
            global GLOBAL_SLIPPAGE_PROTECTION
            if GLOBAL_SLIPPAGE_PROTECTION:
                LOG.warning(f"[SLIPPAGE] High latency detected - converting MARKET to LIMIT")
                # Get tick and place limit order instead
                tick = self.get_fresh_tick()
                if not tick:
                    return 0
                if direction == 'BUY':
                    limit_price = tick['ask'] - (CFG.get('limit_offset_pips', 0.5) * 0.0001)
                else:
                    limit_price = tick['bid'] + (CFG.get('limit_offset_pips', 0.5) * 0.0001)
                LOG.info(f"[SLIPPAGE] Placing LIMIT {direction} @ {limit_price:.4f} instead of MARKET")
                return self.place_limit(direction, limit_price, sl, tp, vol)
            
            # Normalize volume
            vol = round(vol, 2)
            
            tick = self.get_fresh_tick()
            if not tick:
                return 0
            
            if direction == 'BUY':
                order_type = mt5.ORDER_TYPE_BUY
                price = tick['ask']
            else:
                order_type = mt5.ORDER_TYPE_SELL
                price = tick['bid']
            
            request = {
                'action': mt5.TRADE_ACTION_DEAL,
                'symbol': CFG["symbol"],
                'volume': vol,
                'type': order_type,
                'price': price,
                'sl': sl,
                'tp': tp,
                'deviation': 20,
                'magic': 237911,
                'comment': 'SentinelV12_1',
                'type_time': mt5.ORDER_TIME_GTC,
                'type_filling': mt5.ORDER_FILLING_IOC
            }
            
            result = mt5.order_send(request)
            order_id = getattr(result, 'order', 0) if result else 0
            LOG.info(f"[ORDER] Market {direction} result: retcode={result.retcode if result else 'None'} order={order_id}")
            
            if result and (order_id > 0 or result.retcode == mt5.TRADE_RETCODE_DONE):
                return order_id
            return 0
            
        except (OSError, RuntimeError, AttributeError) as e:
            LOG.warning(f"Market order placement failed: {e}")
            return 0
        except Exception as e:
            LOG.error(f"Unexpected error placing market order: {type(e).__name__}: {e}")
            return 0
    
