    def smart_order(self, direction, entry, sl, tp, vol, signal_type='normal', signal_id=None, signal_score=None, bars_dict=None, rsi=None, atr=None, fib_zones=None, smc_obos=None):
        """
        SENTINEL UNIVERSAL EXECUTION: Adaptive order placement using UrgencyScore.
        
        v15.0 ENHANCEMENT: Risk Governor integration for equity protection
        
        Replaces simple smart_order logic with intelligent dispatcher that considers:
        - Session (London/NY = higher urgency)
        - RSI/ATR velocity (fast moves = higher urgency)
        - Distance to Fibonacci/SMC zones
        - Urgency Score to decide: MARKET vs LIMIT vs STOP-LIMIT
        - Risk Governor: Max daily drawdown check + ATR-dynamic sizing
        
        Args:
            direction, entry, sl, tp, vol: Order parameters
            signal_type: 'normal', 'breakout', etc.
            signal_id: Signal identifier for tracking
            signal_score: Initial signal score (0-100)
            bars_dict: Dict with OHLCV bars by timeframe
            rsi, atr: Technical indicators
            fib_zones: Fibonacci retracement levels
            smc_obos: SMC Order Block/Supply distance dict
        
        Returns:
            int: Order ticket or 0 if failed
        """
        if CFG["mode"] != 'live' or not self.ensure_connection():
            return random.randint(100000, 999999)
        
        try:
            # === v15.0 RISK GOVERNOR: Check if bot should be in shutdown ===
            global BOT_SHUTDOWN_UNTIL
            if BOT_SHUTDOWN_UNTIL is not None:
                if datetime.now(timezone.utc) < BOT_SHUTDOWN_UNTIL:
                    LOG.warning(f"[RISK] Bot in shutdown until {BOT_SHUTDOWN_UNTIL}. Order rejected.")
                    return 0
                else:
                    BOT_SHUTDOWN_UNTIL = None  # Reset if shutdown window has passed
            
            # Normalize volume
            vol = round(vol, 2)
            
            tick = self.get_fresh_tick()
            if not tick:
                return 0
            
            current = tick['mid']
            spread = tick['spread']
            
            # Detect stale entry price vs fresh market
            price_diff_pct = abs(entry - current) / current if current else 1.0
            
            # If entry price is stale (>1% difference), use market order
            if price_diff_pct > 0.01:
                LOG.warning(f"[SMART] Entry {entry:.4f} too far from market {current:.4f} ({price_diff_pct*100:.2f}%), using market order")
                return self.place_market(direction, sl, tp, vol)
            
            # Handle breakout signal type (use stop order)
            if signal_type == 'breakout':
                if direction == 'BUY' and entry > current:
                    LOG.info(f"[SMART] Breakout BUY above {entry:.4f}, using STOP order")
                    return self.place_stop(direction, entry, sl, tp, vol)
                elif direction == 'SELL' and entry < current:
                    LOG.info(f"[SMART] Breakout SELL below {entry:.4f}, using STOP order")
                    return self.place_stop(direction, entry, sl, tp, vol)
            
            # Use Adaptive Dispatcher if we have complete signal data
            if signal_id and signal_score is not None and bars_dict and rsi is not None and atr is not None:
                dispatcher = AdaptiveDispatcher(mt5_conn=self, session_detector=SESSION_DETECTOR, cfg=CFG)
                
                # Provide defaults for missing technical data
                fib_zones = fib_zones or []
                smc_obos = smc_obos or {'ob_distance': float('inf'), 'os_distance': float('inf')}
                
                ticket = dispatcher.dispatch_order(
                    direction=direction,
                    entry=entry,
                    sl=sl,
                    tp=tp,
                    vol=vol,
                    signal_id=signal_id,
                    signal_score=signal_score,
                    bars_dict=bars_dict,
                    rsi=rsi,
                    atr=atr,
                    fib_zones=fib_zones,
                    smc_obos=smc_obos
                )
                return ticket
            
            # Fallback: Classic smart order logic if not all data available
            offset = CFG.get("limit_offset_pips", 0.5) * 0.01
            
            # Try limit order if conditions are favorable
            if spread < 0.30 and price_diff_pct < 0.003:
                limit_price = entry - offset if direction == 'BUY' else entry + offset
                
                # Validate limit price
                if direction == 'BUY' and limit_price > 0 and limit_price < current:
                    LOG.info(f"[SMART] Favorable spread, using LIMIT ORDER @ {limit_price:.4f}")
                    return self.place_limit(direction, limit_price, sl, tp, vol)
                elif direction == 'SELL' and limit_price > current:
                    LOG.info(f"[SMART] Favorable spread, using LIMIT ORDER @ {limit_price:.4f}")
                    return self.place_limit(direction, limit_price, sl, tp, vol)
            
            # Default: use market order
            LOG.info(f"[SMART] Fallback to MARKET ORDER")
            return self.place_market(direction, sl, tp, vol)
            
        except Exception as e:
            LOG.error(f"[SMART] Order placement error: {e}")
            return 0
    
