    def partial_close(self, ticket, vol, direction):
        if CFG["mode"] != 'live' or not self.ensure_connection():
            return True
        
        try:
            # Normalize volume
            vol = round(vol, 2)
            
            tick = self.get_fresh_tick()
            if not tick:
                return False
            
            if direction == 'BUY':
                order_type = mt5.ORDER_TYPE_SELL
                price = tick['bid']
            else:
                order_type = mt5.ORDER_TYPE_BUY
                price = tick['ask']
            
            request = {
                'action': mt5.TRADE_ACTION_DEAL,
                'position': ticket,
                'symbol': CFG["symbol"],
                'volume': vol,
                'type': order_type,
                'price': price,
                'deviation': 20,
                'magic': 237911,
                'type_time': mt5.ORDER_TIME_GTC,
                'type_filling': mt5.ORDER_FILLING_IOC
            }
            
            result = mt5.order_send(request)
            if result and result.retcode == mt5.TRADE_RETCODE_DONE:
                LOG.info(f"[PARTIAL] Closed {vol} lots of ticket {ticket} at {price:.4f}")
            return result.retcode == mt5.TRADE_RETCODE_DONE if result else False
        except (OSError, RuntimeError, AttributeError) as e:
            LOG.warning(f"Partial close failed: {e}")
            return False
        except Exception as e:
            LOG.error(f"Unexpected error in partial close: {type(e).__name__}: {e}")
            return False
    
    def partial_close_with_tier(self, ticket: int, init_vol: float, entry: float, tp: float, 
                                direction: str, store=None) -> bool:
        """
        Partial close using 50/25/25 tier logic for volumes >= 0.03 lots.
        Tracks tier levels for sequential closes.
        
        Args:
            ticket: Order ticket
            init_vol: Initial volume (for tier calculation)
            entry: Entry price
            tp: Take profit price
            direction: 'BUY' or 'SELL'
            store: Trade store for updating tier status
        
        Returns:
            bool: Success/failure
        """
        if CFG["mode"] != 'live' or not self.ensure_connection():
            return False
        
        try:
            # Create tier manager instance
            tier_mgr = TierExecutionManager()
            
            # Check if volume qualifies
            if not tier_mgr.should_apply_tier_logic(init_vol):
                # Just do regular close
                return self.partial_close(ticket, init_vol, direction)
            
            # Calculate tier volumes and targets
            tier_vols = tier_mgr.calculate_tier_volumes(init_vol)
            tier_tps = tier_mgr.calculate_tier_targets(entry, tp, direction)
            
            LOG.info(f"[TIER-CLOSE] Applying 50/25/25 logic: {tier_mgr.get_tier_info(init_vol)}")
            
            # Close Tier 1 (50% at 50% distance)
            if tier_vols['tier_1'] > 0:
                success_t1 = self.partial_close(ticket, tier_vols['tier_1'], direction)
                LOG.info(f"[TIER] Tier-1 close: {tier_vols['tier_1']} @ {tier_tps['tier_1_tp']:.4f} - {'✓' if success_t1 else '✗'}")
                if store:
                    store.log_tier_close(ticket, 'tier_1', tier_vols['tier_1'], tier_tps['tier_1_tp'])
            
            # Close Tier 2 (25% at 75% distance)
            if tier_vols['tier_2'] > 0:
                success_t2 = self.partial_close(ticket, tier_vols['tier_2'], direction)
                LOG.info(f"[TIER] Tier-2 close: {tier_vols['tier_2']} @ {tier_tps['tier_2_tp']:.4f} - {'✓' if success_t2 else '✗'}")
                if store:
                    store.log_tier_close(ticket, 'tier_2', tier_vols['tier_2'], tier_tps['tier_2_tp'])
            
            # Close Tier 3 (25% at target)
            if tier_vols['tier_3'] > 0:
                success_t3 = self.partial_close(ticket, tier_vols['tier_3'], direction)
                LOG.info(f"[TIER] Tier-3 close: {tier_vols['tier_3']} @ {tier_tps['tier_3_tp']:.4f} - {'✓' if success_t3 else '✗'}")
                if store:
                    store.log_tier_close(ticket, 'tier_3', tier_vols['tier_3'], tier_tps['tier_3_tp'])
            
            return True
            
        except Exception as e:
            LOG.error(f"[TIER-CLOSE] Error: {e}")
            return False
    
