class QuantumFeatureEngineer:
    """Compute expanded feature set with entropy/fractal metrics."""
    def hurst_exponent(self, series):
        if series is None or len(series) < 100:
            return 0.5
        lags = range(2, 20)
        tau = [np.std(np.subtract(series[lag:], series[:-lag])) for lag in lags]
        poly = np.polyfit(np.log(lags), np.log(tau), 1)
        return poly[0] * 2.0

    def shannon_entropy(self, series, bins=20):
        if series is None or len(series) < 30:
            return 0.0
        hist, _ = np.histogram(series, bins=bins, density=True)
        hist = hist[hist > 0]
        return -np.sum(hist * np.log(hist))

    def fractal_dimension(self, series, kmax=5):
        if series is None or len(series) < 50:
            return 1.0
        n = len(series)
        lk = []
        for k in range(1, kmax + 1):
            lm = []
            for m in range(k):
                idx = np.arange(m, n, k)
                if len(idx) < 2:
                    continue
                diffs = np.abs(np.diff(series[idx]))
                lm.append((np.sum(diffs) * (n - 1) / (len(idx) * k)) / k)
            if lm:
                lk.append(np.mean(lm))
        if len(lk) < 2:
            return 1.0
        coeff = np.polyfit(np.log(1.0 / np.arange(1, len(lk) + 1)), np.log(lk), 1)
        return coeff[0]

    def compute_features(self, df):
        d = add_indicators(df)
        if d is None or d.empty:
            return {}
        close = d['close'].values
        return {
            'hurst': safe_float(self.hurst_exponent(close)),
            'entropy': safe_float(self.shannon_entropy(close)),
            'fractal_dim': safe_float(self.fractal_dimension(close))
        }

class SessionDetector:
    """Detect sessions and overlaps."""
    def current_session(self, now=None):
        now = now or utc_now()
        hour = now.hour
        if 8 <= hour < 9:
            return "ASIAN_LONDON"
        if 13 <= hour < 17:
            return "LONDON_NY"
        if 21 <= hour < 22:
            return "NY_CLOSE"
        if 9 <= hour < 17:
            return "LONDON"
        if 17 <= hour < 22:
            return "NY"
        return "ASIAN"

    def session_multiplier(self):
        session = self.current_session()
        return CFG.get("session_multipliers", {}).get(session, 1.0)

    def is_trade_window(self, now=None):
        # Always return True - let market data drive signal generation
        return True

    def is_market_open(self, now=None):
        """Check if XAUUSD market is open. Market closed: weekends + Friday 22:00 UTC - Sunday 22:00 UTC"""
        now = now or utc_now()
        day = now.weekday()  # 0=Monday, 4=Friday, 5=Saturday, 6=Sunday
        hour = now.hour
        
        # Market closed: Saturday (5) and Sunday (6)
        if day in [5, 6]:
            return False
        
        # Market closed: Friday after 22:00 UTC until Sunday 22:00 UTC
        if day == 4 and hour >= 22:  # Friday 22:00+
            return False
        
        # Market closed: Sunday before 22:00 UTC (until market opens)
        if day == 6:  # Sunday
            return False
        
        # Market closed: Monday before 22:00 UTC if previous day was Sunday
        if day == 0 and hour < 22:  # Monday before 22:00
            return False
        
        return True
    
    def market_status(self, now=None):
        """Return human-readable market status"""
        now = now or utc_now()
        day = now.weekday()
        hour = now.hour
        day_names = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
        
        if not self.is_market_open(now):
            if day in [5, 6]:
                return f"CLOSED ({day_names[day]} - Weekend)"
            elif day == 4 and hour >= 22:
                return f"CLOSED (Friday {hour}:00 UTC - Market closes)"
            elif day == 0 and hour < 22:
                return f"CLOSED (Monday {hour}:00 UTC - Market opens at 22:00)"
            else:
                return "CLOSED (Market hours: Mon 22:00 - Fri 22:00 UTC)"
        
        session = self.current_session(now)
        return f"OPEN ({day_names[day]} {hour:02d}:00 UTC - {session})"

class QuantumRegimeDetector:
    """Nine-regime classifier using indicators + session. FIX 4: Volatility Squeeze (VCP) detection."""
    def detect(self, df):
        d = add_indicators(df)
        if d is None or d.empty:
            return "UNKNOWN"
        last = d.iloc[-1]
        adx = calc_adx(d).iloc[-1] if len(d) > 30 else 20
        atr_pct = (last['atr'] / last['close']) * 100
        bb_width = last.get('bb_width', 0.01)
        session = SessionDetector().current_session()

        # FIX 4: Volatility Squeeze (VCP) - ATR(10) / ATR(100) < 0.75
        atr_10 = d['atr'].rolling(window=10).mean().iloc[-1] if len(d) >= 10 else last['atr']
        atr_100 = d['atr'].rolling(window=100).mean().iloc[-1] if len(d) >= 100 else last['atr']
        vcp_ratio = atr_10 / max(atr_100, 1e-6)
        is_squeeze = vcp_ratio < 0.75

        if adx > 30 and atr_pct < 1.5:
            return "HIGH_MOMENTUM_TREND"
        if 25 < adx <= 30 and atr_pct < 2.0:
            return "LOW_MOMENTUM_TREND"
        if adx < 20 and atr_pct < 1.0 and bb_width < 0.01:
            return "LOW_VOL_RANGE"
        if adx < 20 and atr_pct >= 1.0:
            return "HIGH_VOL_RANGE"
        if bb_width < 0.008:
            return "COMPRESSION"
        if bb_width > 0.02:
            return "EXPANSION"
        if session == "LONDON_NY":
            return "SESSION_TRANSITION"
        if atr_pct > 2.5:
            return "NEWS_VOLATILITY"
        if is_squeeze:  # FIX 4: Add VCP squeeze to regime detection
            return "VOLATILITY_SQUEEZE"
        return "REVERSAL_PATTERNS"
    
    def get_strategy_weights(self, regime):
        """FIX 4: Return dynamic strategy weights based on regime (VCP adjustments)."""
        base_weights = CFG.get("strategy_weights", {})
        
        if regime == "VOLATILITY_SQUEEZE":
            # During squeeze: prioritize breakout (0.6) and reduce mean reversion (0.1)
            return {
                'BreakoutStrategy': 0.6,
                'MeanReversion': 0.1,
                'Momentum': 0.2,
                'CarryTrade': 0.1
            }
        return base_weights
