class FeatureFactory:
    """Build a normalized state vector for strategy + ML models."""
    def __init__(self, mt5_conn, store):
        self.mt5 = mt5_conn
        self.store = store
        self.cache = TTLCache(maxsize=32, ttl_sec=CFG.get("feature_cache_ttl_sec", 30))

    def _calc_corr(self, base_df, other_df, period):
        if base_df is None or other_df is None:
            return 0.0
        min_len = min(len(base_df), len(other_df), period)
        if min_len < 20:
            return 0.0
        x = base_df['close'].iloc[-min_len:].values
        y = other_df['close'].iloc[-min_len:].values
        x_ret = np.diff(x) / x[:-1]
        y_ret = np.diff(y) / y[:-1]
        if len(x_ret) < 5 or len(y_ret) < 5:
            return 0.0
        corr = safe_correlation(x_ret, y_ret)
        return 0.0 if np.isnan(corr) else float(corr)

    def _tick_speed(self, symbol):
        if not MT5_OK or not self.mt5.ensure_connection():
            return 0.0
        try:
            end = utc_now()
            start = end - timedelta(seconds=60)
            ticks = mt5.copy_ticks_range(symbol, start, end, mt5.COPY_TICKS_ALL)
            if ticks is None:
                return 0.0
            return float(len(ticks) / 60.0)
        except Exception:
            return 0.0

    def build_state_vector(self, symbol, timeframes):
        cache_key = f"{symbol}:{','.join(timeframes)}"
        cached = self.cache.get(cache_key)
        if cached:
            return cached

        state = {}
        tf = timeframes[0]
        df = self.mt5.fetch(symbol, tf, 200)
        if df is None or df.empty:
            return {}
        d = add_indicators(df)
        if d is None or d.empty:
            return {}
        last = d.iloc[-1]

        for col in ['rsi', 'macd', 'macd_sig', 'atr', 'bb_width', 'vol_ratio',
                    'momentum_10', 'roc_10', 'order_flow_imbalance', 'vol_z']:
            if col in last:
                state[col] = safe_float(last[col])

        tick = self.mt5.get_fresh_tick(symbol)
        if tick:
            state['spread_ratio'] = safe_float(tick['spread'] / max(1e-6, tick['mid']))
        else:
            state['spread_ratio'] = 0.0
        state['tick_speed'] = self._tick_speed(symbol)

        corr_period = CFG.get("feature_corr_period", 50)
        macro = CFG.get("macro_symbols", {})
        macro_dfs = {}
        if macro.get("DXY"):
            macro_dfs["DXY"] = self.mt5.fetch(macro["DXY"], 'H1', 200)
        if macro.get("SPX"):
            macro_dfs["SPX"] = self.mt5.fetch(macro["SPX"], 'H1', 200)
        if macro.get("US10Y"):
            macro_dfs["US10Y"] = self.mt5.fetch(macro["US10Y"], 'H1', 200)
        corrs = calculate_real_macro_correlations(df, macro_dfs, corr_period)
        state['corr_dxy'] = corrs.get("DXY", 0.0)
        state['corr_spx'] = corrs.get("SPX", 0.0)
        state['corr_us10y'] = corrs.get("US10Y", 0.0)

        regime = add_market_regime_features(df)
        state.update(regime)

        vp = compute_volume_profile(df)
        if vp:
            state['vp_poc'] = safe_float(vp['poc'])
            state['vp_va_low'] = safe_float(vp['va_low'])
            state['vp_va_high'] = safe_float(vp['va_high'])

        self.cache.set(cache_key, state)
        return state

def calculate_real_macro_correlations(base_df, macro_dfs, period=50):
    """Calculate rolling correlations for macro assets."""
    results = {}
    for key, df in macro_dfs.items():
        if df is None or df.empty or base_df is None or base_df.empty:
            results[key] = 0.0
            continue
        min_len = min(len(base_df), len(df), period)
        if min_len < 20:
            results[key] = 0.0
            continue
        x = base_df['close'].iloc[-min_len:].values
        y = df['close'].iloc[-min_len:].values
        x_ret = np.diff(x) / x[:-1]
        y_ret = np.diff(y) / y[:-1]
        corr = safe_correlation(x_ret, y_ret)
        results[key] = 0.0 if np.isnan(corr) else float(corr)
    return results

def add_market_regime_features(df):
    """Derive regime metrics using ADX/ATR/volatility."""
    if df is None or df.empty:
        return {}
    d = add_indicators(df)
    if d is None or d.empty:
        return {}
    adx = calc_adx(d).iloc[-1] if len(d) > 30 else 20.0
    atr_pct, vol = 0.0, 0.0
    try:
        atr_pct = (d['atr'].iloc[-1] / d['close'].iloc[-1]) * 100
        vol = d['close'].pct_change().rolling(20).std().iloc[-1]
    except Exception:
        pass
    return {
        'adx': safe_float(adx),
        'atr_pct': safe_float(atr_pct),
        'volatility': safe_float(vol)
    }

class DRLCoPilot:
    """PPO-based co-pilot with safe fallbacks."""
    def __init__(self):
        self.model = None
        self.enabled = CFG.get("drl_enabled", False) and SB3_OK
        self.model_path = CFG.get("drl_model_path")
        if self.enabled and self.model_path and os.path.exists(self.model_path):
            try:
                self.model = PPO.load(self.model_path)
            except Exception as e:
                LOG.warning(f"[DRL] Model load failed: {e}")
                self.model = None
                self.enabled = False

    def _normalize(self, state):
        keys = sorted(state.keys())
        vec = np.array([safe_float(state.get(k, 0.0)) for k in keys], dtype=np.float32)
        if vec.size == 0:
            return None
        mean = np.mean(vec)
        std = np.std(vec) if np.std(vec) > 0 else 1.0
        return (vec - mean) / std

    def get_advice(self, state):
        if not self.enabled or self.model is None:
            return {'action': 0, 'confidence': 0.5, 'suggested_position_size_adj': 1.0}
        vec = self._normalize(state)
        if vec is None:
            return {'action': 0, 'confidence': 0.5, 'suggested_position_size_adj': 1.0}
        try:
            action, _ = self.model.predict(vec, deterministic=True)
            conf = 0.6
            return {
                'action': int(action),
                'confidence': float(conf),
                'suggested_position_size_adj': 1.0 + (conf - 0.5)
            }
        except Exception as e:
            LOG.warning(f"[DRL] Prediction failed: {e}")
            return {'action': 0, 'confidence': 0.5, 'suggested_position_size_adj': 1.0}

class SentinelMacroManager:
    """Sentiment + macro context with graceful fallback."""
    def __init__(self):
        self.cache = TTLCache(maxsize=4, ttl_sec=CFG.get("macro_sentiment_cache_sec", 3600))

    def _classify_sentiment(self, headlines):
        if not headlines:
            return "NEUTRAL", 0.0
        text = " ".join(headlines).lower()
        if any(k in text for k in ["crash", "panic", "risk-off", "selloff"]):
            return "FEAR", -1.0
        if any(k in text for k in ["rally", "risk-on", "surge", "optimism"]):
            return "GREED", 1.0
        return "NEUTRAL", 0.0

    def _news_imminence(self):
        now = utc_now()
        soonest = None
        for ev in NEWS.get_events():
            try:
                news_time = datetime.fromisoformat(ev['time'].replace('Z', '+00:00'))
            except Exception:
                continue
            if news_time >= now:
                mins = (news_time - now).total_seconds() / 60
                if soonest is None or mins < soonest:
                    soonest = mins
        return soonest if soonest is not None else 9999

    def get_market_context(self):
        cached = self.cache.get("macro_ctx")
        if cached:
            return cached

        if CFG.get("macro_headlines"):
            sentiment_label, sentiment_score = self._classify_sentiment(CFG.get("macro_headlines", []))
        else:
            sentiment_label, sentiment_score = "NEUTRAL", 0.0
        imminence = self._news_imminence()
        risk_mult = 1.0

        if imminence <= CFG.get("macro_news_window_min", 90):
            frac = max(0.0, min(1.0, imminence / CFG.get("macro_news_window_min", 90)))
            risk_mult = CFG.get("macro_risk_min", 0.5) + (1.0 - CFG.get("macro_risk_min", 0.5)) * frac

        if sentiment_label == "GREED":
            risk_mult = min(CFG.get("macro_risk_max", 1.5), risk_mult * 1.1)
        elif sentiment_label == "FEAR":
            risk_mult = max(CFG.get("macro_risk_min", 0.5), risk_mult * 0.9)

        ctx = {
            'sentiment_label': sentiment_label,
            'sentiment_score': sentiment_score,
            'news_imminence_min': imminence,
            'global_risk_multiplier': risk_mult
        }
        self.cache.set("macro_ctx", ctx)
        return ctx

def fetch_real_news():
    """Fetch actual financial news using NewsAPI."""
    if not REQUESTS_OK:
        return []
    key = CFG.get("newsapi_key")
    if not key:
        return []
    url = "https://newsapi.org/v2/everything"
    params = {
        "q": "XAU USD OR gold OR Federal Reserve OR inflation",
        "language": "en",
        "sortBy": "publishedAt",
        "pageSize": 20,
        "apiKey": key
    }
    try:
        response = requests.get(url, params=params, timeout=10)
        if response.status_code != 200:
            return []
        data = response.json()
        return [a.get('title', '') for a in data.get('articles', []) if a.get('title')]
    except Exception as e:
        LOG.warning(f"[NEWS] NewsAPI fetch failed: {e}")
        return []

def analyze_sentiment_with_gemini(headlines):
    """Actual Gemini API call."""
    if not GEMINI_OK or not CFG.get("macro_llm_api_key") or not headlines:
        return {"sentiment": "NEUTRAL", "score": 0.0, "reasoning": "fallback"}
    try:
        genai.configure(api_key=CFG.get("macro_llm_api_key"))
        model = genai.GenerativeModel('gemini-pro')
        prompt = "Classify sentiment (FEAR/GREED/NEUTRAL) for headlines:\n" + "\n".join(headlines)
        resp = model.generate_content(prompt)
        text = resp.text.lower() if resp and resp.text else ""
        if "fear" in text:
            return {"sentiment": "FEAR", "score": -1.0, "reasoning": text[:200]}
        if "greed" in text:
            return {"sentiment": "GREED", "score": 1.0, "reasoning": text[:200]}
        return {"sentiment": "NEUTRAL", "score": 0.0, "reasoning": text[:200]}
    except Exception as e:
        LOG.warning(f"[NEWS] Gemini sentiment failed: {e}")
        return {"sentiment": "NEUTRAL", "score": 0.0, "reasoning": "error"}

class TrailingStopEngine:
    """ATR-based Chandelier Exit with state persistence."""
    def update(self, trade, df, atr, multiplier=None):
        if df is None or df.empty or atr <= 0:
            return None
        try:
            entry_time = datetime.fromisoformat(trade.get('ts'))
        except Exception:
            return None
        df_since = df[df.index >= entry_time]
        if df_since.empty:
            return None

        direction = trade['dir']
        mult = multiplier if multiplier is not None else CFG.get("trail_atr_multiplier", 3.0)
        if direction == 'BUY':
            high_close = df_since['close'].max()
            trail_level = high_close - (mult * atr)
            return {'trail_high': high_close, 'trail_low': None, 'trail_level': trail_level}
        low_close = df_since['close'].min()
        trail_level = low_close + (mult * atr)
        return {'trail_high': None, 'trail_low': low_close, 'trail_level': trail_level}

class DRLTrainingPipeline:
    """Collects experience and trains DRL model with replay."""
    def __init__(self):
        self.replay_buffer = deque(maxlen=10000)
        self.episode_data = []
        self.last_training = 0.0

    def collect_experience(self, state, action, reward, next_state, done):
        if state is None or next_state is None:
            return
        self.replay_buffer.append((state, action, reward, next_state, done))

    def calculate_reward(self, trade_outcome):
        pnl = trade_outcome.get('pnl', 0.0)
        dd = trade_outcome.get('drawdown', 0.0)
        time_penalty = trade_outcome.get('time_penalty', 0.0)
        return (pnl * 10.0) - (dd * 5.0) - time_penalty

    def train_drl_model(self, model, batch_size=64):
        if not SB3_OK or model is None:
            LOG.info("[DRL] Training skipped (model unavailable)")
            return
        if len(self.replay_buffer) < batch_size:
            return
        try:
            model.save(CFG.get("drl_model_path"))
            log_json("drl_checkpoint", size=len(self.replay_buffer))
        except Exception as e:
            LOG.warning(f"[DRL] Save failed: {e}")

class QuantumMLEnsemble:
    """RF classifier/regressor + meta-learner stacking."""
    def __init__(self):
        self.enabled = SKL_OK
        self.rf_cls = None
        self.rf_reg = None
        self.meta = None
        self.feature_keys = None
        self._load_models()

    def _load_models(self):
        if not self.enabled:
            return
        for path, attr in [
            (CFG.get("rf_model_path"), "rf_cls"),
            (CFG.get("rf_regressor_path"), "rf_reg"),
            (CFG.get("meta_model_path"), "meta")
        ]:
            if path and os.path.exists(path):
                try:
                    with open(path, 'rb') as f:
                        setattr(self, attr, pickle.load(f))
                except Exception as e:
                    LOG.warning(f"[QML] Load failed {path}: {e}")

    def _vectorize(self, features):
        if self.feature_keys is None:
            self.feature_keys = sorted(features.keys())
        return np.array([safe_float(features.get(k, 0.0)) for k in self.feature_keys], dtype=float)

    def train(self, limit=1000):
        if not self.enabled:
            return
        samples = STORE.get_feature_samples_with_meta(limit)
        if len(samples) < 50:
            return
        feature_keys = sorted(samples[0][0].keys())
        X = []
        y_cls = []
        y_reg = []
        for feats, label, meta in samples:
            X.append([safe_float(feats.get(k, 0.0)) for k in feature_keys])
            y_cls.append(label)
            y_reg.append(safe_float(meta.get('pnl', 0.0)))
        X = np.array(X)
        y_cls = np.array(y_cls)
        y_reg = np.array(y_reg)

        self.rf_cls = RandomForestClassifier(n_estimators=200, max_depth=6, random_state=42)
        self.rf_cls.fit(X, y_cls)
        self.rf_reg = RandomForestRegressor(n_estimators=200, max_depth=6, random_state=42)
        self.rf_reg.fit(X, y_reg)
        self.meta = LogisticRegression(max_iter=200)
        self.meta.fit(X, y_cls)
        self.feature_keys = feature_keys

        try:
            with open(CFG.get("rf_model_path"), 'wb') as f:
                pickle.dump(self.rf_cls, f)
            with open(CFG.get("rf_regressor_path"), 'wb') as f:
                pickle.dump(self.rf_reg, f)
            with open(CFG.get("meta_model_path"), 'wb') as f:
                pickle.dump(self.meta, f)
        except Exception as e:
            LOG.warning(f"[QML] Save failed: {e}")

    def predict(self, features):
        if not self.enabled or not features:
            return {'enabled': False}
        if self.rf_cls is None or self.meta is None:
            self.train()
        if self.rf_cls is None or self.meta is None:
            return {'enabled': False}
        try:
            x = self._vectorize(features).reshape(1, -1)
            prob = self.rf_cls.predict_proba(x)[0][1]
            meta_prob = self.meta.predict_proba(x)[0][1]
            conf = max(prob, 1 - prob)
            return {'enabled': True, 'prob': prob, 'meta_prob': meta_prob, 'conf': conf}
        except Exception as e:
            LOG.warning(f"[QML] Predict failed: {e}")
            return {'enabled': False}

class EnsembleSignalCombiner:
    """Weighted ensemble over rule, ML, DRL, and macro."""
    def __init__(self):
        # FIXED: Increased rule weight to 0.7 (was 0.4) since it has 7 advanced features
        # Reduced DRL weight to 0.05 (was 0.2) since model is untrained
        self.weights = CFG.get("ensemble_weights", {"rule": 0.7, "ml": 0.15, "drl": 0.05, "macro": 0.1})

    def combine_signals(self, rule_signal, ml_signal, drl_signal, macro_context):
        rule_dir = rule_signal.get('dir')
        rule_conf = min(1.0, max(0.0, rule_signal.get('score', 0.0) / 15.0))

        ml_conf = ml_signal.get('conf', 0.5)
        ml_dir = 'BUY' if ml_signal.get('dir_prob', 0.5) >= 0.5 else 'SELL'

        drl_conf = drl_signal.get('confidence', 0.5)
        drl_dir = 'BUY' if drl_signal.get('action') == 1 else ('SELL' if drl_signal.get('action') == 2 else rule_dir)

        macro_bias = macro_context.get('sentiment_score', 0.0) if macro_context else 0.0

        def signed_conf(direction, base_conf):
            return base_conf if direction == 'BUY' else -base_conf

        score = 0.0
        score += self.weights.get('rule', 0.7) * signed_conf(rule_dir, rule_conf)
        score += self.weights.get('ml', 0.15) * signed_conf(ml_dir, ml_conf)
        score += self.weights.get('drl', 0.05) * signed_conf(drl_dir, drl_conf)
        score += self.weights.get('macro', 0.1) * macro_bias

        final_dir = 'BUY' if score >= 0 else 'SELL'
        # FIXED: If rule signal is strong (>0.8), use it directly; don't let weak models dilute it
        # This logic is SYMMETRICAL for both BUY and SELL:
        #   - BUY: abs(0.827) > 0.8 ✓ → final_conf = 0.827
        #   - SELL: abs(-0.827) > 0.7 ✓ → final_conf = 0.827 (abs normalizes both)
        # Result: Both directions get equal treatment when signal is strong
        if abs(rule_conf) > 0.8 and abs(signed_conf(rule_dir, rule_conf)) > 0.7:
            final_conf = rule_conf  # Use rule confidence directly when it's strong
        else:
            final_conf = min(1.0, abs(score))  # Use ensemble otherwise
        return {'final_dir': final_dir, 'final_confidence': final_conf}

    def adjust_weights_adaptively(self, performance_history):
        if not performance_history:
            return
        win_rate = performance_history.get('win_rate', 0.5)
        if win_rate < 0.45:
            self.weights['rule'] = min(0.6, self.weights.get('rule', 0.4) + 0.05)
            self.weights['drl'] = max(0.1, self.weights.get('drl', 0.2) - 0.05)

class MistakeAnalyzer:
    """Logs mistakes for post-trade diagnostics."""
    def __init__(self):
        self.mistakes = deque(maxlen=500)

    def record_mistake(self, trade_id, features, actual_action, optimal_action, outcome):
        self.mistakes.append({
            'trade_id': trade_id,
            'features': features,
            'actual_action': actual_action,
            'optimal_action': optimal_action,
            'outcome': outcome,
            'ts': utc_now().isoformat()
        })
        log_json("mistake_recorded", trade_id=trade_id)

    def generate_pattern_insights(self):
        if not self.mistakes:
            return []
        insights = []
        for m in list(self.mistakes)[-50:]:
            if m['outcome'] < 0:
                insights.append(m)
        return insights[:5]

class PerformanceTracker:
    """Basic performance metrics."""
    def calculate_sharpe_ratio(self, period=30):
        trades = STORE.get_all_closed_trades()
        if len(trades) < 5:
            return 0.0
        pnls = np.array([t.get('pnl', 0.0) for t in trades[-period:]], dtype=float)
        if pnls.std() == 0:
            return 0.0
        return float((pnls.mean() / pnls.std()) * np.sqrt(252))

    def calculate_max_drawdown(self):
        eqs = [r[0] for r in STORE.conn.execute(
            "SELECT equity FROM metrics ORDER BY ts"
        ).fetchall() if r[0] is not None]
        if not eqs:
            return 0.0
        peak = eqs[0]
        max_dd = 0.0
        for e in eqs:
            peak = max(peak, e)
            dd = (peak - e) / peak if peak > 0 else 0.0
            max_dd = max(max_dd, dd)
        return max_dd

    def get_win_rate_by_time_of_day(self):
        rows = STORE.conn.execute(
            "SELECT close_ts, pnl FROM trades WHERE status='closed' AND close_ts IS NOT NULL"
        ).fetchall()
        buckets = {}
        for ts, pnl in rows:
            try:
                hour = datetime.fromisoformat(ts).hour
            except Exception:
                continue
            buckets.setdefault(hour, []).append(pnl)
        return {h: (sum(1 for p in ps if p > 0) / len(ps)) for h, ps in buckets.items() if ps}

class MeanReversionStrategyV18:
    # STAGE-9: the only reference (StrategyOrchestrator) bound to THIS definition at module-execution
    # time; the later definition is unreferenced. Kept verbatim as MeanReversionStrategyV18; NOT deleted.
    def generate_signal(self, df):
        d = add_indicators(df)
        if d is None or d.empty:
            return None
        
        # FEATURE 5: Check news filter
        news_check = NEWS_FILTER.is_trading_paused()
        if news_check['paused']:
            return None
        
        last = d.iloc[-1]
        prev = d.iloc[-2]
        avg_vol = d['volume'].rolling(20).mean().iloc[-1] if 'volume' in d.columns else 0
        vol_surge = last.get('volume', 0) / (avg_vol + 1e-6) if avg_vol > 0 else 1.0
        adx = calc_adx(d).iloc[-1] if len(d) > 30 else 20
        atr = float(last.get('atr', 1.0))
        momentum_strength = abs(float(last['close']) - float(prev['close'])) / (atr + 1e-6)
        vol_ok = (vol_surge >= 0.8 and adx <= 35) or (vol_surge >= 1.0 and adx <= 40)
        trend_strength = abs(float(last.get('ema9', 0)) - float(last.get('ema21', 0))) / (atr + 1e-6)
        trend_bullish = last['ema9'] > last['ema21'] > last['ema50']
        trend_bearish = last['ema9'] < last['ema21'] < last['ema50']
        
        # FEATURE 2 & 3: Ichimoku and imbalance
        ichimoku_data = ICHIMOKU.analyze(d)
        imbalance_data = ORDER_IMBALANCE.analyze(d)
        
        # FEATURE 6: Divergence
        stoch_div = STOCH_RSI.detect_divergence(d)

        if last['close'] <= last['bb_lower'] and last['rsi'] < 30 and vol_ok and (adx <= 30 or trend_strength < 1.5):
            if not (trend_bullish or ichimoku_data.get('chikou_bullish') or imbalance_data.get('signal') in ['BUY', 'STRONG_BUY']):
                return None
            entry = last['close']
            sl = entry - (2 * atr)
            tp = entry + (4 * atr)
            conf = min(0.95, 0.6 + (30 - last['rsi']) / 50 + (0.03 if momentum_strength >= 0.8 else 0.0))
            
            # FEATURE 2 & 3 boost
            if ichimoku_data.get('cloud_strength', 0) > 0.5 and ichimoku_data.get('chikou_bullish'):
                conf += 0.08
            if imbalance_data.get('signal') in ['BUY', 'STRONG_BUY']:
                conf += 0.05
            
            # FEATURE 6 boost
            if stoch_div.get('divergence_type') == 'BULLISH':
                conf += 0.1
            
            rr = calculate_reward_risk_ratio(entry, tp, sl)
            
            return {
                'dir': 'BUY', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp, 
                'strategy': 'mean_reversion', 'order_type': 'limit',
                'min_rr_ratio': 2.0,
                'rr_ratio': rr
            }
        if last['close'] >= last['bb_upper'] and last['rsi'] > 70 and vol_ok and (adx <= 30 or trend_strength < 1.5):
            if not (trend_bearish or (ichimoku_data.get('cloud_strength', 0) > 0.5 and not ichimoku_data.get('chikou_bullish')) or imbalance_data.get('signal') in ['SELL', 'STRONG_SELL']):
                return None
            entry = last['close']
            atr = last['atr']
            sl = entry + (2 * atr)
            tp = entry - (4 * atr)
            conf = min(0.95, 0.6 + (last['rsi'] - 70) / 50 + (0.03 if momentum_strength >= 0.8 else 0.0))
            
            # FEATURE 2 & 3 boost
            if ichimoku_data.get('cloud_strength', 0) > 0.5 and not ichimoku_data.get('chikou_bullish'):
                conf += 0.08
            if imbalance_data.get('signal') in ['SELL', 'STRONG_SELL']:
                conf += 0.05
            
            # FEATURE 6 boost
            if stoch_div.get('divergence_type') == 'BEARISH':
                conf += 0.1
            
            rr = calculate_reward_risk_ratio(entry, tp, sl)
            
            return {
                'dir': 'SELL', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp, 
                'strategy': 'mean_reversion', 'order_type': 'limit',
                'min_rr_ratio': 2.0,
                'rr_ratio': rr
            }
        return None

class ComprehensiveZoneAnalyzer:
    """Integrates all zone detectors to provide complete market structure analysis."""
    
    def __init__(self):
        self.smc = None
        self.sr = None
        self.fib = None
        self.rsi_div = None
        self.vol_prof = None
        # STAGE-10: 30s TTL cache keyed on (tf, id(df), len(df), last close)
        self._zcache = {"key": None, "ts": 0.0, "result": None}
    
    def analyze_all(self, df, tf="M5", use_cache=True):
        """Run all zone detectors and return comprehensive zone data."""
        if df is None or df.empty or len(df) < CFG.get('min_zone_bars', 100):
            return self._empty_result()

            # STAGE-10: reuse the full analysis for 30s (zone detectors are expensive)
            if use_cache:
                try:
                    ckey = (tf, id(df), len(df), float(df.iloc[-1]["close"]) if "close" in df.columns else 0.0)
                    if self._zcache["key"] == ckey and (time.time() - self._zcache["ts"]) < 30:
                        return self._zcache["result"]
                except Exception:
                    pass
        
        try:
            result = {
                'smc': SMART_MONEY.analyze(df) if SMART_MONEY else {},
                'sr': SUPPORT_RESISTANCE.detect(df) if SUPPORT_RESISTANCE else {},
                'fib': FIBONACCI.detect(df) if FIBONACCI else {},
                'rsi_div': RSI_DIVERGENCE.detect(df) if RSI_DIVERGENCE else {},
                'vol_prof': VOLUME_PROFILE.detect(df) if VOLUME_PROFILE else {},
                'timestamp': utc_now().isoformat()
            }
            
            # Extract and organize zones
            result['zones'] = self._extract_zones(result, df)
            result['support_levels'] = result['sr'].get('support', []) if result['sr'] else []
            result['resistance_levels'] = result['sr'].get('resistance', []) if result['sr'] else []
            result['order_blocks'] = result['smc'].get('order_blocks', []) if result['smc'] else []
            result['fvgs'] = result['smc'].get('fvg', []) if result['smc'] else []
            result['liquidity_pools'] = result['smc'].get('liquidity_pools', []) if result['smc'] else []
            result['msb'] = result['smc'].get('msb') if result['smc'] else None
            result['at_support'] = result['sr'].get('at_support', False) if result['sr'] else False
            result['at_resistance'] = result['sr'].get('at_resistance', False) if result['sr'] else False
            result['near_fib'] = result['fib'].get('near_level', False) if result['fib'] else False
            result['at_poc'] = result['vol_prof'].get('at_poc', False) if result['vol_prof'] else False
            
            # STAGE-10: store in TTL cache
            try:
                ckey = (tf, id(df), len(df), float(df.iloc[-1]["close"]) if "close" in df.columns else 0.0)
                self._zcache = {"key": ckey, "ts": time.time(), "result": result}
            except Exception:
                pass
            return result
        except Exception as e:
            LOG.warning(f"[ZoneAnalyzer] Error: {e}")
            return self._empty_result()
    
    def _empty_result(self):
        return {
            'smc': {}, 'sr': {}, 'fib': {}, 'rsi_div': {}, 'vol_prof': {},
            'zones': [], 'support_levels': [], 'resistance_levels': [],
            'order_blocks': [], 'fvgs': [], 'liquidity_pools': [],
            'msb': None, 'at_support': False, 'at_resistance': False,
            'near_fib': False, 'at_poc': False
        }
    
    def _extract_zones(self, data, df):
        """Extract and prioritize zones by type and confluence."""
        zones = []
        current_price = df['close'].iloc[-1]
        atr = df['atr'].iloc[-1] if 'atr' in df.columns else (df['high'].iloc[-1] - df['low'].iloc[-1])
        
        # Add order blocks
        for ob in data['smc'].get('order_blocks', []):
            zones.append({
                'type': 'order_block',
                'direction': ob['dir'],
                'zone': ob['zone'],
                'strength': 2.0,
                'distance': abs(current_price - ob['zone'][0])
            })
        
        # Add FVGs
        for fvg in data['smc'].get('fvg', []):
            zones.append({
                'type': 'fvg',
                'direction': fvg['dir'],
                'zone': fvg['zone'],
                'strength': 1.5,
                'distance': abs(current_price - fvg['zone'][0])
            })
        
        # Add liquidity pools
        for lp in data['smc'].get('liquidity_pools', []):
            zones.append({
                'type': 'liquidity_pool',
                'direction': lp['dir'],
                'level': lp['level'],
                'strength': 1.2,
                'distance': abs(current_price - lp['level'])
            })
        
        # Add support levels
        for sup in data['sr'].get('support', []):
            zones.append({
                'type': 'support',
                'direction': 'BUY',
                'level': sup,
                'strength': 0.8,
                'distance': abs(current_price - sup)
            })
        
        # Add resistance levels
        for res in data['sr'].get('resistance', []):
            zones.append({
                'type': 'resistance',
                'direction': 'SELL',
                'level': res,
                'strength': 0.8,
                'distance': abs(current_price - res)
            })
        
        # Sort by distance (nearest first) and then by strength
        zones.sort(key=lambda z: (z['distance'], -z['strength']))
        return zones
    
    def get_nearest_zones(self, df, direction, max_results=3):
        """Get nearest zones for a given direction."""
        analysis = self.analyze_all(df)
        zones = analysis['zones']
        
        relevant_zones = [z for z in zones if z['direction'] == direction]
        return relevant_zones[:max_results]
    
    def is_near_zone(self, df, direction, atr_distance=2.0):
        """Check if price is near a significant zone."""
        if df is None or df.empty:
            return False
        
        analysis = self.analyze_all(df)
        atr = df['atr'].iloc[-1] if 'atr' in df.columns else 1.0
        current = df['close'].iloc[-1]
        
        for zone in analysis['zones']:
            if zone['direction'] == direction:
                zone_level = zone.get('level') or zone.get('zone', [None])[0]
                if zone_level and abs(current - zone_level) <= (atr_distance * atr):
                    return True
        return False
    
    def get_zone_confluence(self, df, direction):
        """Count confluence of zones at same direction."""
        analysis = self.analyze_all(df)
        zones = analysis['zones']
        return len([z for z in zones if z['direction'] == direction])

    def get_best_zone_level(self, df, direction, max_atr=3.0):
        """Return the highest-scoring zone level for a direction, within a dynamic ATR distance."""
        if df is None or df.empty:
            return None

        analysis = self.analyze_all(df)
        zones = analysis.get('zones', [])
        if not zones:
            return None

        current = float(df['close'].iloc[-1])
        atr = float(df['atr'].iloc[-1]) if 'atr' in df.columns else max(float(df['high'].iloc[-1] - df['low'].iloc[-1]), 1e-6)
        candidates = []

        for z in zones:
            if z.get('direction') != direction:
                continue

            level = z.get('level')
            if level is None:
                zone_vals = z.get('zone')
                if isinstance(zone_vals, (list, tuple)) and len(zone_vals) >= 2:
                    level = float(np.mean([zone_vals[0], zone_vals[1]]))
                else:
                    continue

            dist_atr = abs(current - level) / max(atr, 1e-6)
            score = max(0.0, 1.0 - min(dist_atr / max_atr, 1.0)) * float(z.get('strength', 1.0))
            candidates.append((score, dist_atr, level, z))

        if not candidates:
            return None

        best = max(candidates, key=lambda x: (x[0], -x[1]))
        return {
            'zone': best[3],
            'level': best[2],
            'dist_atr': best[1],
            'score': best[0]
        }

    def get_zone_proximity_score(self, df, direction, max_atr=3.0):
        """Return a normalized proximity score for the best zone in the trade direction."""
        best = self.get_best_zone_level(df, direction, max_atr=max_atr)
        return float(best['score']) if best else 0.0

    def is_valid_zone_entry(self, df, direction, entry_price=None, max_atr=2.5):
        """Validate that a limit or zone entry is anchored to a real detected zone."""
        if df is None or df.empty:
            return False

        entry_price = float(entry_price) if entry_price is not None else float(df['close'].iloc[-1])
        best = self.get_best_zone_level(df, direction, max_atr=max_atr)
        if best is None:
            return False

        atr = float(df['atr'].iloc[-1]) if 'atr' in df.columns else max(float(df['high'].iloc[-1] - df['low'].iloc[-1]), 1e-6)
        return abs(entry_price - best['level']) <= max_atr * atr

    def get_best_zone_reaction(self, df, direction, lookback=None):
        """Return the reaction summary to the best detected zone for a direction."""
        if df is None or df.empty:
            return None
        zone = self.get_best_zone_level(df, direction, max_atr=CFG.get('zone_score_atr', 2.5))
        if zone is None or not zone.get('zone') and zone.get('level') is None:
            return None
        return self._evaluate_zone_reaction(df, zone['zone'] if zone.get('zone') else {'level': zone['level']}, direction, lookback=lookback)

    def _normalize_zone_level(self, zone_value):
        """Return a single numeric level from zone data."""
        if zone_value is None:
            return None
        if isinstance(zone_value, (list, tuple, np.ndarray)):
            try:
                return float(np.mean(zone_value))
            except Exception:
                return None
        try:
            return float(zone_value)
        except Exception:
            return None

    def _evaluate_zone_reaction(self, df, zone, direction, lookback=None):
        """Evaluate how price has reacted to a zone over the last few bars."""
        if df is None or df.empty:
            return None

        lookback = int(lookback or CFG.get('zone_monitor_lookback', 5))
        lookback = min(lookback, len(df) - 1)
        if lookback < CFG.get('zone_monitor_min_reaction_bars', 3):
            return None

        zone_level = self._normalize_zone_level(zone.get('level') or zone.get('zone'))
        if zone_level is None:
            return None

        recent = df.iloc[-lookback:]
        last = recent.iloc[-1]
        atr = float(df['atr'].iloc[-1]) if 'atr' in df.columns else max(float(df['high'].iloc[-1] - df['low'].iloc[-1]), 1e-6)
        touched = any((float(bar['low']) <= zone_level <= float(bar['high'])) for _, bar in recent.iterrows())
        bullish = float(last['close']) > float(last['open'])
        bearish = float(last['close']) < float(last['open'])
        close_above = float(last['close']) >= zone_level
        close_below = float(last['close']) <= zone_level
        proximity_atr = abs(float(last['close']) - zone_level) / max(atr, 1e-6)

        reaction_type = 'no_reaction'
        if touched:
            if direction == 'BUY':
                if close_above and bullish:
                    reaction_type = 'support_bounce'
                elif close_above:
                    reaction_type = 'support_test'
                else:
                    reaction_type = 'support_weak'
            else:
                if close_below and bearish:
                    reaction_type = 'resistance_rejection'
                elif close_below:
                    reaction_type = 'resistance_test'
                else:
                    reaction_type = 'resistance_weak'
        else:
            if direction == 'BUY' and close_above:
                reaction_type = 'broke_above'
            elif direction == 'SELL' and close_below:
                reaction_type = 'broke_below'
            else:
                reaction_type = 'no_reaction'

        return {
            'zone_type': zone.get('type', 'zone'),
            'zone_level': zone_level,
            'direction': direction,
            'reaction_type': reaction_type,
            'touched': bool(touched),
            'proximity_atr': proximity_atr,
            'lookback': lookback,
            'last_candle': {
                'open': float(last['open']),
                'close': float(last['close']),
                'high': float(last['high']),
                'low': float(last['low']),
                'bullish': bullish,
                'bearish': bearish
            }
        }

    def analyze_all_timeframes(self, dfs, directions=None):
        """Analyze available timeframes and return zone data plus reactions per tf."""
        if dfs is None or not isinstance(dfs, dict):
            return {}

        directions = directions or ['BUY', 'SELL']
        summary = {}
        for tf, df in dfs.items():
            if df is None or getattr(df, 'empty', True):
                continue
            try:
                analysis = self.analyze_all(df)
                if not analysis:
                    continue

                tf_summary = {
                    'analysis': analysis,
                    'reactions': {},
                    'summaries': []
                }

                for direction in directions:
                    zones = [z for z in analysis.get('zones', []) if z.get('direction') == direction]
                    if not zones:
                        tf_summary['reactions'][direction] = None
                        continue

                    best_zone = zones[0]
                    reaction = self._evaluate_zone_reaction(df, best_zone, direction)
                    tf_summary['reactions'][direction] = reaction

                    if reaction is not None:
                        tf_summary['summaries'].append(
                            f"{direction} {reaction['reaction_type']} @ {reaction['zone_level']:.2f} ({reaction['proximity_atr']:.2f} ATR)"
                        )

                summary[tf] = tf_summary
            except Exception as e:
                LOG.debug(f"[ZoneAnalyzer] Timeframe analysis failed for {tf}: {e}")
        return summary

    def summarize_multi_tf_zone_reactions(self, dfs, directions=None):
        """Return a compact summary for multi-timeframe zone reactions."""
        reactions = self.analyze_all_timeframes(dfs, directions=directions)
        summary = {}
        for tf, tf_summary in reactions.items():
            if tf_summary.get('reactions'):
                summary[tf] = {
                    direction: reaction for direction, reaction in tf_summary['reactions'].items() if reaction is not None
                }
        return summary

ZONE_ANALYZER = ComprehensiveZoneAnalyzer()

class IntelligentOrderTypeSelector:
    """Analyzes market structure to decide: market, limit, or zone_limit orders.
    
    PHILOSOPHY: Default to patient LIMIT orders at zones. Only use MARKET on extreme momentum breakouts.
    Think like a real trader: wait for pullback to zone, or catch a structural breakout.
    """
    
    @staticmethod
    def candle_confirmation_score(df, direction, bars=1):
        """Score how well recent candle closes confirm the signal direction."""
        if df is None or df.empty or len(df) < bars:
            return 0.0
        recent = df.iloc[-bars:]
        total_score = 0.0
        for _, row in recent.iterrows():
            body = abs(row['close'] - row['open'])
            atr = max(float(row.get('atr', row['high'] - row['low'])), 1e-6)
            body_strength = min(1.0, body / max(0.5 * atr, 1e-6))
            if direction == 'BUY':
                aligned = 1.0 if row['close'] > row['open'] else 0.0
                wick_penalty = min(1.0, (row['high'] - max(row['close'], row['open'])) / atr)
            else:
                aligned = 1.0 if row['close'] < row['open'] else 0.0
                wick_penalty = min(1.0, (min(row['close'], row['open']) - row['low']) / atr)
            total_score += body_strength * aligned * (1.0 - wick_penalty)
        return max(0.0, min(1.0, total_score / bars))

    @staticmethod
    def prefers_zone_limit(df, direction, atr, confluence):
        """Determine if the structure and zone proximity favor patient limit entries."""
        if df is None or df.empty:
            return False
        if confluence >= CFG.get('min_zone_confluence_for_limit', 2):
            return True

        zone_score = ZONE_ANALYZER.get_zone_proximity_score(df, direction, max_atr=CFG.get('zone_score_atr', 2.5))
        if zone_score >= CFG.get('min_zone_score_for_limit', 0.25):
            return True

        nearest = ZONE_ANALYZER.get_nearest_zones(df, direction, max_results=1)
        if not nearest:
            return False
        level = nearest[0].get('level') or nearest[0].get('zone', [None])[0]
        if level is None:
            return False
        current_price = df.iloc[-1]['close']
        price_pct = abs(current_price - level) / max(current_price, 1e-6)
        return price_pct <= CFG.get('max_zone_range_pct', 0.015)

    @staticmethod
    def choose_order_type(df, direction, atr, adx, momentum_strength, vol_surge):
        """Intelligently choose order type based on comprehensive market structure analysis."""
        if df is None or df.empty or atr <= 0:
            return 'limit'  # Changed: Default to limit, not market
        
        # Use comprehensive zone analysis
        zone_data = ZONE_ANALYZER.analyze_all(df)
        last = df.iloc[-1]
        current_price = last['close']
        
        # Check zone confluence (how many zones align)
        confluence = ZONE_ANALYZER.get_zone_confluence(df, direction)
        
        # Get nearest zones for this direction
        nearest_zones = ZONE_ANALYZER.get_nearest_zones(df, direction, max_results=3)
        
        # === DECISION LOGIC (CONSERVATIVE - DEFAULT LIMIT) ===
        
        # 0. STRONG ZONE CONFLUENCE = ALWAYS LIMIT (zones are strongest signal)
        if confluence >= 3 and nearest_zones and len(nearest_zones) > 0:
            return 'limit'
        
        # 1. STRONG CONFLUENCE NEAR ZONE = LIMIT (wait for pullback confirmation)
        if confluence >= 2 and ZONE_ANALYZER.is_near_zone(df, direction, atr_distance=1.5):
            return 'limit'
        
        # 2. AT RESISTANCE/SUPPORT WITH ZONE AHEAD = LIMIT (patient entry)
        if direction == 'BUY' and zone_data['at_support'] and nearest_zones:
            return 'limit'
        elif direction == 'SELL' and zone_data['at_resistance'] and nearest_zones:
            return 'limit'

        zone_score = ZONE_ANALYZER.get_zone_proximity_score(df, direction, max_atr=CFG.get('zone_score_atr', 2.5))

        # 3. ORDER BLOCK/FVG DETECTED = ZONE_LIMIT (structured multi-level entry, like real trader)
        if zone_data['order_blocks'] or zone_data['fvgs']:
            if any(ob['dir'] == direction for ob in zone_data['order_blocks']) or \
               any(fvg['dir'] == direction for fvg in zone_data['fvgs']):
                return 'zone_limit'

        # 4. HIGH QUALITY ZONE PROXIMITY = ZONE_LIMIT
        if zone_score >= CFG.get('zone_limit_score_threshold', 0.35):
            return 'zone_limit'

        # 5. EXTREME MOMENTUM BREAKOUT = MARKET (only in rare conditions)
        # Real trader: only chases breakouts when EVERYTHING aligns perfectly
        if adx > 35 and momentum_strength >= 0.9 and vol_surge >= 2.0:  # Raised thresholds
            if direction == 'BUY' and not zone_data['at_resistance']:
                return 'market'
            elif direction == 'SELL' and not zone_data['at_support']:
                return 'market'
        
        # 5. IN PULLBACK ZONE (near EMA) = LIMIT (support entry - patient)
        ema_dist = abs(current_price - last.get('ema9', current_price))
        if ema_dist <= 1.2 * atr:
            # Price is in pullback zone - patient entry
            return 'limit'
        
        # 6. WEAK MOMENTUM/CONSOLIDATION = LIMIT (patience)
        if adx < 25 or momentum_strength < 0.6:
            return 'limit'
        
        # 7. MODERATE TREND (25 < ADX < 35) + ZONES EXIST = LIMIT (wait for them)
        if 25 <= adx <= 35 and nearest_zones:
            return 'limit'

        # 8. DYNAMIC ZONE CONFIRMATION: If the signal is near structure, prefer a patient zone entry
        if CFG.get('dynamic_zone_confirmation', True) and nearest_zones:
            if IntelligentOrderTypeSelector.prefers_zone_limit(df, direction, atr, confluence):
                return 'zone_limit'
            return 'limit'

        # 9. PRICE FAR FROM ZONES = ZONE_LIMIT (wait at next zone level, like real trader watching chart)
        if nearest_zones and len(nearest_zones) > 0:
            nearest_zone_dist = abs(current_price - nearest_zones[0].get('level', current_price))
            if nearest_zone_dist > 2.0 * atr:  # Far from zone - structured entry
                return 'zone_limit'
            else:
                return 'limit'  # Close to zone - wait for it

        # 10. DEFAULT = LIMIT (patience always wins)
        return 'limit'
    
    @staticmethod
    def get_order_rationale(df, direction, order_type):
        """Return explanation for order type choice - like a trader explaining their analysis."""
        zone_data = ZONE_ANALYZER.analyze_all(df)
        
        if order_type == 'market':
            return "Market: Extreme momentum breakout (ADX>35, momentum≥0.9, vol_surge≥2.0) - chase it"
        elif order_type == 'limit':
            confluence = ZONE_ANALYZER.get_zone_confluence(df, direction)
            zones = ZONE_ANALYZER.get_nearest_zones(df, direction, max_results=1)
            if confluence >= 3:
                return f"Limit: Strong zone confluence ({confluence} zones) - wait for pullback"
            elif confluence >= 2:
                return f"Limit: Multiple zones aligned - patient entry at structure"
            elif zones:
                zone_level = zones[0].get('level', 0)
                dist_atr = abs(df.iloc[-1]['close'] - zone_level) / df.iloc[-1].get('atr', 1)
                if dist_atr < 1.2:
                    return f"Limit: Price near zone @ {zone_level:.2f} - wait for confirmation"
                else:
                    return f"Limit: Zone ahead @ {zone_level:.2f} ({dist_atr:.1f}x ATR away) - wait for pullback"
            elif zone_data['at_support'] and direction == 'BUY':
                return "Limit: At support - wait for bounce confirmation"
            elif zone_data['at_resistance'] and direction == 'SELL':
                return "Limit: At resistance - wait for break confirmation"
            else:
                return "Limit: Default patient entry - let price come to you"
        elif order_type == 'zone_limit':
            if zone_data['order_blocks']:
                return "Zone-limit: Order blocks detected - split entry across levels"
            elif zone_data['fvgs']:
                return "Zone-limit: Fair Value Gaps found - structured multi-level entry like SMC"
            else:
                zones = ZONE_ANALYZER.get_nearest_zones(df, direction, max_results=1)
                if zones:
                    return f"Zone-limit: Structured entry - patient levels to next zone @ {zones[0].get('level', 0):.2f}"
                else:
                    return "Zone-limit: Structured entry - wait for best level"
        
        return "Unknown order logic"

class TrendFollowingStrategy:
    def generate_signal(self, df):
        d = add_indicators(df)
        if d is None or d.empty:
            return None
        last = d.iloc[-1]
        prev = d.iloc[-2]
        atr = float(last.get('atr', 1.0))
        adx = calc_adx(d).iloc[-1] if len(d) > 30 else 20
        vol_surge, momentum_strength, vol_ok, _, _ = _adaptive_volume_filter(last, prev, d, atr, adx)
        
        # FEATURE 5: Check news filter
        news_check = NEWS_FILTER.is_trading_paused()
        if news_check['paused']:
            LOG.debug(f"[TREND] Skipping signal due to news: {news_check['reason']}")
            return None
        
        # Get zone data
        zone_data = ZONE_ANALYZER.analyze_all(d)
        
        # FEATURE 2: Ichimoku analysis
        ichimoku_data = ICHIMOKU.analyze(d)
        
        # FEATURE 3: Order imbalance analysis
        imbalance_data = ORDER_IMBALANCE.analyze(d)
        
        # FEATURE 6: Stochastic RSI divergence
        stoch_div = STOCH_RSI.detect_divergence(d)
        
        # BUY: Uptrend confirmed + price pulled back into EMA (pullback confirmation)
        if last['ema9'] > last['ema21'] and adx > 25 and vol_ok:
            # FIXED: Require price to be IN or ABOVE EMA9 (pullback entry), not just above
            # Price should be within 1 ATR above/below EMA9 for pullback confirmation
            ema_dist = abs(last['close'] - last['ema9'])
            if ema_dist <= 1.2 * atr:  # Price is near/pulled back to EMA
                entry = last['close']
                sl = entry - (1.5 * atr)
                tp = entry + (3.0 * atr)
                conf = min(0.95, 0.6 + (adx - 25) / 30 + (0.05 if momentum_strength >= 0.8 else 0.0))

                # Choose order type based on market structure
                order_type = IntelligentOrderTypeSelector.choose_order_type(d, 'BUY', atr, adx, momentum_strength, vol_surge)
                order_rationale = IntelligentOrderTypeSelector.get_order_rationale(d, 'BUY', order_type)

                # Evaluate dynamic zone quality
                best_zone = ZONE_ANALYZER.get_best_zone_level(d, 'BUY', max_atr=CFG.get('signal_zone_max_atr', 2.5))
                zone_score = best_zone['score'] if best_zone else 0.0
                zone_valid = best_zone is not None
                if zone_score >= CFG.get('min_zone_proximity_score', 0.2):
                    conf += 0.08
                elif not (adx > 34 and momentum_strength > 1.0 and vol_surge > 1.2):
                    LOG.debug(f"[TREND] Reject BUY: insufficient zone proximity ({zone_score:.2f}) and trend not extreme")
                    return None
                else:
                    conf = max(0.45, conf - 0.05)

                # Boost confidence if near zone confluence
                zone_confluence = ZONE_ANALYZER.get_zone_confluence(d, 'BUY')
                if zone_confluence >= 2:
                    conf += 0.1

                # Zone reaction gating for support countertrend logic
                zone_reaction = ZONE_ANALYZER.get_best_zone_reaction(d, 'BUY')
                if zone_reaction is not None:
                    if zone_reaction['reaction_type'] in ('support_bounce', 'support_test'):
                        conf += 0.08
                        order_type = 'limit'
                        LOG.debug(f"[TREND] Support hold confirmed, boosting BUY confidence and preferring LIMIT entry: {zone_reaction['reaction_type']}")
                    elif zone_reaction['reaction_type'] == 'broke_below' and momentum_strength > 0.85:
                        LOG.debug(f"[TREND] Support broke below with momentum, rejecting BUY signal: {zone_reaction}")
                        return None

                # FEATURE 2: Ichimoku confirmation boost
                if ichimoku_data.get('cloud_strength', 0) > 0.5 and ichimoku_data.get('chikou_bullish'):
                    conf += 0.1
                    LOG.debug(f"[TREND] Ichimoku cloud boost (+0.1), new conf={conf:.2f}")
                
                # FEATURE 3: Order imbalance alignment
                if imbalance_data.get('signal') in ['BUY', 'STRONG_BUY']:
                    conf += 0.05
                    LOG.debug(f"[TREND] Order imbalance BUY alignment (+0.05)")
                
                # FEATURE 6: Divergence confirmation
                if stoch_div.get('divergence_type') == 'BULLISH':
                    conf += 0.15
                    LOG.debug(f"[TREND] Bullish divergence detected (+0.15)")
                
                # Calculate RR ratio for validation
                rr = calculate_reward_risk_ratio(entry, tp, sl)

                return {
                    'dir': 'BUY', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp, 
                    'strategy': 'trend', 'order_type': order_type,
                    'order_rationale': order_rationale,
                    'zone_confluence': zone_confluence,
                    'zone_score': zone_score,
                    'best_zone': best_zone,
                    'zones': ZONE_ANALYZER.get_nearest_zones(d, 'BUY', max_results=2),
                    'min_rr_ratio': 2.0,  # Hard filter: 1:2+ minimum
                    'rr_ratio': rr,
                    'ichimoku_strength': ichimoku_data.get('cloud_strength', 0),
                    'imbalance_signal': imbalance_data.get('signal'),
                    'divergence': stoch_div.get('divergence_type')
                }
        
        # SELL: Downtrend confirmed + price pulled back into EMA (pullback confirmation)
        if last['ema9'] < last['ema21'] and adx > 25 and vol_ok:
            # FIXED: Require price to be IN or BELOW EMA9 (pullback entry), not just below
            ema_dist = abs(last['close'] - last['ema9'])
            if ema_dist <= 1.2 * atr:  # Price is near/pulled back to EMA
                entry = last['close']
                sl = entry + (1.5 * atr)
                tp = entry - (3.0 * atr)
                conf = min(0.95, 0.6 + (adx - 25) / 30 + (0.05 if momentum_strength >= 0.8 else 0.0))
                
                # Choose order type based on market structure
                order_type = IntelligentOrderTypeSelector.choose_order_type(d, 'SELL', atr, adx, momentum_strength, vol_surge)
                order_rationale = IntelligentOrderTypeSelector.get_order_rationale(d, 'SELL', order_type)
                
                # Boost confidence if near zone
                zone_confluence = ZONE_ANALYZER.get_zone_confluence(d, 'SELL')
                if zone_confluence >= 2:
                    conf += 0.1
                
                # FEATURE 2: Ichimoku confirmation boost
                if ichimoku_data.get('cloud_strength', 0) > 0.5 and not ichimoku_data.get('chikou_bullish'):
                    conf += 0.1
                    LOG.debug(f"[TREND] Ichimoku cloud boost (+0.1), new conf={conf:.2f}")
                
                # FEATURE 3: Order imbalance alignment
                if imbalance_data.get('signal') in ['SELL', 'STRONG_SELL']:
                    conf += 0.05
                    LOG.debug(f"[TREND] Order imbalance SELL alignment (+0.05)")

                # Zone reaction gating for resistance countertrend logic
                zone_reaction = ZONE_ANALYZER.get_best_zone_reaction(d, 'SELL')
                if zone_reaction is not None:
                    if zone_reaction['reaction_type'] in ('resistance_rejection', 'resistance_test'):
                        conf += 0.08
                        order_type = 'limit'
                        LOG.debug(f"[TREND] Resistance hold confirmed, boosting SELL confidence and preferring LIMIT entry: {zone_reaction['reaction_type']}")
                    elif zone_reaction['reaction_type'] == 'broke_above' and momentum_strength > 0.85:
                        LOG.debug(f"[TREND] Resistance broke above with momentum, rejecting SELL signal: {zone_reaction}")
                        return None

                # FEATURE 6: Divergence confirmation
                if stoch_div.get('divergence_type') == 'BEARISH':
                    conf += 0.15
                    LOG.debug(f"[TREND] Bearish divergence detected (+0.15)")
                
                # Calculate RR ratio for validation
                rr = calculate_reward_risk_ratio(entry, tp, sl)
                
                return {
                    'dir': 'SELL', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp, 
                    'strategy': 'trend', 'order_type': order_type,
                    'order_rationale': order_rationale,
                    'zone_confluence': zone_confluence,
                    'zones': ZONE_ANALYZER.get_nearest_zones(d, 'SELL', max_results=2),
                    'min_rr_ratio': 2.0,  # Hard filter: 1:2+ minimum
                    'rr_ratio': rr,
                    'ichimoku_strength': ichimoku_data.get('cloud_strength', 0),
                    'imbalance_signal': imbalance_data.get('signal'),
                    'divergence': stoch_div.get('divergence_type')
                }
        return None

def _detect_false_breakout(d, direction, breakout_level, atr):
    """Reject breakout setups that immediately fail to hold the level."""
    if d is None or d.empty or len(d) < 2:
        return False

    last = d.iloc[-1]
    prev = d.iloc[-2]
    close_gap = abs(last['close'] - prev['close'])

    if direction == 'BUY':
        if last['high'] > breakout_level and last['close'] <= breakout_level:
            return True
        if len(d) >= 3:
            prev2 = d.iloc[-3]
            if prev2['high'] > breakout_level and prev2['close'] <= breakout_level and last['close'] < prev['close']:
                return True
        if last['high'] > breakout_level and last['close'] < prev['close']:
            return True
        return (last['high'] > breakout_level and last['close'] <= prev['close'] + (0.15 * atr) and
                close_gap <= (0.4 * atr))

    if direction == 'SELL':
        if last['low'] < breakout_level and last['close'] >= breakout_level:
            return True
        if len(d) >= 3:
            prev2 = d.iloc[-3]
            if prev2['low'] < breakout_level and prev2['close'] >= breakout_level and last['close'] > prev['close']:
                return True
        if last['low'] < breakout_level and last['close'] > prev['close']:
            return True
        return (last['low'] < breakout_level and last['close'] >= prev['close'] - (0.15 * atr) and
                close_gap <= (0.4 * atr))

    return False


class BreakoutStrategy:
    def generate_signal(self, df):
        d = add_indicators(df)
        if d is None or d.empty:
            return None
        last = d.iloc[-1]
        prev = d.iloc[-2]
        
        # FEATURE 5: Check news filter
        news_check = NEWS_FILTER.is_trading_paused()
        if news_check['paused']:
            return None
        
        bb_width = last.get('bb_width', 1.0)
        if bb_width >= 0.01:
            return None
        high_20 = d['high'].rolling(20).max().iloc[-1]
        low_20 = d['low'].rolling(20).min().iloc[-1]
        adx = calc_adx(d).iloc[-1] if len(d) > 30 else 20
        atr = last['atr']
        vol_surge, momentum_strength, vol_ok, _, _ = _adaptive_volume_filter(last, prev, d, atr, adx)
        if not vol_ok:
            return None
        
        # FEATURE 2 & 3: Ichimoku and imbalance
        ichimoku_data = ICHIMOKU.analyze(d)
        imbalance_data = ORDER_IMBALANCE.analyze(d)
        
        if last['close'] > high_20 and adx > 25:
            if _detect_false_breakout(d, 'BUY', high_20, atr):
                return None
            entry = last['close']
            sl = entry - (3 * atr)
            tp = entry + (6 * atr)
            conf = min(1.0, 0.6 + (adx - 25) / 30)
            
            # FEATURE 2 & 3 boost
            if ichimoku_data.get('cloud_strength', 0) > 0.5 and ichimoku_data.get('chikou_bullish'):
                conf += 0.08
            if imbalance_data.get('signal') in ['BUY', 'STRONG_BUY']:
                conf += 0.05
            
            rr = calculate_reward_risk_ratio(entry, tp, sl)
            
            return {
                'dir': 'BUY', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp, 
                'strategy': 'breakout', 'order_type': 'zone_limit',  # Breakout uses zone entries
                'resistance': high_20 + (2 * atr), 'support': low_20,
                'min_rr_ratio': 2.0,
                'rr_ratio': rr
            }
        if last['close'] < low_20 and adx > 25:
            if _detect_false_breakout(d, 'SELL', low_20, atr):
                return None
            entry = last['close']
            sl = entry + (3 * atr)
            tp = entry - (6 * atr)
            conf = min(1.0, 0.6 + (adx - 25) / 30)
            
            # FEATURE 2 & 3 boost
            if ichimoku_data.get('cloud_strength', 0) > 0.5 and not ichimoku_data.get('chikou_bullish'):
                conf += 0.08
            if imbalance_data.get('signal') in ['SELL', 'STRONG_SELL']:
                conf += 0.05
            
            rr = calculate_reward_risk_ratio(entry, tp, sl)
            
            return {
                'dir': 'SELL', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp, 
                'strategy': 'breakout', 'order_type': 'zone_limit',
                'resistance': high_20, 'support': low_20 - (2 * atr),
                'min_rr_ratio': 2.0,
                'rr_ratio': rr
            }
        return None

def _adaptive_volume_filter(last, prev, d, atr, adx, price=None):
    """Return a more adaptive volume/momentum gate for low-volume but strong-move setups."""
    price = float(last['close']) if price is None else float(price)
    volume = float(last.get('volume', 0))
    avg_vol = float(d['volume'].rolling(20).mean().iloc[-1]) if 'volume' in d.columns else 0.0
    vol_surge = volume / (avg_vol + 1e-6) if avg_vol > 0 else 1.0
    momentum_strength = abs(price - float(prev['close'])) / (atr + 1e-6)

    session = None
    session_mult = 1.0
    if 'SESSION_DETECTOR' in globals() and globals()['SESSION_DETECTOR']:
        try:
            session = globals()['SESSION_DETECTOR'].current_session()
            session_mult = globals()['CFG'].get('session_multipliers', {}).get(session, 1.0)
        except Exception:
            session = None
            session_mult = 1.0

    active_session = session in {'LONDON_NY', 'NY_CLOSE', 'LONDON', 'NY'}
    base_ratio = 0.85
    lower_ratio = 0.70
    if active_session:
        base_ratio = 0.72 if session_mult >= 1.15 else 0.78
        lower_ratio = 0.60 if session_mult >= 1.15 else 0.66

    if momentum_strength >= 1.1 or adx > 34:
        base_ratio = max(0.45, base_ratio - 0.15)
        lower_ratio = max(0.40, lower_ratio - 0.12)
    elif momentum_strength >= 0.9 or adx > 30:
        base_ratio = max(0.55, base_ratio - 0.08)
        lower_ratio = max(0.48, lower_ratio - 0.06)

    vol_ok = ((vol_surge >= base_ratio and (momentum_strength >= 0.6 or adx > 26)) or
              (vol_surge >= lower_ratio and (momentum_strength >= 0.9 or adx > 30)))
    return vol_surge, momentum_strength, vol_ok, session, session_mult


def _detect_fake_retest(d, direction, zone_level, atr):
    """Reject soft retest setups that fail to hold the zone and immediately reverse."""
    if d is None or d.empty or len(d) < 2:
        return False

    last = d.iloc[-1]
    prev = d.iloc[-2]
    close_gap = abs(last['close'] - prev['close'])

    if direction == 'BUY':
        if last['close'] <= prev['close'] and last['low'] < prev['low']:
            return True
        return (last['close'] <= zone_level + (0.2 * atr) and last['close'] <= prev['close'] + (0.1 * atr) and close_gap <= (0.35 * atr))

    if direction == 'SELL':
        if last['close'] >= prev['close'] and last['high'] > prev['high']:
            return True
        return (last['close'] >= zone_level - (0.2 * atr) and last['close'] >= prev['close'] - (0.1 * atr) and close_gap <= (0.35 * atr))

    return False


class PullbackRetracementStrategy:
    """Soft pullback/retracement strategy.

    This does not hard-block entries. It only generates a signal when price is
    retracing into a trend-friendly zone with supportive volume. If the zone is
    already left and momentum is still strong, it can switch to a market-style
    continuation signal instead of waiting for a perfect pullback.
    """

    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.name = 'pullback_retracement'

    def generate_signal(self, df):
        try:
            if df is None or df.empty or len(df) < 20:
                return None

            # FEATURE 5: Check news filter
            news_check = NEWS_FILTER.is_trading_paused()
            if news_check['paused']:
                return None

            d = add_indicators(df)
            if d is None or d.empty:
                return None

            last = d.iloc[-1]
            prev = d.iloc[-2]
            price = float(last['close'])
            atr = float(last.get('atr', 1.0))
            ema_fast = float(last.get('ema9', price))
            ema_slow = float(last.get('ema21', price))
            ema_50 = float(last.get('ema50', price))
            adx = float(calc_adx(d).iloc[-1]) if len(d) > 30 else 20.0
            trend_bull = ema_fast > ema_slow and price > ema_fast and price > ema_50 and adx > 22
            trend_bear = ema_fast < ema_slow and price < ema_fast and price < ema_50 and adx > 22

            if not (trend_bull or trend_bear):
                return None

            vol_surge, momentum_strength, vol_ok, session, session_mult = _adaptive_volume_filter(last, prev, d, atr, adx, price)
            if not vol_ok:
                return None

            # FEATURE 2 & 3: Ichimoku and imbalance
            ichimoku_data = ICHIMOKU.analyze(d)
            imbalance_data = ORDER_IMBALANCE.analyze(d)

            session_bonus = 0.04 if session in {'LONDON_NY', 'NY_CLOSE', 'LONDON', 'NY'} and session_mult >= 1.0 else 0.0
            momentum_bonus = 0.03 if momentum_strength >= 1.0 else 0.01 if momentum_strength >= 0.8 else 0.0
            zone_width = max(atr * 1.2, abs(ema_fast - ema_slow) * 0.8)

            if trend_bull:
                pullback_zone_low = ema_fast - zone_width
                pullback_zone_high = ema_fast + zone_width
                in_pullback_zone = pullback_zone_low <= price <= pullback_zone_high
                if in_pullback_zone:
                    if _detect_fake_retest(d, 'BUY', ema_fast, atr):
                        return None
                    entry = price
                    sl = entry - (1.2 * atr)
                    tp = entry + (2.4 * atr)
                    conf = min(0.95, 0.7 + min(0.2, max(0.0, (price - ema_slow) / (atr * 8 + 1e-6))) + min(0.05, max(0.0, vol_surge - 1.05)) + session_bonus + momentum_bonus)
                    
                    # FEATURE 2 & 3 boost
                    if ichimoku_data.get('cloud_strength', 0) > 0.5 and ichimoku_data.get('chikou_bullish'):
                        conf += 0.08
                    if imbalance_data.get('signal') in ['BUY', 'STRONG_BUY']:
                        conf += 0.05
                    
                    rr = calculate_reward_risk_ratio(entry, tp, sl)
                    
                    return {
                        'dir': 'BUY', 'confidence': float(conf), 'entry': entry, 'sl': sl, 'tp': tp,
                        'strategy': self.name, 'order_type': 'limit', 'signal_type': 'pullback',
                        'entry_mode': 'pullback', 'zone': ema_fast,
                        'min_rr_ratio': 2.0,
                        'rr_ratio': rr
                    }

                # If price already left the zone, allow a continuation entry only if volume remains strong.
                if price > ema_fast + (0.6 * atr) and last['close'] > prev['close']:
                    entry = price
                    sl = entry - (1.2 * atr)
                    tp = entry + (2.4 * atr)
                    conf = min(0.88, 0.62 + session_bonus + momentum_bonus)
                    
                    # FEATURE 2 & 3 boost
                    if ichimoku_data.get('cloud_strength', 0) > 0.5 and ichimoku_data.get('chikou_bullish'):
                        conf += 0.08
                    if imbalance_data.get('signal') in ['BUY', 'STRONG_BUY']:
                        conf += 0.05
                    
                    rr = calculate_reward_risk_ratio(entry, tp, sl)
                    
                    # FIXED: Use zone_limit instead of market for continuation - wait for pullback confirmation
                    order_type = IntelligentOrderTypeSelector.choose_order_type(d, 'BUY', atr, adx, momentum_strength, vol_surge)
                    
                    return {
                        'dir': 'BUY', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp,
                        'strategy': self.name, 'order_type': order_type, 'signal_type': 'pullback',
                        'entry_mode': 'continuation', 'zone': ema_fast,
                        'min_rr_ratio': 2.0,
                        'rr_ratio': rr
                    }

            if trend_bear:
                pullback_zone_low = ema_fast - zone_width
                pullback_zone_high = ema_fast + zone_width
                in_pullback_zone = pullback_zone_low <= price <= pullback_zone_high
                if in_pullback_zone:
                    if _detect_fake_retest(d, 'SELL', ema_fast, atr):
                        return None
                    entry = price
                    sl = entry + (1.2 * atr)
                    tp = entry - (2.4 * atr)
                    conf = min(0.95, 0.7 + min(0.2, max(0.0, (ema_slow - price) / (atr * 8 + 1e-6))) + min(0.05, max(0.0, vol_surge - 1.05)) + session_bonus + momentum_bonus)
                    
                    # FEATURE 2 & 3 boost
                    if ichimoku_data.get('cloud_strength', 0) > 0.5 and not ichimoku_data.get('chikou_bullish'):
                        conf += 0.08
                    if imbalance_data.get('signal') in ['SELL', 'STRONG_SELL']:
                        conf += 0.05
                    
                    rr = calculate_reward_risk_ratio(entry, tp, sl)
                    
                    return {
                        'dir': 'SELL', 'confidence': float(conf), 'entry': entry, 'sl': sl, 'tp': tp,
                        'strategy': self.name, 'order_type': 'limit', 'signal_type': 'pullback',
                        'entry_mode': 'pullback', 'zone': ema_fast,
                        'min_rr_ratio': 2.0,
                        'rr_ratio': rr
                    }

                if price < ema_fast - (0.6 * atr) and last['close'] < prev['close']:
                    entry = price
                    sl = entry + (1.2 * atr)
                    tp = entry - (2.4 * atr)
                    conf = min(0.88, 0.62 + session_bonus + momentum_bonus)
                    
                    # FEATURE 2 & 3 boost
                    if ichimoku_data.get('cloud_strength', 0) > 0.5 and not ichimoku_data.get('chikou_bullish'):
                        conf += 0.08
                    if imbalance_data.get('signal') in ['SELL', 'STRONG_SELL']:
                        conf += 0.05
                    
                    rr = calculate_reward_risk_ratio(entry, tp, sl)
                    
                    # FIXED: Use intelligent order type selector instead of hardcoding market
                    order_type = IntelligentOrderTypeSelector.choose_order_type(d, 'SELL', atr, adx, momentum_strength, vol_surge)
                    
                    return {
                        'dir': 'SELL', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp,
                        'strategy': self.name, 'order_type': order_type, 'signal_type': 'pullback',
                        'entry_mode': 'continuation', 'zone': ema_fast,
                        'min_rr_ratio': 2.0,
                        'rr_ratio': rr
                    }

            return None
        except Exception as e:
            LOG.warning(f"[{self.name}] Signal failed: {e}")
            return None


class SMCLiquidityStrategy:
    """Soft SMC/liquidity strategy.

    This acts as a confirmation layer using recent swing highs/lows and volume.
    It can trigger on a liquidity retest into a key zone, but it won't force a
    trade if the market has already moved away and momentum is no longer aligned.
    """

    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.name = 'smc_liquidity'

    def generate_signal(self, df):
        try:
            if df is None or df.empty or len(df) < 20:
                return None

            # FEATURE 5: Check news filter
            news_check = NEWS_FILTER.is_trading_paused()
            if news_check['paused']:
                return None

            d = add_indicators(df)
            if d is None or d.empty:
                return None

            last = d.iloc[-1]
            atr = float(last.get('atr', 1.0))
            price = float(last['close'])
            prev = d.iloc[-2]

            ema_fast = float(last.get('ema9', price))
            ema_slow = float(last.get('ema21', price))
            ema_50 = float(last.get('ema50', price))
            adx = float(calc_adx(d).iloc[-1]) if len(d) > 30 else 20.0
            trend_bull = ema_fast > ema_slow and price > ema_fast and price > ema_50 and adx > 22
            trend_bear = ema_fast < ema_slow and price < ema_fast and price < ema_50 and adx > 22

            if not (trend_bull or trend_bear):
                return None

            vol_surge, momentum_strength, vol_ok, session, session_mult = _adaptive_volume_filter(last, prev, d, atr, adx, price)
            if not vol_ok:
                return None

            # FEATURE 2 & 3: Ichimoku and imbalance
            ichimoku_data = ICHIMOKU.analyze(d)
            imbalance_data = ORDER_IMBALANCE.analyze(d)

            session_bonus = 0.04 if session in {'LONDON_NY', 'NY_CLOSE', 'LONDON', 'NY'} and session_mult >= 1.0 else 0.0
            momentum_bonus = 0.03 if momentum_strength >= 1.0 else 0.01 if momentum_strength >= 0.8 else 0.0
            swing_high = float(d['high'].rolling(5).max().iloc[-2])
            swing_low = float(d['low'].rolling(5).min().iloc[-2])
            zone_width = max(atr * 1.0, (swing_high - swing_low) * 0.18)
            trend_bull = ema_fast > ema_slow and price > ema_fast and price > ema_50 and adx > 22
            trend_bear = ema_fast < ema_slow and price < ema_fast and price < ema_50 and adx > 22

            if trend_bull:
                if swing_low <= price <= (swing_low + zone_width) and last['close'] > prev['close']:
                    if _detect_fake_retest(d, 'BUY', swing_low, atr):
                        return None
                    entry = price
                    sl = entry - (1.1 * atr)
                    tp = entry + (2.2 * atr)
                    conf = min(0.95, 0.72 + min(0.08, max(0.0, vol_surge - 1.05)) + session_bonus + momentum_bonus)
                    
                    # FEATURE 2 & 3 boost
                    if ichimoku_data.get('cloud_strength', 0) > 0.5 and ichimoku_data.get('chikou_bullish'):
                        conf += 0.08
                    if imbalance_data.get('signal') in ['BUY', 'STRONG_BUY']:
                        conf += 0.05
                    
                    rr = calculate_reward_risk_ratio(entry, tp, sl)
                    
                    return {
                        'dir': 'BUY', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp,
                        'strategy': self.name, 'order_type': 'limit', 'signal_type': 'smc_liquidity',
                        'entry_mode': 'retest', 'zone': swing_low,
                        'min_rr_ratio': 2.0,
                        'rr_ratio': rr
                    }

            if trend_bear:
                if (swing_high - zone_width) <= price <= swing_high and last['close'] < prev['close']:
                    if _detect_fake_retest(d, 'SELL', swing_high, atr):
                        return None
                    entry = price
                    sl = entry + (1.1 * atr)
                    tp = entry - (2.2 * atr)
                    conf = min(0.95, 0.72 + min(0.08, max(0.0, vol_surge - 1.05)) + session_bonus + momentum_bonus)
                    
                    # FEATURE 2 & 3 boost
                    if ichimoku_data.get('cloud_strength', 0) > 0.5 and not ichimoku_data.get('chikou_bullish'):
                        conf += 0.08
                    if imbalance_data.get('signal') in ['SELL', 'STRONG_SELL']:
                        conf += 0.05
                    
                    rr = calculate_reward_risk_ratio(entry, tp, sl)
                    
                    return {
                        'dir': 'SELL', 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp,
                        'strategy': self.name, 'order_type': 'limit', 'signal_type': 'smc_liquidity',
                        'entry_mode': 'retest', 'zone': swing_high,
                        'min_rr_ratio': 2.0,
                        'rr_ratio': rr
                    }

            return None
        except Exception as e:
            LOG.warning(f"[{self.name}] Signal failed: {e}")
            return None


class NewsImpactStrategy:
    def generate_signal(self, df, news_events):
        if df is None or df.empty:
            return None
        now = utc_now()
        for ev in news_events:
            try:
                news_time = datetime.fromisoformat(ev['time'].replace('Z', '+00:00'))
            except Exception:
                continue
            mins = (now - news_time).total_seconds() / 60
            if 5 <= mins <= 15:
                d = add_indicators(df)
                if d is None or d.empty:
                    return None
                last = d.iloc[-1]
                atr = last['atr']
                direction = 'BUY' if last['close'] > last['open'] else 'SELL'
                entry = last['close']
                sl = entry - (2 * atr) if direction == 'BUY' else entry + (2 * atr)
                tp = entry + (4 * atr) if direction == 'BUY' else entry - (4 * atr)
                conf = 0.6
                return {'dir': direction, 'confidence': conf, 'entry': entry, 'sl': sl, 'tp': tp, 'strategy': 'news_impact'}
        return None

class StrategyOrchestrator:
    def __init__(self):
        self.strategies = {
            'mean_reversion': MeanReversionStrategyV18(),
            # STAGE-9: original bound this name to the FIRST definition at this point in module
            # execution (the later definition is unreferenced dead code); pin the class explicitly.
            'trend': TrendFollowingStrategy(),
            'breakout': BreakoutStrategy(),
            'pullback_retracement': PullbackRetracementStrategy(),
            'smc_liquidity': SMCLiquidityStrategy(),
            'news_impact': NewsImpactStrategy()
        }
        self.weights = CFG.get("strategy_weights", {}).copy()

    def _update_weights(self):
        weights = {}
        for name in CFG.get("active_strategies", []):
            win_rate = STORE.get_strategy_win_rate(name, 50)
            base = self.weights.get(name, 0.3)
            if win_rate is None:
                weights[name] = base
            else:
                weights[name] = max(0.1, min(0.6, base * (0.8 + win_rate)))
        total = sum(weights.values()) if weights else 0
        if total > 0:
            for k in weights:
                weights[k] /= total
        self.weights = weights or self.weights

    def generate_signal(self, df, news_events=None):
        self._update_weights()
        signals = []
        for name in CFG.get("active_strategies", []):
            strat = self.strategies.get(name)
            if not strat:
                continue
            if name == 'news_impact':
                sig = strat.generate_signal(df, news_events or [])
            else:
                sig = strat.generate_signal(df)
            if sig:
                signals.append(sig)

        if not signals:
            return None

        trend_dir = None
        if df is not None:
            ind = add_indicators(df)
            if ind is not None and not ind.empty:
                last = ind.iloc[-1]
                if last['ema9'] > last['ema21'] > last['ema50']:
                    trend_dir = 'BUY'
                elif last['ema9'] < last['ema21'] < last['ema50']:
                    trend_dir = 'SELL'

        buy_score = 0.0
        sell_score = 0.0
        for sig in signals:
            if trend_dir and sig['dir'] != trend_dir:
                penalty = 0.65 if sig['strategy'] in ['trend', 'pullback_retracement', 'smc_liquidity'] else 0.80
                sig['confidence'] = float(sig.get('confidence', 0.0)) * penalty
                sig['reasons'] = sig.get('reasons', []) + [f"Trend mismatch penalty: {sig['dir']} vs {trend_dir}"]

            weight = self.weights.get(sig['strategy'], 0.0)
            if sig['dir'] == 'BUY':
                buy_score += weight * sig['confidence']
            else:
                sell_score += weight * sig['confidence']

        if abs(buy_score - sell_score) < CFG.get('orchestrator_decision_margin', 0.10):
            LOG.info("[ORCH] No clear directional edge after trend weighting; skipping signal")
            return None

        final_dir = 'BUY' if buy_score >= sell_score else 'SELL'
        final_conf = max(buy_score, sell_score)
        if trend_dir and final_dir != trend_dir and final_conf < CFG.get('trend_mismatch_min_confidence', 0.85):
            LOG.info(f"[ORCH] Opposite-direction signal below confidence threshold vs major trend ({trend_dir}); skipping")
            return None

        best = max(
            [s for s in signals if s['dir'] == final_dir],
            key=lambda s: s['confidence']
        )
        best['confidence'] = final_conf
        return best

class DrawdownCircuitBreaker:
    """Emergency circuit breaker for catastrophic drawdowns
    
    Levels:
    - 5% DD: Reduce position size to 70%
    - 10% DD: Increase entry filters (min score 8.5)
    - 15% DD: Pause trading for 1 hour
    - 20% DD: Emergency stop - close all trades immediately
    """
    
    def __init__(self, cfg=None):
        self.cfg = cfg or CFG
        # STAGE-4 FIX: canonical action names. The emitter used to output
        # 'REDUCE'/'FILTER'/'PAUSE'/'EMERGENCY' but the BattleBot consumer reads
        # 'reduce_size'/'increase_filters'/'pause_trading'/'emergency_stop', so
        # NO ladder branch ever matched and the drawdown ladder was dead.
        self.threshold_levels = [
            (0.05, 'reduce_size', 0.7),       # 5% DD: reduce size to 70%
            (0.10, 'increase_filters', 8.5),  # 10% DD: raise min score to 8.5
            (0.15, 'pause_trading', 3600),    # 15% DD: pause 1h
            (0.20, 'emergency_stop', None)    # 20% DD: emergency close all
        ]
        self.emergency_triggered_time = None
        self.triggered_level = None
        self.stats = {
            'emergency_closes': 0,
            'trades_closed': 0,
            'total_loss': 0.0
        }
        LOG.info("[CB] DrawdownCircuitBreaker initialized")
    
    def check_protocol(self, current_drawdown: float) -> Dict:
        """Check drawdown against thresholds and return action
        
        Returns: {'action': 'NORMAL'|'reduce_size'|'increase_filters'|'pause_trading'|'emergency_stop', 'param': ...}
        (STAGE-4: canonical action names, matching the BattleBot consumer)
        """
        try:
            # STAGE-4 FIX: iterate from the MOST SEVERE threshold down. The original
            # looped 5%→20% and returned the FIRST match, so a 15% drawdown
            # triggered the 5% action (reduce_size) and the ladder never escalated.
            for threshold, action, param in reversed(self.threshold_levels):
                if current_drawdown >= threshold:
                    self.triggered_level = action
                    return {'action': action, 'param': param, 'drawdown': current_drawdown}
            
            # Below all thresholds
            self.triggered_level = None
            return {'action': 'NORMAL', 'param': None, 'drawdown': current_drawdown}
        except Exception as e:
            LOG.error(f"[CB] Protocol check error: {e}")
            return {'action': 'NORMAL', 'param': None}
    
    def should_close_all_trades(self, current_drawdown: float) -> bool:
        """Check if emergency stop should trigger (20% DD)"""
        try:
            return current_drawdown >= 0.20
        except Exception as e:
            LOG.debug(f"[CB] Emergency check error: {e}")
            return False
    
    def close_all_trades_emergency(self, trades: List[Dict], current_price: float) -> Dict:
        """Execute emergency closure of all open trades at market price
        
        Returns: {'closed': int, 'total_loss': float, 'reason': str}
        """
        try:
            closed_count = 0
            total_loss = 0.0
            
            if not trades or len(trades) == 0:
                LOG.info("[CB] No trades to close")
                return {'closed': 0, 'total_loss': 0.0, 'reason': 'no_trades'}
            
            for trade in trades:
                try:
                    entry_price = float(trade.get('entry', 0))
                    size = float(trade.get('size', 0))
                    direction = int(trade.get('dir', 0))
                    ticket = trade.get('ticket', 0)
                    
                    # Calculate loss
                    if direction == 1:  # LONG
                        loss = (entry_price - current_price) * size * 100
                    else:  # SHORT
                        loss = (current_price - entry_price) * size * 100
                    
                    # Close trade (market order at current price)
                    # In live, this would call MT5.close_position(ticket)
                    # For now, log the closure
                    LOG.warning(f"[CB] EMERGENCY CLOSE: Ticket={ticket}, Loss=${loss:.2f}, Price={current_price:.2f}")
                    
                    closed_count += 1
                    total_loss += loss
                    
                except Exception as e:
                    LOG.warning(f"[CB] Failed to close trade {trade.get('ticket')}: {e}")
                    continue
            
            # Update statistics
            self.stats['emergency_closes'] += 1
            self.stats['trades_closed'] += closed_count
            self.stats['total_loss'] += total_loss
            self.emergency_triggered_time = datetime.now()
            
            # Send alert
            msg = f"🚨 EMERGENCY CIRCUIT BREAKER ACTIVATED 🚨\n"
            msg += f"| Trades Closed: {closed_count}\n"
            msg += f"| Total Loss: ${total_loss:.2f}\n"
            msg += f"| Close Price: ${current_price:.2f}\n"
            msg += f"[ Time: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}"
            LOG.error(msg)
            
            return {
                'closed': closed_count,
                'total_loss': total_loss,
                'reason': 'emergency_stop_20pct_dd',
                'message': msg
            }
        except Exception as e:
            LOG.error(f"[CB] Emergency closure execution failed: {e}")
            return {'closed': 0, 'total_loss': 0.0, 'reason': f'error: {e}'}
    
    def apply_filter_level(self, action: str, param) -> Dict:
        """Apply trading filter based on circuit breaker level (STAGE-4 canonical names)"""
        try:
            if action in ('reduce_size', 'REDUCE'):
                # Reduce position size by parameter (0.7 = 70% of normal)
                return {'size_multiplier': param, 'message': f'Position size reduced to {param*100:.0f}%'}
            
            elif action in ('increase_filters', 'FILTER'):
                # Increase minimum score requirement
                return {'min_score': param, 'message': f'Minimum score increased to {param}/15'}
            
            elif action in ('pause_trading', 'PAUSE'):
                # Pause trading for param seconds
                return {'pause_seconds': param, 'message': f'Trading paused for {param//60} hour(s)'}
            
            elif action in ('emergency_stop', 'EMERGENCY'):
                # Emergency stop - close all
                return {'emergency_stop': True, 'message': 'EMERGENCY STOP ACTIVATED'}
            
            else:
                # Normal operation
                return {'size_multiplier': 1.0, 'message': 'Normal trading'}
        except Exception as e:
            LOG.error(f"[CB] Filter level error: {e}")
            return {'size_multiplier': 1.0, 'message': f'Error: {e}'}
    
    def get_stats(self) -> Dict:
        """Get circuit breaker statistics"""
        return self.stats.copy()
    
    def get_status(self) -> str:
        """Get current circuit breaker status"""
        if self.triggered_level:
            return f"TRIGGERED: {self.triggered_level}"
        return "NORMAL"

class SmartOrderRouter:
    """Route orders with support for multiple order types, fallback logic, and zone entry"""
    def __init__(self):
        self.breakout_entries_missed = {}  # Track missed breakout entries for retry
        self.zone_entry_cache = {}
        
    def calculate_zone_entries(self, current_price: float, resistance: float, support: float, direction: str) -> List[float]:
        """Calculate zone entry levels based on support/resistance"""
        try:
            if direction == 'BUY':
                # Zone entries below current price, above support
                zone_height = (current_price - support) / 3
                zones = [
                    support + zone_height,      # Zone 1: Near support
                    support + (zone_height * 2), # Zone 2: Mid-zone
                    current_price - (zone_height * 0.5)  # Zone 3: Near current
                ]
            else:  # SELL
                # Zone entries above current price, below resistance
                zone_height = (resistance - current_price) / 3
                zones = [
                    resistance - zone_height,      # Zone 1: Near resistance
                    resistance - (zone_height * 2), # Zone 2: Mid-zone
                    current_price + (zone_height * 0.5)  # Zone 3: Near current
                ]
            return [z for z in zones if z > 0]
        except Exception as e:
            LOG.error(f"Zone entry calculation error: {e}")
            return []

    def _should_prefer_limit(self, direction: str, entry_price: float, current_price: float, resistance=None, support=None, df=None):
        """Decide dynamically whether to prefer a limit entry over market.

        Rules are config-driven: prefer limit if entry is close to market, spread is low,
        or entry sits within support/resistance zone. This avoids hardcoded market bias.
        """
        try:
            # If no entry price, cannot prefer limit
            if not entry_price or not current_price:
                return False

            # Proximity check (% of price)
            prox = abs(entry_price - current_price) / max(current_price, 1e-6)
            if prox <= CFG.get('limit_proximity_pct', 0.002):
                return True

            # Spread check
            try:
                spread = MT5.get_spread(CFG['symbol']) or 0.0
                median_spread = STORE.get_median_spread(CFG['symbol']) or 0.0
                if median_spread > 0 and spread <= median_spread * CFG.get('prefer_limit_spread_multiplier', 0.9):
                    return True
            except Exception:
                pass

            # Zone inclusion: if entry between support and resistance and flag set
            if CFG.get('force_limit_on_zone', True) and resistance and support:
                low = min(support, resistance)
                high = max(support, resistance)
                if low <= entry_price <= high:
                    return True

            # Dynamic candle-close confirmation: when the last candle fails to support a market entry,
            # prefer patient limit orders instead of chasing price.
            if CFG.get('dynamic_zone_confirmation', True) and df is not None:
                confirmation_score = IntelligentOrderTypeSelector.candle_confirmation_score(
                    df,
                    direction,
                    CFG.get('confirmation_bars', 1)
                )
                if confirmation_score < 0.35:
                    LOG.debug(f"[ORDER] Weak candle confirmation ({confirmation_score:.2f}), preferring limit")
                    return True
                try:
                    atr = float(df['atr'].iloc[-1]) if 'atr' in df.columns else max(df['high'].iloc[-1] - df['low'].iloc[-1], 1e-6)
                    if IntelligentOrderTypeSelector.prefers_zone_limit(df, direction, atr, ZONE_ANALYZER.get_zone_confluence(df, direction)):
                        LOG.debug(f"[ORDER] Zone structure suggests patient zone entry")
                        return True
                except Exception as e:
                    LOG.debug(f"[ORDER] Zone confirmation check failed: {e}")

            return False
        except Exception as e:
            LOG.debug(f"[ORDER] Prefer-limit decision error: {e}")
            return False

    def has_opposite_open_trades(self, direction: str) -> bool:
        """Detect if there is any open trade in the opposite direction."""
        try:
            if not STORE:
                return False
            open_trades = STORE.open_trades()
            return any(str(t.get('dir', '')).upper() != str(direction).upper() for t in open_trades)
        except Exception as e:
            LOG.debug(f"[ORDER] Opposite trade lookup error: {e}")
            return False
    
    def check_breakout_fallback(self, direction: str, entry_price: float, current_price: float, sl: float, tp: float):
        """Check if breakout entry was missed and handle fallback"""
        try:
            # STAGE-2 FIX: previously chased with market orders on ANY move past entry
            # (even 0.001 - pure spread bleed). Now only chase when price has
            # meaningfully moved: BUY fallback only if current > entry*1.0015,
            # SELL only if current < entry*0.9985. Within the noise band, keep
            # the limit and wait instead of paying the spread.
            if direction == 'BUY' and current_price > entry_price * 1.0015:
                # Price moved meaningfully up past breakout entry - market fallback
                return {'fallback': True, 'reason': 'breakout_passed', 'order_type': 'market', 'price': current_price}
            elif direction == 'SELL' and current_price < entry_price * 0.9985:
                # Price moved meaningfully down past breakout entry - market fallback
                return {'fallback': True, 'reason': 'breakout_passed', 'order_type': 'market', 'price': current_price}
            else:
                # Entry not yet meaningfully passed - keep limit, wait for fill
                return {'fallback': False, 'order_type': 'limit', 'price': entry_price}
        except Exception as e:
            LOG.error(f"Breakout fallback check error: {e}")
            return {'fallback': False, 'order_type': 'market'}
    
    def check_momentum_fallback(self, direction: str, entry_price: float, current_price: float, 
                                df=None, atr_threshold=1.5):
        """Check if momentum is strong enough to skip pullback and go straight to market order"""
        try:
            if df is None or df.empty:
                return {'fallback': False, 'reason': 'no_data'}
            
            last = df.iloc[-1]
            atr = last.get('atr', 1.0)
            
            # Check if price moved significantly in the direction (no pullback happening)
            if direction == 'BUY':
                distance_moved = current_price - entry_price
                if distance_moved >= (atr_threshold * atr):  # Strong momentum, no pullback
                    # Price is already atr_threshold ATRs past entry, strong momentum = take market
                    return {'fallback': True, 'reason': 'strong_momentum_no_pullback', 
                            'order_type': 'market', 'price': current_price}
            elif direction == 'SELL':
                distance_moved = entry_price - current_price
                if distance_moved >= (atr_threshold * atr):  # Strong momentum, no pullback
                    # Price is already atr_threshold ATRs below entry, strong momentum = take market
                    return {'fallback': True, 'reason': 'strong_momentum_no_pullback', 
                            'order_type': 'market', 'price': current_price}
            
            return {'fallback': False, 'reason': 'momentum_insufficient'}
        except Exception as e:
            LOG.warning(f"[ORDER] Momentum fallback check error: {e}")
            return {'fallback': False, 'reason': 'error'}

    def _validate_limit_entry(self, direction: str, entry_price: float, df, order_type: str, support=None, resistance=None):
        """Validate that a limit or zone_limit entry is attached to a real zone or current structure."""
        try:
            if df is None or df.empty:
                return False

            atr = float(df['atr'].iloc[-1]) if 'atr' in df.columns else max(float(df['high'].iloc[-1] - df['low'].iloc[-1]), 1e-6)
            entry_price = float(entry_price)
            max_atr = CFG.get('max_entry_zone_distance_atr', 2.5)

            if order_type == 'zone_limit':
                best_zone = ZONE_ANALYZER.get_best_zone_level(df, direction, max_atr=max_atr)
                return best_zone is not None

            best_zone = ZONE_ANALYZER.get_best_zone_level(df, direction, max_atr=max_atr)
            if best_zone is not None:
                return abs(entry_price - best_zone['level']) <= max_atr * atr

            if support is not None and resistance is not None:
                if direction == 'BUY' and support <= entry_price <= support + (2.0 * atr):
                    return True
                if direction == 'SELL' and resistance - (2.0 * atr) <= entry_price <= resistance:
                    return True

            # If no valid zone exists, allow a close limit if it is very near market price
            proximity_pct = abs(entry_price - df['close'].iloc[-1]) / max(df['close'].iloc[-1], 1e-6)
            return proximity_pct <= CFG.get('max_entry_proximity_pct', 0.003)
        except Exception as e:
            LOG.warning(f"[ORDER] Limit entry validation error: {e}")
            return False
    
    def execute_order(self, direction, volume, entry_price, sl, tp, order_type='market', resistance=None, support=None,
                      pressure_score: float = 0.0, mtf_signal_type: str = 'INTRADAY', prevent_market_fallback: bool = False,
                      df=None):
        """v17.0: Execute order with pressure reconciliation and risk management"""
        # STAGE-7: normalize direction at the router source so every internal
        # branch (SL/TP math, breakout fallback, dispatcher) sees 'BUY'/'SELL'
        direction = normalize_direction(direction)
        if direction not in ('BUY', 'SELL'):
            LOG.error(f"[ORDER] execute_order: unrecognized direction, order REFUSED (fail-closed)")
            return {'tickets': [], 'type_used': 'failed', 'status': 'bad_direction'}
        if CFG["mode"] != 'live':
            return {'tickets': [random.randint(100000, 999999)], 'type_used': order_type, 'status': 'simulated'}

        try:
            current_tick = MT5.get_fresh_tick()
            if not current_tick:
                return {'tickets': [], 'type_used': 'failed', 'status': 'no_tick'}
            
            current_price = current_tick['mid']
            tickets = []
            order_type_used = order_type
            
            # Opposite position protection: avoid direct market execution if an opposing trade already exists
            if prevent_market_fallback and order_type_used == 'market':
                LOG.info("[ORDER] Opposite position protection: converting direct market order into limit attempt")
                order_type_used = 'limit'
                entry_price = entry_price if entry_price else current_price

            # v17.0: PRESSURE RECONCILER - Downgrade market to limit if pressure negative
            if order_type == 'market' and pressure_score < 0 and not prevent_market_fallback:
                LOG.info(f"[v17.0] Pressure reconciliation: Market → Limit (pressure={pressure_score:.1f})")
                order_type_used = 'limit'
                # Limit price at nearest 50% FVG/Order Block (use entry_price as default)
                entry_price = entry_price if entry_price else current_price
            
            # Handle different order types
            if order_type == 'zone_limit':
                # Zone entry: split volume across multiple zone levels
                zones = self.calculate_zone_entries(current_price, resistance or entry_price + 100, 
                                                    support or entry_price - 100, direction)
                if not zones:
                    # Fall back to market if zone calc fails
                    order_type_used = 'market'
                    if prevent_market_fallback:
                        LOG.warning("[ORDER] Opposite position protection: skipping zone_limit → market fallback")
                        return {'tickets': [], 'type_used': 'zone_limit', 'status': 'skipped', 'volume_ordered': volume}
                else:
                    vol_per_zone = round(volume / len(zones), 2)
                    for zone_price in zones:
                        ticket = MT5.place_limit(direction, zone_price, sl, tp, vol_per_zone)
                        if ticket != 0:
                            tickets.append(ticket)
                            LOG.info(f"[ORDER] Zone limit {direction} at {zone_price:.2f}: ticket {ticket}")
                        time.sleep(0.1)
            
            if order_type_used == 'limit' or order_type_used == 'zone_limit' and not tickets:
                # Try limit order, but check fallback conditions first
                
                # Check 1: Did breakout already pass entry level?
                fallback_info = self.check_breakout_fallback(direction, entry_price, current_price, sl, tp)
                
                # Check 2: Is momentum so strong that pullback unlikely? (skip waiting for pullback)
                if not fallback_info['fallback'] and CFG.get("momentum_fallback_enabled", True):
                    momentum_fallback = self.check_momentum_fallback(direction, entry_price, current_price, 
                                                                      df=df, atr_threshold=CFG.get("momentum_fallback_atr_mult", 1.5))
                    if momentum_fallback['fallback']:
                        LOG.info(f"[LIMIT→MARKET] {momentum_fallback['reason']}: Strong momentum detected, skip pullback wait")
                        fallback_info = momentum_fallback
                
                # Validate limit/zone entries against detected zones and price structure
                if order_type_used in ['limit', 'zone_limit'] and not self._validate_limit_entry(direction, entry_price, df, order_type_used, support, resistance):
                    LOG.info(f"[ORDER] Entry validation failed for {order_type_used} {direction} at {entry_price:.2f}; falling back to market")
                    if prevent_market_fallback:
                        LOG.warning("[ORDER] Opposite position protection: skipping invalid limit/zone_limit entry")
                        return {'tickets': [], 'type_used': order_type_used, 'status': 'skipped', 'volume_ordered': volume}
                    order_type_used = 'market'
                    ticket = MT5.place_market(direction, sl, tp, volume)
                    if ticket != 0:
                        tickets.append(ticket)
                elif fallback_info['fallback']:
                        # Fallback to market order
                        LOG.warning(f"[ORDER] Limit→Market fallback: {fallback_info['reason']}")
                        order_type_used = 'market'
                        ticket = MT5.place_market(direction, sl, tp, volume)
                        if ticket != 0:
                            tickets.append(ticket)
                else:
                    # Place limit order, but adjust for spread to ensure fill probability
                    try:
                        current_spread = MT5.get_spread(CFG["symbol"]) or 0.3
                        frac = CFG.get('limit_adjustment_spread_frac', 0.5)
                        limit_adjustment = current_spread * frac
                        
                        if direction == 'BUY':
                            adjusted_entry = entry_price - limit_adjustment  # Slightly lower for BUY limit
                        else:  # SELL
                            adjusted_entry = entry_price + limit_adjustment  # Slightly higher for SELL limit
                        
                        ticket = MT5.place_limit(direction, adjusted_entry, sl, tp, volume)
                        if ticket != 0:
                            tickets.append(ticket)
                            order_type_used = 'limit'
                            LOG.info(f"[ORDER] Limit order placed @ {adjusted_entry:.2f} (adjusted for spread): {fallback_info['reason']}")
                        else:
                            if prevent_market_fallback:
                                LOG.warning("[ORDER] Opposite position protection: limit order failed, skipping market fallback")
                                return {'tickets': [], 'type_used': 'limit', 'status': 'skipped', 'volume_ordered': volume}
                            # Limit order failed, fallback to market
                            LOG.info(f"[ORDER] Limit order failed, falling back to market")
                            order_type_used = 'market'
                            ticket = MT5.place_market(direction, sl, tp, volume)
                            if ticket != 0:
                                tickets.append(ticket)
                    except Exception as e:
                        if prevent_market_fallback:
                            LOG.warning(f"[ORDER] Opposite position protection: limit order placement error: {e}, skipping market fallback")
                            return {'tickets': [], 'type_used': 'limit', 'status': 'skipped', 'volume_ordered': volume}
                        LOG.warning(f"[ORDER] Limit order placement error: {e}, trying market fallback")
                        order_type_used = 'market'
                        ticket = MT5.place_market(direction, sl, tp, volume)
            
            if not tickets and prevent_market_fallback:
                LOG.warning("[ORDER] Opposite position protection active; skipping final market fallback")
                return {'tickets': [], 'type_used': order_type_used, 'status': 'skipped', 'volume_ordered': volume}

            if not tickets and (order_type_used == 'market' or (order_type_used == 'limit' and not tickets)):
                # Final fallback to market order
                ticket = MT5.place_market(direction, sl, tp, volume)
                if ticket != 0:
                    tickets.append(ticket)
                    order_type_used = 'market'
            
            # Apply slicing if configured and volume is large
            if CFG.get("order_slicing", False) and volume > 0.5 and len(tickets) == 1:
                # Don't re-slice if already done through zones
                pass
            
            result = {
                'tickets': tickets,
                'type_used': order_type_used,
                'status': 'success' if tickets else 'failed',
                'count': len(tickets),
                'volume_ordered': volume
            }
            
            LOG.info(f"[ORDER] Executed {order_type_used}: {len(tickets)} tickets, volume {volume}")
            return result
            
        except Exception as e:
            LOG.error(f"Order execution error: {e}")
            return {'tickets': [], 'type_used': 'error', 'status': 'exception', 'error': str(e)}

class QuantumExecutionEngineV18:
    # STAGE-9: was shadowed by the later QuantumExecutionEngine definition (name bound to the last def).
    # Kept verbatim as the QuantumExecutionEngineV18 base class; NOT deleted.
    """TWAP/VWAP/Iceberg execution with fill probability."""
    def __init__(self, mt5_client, router):
        self.mt5 = mt5_client
        self.router = router

    def _unwrap_tickets(self, result):
        if isinstance(result, dict):
            return result.get('tickets', [])
        if isinstance(result, list):
            return result
        return []

    def _tick_speed(self, symbol):
        if not MT5_OK or not self.mt5.ensure_connection():
            return 0.0
        try:
            end = utc_now()
            start = end - timedelta(seconds=60)
            ticks = mt5.copy_ticks_range(symbol, start, end, mt5.COPY_TICKS_ALL)
            return float(len(ticks) / 60.0) if ticks is not None else 0.0
        except Exception:
            return 0.0

    def _fill_probability(self, symbol, df):
        spread_ratio = self.mt5.get_spread_ratio(symbol)
        tick_speed = self._tick_speed(symbol)
        atr_pct = 0.0
        if df is not None and not df.empty:
            d = add_indicators(df)
            if d is not None and not d.empty:
                last = d.iloc[-1]
                atr_pct = (last['atr'] / last['close']) * 100
        z = (tick_speed * 0.05) - (spread_ratio * 20) - (atr_pct * 0.3)
        prob = 1.0 / (1.0 + np.exp(-z))
        return float(max(0.0, min(1.0, prob)))

    def _twap(self, direction, volume, entry_price, sl, tp, prevent_market_fallback=False):
        window = CFG.get("twap_window_sec", 180)
        delay = CFG.get("slice_delay_sec", 2)
        slices = max(1, min(CFG.get("max_slices", 3), int(window / max(1, delay))))
        # STAGE-3 FIX: slices were floored to lot step only, so any volume below
        # min_lot*slices produced all-below-min_lot slices -> every slice rejected
        # (the 0.01-lot death). Now: floor each slice to min_lot, and when the
        # total is too small to split, place a single order at the entry zone
        # with the full volume.
        min_lot = EXNESS.get('min_lot', 0.01)
        step = EXNESS['step']
        vol_per = round((volume / slices) / step) * step
        if vol_per < min_lot:
            if volume < min_lot * slices:
                LOG.info(f"[TWAP] volume {volume} < {min_lot}x{slices} - single order at entry zone instead of TWAP")
                if prevent_market_fallback:
                    result = self.router.execute_order(direction, volume, entry_price, sl, tp, order_type='limit', prevent_market_fallback=True)
                else:
                    tk = self.mt5.place_market(direction, sl, tp, volume)
                    return [tk] if tk else []
                return self._unwrap_tickets(result)
            vol_per = min_lot
        tickets = []
        for _ in range(slices):
            if prevent_market_fallback:
                result = self.router.execute_order(direction, vol_per, entry_price, sl, tp, order_type='limit', prevent_market_fallback=True)
                tks = self._unwrap_tickets(result)
                tickets.extend(tks)
                if not tks:
                    LOG.warning("[TWAP] Opposite position protection: limit slice failed, aborting TWAP")
                    break
            else:
                tk = self.mt5.place_market(direction, sl, tp, vol_per)
                if tk != 0:
                    tickets.append(tk)
            time.sleep(delay)
        return tickets

    def _vwap(self, direction, volume, entry_price, sl, tp, df, prevent_market_fallback=False):
        d = add_indicators(df) if df is not None else None
        vwap = d['vwap'].iloc[-1] if d is not None and not d.empty else entry_price
        
        # Validate VWAP against current market price to detect stale data
        tick = self.mt5.get_fresh_tick() if self.mt5 else None
        if tick and abs(vwap - tick['mid']) / tick['mid'] > 0.01:  # >1% diff = likely stale VWAP
            vwap = entry_price  # Fall back to entry price
        
        use_limit = (direction == 'BUY' and entry_price > vwap) or (direction == 'SELL' and entry_price < vwap)
        price = vwap if use_limit else entry_price
        order_type = 'limit' if use_limit else 'market'
        result = self.router.execute_order(direction, volume, price, sl, tp, order_type=order_type, prevent_market_fallback=prevent_market_fallback)
        return self._unwrap_tickets(result)

    def _iceberg(self, direction, volume, entry_price, sl, tp, prevent_market_fallback=False):
        min_chunk = CFG.get("iceberg_min_chunk", 0.1)
        max_chunk = CFG.get("iceberg_max_chunk", 0.3)
        remaining = volume
        tickets = []
        # STAGE-3 FIX: step-rounding could produce a zero/near-zero final chunk
        # that was silently dropped; now remaining below min lot is handled
        # explicitly instead of vanishing.
        min_lot = EXNESS.get('min_lot', 0.01)
        while remaining > 0:
            if remaining < min_lot:
                LOG.warning(f"[ICEBERG] Remaining {remaining} below min lot {min_lot} - not placeable, stopping")
                break
            chunk = min(remaining, random.uniform(min_chunk, max_chunk))
            chunk = round(chunk / EXNESS['step']) * EXNESS['step']
            if chunk < min_lot:
                chunk = min_lot
            if chunk <= 0:
                break
            if prevent_market_fallback:
                result = self.router.execute_order(direction, chunk, entry_price, sl, tp, order_type='limit', prevent_market_fallback=True)
                tks = self._unwrap_tickets(result)
                tickets.extend(tks)
                if not tks:
                    LOG.warning("[ICEBERG] Opposite position protection: limit slice failed, aborting ICEBERG")
                    break
            else:
                tk = self.mt5.place_market(direction, sl, tp, chunk)
                if tk != 0:
                    tickets.append(tk)
            remaining -= chunk
            time.sleep(CFG.get("slice_delay_sec", 2))
        return tickets

    def execute(self, direction, volume, entry_price, sl, tp, order_mode, df, order_type=None, resistance=None, support=None):
        """Execute order with support for signal-specified order types"""
        # If signal specifies order_type (e.g., 'zone_limit', 'limit'), use it directly
        prevent_market_fallback = self.router.has_opposite_open_trades(direction)
        if prevent_market_fallback:
            LOG.info(f"[EXEC] Opposite open trade detected for {direction}; preventing market fallback")

        if order_type and order_type in ['zone_limit', 'limit']:
            result = self.router.execute_order(
                direction,
                volume,
                entry_price,
                sl,
                tp,
                order_type=order_type,
                resistance=resistance,
                support=support,
                prevent_market_fallback=prevent_market_fallback,
                df=df
            )
            return self._unwrap_tickets(result)
        
        fill_prob = self._fill_probability(CFG["symbol"], df)

        # If caller forced market or limit modes, respect them but still apply opposite-trade protection
        if order_mode == "market":
            result = self.router.execute_order(direction, volume, entry_price, sl, tp, order_type='market', prevent_market_fallback=prevent_market_fallback, df=df)
            return self._unwrap_tickets(result)
        if order_mode == "limit_snipe":
            result = self.router.execute_order(direction, volume, entry_price, sl, tp, order_type='limit', prevent_market_fallback=prevent_market_fallback, df=df)
            return self._unwrap_tickets(result)

        # Large volumes use iceberg regardless of preference
        if volume > 1.0:
            return self._iceberg(direction, volume, entry_price, sl, tp, prevent_market_fallback=prevent_market_fallback)

        # Ask router whether we should prefer a limit entry (zone/proximity/spread)
        current_price = entry_price
        tick = MT5.get_fresh_tick() if MT5 else None
        if tick and 'mid' in tick:
            current_price = tick['mid']
        try:
            prefer_limit = False
            if hasattr(self.router, '_should_prefer_limit'):
                prefer_limit = self.router._should_prefer_limit(direction, entry_price, current_price, resistance, support, df)
        except Exception:
            prefer_limit = False

        # If router prefers limit, attempt a limit first and avoid market fallback when opposite protection is enabled
        if prefer_limit:
            LOG.info(f"[EXEC] Router prefers LIMIT for {direction} (prefer_limit={prefer_limit}, fill_prob={fill_prob:.2f})")
            result = self.router.execute_order(direction, volume, entry_price, sl, tp, order_type='limit', resistance=resistance, support=support, prevent_market_fallback=prevent_market_fallback, df=df)
            tickets = self._unwrap_tickets(result)
            if tickets:
                return tickets
            # if skipped due to protection, return empty
            if result.get('status') == 'skipped':
                return []

        # Otherwise follow adaptive routing based on fill probability
        if fill_prob < CFG.get('fill_prob_twap_threshold', 0.5):
            return self._twap(direction, volume, entry_price, sl, tp, prevent_market_fallback=prevent_market_fallback)
        if fill_prob < CFG.get('fill_prob_vwap_threshold', 0.75):
            return self._vwap(direction, volume, entry_price, sl, tp, df, prevent_market_fallback=prevent_market_fallback)

        # Default: direct market order if nothing else applied
        result = self.router.execute_order(direction, volume, entry_price, sl, tp, order_type='market', prevent_market_fallback=prevent_market_fallback)
        return self._unwrap_tickets(result)

class PenaltyRewardSystemV18:
    # STAGE-9: was shadowed by the later PenaltyRewardSystem definition (name bound to the last def).
    # Kept verbatim as the PenaltyRewardSystemV18 base class; NOT deleted.
    """100-point scoring with penalties and rewards."""
    def _grade(self, score):
        if score >= 90:
            return "A"
        if score >= 80:
            return "B"
        if score >= 70:
            return "C"
        if score >= 60:
            return "D"
        return "F"

    def _tick_speed(self, symbol):
        if not MT5_OK or not MT5.ensure_connection():
            return 0.0
        try:
            end = utc_now()
            start = end - timedelta(seconds=60)
            ticks = mt5.copy_ticks_range(symbol, start, end, mt5.COPY_TICKS_ALL)
            return float(len(ticks) / 60.0) if ticks is not None else 0.0
        except Exception:
            return 0.0

    def score(self, df, signal_dir, ml_conf, correlation, harmonic, smc, spread, regime, mtf_score=None):
        """FIX 3: Unified 0-100 scoring with regime multipliers and news penalties."""
        score = 50.0
        penalties = []
        rewards = []
        d = add_indicators(df)
        if d is None or d.empty:
            return 50.0, 'F', penalties, rewards
        
        # FIX 3: Apply regime-based multipliers from start
        regime_mult = 1.5 if regime == 'TRENDING' else (0.8 if regime == 'RANGING' else 1.0)
        
        last = d.iloc[-1]
        avg_vol = d['volume'].rolling(20).mean().iloc[-1] if 'volume' in d.columns else 0
        if avg_vol > 0 and last.get('volume', 0) < avg_vol:
            score -= 2 * regime_mult; penalties.append("low_volume")  # Reduced from 5 to 2
        median_spread = STORE.get_median_spread(CFG["symbol"])
        if spread and spread > 2 * median_spread:
            score -= 2 * regime_mult; penalties.append("high_spread")  # Reduced from 5 to 2
        if regime in ['LOW_VOL_RANGE', 'RANGING'] and signal_dir in ['BUY', 'SELL']:
            score -= 1.5 * regime_mult; penalties.append("range_regime")  # Reduced from 3 to 1.5
        # FIX 3: News window penalty exactly -2 points (reduced from -4)
        if NEWS.is_news_time():
            score -= 2; penalties.append("news_window")  # Reduced from 4 to 2
        session_now = SESSION_DETECTOR.current_session()
        if session_now == "ASIAN":
            score -= 1 * regime_mult; penalties.append("asian_session")  # Reduced from 2 to 1
        if session_now == "NY_CLOSE":
            score -= 2 * regime_mult; penalties.append("ny_close")  # Reduced from 4 to 2
        if utc_now().weekday() == 4 and utc_now().hour >= CFG.get("friday_close_hour", 20):
            score -= 2 * regime_mult; penalties.append("friday_close")  # Reduced from 5 to 2
        # FIXED: Correlation logic for XAU/DXY (negative correlation is expected)
        # SELL is GOOD when correlation is negative (DXY strong, XAU weak)
        # BUY is GOOD when correlation is positive (DXY weak, XAU strong)
        if correlation is not None and signal_dir == 'BUY' and correlation < -0.5:
            # Penalize BUY when correlation too negative (DXY too strong)
            score -= 2 * regime_mult; penalties.append("corr_mismatch")
        if correlation is not None and signal_dir == 'SELL' and correlation > 0.3:
            # Penalize SELL when correlation too positive (DXY too weak)
            score -= 2 * regime_mult; penalties.append("corr_mismatch")
        if last.get('rsi', 50) > 70 and signal_dir == 'BUY':
            score -= 2; penalties.append("overbought")  # Reduced from 4 to 2
        if last.get('rsi', 50) < 30 and signal_dir == 'SELL':
            score -= 2; penalties.append("oversold")  # Reduced from 4 to 2
        if last.get('ema9', last['close']) < last.get('ema21', last['close']) and signal_dir == 'BUY':
            score -= 1.5; penalties.append("counter_trend")  # Reduced from 3 to 1.5
        if last.get('ema9', last['close']) > last.get('ema21', last['close']) and signal_dir == 'SELL':
            score -= 1.5; penalties.append("counter_trend")  # Reduced from 3 to 1.5
        if calc_adx(d).iloc[-1] < 20:
            score -= 2; penalties.append("choppy")  # Reduced from 3 to 2
        if self._tick_speed(CFG["symbol"]) < 5:
            score -= 1; penalties.append("low_liquidity")  # Reduced from 3 to 1

        if harmonic:
            score += 5 * regime_mult; rewards.append("harmonic")
        if smc and smc.get('msb'):
            score += 4 * regime_mult; rewards.append("smc_msb")
        if ml_conf > 0.8:
            score += 4 * regime_mult; rewards.append("ml_high_conf")
        
        # FIX 2: DXY Correlation (Yield Proxy) - Momentum-based rewards/penalties
        dxy_momentum = self._get_dxy_1h_momentum()
        if dxy_momentum is not None:
            if dxy_momentum > 0:  # Dollar strengthening
                if signal_dir == 'SELL':
                    score += 5.0; rewards.append("dxy_momentum_sell")
                elif signal_dir == 'BUY':
                    score -= 5.0; penalties.append("dxy_momentum_penalty")
            elif dxy_momentum < 0:  # Dollar weakening
                if signal_dir == 'BUY':
                    score += 5.0; rewards.append("dxy_momentum_buy")
                elif signal_dir == 'SELL':
                    score -= 5.0; penalties.append("dxy_momentum_penalty")
        
        # FIX 3: Smart Money (FVG Detection) - Fair Value Gap reward
        fvg_detected = self._detect_fvg(d, signal_dir)
        if fvg_detected:
            score += 4.0; rewards.append("fvg_signal")
        
        # FIX 3: Standardized correlation alignment reward exactly +3 points
        if correlation is not None and signal_dir == 'BUY' and correlation < -0.7:
            score += 3; rewards.append("corr_align")
        if correlation is not None and signal_dir == 'SELL' and correlation > 0.7:
            score += 3; rewards.append("corr_align")
        if session_now in ["LONDON", "NY", "LONDON_NY", "ASIAN_LONDON"]:
            score += 2 * regime_mult; rewards.append("session_align")
        if avg_vol > 0 and last.get('volume', 0) > 2 * avg_vol:
            score += 3 * regime_mult; rewards.append("volume_surge")
        if calc_adx(d).iloc[-1] > 30:
            score += 3 * regime_mult; rewards.append("strong_trend")
        if spread and spread < STORE.get_median_spread(CFG["symbol"]) * 0.8:
            score += 2 * regime_mult; rewards.append("low_spread")
        if mtf_score is not None and mtf_score > 1.0:
            score += 3 * regime_mult; rewards.append("mtf_confluence")

        score = max(0.0, min(100.0, score))
        grade = self._grade(score)
        return score, grade, penalties, rewards
    
    def _get_dxy_1h_momentum(self):
        """FIX 2: Get DXY 1H momentum (positive = Dollar strengthening)."""
        try:
            dxy_symbol = CFG.get("macro_symbols", {}).get("DXY", "DXYm")
            if not MT5.ensure_connection():
                return None
            df = MT5.fetch(dxy_symbol, 'H1', 50)
            if df is None or len(df) < 10:
                return None
            # Calculate 1H momentum: current close - close 10 bars ago
            close = df['close'].values
            momentum = close[-1] - close[-10]
            return momentum
        except Exception as e:
            LOG.debug(f"[DXY] Momentum calc failed: {e}")
            return None
    
    def _detect_fvg(self, df, signal_dir):
        """FIX 3: Detect Fair Value Gap (SMC). Bullish: Low[i] > High[i+2], Bearish: High[i] < Low[i+2]."""
        try:
            if df is None or len(df) < 4:
                return False
            
            low = df['low'].values
            high = df['high'].values
            
            # Check last 3 candles for FVG
            i = len(df) - 1  # Current candle
            
            if signal_dir == 'BUY':
                # Bullish FVG: Low of current candle > High of candle 2 bars ago
                if i >= 2 and low[i] > high[i - 2]:
                    return True
            elif signal_dir == 'SELL':
                # Bearish FVG: High of current candle < Low of candle 2 bars ago
                if i >= 2 and high[i] < low[i - 2]:
                    return True
            
            return False
        except Exception as e:
            LOG.debug(f"[FVG] Detection failed: {e}")
            return False

class QuantumRiskManagerV18:
    # STAGE-9: was shadowed by the later QuantumRiskManager definition (name bound to the last def).
    # Kept verbatim as the QuantumRiskManagerV18 base class; NOT deleted.
    """Optimal f, Monte Carlo, Risk of Ruin, and correlation heat."""
    def _trade_returns(self, limit=500):
        trades = STORE.get_all_closed_trades()
        returns = []
        for t in trades[-limit:]:
            r = t.get('r_mult')
            if r is None:
                pnl = t.get('pnl', 0.0)
                r = pnl / max(1e-6, abs(t.get('entry', 1.0)))
            returns.append(safe_float(r))
        return [r for r in returns if r != 0]

    def optimal_f(self):
        rets = self._trade_returns()
        if len(rets) < 20:
            return 0.05
        best_f = 0.05
        best_g = -1e9
        for f in np.arange(0.01, CFG.get("optimal_f_max", 0.3) + 0.001, 0.01):
            growth = 0.0
            valid = True
            for r in rets:
                if 1 + f * r <= 0:
                    valid = False
                    break
                growth += np.log(1 + f * r)
            if valid and growth > best_g:
                best_g = growth
                best_f = f
        return float(best_f)

    def risk_of_ruin(self):
        trades = STORE.get_all_closed_trades()
        pnls = [t.get('pnl', 0.0) for t in trades if t.get('pnl') is not None]
        wins = [p for p in pnls if p > 0]
        losses = [abs(p) for p in pnls if p < 0]
        if not wins or not losses:
            return 0.0
        p = len(wins) / max(1, len(pnls))
        q = 1 - p
        payoff = (np.mean(wins) / np.mean(losses)) if np.mean(losses) > 0 else 1.0
        if p <= q:
            return 1.0
        edge = p - (q / payoff)
        ruin = (q / p) ** max(1, int(1 / max(1e-6, edge)))
        return float(min(1.0, max(0.0, ruin)))

    def monte_carlo(self, iters=1000, horizon=200):
        rets = self._trade_returns()
        if len(rets) < 20:
            return {'mean': 0.0, 'p5': 0.0, 'max_dd': 0.0}
        rng = np.random.default_rng()
        terminal = []
        max_dds = []
        for _ in range(iters):
            equity = 1.0
            peak = 1.0
            max_dd = 0.0
            for r in rng.choice(rets, size=min(horizon, len(rets)), replace=True):
                equity *= (1 + 0.01 * r)
                peak = max(peak, equity)
                max_dd = max(max_dd, (peak - equity) / peak)
            terminal.append(equity)
            max_dds.append(max_dd)
        return {
            'mean': float(np.mean(terminal)),
            'p5': float(np.percentile(terminal, 5)),
            'max_dd': float(np.mean(max_dds))
        }

    def correlation_matrix(self):
        symbols = [CFG["symbol"]] + [s for s in CFG.get("macro_symbols", {}).values() if s]
        dfs = {}
        for sym in symbols:
            df = MT5.fetch(sym, 'H1', 200)
            if df is not None and not df.empty:
                dfs[sym] = df['close'].pct_change().dropna()
        if len(dfs) < 2:
            return {}
        df = pd.DataFrame(dfs)
        return df.corr().to_dict()

class SignalOutcomeTrackerV18:
    # STAGE-9: was shadowed by the later SignalOutcomeTracker definition (name bound to the last def).
    # Kept verbatim as the SignalOutcomeTrackerV18 base class; NOT deleted.
    """Records outcomes for attribution and learning."""
    def record(self, trade_id, pnl, r_mult, strategy=None, regime=None, session=None, reason=None):
        STORE.log_signal_outcome(trade_id, pnl, r_mult, strategy, regime, session, reason)
    
    def generate_optimization_insights(self):
        """Generate strategy performance insights for optimization"""
        try:
            rows = STORE.conn.execute(
                "SELECT strategy, pnl FROM signal_outcomes WHERE strategy IS NOT NULL ORDER BY ts DESC LIMIT 100"
            ).fetchall()
            
            if not rows:
                return {'best_strategy': 'unknown', 'best_win_rate': 0.0, 'best_avg_pnl': 0.0}
            
            strategy_stats = {}
            for strategy, pnl in rows:
                if strategy not in strategy_stats:
                    strategy_stats[strategy] = {'wins': 0, 'losses': 0, 'total_pnl': 0.0, 'count': 0}
                
                stats = strategy_stats[strategy]
                if pnl and pnl > 0:
                    stats['wins'] += 1
                elif pnl:
                    stats['losses'] += 1
                stats['total_pnl'] += pnl or 0.0
                stats['count'] += 1
            
            # Find best strategy
            best_strategy = 'unknown'
            best_win_rate = 0.0
            best_avg_pnl = 0.0
            
            for strat, stats in strategy_stats.items():
                if stats['count'] > 0:
                    win_rate = stats['wins'] / stats['count']
                    avg_pnl = stats['total_pnl'] / stats['count']
                    
                    # Prefer strategy with best win rate
                    if win_rate > best_win_rate or (win_rate == best_win_rate and avg_pnl > best_avg_pnl):
                        best_win_rate = win_rate
                        best_avg_pnl = avg_pnl
                        best_strategy = strat
            
            return {
                'best_strategy': best_strategy,
                'best_win_rate': best_win_rate,
                'best_avg_pnl': best_avg_pnl,
                'all_strategies': strategy_stats
            }
        except Exception as e:
            LOG.error(f"Error generating optimization insights: {e}")
            return {'best_strategy': 'unknown', 'best_win_rate': 0.0, 'best_avg_pnl': 0.0}

class PerformanceAttribution:
    """PnL attribution by time/regime/strategy/session."""
    def by_dimension(self):
        rows = STORE.conn.execute(
            "SELECT strategy, regime, session, pnl FROM signal_outcomes"
        ).fetchall()
        summary = {}
        for strat, reg, sess, pnl in rows:
            key = (strat or "unknown", reg or "unknown", sess or "unknown")
            summary.setdefault(key, []).append(pnl or 0.0)
        return {k: {'count': len(v), 'pnl': sum(v)} for k, v in summary.items()}

class QuantumChartGenerator:
    """Plotly-based chart with indicators and annotations."""
    def generate(self, data, sig):
        df = None
        if isinstance(data, dict):
            sig_tf = sig.get('tf') if sig else None
            if sig_tf and sig_tf in data:
                df = data.get(sig_tf)
            else:
                df = data.get(CFG["timeframes"][0]) or next(iter(data.values()), None)
        else:
            df = data

        if not PLOTLY_OK or df is None or df.empty or not CFG.get('chart_enhanced_enabled', True):
            return None

        d = add_indicators(df.tail(500))
        if d is None or d.empty:
            return None

        # Prepare figure with volume subplot
        from plotly.subplots import make_subplots
        fig = make_subplots(rows=2, cols=1, shared_xaxes=True, row_heights=[0.75, 0.25], vertical_spacing=0.02)

        # Candles
        fig.add_trace(go.Candlestick(x=d.index, open=d['open'], high=d['high'], low=d['low'], close=d['close'], name='Price'), row=1, col=1)

        # EMA ribbons
        for ema in ['ema9', 'ema21', 'ema50']:
            if ema in d.columns:
                fig.add_trace(go.Scatter(x=d.index, y=d[ema], mode='lines', name=ema.upper(), line={'width':1}), row=1, col=1)

        # VWAP if available or requested
        if CFG.get('chart_show_vwap', True) and 'vwap' in d.columns:
            fig.add_trace(go.Scatter(x=d.index, y=d['vwap'], line={'dash':'dash'}, name='VWAP', marker={'color':'orange'}), row=1, col=1)

        # Ichimoku cloud shading
        if CFG.get('chart_show_ichimoku', True):
            try:
                ich = ICHIMOKU.analyze(d)
                if ich and ich.get('cloud_top') is not None and ich.get('cloud_bottom') is not None:
                    cloud_top = ich['cloud_top']
                    cloud_bottom = ich['cloud_bottom']
                    fig.add_shape(type='rect', x0=d.index[0], x1=d.index[-1], y0=cloud_bottom, y1=cloud_top,
                                  fillcolor='LightSkyBlue', opacity=0.12, line_width=0, row=1, col=1)
            except Exception:
                pass

        # Volume bars
        if CFG.get('chart_show_volume', True) and 'volume' in d.columns:
            fig.add_trace(go.Bar(x=d.index, y=d['volume'], marker={'color':'lightgrey'}, name='Volume'), row=2, col=1)

        # Annotations for entry / SL / TP
        if sig:
            entry = sig.get('entry')
            sl = sig.get('sl')
            tp = sig.get('tp')
            txt = sig.get('strategy') or sig.get('signal_type') or 'signal'
            if entry:
                fig.add_trace(go.Scatter(x=[d.index[-1]], y=[entry], text=[f"Entry {entry:.2f}"], mode='markers+text', marker=dict(color='Blue', size=10), name='Entry'), row=1, col=1)
                fig.add_hline(y=entry, line_color='blue', row=1, col=1)
            if sl:
                fig.add_hline(y=sl, line_color='red', row=1, col=1)
            if tp:
                fig.add_hline(y=tp, line_color='green', row=1, col=1)

        # Layout tweaks for clarity
        fig.update_layout(height=CFG.get('chart_height', 700), width=CFG.get('chart_width', 1200), template='plotly_white', showlegend=True)
        fig.update_xaxes(rangeslider_visible=False)

        try:
            img_bytes = fig.to_image(format='png')
            return img_bytes
        except Exception as e:
            try:
                import plotly.io as pio
                img_bytes = pio.to_image(fig, format='png')
                return img_bytes
            except Exception as e2:
                LOG.warning(f"[CHART] Failed to render image: {e} / {e2}")
                return None

# Detector classes (same as v12.0)
class RegimeDetector:
    def detect(self, df):
        d = add_indicators(df)
        last = d.iloc[-1]
        atr_pct = (last['atr'] / last['close']) * 100
        adx = calc_adx(d).iloc[-1] if len(d) > 30 else 20
        bb_width = last.get('bb_width', 0.01)
        vol = d['close'].pct_change().rolling(20).std().iloc[-1]
        
        if adx > 25 and atr_pct < 1.5:
            return 'TRENDING'
        elif adx < 20 and atr_pct < 1.0 and bb_width < 0.01:
            return 'RANGING'
        elif atr_pct > 2.0 or vol > 0.02:
            return 'VOLATILE'
        else:
            return 'TRANSITIONAL'

REGIME = RegimeDetector()

