# FEATURE 1: MULTI-TIMEFRAME SYNCHRONIZATION (Higher TF Gate)
# ============================================================================
class MultiTimeframeGate:
    """Ensures M5/M15 entries align with H1+ trend direction."""
    
    def __init__(self):
        self.tf_hierarchy = {
            'M1': ['M5', 'M15', 'H1', 'H4', 'D1'],
            'M5': ['M15', 'H1', 'H4', 'D1'],
            'M15': ['H1', 'H4', 'D1'],
            'H1': ['H4', 'D1'],
            'H4': ['D1'],
            'D1': []
        }
    
    def get_trend_direction(self, df, direction_type='ema'):
        """Get trend direction: 'UP', 'DOWN', or 'NEUTRAL'."""
        if df is None or len(df) < 50:
            return 'NEUTRAL'
        
        try:
            d = add_indicators(df)
            last = d.iloc[-1]
            
            if direction_type == 'ema':
                # EMA-based: 9 > 21 = UP, 9 < 21 = DOWN
                if last['ema9'] > last['ema21']:
                    return 'UP'
                elif last['ema9'] < last['ema21']:
                    return 'DOWN'
                else:
                    return 'NEUTRAL'
            elif direction_type == 'adx':
                # ADX-based: strong trend vs weak
                adx = calc_adx(d).iloc[-1]
                if last['ema9'] > last['ema21'] and adx > 25:
                    return 'UP'
                elif last['ema9'] < last['ema21'] and adx > 25:
                    return 'DOWN'
                else:
                    return 'NEUTRAL'
        except Exception as e:
            LOG.warning(f"[MTF] Trend detection failed: {e}")
            return 'NEUTRAL'
    
    def check_higher_tf_gate(self, signal, current_tf, mt5_feed=None):
        """
        Check if signal aligns with higher timeframe trend.
        Returns: {'allowed': True/False, 'reason': str, 'higher_tf_trend': str}
        """
        if mt5_feed is None or current_tf not in self.tf_hierarchy:
            return {'allowed': True, 'reason': 'No MTF gate', 'higher_tf_trend': 'NEUTRAL'}
        
        signal_dir = 'UP' if signal.get('dir') in ['BUY', 1] else 'DOWN'
        higher_tfs = self.tf_hierarchy.get(current_tf, [])
        
        if not higher_tfs:
            return {'allowed': True, 'reason': 'No higher TF', 'higher_tf_trend': 'NEUTRAL'}
        
        # Check H1 (most important) first
        check_tfs = [tf for tf in higher_tfs if tf in ['H1', 'H4', 'D1']][:1]  # Check highest available
        
        for check_tf in check_tfs:
            try:
                df_higher = mt5_feed.fetch(current_tf=check_tf, bars=300)
                if df_higher is not None and len(df_higher) > 50:
                    trend = self.get_trend_direction(df_higher)
                    
                    # Gate: only allow if aligned with higher TF
                    if (signal_dir == 'UP' and trend == 'UP') or (signal_dir == 'DOWN' and trend == 'DOWN'):
                        return {'allowed': True, 'reason': f'{check_tf} aligned', 'higher_tf_trend': trend}
                    else:
                        return {'allowed': False, 'reason': f'{check_tf} against signal', 'higher_tf_trend': trend}
            except Exception as e:
                LOG.warning(f"[MTF] Failed to check {check_tf}: {e}")
                continue
        
        return {'allowed': True, 'reason': 'Data unavailable', 'higher_tf_trend': 'NEUTRAL'}

MTF_GATE = MultiTimeframeGate()

