# FEATURE 2 & 3: ICHIMOKU CLOUD & ORDER IMBALANCE ENHANCEMENTS
# ============================================================================
class IchimokuCloudAnalyzer:
    """Ichimoku-based support/resistance and trend confirmation."""
    
    def analyze(self, df):
        """Analyze Ichimoku cloud zones for support/resistance."""
        if df is None or len(df) < 52:
            return {'senkou_a': None, 'senkou_b': None, 'kumo_twist': False, 'cloud_strength': 0.0}
        
        try:
            d = add_indicators(df)
            last = d.iloc[-1]
            
            # Cloud components (already calculated in add_indicators)
            senkou_a = last.get('senkou_a', last['close'])
            senkou_b = last.get('senkou_b', last['close'])
            tenkan = last.get('tenkan', last['close'])
            kijun = last.get('kijun', last['close'])
            chikou = last.get('chikou', last['close'])
            
            # Kumo Twist: A and B lines cross (early reversal signal)
            kumo_twist = False
            if len(d) >= 2:
                prev = d.iloc[-2]
                senkou_a_prev = prev.get('senkou_a', prev['close'])
                senkou_b_prev = prev.get('senkou_b', prev['close'])
                if (senkou_a_prev <= senkou_b_prev and senkou_a > senkou_b) or \
                   (senkou_a_prev >= senkou_b_prev and senkou_a < senkou_b):
                    kumo_twist = True
            
            # Cloud strength: how thick is the cloud?
            cloud_thickness = abs(senkou_a - senkou_b)
            price_to_cloud = abs(last['close'] - max(senkou_a, senkou_b))
            cloud_strength = 1.0 - min(1.0, price_to_cloud / (cloud_thickness + 1e-6))
            
            # Chikou span confirmation: price above chikou = bullish
            chikou_bullish = last['close'] > chikou
            
            return {
                'senkou_a': senkou_a,
                'senkou_b': senkou_b,
                'cloud_top': max(senkou_a, senkou_b),
                'cloud_bottom': min(senkou_a, senkou_b),
                'kumo_twist': kumo_twist,
                'cloud_strength': cloud_strength,
                'chikou_bullish': chikou_bullish,
                'tenkan': tenkan,
                'kijun': kijun
            }
        except Exception as e:
            LOG.warning(f"[Ichimoku] Analysis failed: {e}")
            return {'senkou_a': None, 'senkou_b': None, 'kumo_twist': False, 'cloud_strength': 0.0}

ICHIMOKU = IchimokuCloudAnalyzer()

class OrderImbalanceAnalyzer:
    """Detects buy/sell volume imbalance (buy vs sell pressure)."""
    
    def analyze(self, df):
        """Analyze order flow imbalance."""
        if df is None or len(df) < 20:
            return {'buy_pressure': 0.5, 'sell_pressure': 0.5, 'imbalance': 0.0, 'signal': 'NEUTRAL'}
        
        try:
            d = df.copy()
            
            # Calculate order flow: close > open = buying, close < open = selling
            d['body_up'] = (d['close'] > d['open']).astype(float)
            d['body_size'] = (d['close'] - d['open']).abs()
            d['total_range'] = d['high'] - d['low']
            
            # Buy pressure: close-open relative to candle range (up candle pressure)
            d['buy_vol'] = d['body_up'] * d['body_size'] * (d['volume'] if 'volume' in d.columns else 1.0)
            d['sell_vol'] = (1 - d['body_up']) * d['body_size'] * (d['volume'] if 'volume' in d.columns else 1.0)
            
            # 20-bar average
            buy_pressure = d['buy_vol'].rolling(20).mean().iloc[-1]
            sell_pressure = d['sell_vol'].rolling(20).mean().iloc[-1]
            total_pressure = buy_pressure + sell_pressure + 1e-6
            
            buy_pct = buy_pressure / total_pressure
            sell_pct = sell_pressure / total_pressure
            imbalance = buy_pct - sell_pct  # +1 = all buying, -1 = all selling
            
            # Signal
            if imbalance > 0.3:
                signal = 'STRONG_BUY'
            elif imbalance > 0.1:
                signal = 'BUY'
            elif imbalance < -0.3:
                signal = 'STRONG_SELL'
            elif imbalance < -0.1:
                signal = 'SELL'
            else:
                signal = 'NEUTRAL'
            
            return {
                'buy_pressure': buy_pct,
                'sell_pressure': sell_pct,
                'imbalance': imbalance,
                'signal': signal
            }
        except Exception as e:
            LOG.warning(f"[OrderImbalance] Analysis failed: {e}")
            return {'buy_pressure': 0.5, 'sell_pressure': 0.5, 'imbalance': 0.0, 'signal': 'NEUTRAL'}

ORDER_IMBALANCE = OrderImbalanceAnalyzer()

