# FEATURE 4: ENHANCED RISK/REWARD RATIO FILTER
# ============================================================================
def calculate_reward_risk_ratio(entry, tp, sl):
    """Calculate reward/risk ratio. Returns ratio or None if invalid."""
    try:
        risk = abs(entry - sl)
        reward = abs(tp - entry)
        if risk > 0:
            return reward / risk
        return 0.0
    except:
        return 0.0

def validate_rr_ratio(rr, min_ratio=2.0):
    """Check if RR ratio meets minimum threshold."""
    return rr >= min_ratio

