# FEATURE 6: STOCHASTIC RSI DIVERGENCE DETECTOR
# ============================================================================
class StochasticRSIDivergenceDetector:
    """Detects hidden and regular divergences using Stochastic RSI."""
    
    def calculate_stoch_rsi(self, df, rsi_period=14, stoch_period=14):
        """Calculate Stochastic RSI (K and D lines)."""
        if df is None or len(df) < max(rsi_period + stoch_period, 50):
            return None
        
        try:
            d = add_indicators(df)
            rsi = d['rsi'].values
            
            # Stochastic calculation on RSI
            rsi_low = pd.Series(rsi).rolling(window=stoch_period).min()
            rsi_high = pd.Series(rsi).rolling(window=stoch_period).max()
            
            k_line = 100 * (pd.Series(rsi) - rsi_low) / (rsi_high - rsi_low + 1e-6)
            d_line = k_line.rolling(window=3).mean()
            
            return {
                'k_line': k_line.values,
                'd_line': d_line.values,
                'rsi': rsi
            }
        except Exception as e:
            LOG.warning(f"[StochRSI] Calculation failed: {e}")
            return None
    
    def detect_divergence(self, df):
        """
        Detect bullish/bearish divergences.
        Bullish: Price lower low, but RSI higher low (reversal signal)
        Bearish: Price higher high, but RSI lower high (reversal signal)
        """
        if df is None or len(df) < 50:
            return {'divergence_type': 'NONE', 'confidence': 0.0}
        
        try:
            stoch_data = self.calculate_stoch_rsi(df)
            if stoch_data is None:
                return {'divergence_type': 'NONE', 'confidence': 0.0}
            
            k_line = stoch_data['k_line']
            rsi = stoch_data['rsi']
            closes = df['close'].values
            lows = df['low'].values
            highs = df['high'].values
            
            # Find last 2 significant lows/highs
            if len(closes) < 20:
                return {'divergence_type': 'NONE', 'confidence': 0.0}
            
            # Bullish divergence: price makes lower low, but Stoch RSI makes higher low
            price_min_idx = np.argmin(lows[-20:]) + (len(lows) - 20)
            price_min_idx2 = np.argmin(lows[-40:-20]) + (len(lows) - 40)
            
            if price_min_idx > price_min_idx2:
                price_low1 = lows[price_min_idx2]
                price_low2 = lows[price_min_idx]
                rsi_low1 = k_line[price_min_idx2]
                rsi_low2 = k_line[price_min_idx]
                
                if price_low2 < price_low1 and rsi_low2 > rsi_low1 and rsi_low2 < 30:
                    confidence = min(1.0, abs(rsi_low2 - rsi_low1) / 20)
                    return {'divergence_type': 'BULLISH', 'confidence': confidence, 'signal': 'BUY'}
            
            # Bearish divergence: price makes higher high, but Stoch RSI makes lower high
            price_max_idx = np.argmax(highs[-20:]) + (len(highs) - 20)
            price_max_idx2 = np.argmax(highs[-40:-20]) + (len(highs) - 40)
            
            if price_max_idx > price_max_idx2:
                price_high1 = highs[price_max_idx2]
                price_high2 = highs[price_max_idx]
                rsi_high1 = k_line[price_max_idx2]
                rsi_high2 = k_line[price_max_idx]
                
                if price_high2 > price_high1 and rsi_high2 < rsi_high1 and rsi_high2 > 70:
                    confidence = min(1.0, abs(rsi_high1 - rsi_high2) / 20)
                    return {'divergence_type': 'BEARISH', 'confidence': confidence, 'signal': 'SELL'}
            
            return {'divergence_type': 'NONE', 'confidence': 0.0}
        except Exception as e:
            LOG.warning(f"[Divergence] Detection failed: {e}")
            return {'divergence_type': 'NONE', 'confidence': 0.0}

STOCH_RSI = StochasticRSIDivergenceDetector()

def calc_adx(df, period=14):
    high = df['high']
    low = df['low']
    close = df['close']
    
    up = high.diff()
    down = -low.diff()
    
    plus_dm = np.where((up > down) & (up > 0), up, 0.0)
    minus_dm = np.where((down > up) & (down > 0), down, 0.0)
    
    tr1 = high - low
    tr2 = abs(high - close.shift())
    tr3 = abs(low - close.shift())
    tr = pd.concat([tr1, tr2, tr3], axis=1).max(axis=1)
    
    atr = tr.rolling(window=period).mean()
    
    plus_di = 100 * pd.Series(plus_dm).rolling(window=period).sum() / (atr * period + 1e-12)
    minus_di = 100 * pd.Series(minus_dm).rolling(window=period).sum() / (atr * period + 1e-12)
    
    dx = 100 * abs(plus_di - minus_di) / (plus_di + minus_di + 1e-12)
    return dx.rolling(window=period).mean()

class HarmonicDetector:
    def detect(self, df):
        if len(df) < 100 or not SCIPY_OK:
            return None
        
        try:
            highs = df['high'].values
            lows = df['low'].values
            
            max_idx = argrelextrema(highs, np.greater, order=5)[0]
            min_idx = argrelextrema(lows, np.less, order=5)[0]
            
            if len(max_idx) < 3 or len(min_idx) < 2:
                return None
            
            peaks = sorted(
                [(i, highs[i]) for i in max_idx] +
                [(i, lows[i]) for i in min_idx],
                key=lambda x: x[0]
            )
            
            if len(peaks) < 5:
                return None
            
            for i in range(len(peaks) - 4):
                X = peaks[i]
                A = peaks[i + 1]
                B = peaks[i + 2]
                C = peaks[i + 3]
                D = peaks[i + 4]
                
                XA = abs(A[1] - X[1])
                AB = abs(B[1] - A[1])
                BC = abs(C[1] - B[1])
                
                if XA > 0 and 0.58 <= AB / XA <= 0.68 and AB > 0:
                    if 0.78 <= BC / AB <= 0.88 and D[1] > A[1]:
                        window_df = add_indicators(df.iloc[:D[0] + 1])
                        rsi = window_df['rsi'].iloc[-1]
                        volume = df['volume'].iloc[D[0]]
                        avg_vol = df['volume'].iloc[max(0, D[0] - 20):D[0]].mean()
                        
                        if rsi > 70 or volume > 1.5 * avg_vol:
                            return {
                                'type': 'bull',
                                'pattern': 'Gartley',
                                'D_idx': D[0],
                                'D_price': D[1]
                            }
            
            return None
        except Exception:
            return None

class HarmonicPatternDetector:
    """Detects multiple harmonic patterns using ratio rules."""
    def __init__(self, tol=0.05):
        self.tol = tol

    def _near(self, val, target):
        return abs(val - target) <= self.tol

    def _in(self, val, low, high):
        return low - self.tol <= val <= high + self.tol

    def _extrema(self, df):
        if not SCIPY_OK or df is None or len(df) < 50:
            return []
        highs = df['high'].values
        lows = df['low'].values
        max_idx = argrelextrema(highs, np.greater, order=5)[0]
        min_idx = argrelextrema(lows, np.less, order=5)[0]
        points = sorted(
            [(i, highs[i]) for i in max_idx] +
            [(i, lows[i]) for i in min_idx],
            key=lambda x: x[0]
        )
        return points[-10:]

    def _ratios(self, X, A, B, C, D):
        XA = abs(A - X)
        AB = abs(B - A)
        BC = abs(C - B)
        CD = abs(D - C)
        AD = abs(D - X)
        return {
            'ab_xa': AB / XA if XA else 0.0,
            'bc_ab': BC / AB if AB else 0.0,
            'cd_bc': CD / BC if BC else 0.0,
            'ad_xa': AD / XA if XA else 0.0
        }

    def _match_patterns(self, ratios):
        r = ratios
        patterns = []
        if self._near(r['ab_xa'], 0.618) and self._in(r['bc_ab'], 0.382, 0.886) and \
           self._in(r['cd_bc'], 1.13, 1.618) and self._near(r['ad_xa'], 0.786):
            patterns.append("GARTLEY")
        if self._in(r['ab_xa'], 0.382, 0.5) and self._in(r['bc_ab'], 0.382, 0.886) and \
           self._in(r['cd_bc'], 1.618, 2.618) and self._near(r['ad_xa'], 0.886):
            patterns.append("BAT")
        if self._near(r['ab_xa'], 0.786) and self._in(r['bc_ab'], 0.382, 0.886) and \
           self._in(r['cd_bc'], 1.618, 2.618) and self._in(r['ad_xa'], 1.27, 1.618):
            patterns.append("BUTTERFLY")
        if self._in(r['ab_xa'], 0.382, 0.618) and self._in(r['bc_ab'], 0.382, 0.886) and \
           self._in(r['cd_bc'], 2.24, 3.618) and self._near(r['ad_xa'], 1.618):
            patterns.append("CRAB")
        if self._in(r['ab_xa'], 1.13, 1.618) and self._in(r['bc_ab'], 1.13, 1.618) and \
           self._in(r['cd_bc'], 0.886, 1.13):
            patterns.append("SHARK")
        if self._in(r['ab_xa'], 0.382, 0.618) and self._in(r['bc_ab'], 1.13, 1.414) and \
           self._near(r['ad_xa'], 0.786):
            patterns.append("CYPHER")
        if self._in(r['bc_ab'], 0.382, 0.886) and self._near(r['cd_bc'], 1.0):
            patterns.append("ABCD")
        return patterns

    def detect_all(self, df):
        points = self._extrema(df)
        if len(points) < 5:
            return []
        patterns = []
        for i in range(len(points) - 4):
            X, A, B, C, D = [p[1] for p in points[i:i+5]]
            ratios = self._ratios(X, A, B, C, D)
            matches = self._match_patterns(ratios)
            for name in matches:
                direction = "bull" if D < C else "bear"
                patterns.append({
                    'pattern': name,
                    'type': direction,
                    'D_price': D,
                    'ratios': ratios
                })
        return patterns[-3:]

    def detect(self, df):
        pats = self.detect_all(df)
        return pats[-1] if pats else None

HARMONIC = HarmonicPatternDetector()

class SmartMoneyDetector:
    """Detect order blocks, FVGs, liquidity pools, and structure breaks."""
    def _swing_levels(self, df, order=5):
        highs = df['high'].values
        lows = df['low'].values
        max_idx = argrelextrema(highs, np.greater, order=order)[0]
        min_idx = argrelextrema(lows, np.less, order=order)[0]
        swing_highs = [(i, highs[i]) for i in max_idx]
        swing_lows = [(i, lows[i]) for i in min_idx]
        return swing_highs, swing_lows

    def detect_order_blocks(self, df):
        swing_highs, swing_lows = self._swing_levels(df)
        blocks = []
        if swing_highs:
            last_high_idx, last_high = swing_highs[-1]
            if df['close'].iloc[-1] > last_high:
                ob = df.iloc[max(0, last_high_idx - 1)]
                blocks.append({'dir': 'BUY', 'zone': (ob['low'], ob['high'])})
        if swing_lows:
            last_low_idx, last_low = swing_lows[-1]
            if df['close'].iloc[-1] < last_low:
                ob = df.iloc[max(0, last_low_idx - 1)]
                blocks.append({'dir': 'SELL', 'zone': (ob['low'], ob['high'])})
        return blocks

    def detect_fvg(self, df):
        gaps = []
        for i in range(2, len(df)):
            if df['low'].iloc[i] > df['high'].iloc[i - 2]:
                gaps.append({'dir': 'BUY', 'zone': (df['high'].iloc[i - 2], df['low'].iloc[i])})
            if df['high'].iloc[i] < df['low'].iloc[i - 2]:
                gaps.append({'dir': 'SELL', 'zone': (df['high'].iloc[i], df['low'].iloc[i - 2])})
        return gaps[-2:]

    def detect_liquidity_pools(self, df, window=None, tol_mult=0.2):
        window = min(len(df), CFG.get('smc_liquidity_window', 200)) if window is None else min(len(df), window)
        recent = df.tail(window)
        d = add_indicators(recent)
        if d is None or d.empty or 'atr' not in d.columns:
            return []
        atr = d['atr'].iloc[-1]
        tol = atr * tol_mult
        highs = recent['high'].values
        lows = recent['low'].values
        pools = []
        for level in [np.mean(highs), np.mean(lows)]:
            near_highs = highs[np.abs(highs - level) <= tol]
            near_lows = lows[np.abs(lows - level) <= tol]
            if len(near_highs) >= 3:
                pools.append({'dir': 'SELL', 'level': float(level)})
            if len(near_lows) >= 3:
                pools.append({'dir': 'BUY', 'level': float(level)})
        return pools

    def detect_structure_breaks(self, df):
        swing_highs, swing_lows = self._swing_levels(df)
        last = df.iloc[-1]
        msb = None
        if swing_highs and last['close'] > swing_highs[-1][1]:
            msb = {'type': 'BOS_UP', 'level': swing_highs[-1][1]}
        if swing_lows and last['close'] < swing_lows[-1][1]:
            msb = {'type': 'BOS_DOWN', 'level': swing_lows[-1][1]}
        return msb

    def analyze(self, df):
        if df is None or df.empty:
            return {}
        return {
            'order_blocks': self.detect_order_blocks(df),
            'fvg': self.detect_fvg(df),
            'liquidity_pools': self.detect_liquidity_pools(df),
            'msb': self.detect_structure_breaks(df)
        }

SMART_MONEY = SmartMoneyDetector()

class CandlestickDetector:
    def detect(self, df):
        if len(df) < 3:
            return []
        
        patterns = []
        last = df.iloc[-1]
        prev = df.iloc[-2]
        
        body = abs(last['close'] - last['open'])
        range_ = last['high'] - last['low']
        upper_wick = last['high'] - max(last['close'], last['open'])
        lower_wick = min(last['close'], last['open']) - last['low']
        prev_body = abs(prev['close'] - prev['open'])
        
        if body > prev_body * 1.5 and body > 0.6 * range_:
            if last['close'] > last['open'] and prev['close'] < prev['open']:
                patterns.append({
                    'type': 'bullish_engulfing',
                    'strength': 2.5
                })
            elif last['close'] < last['open'] and prev['close'] > prev['open']:
                patterns.append({
                    'type': 'bearish_engulfing',
                    'strength': 2.5
                })
        
        if lower_wick > 2 * body and upper_wick < 0.3 * range_ and last['close'] > last['open']:
            patterns.append({
                'type': 'hammer',
                'strength': 2.0
            })
        
        if upper_wick > 2 * body and lower_wick < 0.3 * range_ and last['close'] < last['open']:
            patterns.append({
                'type': 'shooting_star',
                'strength': 2.0
            })
        
        if body < 0.1 * range_ and upper_wick > 0.4 * range_ and lower_wick > 0.4 * range_:
            patterns.append({
                'type': 'doji',
                'strength': 1.5
            })
        
        if patterns:
            d = add_indicators(df)
            rsi = d['rsi'].iloc[-1]
            vol = last['volume']
            vol_avg = df['volume'].iloc[-20:].mean()
            
            for p in patterns:
                if rsi < 30 or rsi > 70:
                    p['strength'] += 0.5
                if vol > 1.5 * vol_avg:
                    p['strength'] += 0.5
        
        return patterns

CANDLESTICK = CandlestickDetector()

class SupportResistanceDetector:
    def detect(self, df):
        if len(df) < CFG.get('min_zone_bars', 100):
            return None
        
        try:
            window = min(len(df), CFG.get('sr_detection_window', 200))
            recent = df.iloc[-window:]
            highs = recent['high'].values
            lows = recent['low'].values
            current = df['close'].iloc[-1]
            
            resistance_levels = []
            support_levels = []
            
            for i in range(1, len(highs) - 1):
                if highs[i] > highs[i - 1] and highs[i] > highs[i + 1]:
                    resistance_levels.append(highs[i])
            
            for i in range(1, len(lows) - 1):
                if lows[i] < lows[i - 1] and lows[i] < lows[i + 1]:
                    support_levels.append(lows[i])
            
            nearby_support = [
                s for s in support_levels
                if abs(current - s) / current < CFG.get('sr_near_pct', 0.01)
            ]
            nearby_resistance = [
                r for r in resistance_levels
                if abs(current - r) / current < CFG.get('sr_near_pct', 0.01)
            ]
            
            return {
                'support': nearby_support,
                'resistance': nearby_resistance,
                'at_support': len(nearby_support) > 0,
                'at_resistance': len(nearby_resistance) > 0
            }
        except Exception:
            return None

SUPPORT_RESISTANCE = SupportResistanceDetector()

class FibonacciDetector:
    def detect(self, df):
        if len(df) < CFG.get('min_zone_bars', 100):
            return None
        
        try:
            window_size = min(len(df), CFG.get('fib_detection_window', 200))
            window = df.iloc[-window_size:]
            high = window['high'].max()
            low = window['low'].min()
            current = df['close'].iloc[-1]
            diff = high - low
            
            fib_levels = {
                '0.236': low + diff * 0.236,
                '0.382': low + diff * 0.382,
                '0.5': low + diff * 0.5,
                '0.618': low + diff * 0.618,
                '0.786': low + diff * 0.786
            }
            
            near_fib = None
            for name, level in fib_levels.items():
                if abs(current - level) / current < 0.005:
                    near_fib = level
                    break
            
            return {
                'at_618': near_fib == fib_levels['0.618'],
                'at_382': near_fib == fib_levels['0.382'],
                'near_level': near_fib is not None
            }
        except Exception:
            return None

FIBONACCI = FibonacciDetector()

class RSIDivergenceDetector:
    def detect(self, df):
        if len(df) < 50:
            return None
        
        try:
            d = add_indicators(df.iloc[-50:])
            prices = d['close'].values
            rsi_vals = d['rsi'].values
            
            price_highs = [
                i for i in range(1, len(prices) - 1)
                if prices[i] > prices[i - 1] and prices[i] > prices[i + 1]
            ]
            
            price_lows = [
                i for i in range(1, len(prices) - 1)
                if prices[i] < prices[i - 1] and prices[i] < prices[i + 1]
            ]
            
            if len(price_highs) >= 2:
                if (prices[price_highs[-1]] > prices[price_highs[-2]] and
                    rsi_vals[price_highs[-1]] < rsi_vals[price_highs[-2]]):
                    return {
                        'type': 'bearish_divergence',
                        'strength': 2.5
                    }
            
            if len(price_lows) >= 2:
                if (prices[price_lows[-1]] < prices[price_lows[-2]] and
                    rsi_vals[price_lows[-1]] > rsi_vals[price_lows[-2]]):
                    return {
                        'type': 'bullish_divergence',
                        'strength': 2.5
                    }
            
            return None
        except Exception:
            return None

RSI_DIVERGENCE = RSIDivergenceDetector()

class VolumeProfileDetector:
    def detect(self, df):
        if len(df) < 100:
            return None
        
        try:
            window = df.iloc[-100:]
            price_bins = np.linspace(
                window['low'].min(),
                window['high'].max(),
                20
            )
            vol_profile = np.zeros(19)
            
            for i in range(len(window)):
                price = window['close'].iloc[i]
                vol = window['volume'].iloc[i]
                
                bin_idx = np.digitize(price, price_bins) - 1
                if 0 <= bin_idx < len(vol_profile):
                    vol_profile[bin_idx] += vol
            max_vol_idx = np.argmax(vol_profile)
            poc = (price_bins[max_vol_idx] + price_bins[max_vol_idx + 1]) / 2
            current = df['close'].iloc[-1]
            
            return {
                'at_poc': abs(current - poc) / current < 0.005,
                'poc_level': poc,
                'near_high_volume': abs(current - poc) / current < 0.01
            }
        except Exception:
            return None

VOLUME_PROFILE = VolumeProfileDetector()

class StrategyEngine:
    def analyze(self, dfs, regime, dxy_data=None):
        signals = []
        
        for tf, df in dfs.items():
            if df is None or len(df) < 100:
                continue
            
            d = add_indicators(df)
            last = d.iloc[-1]
            
            trend_direction = None
            if last['ema9'] > last['ema21'] > last['ema50']:
                trend_direction = 'BUY'
            elif last['ema9'] < last['ema21'] < last['ema50']:
                trend_direction = 'SELL'
            
            score = 0.0
            reasons = []
            direction = None
            signal_type = 'normal'
            
            if last['ema9'] > last['ema21'] > last['ema50']:
                score += 3.0
                reasons.append(f"{tf}: EMA_bull")
                direction = 'BUY'
            elif last['ema9'] < last['ema21'] < last['ema50']:
                score += 3.0
                reasons.append(f"{tf}: EMA_bear")
                direction = 'SELL'
            
            ichimoku_bull = (last['close'] > max(last.get('senkou_a', last['close']), 
                                                last.get('senkou_b', last['close'])) and
                            last['tenkan'] > last['kijun'])
            ichimoku_bear = (last['close'] < min(last.get('senkou_a', last['close']), 
                                                last.get('senkou_b', last['close'])) and
                            last['tenkan'] < last['kijun'])
            
            if ichimoku_bull:
                score += 3.0
                reasons.append(f"{tf}: Ichimoku_bull")
                direction = 'BUY'
            elif ichimoku_bear:
                score += 3.0
                reasons.append(f"{tf}: Ichimoku_bear")
                direction = 'SELL'
            
            if last['bb_width'] < 0.01:
                if last['close'] > last['bb_upper']:
                    score += 2.5
                    reasons.append(f"{tf}: BB_squeeze_bull")
                    direction = 'BUY'
                    signal_type = 'breakout'
                elif last['close'] < last['bb_lower']:
                    score += 2.5
                    reasons.append(f"{tf}: BB_squeeze_bear")
                    direction = 'SELL'
                    signal_type = 'breakout'
            
            harmonic = HARMONIC.detect(d)
            if harmonic and harmonic['type'] == 'bull' and direction == 'BUY':
                score += 3.0
                reasons.append(f"{tf}: Harmonic_{harmonic['pattern']}")
            
            if (last['macd'] > last['macd_sig'] and 
                last['rsi'] < 70 and direction == 'BUY'):
                score += 2.0
                reasons.append(f"{tf}: MACD_bull")
            elif (last['macd'] < last['macd_sig'] and 
                  last['rsi'] > 30 and direction == 'SELL'):
                score += 2.0
                reasons.append(f"{tf}: MACD_bear")
            
            if (regime == 'RANGING' and 
                abs(last['close'] - last['vwap']) > 1.5 * last['atr']):
                score += 2.0
                reasons.append(f"{tf}: VWAP_reversion")
            
            for cs in CANDLESTICK.detect(df):
                if (cs['type'] in ['bullish_engulfing', 'hammer'] and 
                    direction == 'BUY'):
                    score += cs['strength']
                    reasons.append(f"{tf}: Candle_{cs['type']}")
                elif (cs['type'] in ['bearish_engulfing', 'shooting_star'] and 
                      direction == 'SELL'):
                    score += cs['strength']
                    reasons.append(f"{tf}: Candle_{cs['type']}")
                elif cs['type'] == 'doji':
                    score += cs['strength']
                    reasons.append(f"{tf}: Candle_doji")
            
            sr = SUPPORT_RESISTANCE.detect(df)
            if sr and sr['at_support'] and direction == 'BUY':
                score += 2.0
                reasons.append(f"{tf}: At_support")
            elif sr and sr['at_resistance'] and direction == 'SELL':
                score += 2.0
                reasons.append(f"{tf}: At_resistance")
            
            fib = FIBONACCI.detect(df)
            if fib and fib['at_618'] and direction == 'BUY':
                score += 2.5
                reasons.append(f"{tf}: Fib_618_bull")
            elif fib and fib['at_382'] and direction == 'SELL':
                score += 2.5
                reasons.append(f"{tf}: Fib_382_bear")
            
            div = RSI_DIVERGENCE.detect(df)
            if div and div['type'] == 'bullish_divergence' and direction == 'BUY':
                score += div['strength']
                reasons.append(f"{tf}: RSI_div_bull")
            elif div and div['type'] == 'bearish_divergence' and direction == 'SELL':
                score += div['strength']
                reasons.append(f"{tf}: RSI_div_bear")
            
            vp = VOLUME_PROFILE.detect(df)
            if vp and vp['at_poc']:
                score += 1.5
                reasons.append(f"{tf}: At_POC")
            
            if direction:
                print(f"[DEBUG] Strategy evaluate {tf}: direction={direction}, score={score:.2f}, trend={trend_direction}, signal_type={signal_type}, reasons={reasons}", flush=True)
                LOG.info(f"[DEBUG] Strategy evaluate {tf}: direction={direction}, score={score:.2f}, trend={trend_direction}, signal_type={signal_type}, reasons={reasons}")

            if direction and score >= 5.0:
                if trend_direction and direction != trend_direction and signal_type != 'breakout':
                    print(f"[DEBUG] Strategy skip {tf}: directional conflict ({direction} vs {trend_direction})", flush=True)
                    LOG.debug(f"[STRATEGY] Skipping {direction} signal on {tf} because it conflicts with major trend {trend_direction}")
                    continue
                # Lightweight strategy attribution heuristic so notifications show meaningful strategy
                reasons_text = " ".join(reasons).lower()
                if signal_type == 'breakout' or 'bb_squeeze' in reasons_text:
                    strategy = 'breakout'
                elif 'fib' in reasons_text or 'support' in reasons_text or 'resistance' in reasons_text or 'vwap' in reasons_text:
                    strategy = 'mean_reversion'
                elif 'ema' in reasons_text or 'macd' in reasons_text:
                    strategy = 'trend'
                else:
                    # fallback to first active strategy or 'rule'
                    active = CFG.get('active_strategies', []) or ['rule']
                    strategy = active[0] if len(active) > 0 else 'rule'

                # Ensure strategy is one of configured active strategies when possible
                if strategy not in CFG.get('active_strategies', []):
                    active = CFG.get('active_strategies', []) or ['rule']
                    strategy = active[0]

                signals.append({
                    'tf': tf,
                    'dir': direction,
                    'score': score,
                    'raw_score': score,  # Store base score before adjustments
                    'reasons': reasons,
                    'entry': last['close'],
                    'atr': last['atr'],
                    'ema9': last['ema9'],
                    'rsi': last['rsi'],
                    'macd': last['macd'],
                    'bb_width': last['bb_width'],
                    'vwap': last['vwap'],
                    'signal_type': signal_type,
                    'strategy': strategy,
                    'features': {        # V12.1: Structured features for ML
                        'ema9': last['ema9'],
                        'ema21': last['ema21'],
                        'ema50': last['ema50'],
                        'rsi': last['rsi'],
                        'macd': last['macd'],
                        'atr': last['atr'],
                        'bb_width': last['bb_width'],
                        'vwap': last['vwap']
                    }
                })
        
        return signals
    
    def multi_tf_alignment(self, dfs):
        count = 0
        for tf, df in dfs.items():
            if df is None or len(df) < 50:
                continue
            
            last = add_indicators(df).iloc[-1]
            if (last['ema9'] > last['ema21'] > last['ema50'] or
                last['ema9'] < last['ema21'] < last['ema50']):
                count += 1
        
        if count == 3:
            return 3.0
        elif count == 2:
            return 1.5
        return 0.0
    
    def apply_correlation_adjustment(self, signals, xau_data, dxy_data):
        if not signals or not CFG["correlation_check_enabled"]:
            return signals
        
        print(f"[DEBUG] apply_correlation_adjustment called with {len(signals)} signals", flush=True)
        LOG.info(f"[DEBUG] apply_correlation_adjustment called with {len(signals)} signals")
        correlation = CORRELATION.calculate_correlation(xau_data, dxy_data, period=50)
        print(f"[DEBUG] Correlation calculated: {correlation}", flush=True)
        LOG.info(f"[DEBUG] Correlation calculated: {correlation}")
        
        for signal in signals:
            direction = signal['dir']
            adjustment = 0.0
            signal['correlation'] = correlation
            signal['correlation_checked'] = 1

            if direction == 'BUY':
                if correlation < -0.7:
                    adjustment = 2.0
                    signal['reasons'].append(f"Strong DXY negative correlation supports BUY: {correlation:.2f}")
                elif correlation < -0.5:
                    adjustment = 1.0
                    signal['reasons'].append(f"Good DXY negative correlation supports BUY: {correlation:.2f}")
                elif correlation < -0.2:
                    adjustment = 0.0
                    signal['reasons'].append(f"Weak DXY correlation for BUY: {correlation:.2f}")
                elif correlation < 0.2:
                    adjustment = -0.5
                    signal['reasons'].append(f"Mild DXY contradiction for BUY: {correlation:.2f}")
                else:
                    adjustment = -1.0
                    signal['reasons'].append(f"Strong DXY contradiction for BUY: {correlation:.2f}")
            elif direction == 'SELL':
                if correlation > 0.7:
                    adjustment = 2.0
                    signal['reasons'].append(f"Strong DXY positive correlation supports SELL: {correlation:.2f}")
                elif correlation > 0.5:
                    adjustment = 1.0
                    signal['reasons'].append(f"Good DXY positive correlation supports SELL: {correlation:.2f}")
                elif correlation > 0.2:
                    adjustment = 0.0
                    signal['reasons'].append(f"Weak DXY correlation for SELL: {correlation:.2f}")
                elif correlation > -0.2:
                    adjustment = -0.5
                    signal['reasons'].append(f"Mild DXY contradiction for SELL: {correlation:.2f}")
                else:
                    adjustment = -1.0
                    signal['reasons'].append(f"Strong DXY contradiction for SELL: {correlation:.2f}")
            else:
                signal['reasons'].append(f"DXY correlation applied: {correlation:.2f}")

            signal['score'] += adjustment
            print(f"[DEBUG] Signal after correlation adj: dir={direction} score={signal['score']} corr={signal['correlation']} adj={adjustment}", flush=True)
            LOG.info(f"[DEBUG] Signal after correlation adj: dir={direction} score={signal['score']} corr={signal['correlation']} adj={adjustment}")
        
        return signals

STRATEGY = StrategyEngine()

class PredictiveML:
    def __init__(self):
        self.xgb_reg = None
        self.xgb_cls = None
        self.lgbm_reg = None
        self.lgbm_cls = None
        self.trained = False
        self._scaler = None  # STAGE-15: (mean, std) applied to features at predict time
        self._last_train_n = 0    # STAGE-15d: closed-trade count at last retrain attempt
        self._last_train_ts = 0.0  # STAGE-15d: timestamp of last retrain attempt
        self._load()
    
    def _load(self):
        if not ML_OK:
            return
        
        try:
            def _stg15_load(p):
                # STAGE-15: new pickles are {'model','scaler','report'}; old ones are raw models
                with open(p, 'rb') as f:
                    obj = pickle.load(f)
                if isinstance(obj, dict):
                    self._scaler = obj.get('scaler', self._scaler)
                    return obj['model']
                return obj
            if os.path.exists(CFG["ml_regressor_path"]):
                self.xgb_reg = _stg15_load(CFG["ml_regressor_path"])
            if os.path.exists(CFG["ml_classifier_path"]):
                self.xgb_cls = _stg15_load(CFG["ml_classifier_path"])
            if LGBM_OK:
                if os.path.exists(CFG["lgbm_regressor_path"]):
                    self.lgbm_reg = _stg15_load(CFG["lgbm_regressor_path"])
                if os.path.exists(CFG["lgbm_classifier_path"]):
                    self.lgbm_cls = _stg15_load(CFG["lgbm_classifier_path"])
            self.trained = bool(self.xgb_reg and self.xgb_cls)
            if self.trained:
                LOG.info("[ML] Models loaded")
        except Exception:
            self.xgb_reg = None
            self.xgb_cls = None
            self.trained = False
    
    def _champion_meta(self):
        # STAGE-15f: champion/challenger bookkeeping (consec_fails, champion_ts)
        try:
            _d = os.path.dirname(CFG.get('state_file', 'state/bot_state.json')) or '.'
            p = os.path.join(_d, 'ml_champion_meta.json')
            if os.path.exists(p):
                with open(p) as f:
                    return json.load(f)
        except Exception:
            pass
        return {}
    
    def _save_champion_meta(self, meta):
        try:
            _d = os.path.dirname(CFG.get('state_file', 'state/bot_state.json')) or '.'
            p = os.path.join(_d, 'ml_champion_meta.json')
            with open(p, 'w') as f:
                json.dump(meta, f, indent=2)
        except Exception:
            pass
    
    def train(self, dfs):
        """STAGE-15: REAL training pipeline (replaces the old fit-everything-once).

        The original fit XGBoost on 100% of trades, saved it, and immediately
        trusted its own IN-SAMPLE predictions - that is exactly the overfitting
        the walk-forward gate below exists to catch.

        Overfitting protections:
          1. Time-ordered data (never shuffled - the market is a series)
          2. 60/20/20 train/val/test split WITH a purge (embargo) between
             windows so near-duplicate market states can't leak across
          3. BASELINE GATE: the model must beat majority-class accuracy by
             +5pts on the never-touched holdout, otherwise trained stays
             False and heuristic scoring runs alone - the model must earn
             the right to vote
          4. Shallow, regularized trees (small-data regime)
          5. Fixed protocol - NO hyperparameter search (searching until the
             backtest looks good IS overfitting)
          6. Feature standardization - stats computed on train only, stored
             with the model, applied at predict time
        """
        if not ML_OK:
            return
        
        try:
            self._last_train_ts = time.time()  # STAGE-15d: cooldown starts on every attempt
            data = STORE.get_training_data(15000)
            data = list(reversed(data))  # get_training_data orders by close_ts DESC
            n = len(data)
            self._last_train_n = n  # STAGE-15d: baseline for "every 10 new closed trades"
            if n < 150:
                LOG.info(f"[ML] Training skipped: {n} labeled trades < 150 minimum (no model on tiny data)")
                return
            
            X, y_dir, y_price = [], [], []
            for feats_json, entry, close_price, pnl in data:
                feats = json.loads(feats_json)
                X.append([
                    safe_float(feats.get('ema9')),
                    safe_float(feats.get('rsi')),
                    safe_float(feats.get('macd')),
                    safe_float(feats.get('atr')),
                    safe_float(feats.get('bb_width')),
                    safe_float(feats.get('vwap'))
                ])
                y_price.append(close_price - entry)
                y_dir.append(1 if close_price > entry else 0)
            
            X = np.array(X, dtype=float)
            y_dir = np.array(y_dir)
            y_price = np.array(y_price, dtype=float)
            
            # --- time-ordered split with purge (embargo) between windows ---
            i_train_end = int(n * 0.6)
            i_val_end = int(n * 0.8)
            purge = max(5, int(n * 0.02))
            X_tr = X[:i_train_end - purge];  y_tr_d = y_dir[:i_train_end - purge];  y_tr_p = y_price[:i_train_end - purge]
            X_va = X[i_train_end:i_val_end - purge]; y_va_d = y_dir[i_train_end:i_val_end - purge]
            X_te = X[i_val_end:]; y_te_d = y_dir[i_val_end:]
            
            if len(X_tr) < 80 or len(X_va) < 10 or len(X_te) < 20:
                LOG.info(f"[ML] Training skipped: split too small (train={len(X_tr)}, val={len(X_va)}, test={len(X_te)})")
                return
            
            # standardize using TRAIN-window stats only (no test leakage)
            mu = X_tr.mean(axis=0)
            sd = X_tr.std(axis=0) + 1e-9
            Xs_tr = (X_tr - mu) / sd
            Xs_va = (X_va - mu) / sd
            Xs_te = (X_te - mu) / sd
            
            def _acc(y_true, y_pred):
                return float(np.mean(np.asarray(y_true) == np.asarray(y_pred)))
            
            # --- direction classifier (shallow + regularized) ---
            xgb_cls = XGBClassifier(
                n_estimators=100, max_depth=3, learning_rate=0.03,
                subsample=0.8, colsample_bytree=0.8, min_child_weight=5,
                reg_lambda=2.0, eval_metric='logloss'
            )
            xgb_cls.fit(Xs_tr, y_tr_d)
            val_acc = _acc(y_va_d, xgb_cls.predict(Xs_va))
            test_acc = _acc(y_te_d, xgb_cls.predict(Xs_te))
            base_acc = max(float(y_te_d.mean()), 1.0 - float(y_te_d.mean()))
            passed = bool(test_acc >= max(base_acc, 0.5) + 0.05)
            
            report = {
                'ts': utc_now().isoformat(), 'symbol': CFG.get('symbol'),
                'n_samples': int(n), 'n_train': int(len(X_tr)),
                'n_val': int(len(X_va)), 'n_test': int(len(X_te)),
                'purge': int(purge),
                'val_acc': val_acc, 'test_acc': test_acc,
                'baseline_acc': base_acc, 'gate_margin': 0.05, 'passed': passed
            }
            try:
                os.makedirs('state', exist_ok=True)
                with open('state/ml_validation.json', 'w') as f:
                    json.dump(report, f, indent=2)
            except Exception:
                pass
            
            if not passed:
                # STAGE-15f: CHAMPION/CHALLENGER. A failed retrain is a failed
                # CHALLENGER - it is not a verdict on the current champion.
                # The last PASSING model (champion) is kept unless it has now
                # failed re-validation 3 times in a row (edge decay), in which
                # case it is retired. Data in the DB is never touched.
                meta = self._champion_meta()
                meta['consec_fails'] = meta.get('consec_fails', 0) + 1
                meta['last_attempt_ts'] = report['ts']
                champion_alive = os.path.exists(CFG["ml_classifier_path"]) and meta['consec_fails'] < 3
                self._save_champion_meta(meta)
                if champion_alive:
                    # champion untouched - stays in memory and on disk
                    self.trained = bool(self.xgb_reg and self.xgb_cls)
                    LOG.warning(f"[ML] Challenger FAILED gate (holdout={test_acc:.3f} vs baseline={base_acc:.3f}) - keeping previous champion (fail {meta['consec_fails']}/3, retires at 3)")
                    return
                self.trained = False
                self.xgb_reg = self.xgb_cls = None
                self.lgbm_reg = self.lgbm_cls = None
                self._scaler = None
                # wipe model files so a restart can't resurrect a retired model
                for _p in (CFG["ml_regressor_path"], CFG["ml_classifier_path"],
                           CFG["lgbm_regressor_path"], CFG["lgbm_classifier_path"]):
                    try:
                        if os.path.exists(_p):
                            os.remove(_p)
                    except Exception:
                        pass
                LOG.warning(f"[ML] Walk-forward gate FAILED x{meta['consec_fails']} - champion RETIRED: holdout={test_acc:.3f} vs baseline={base_acc:.3f} (needs +0.05) - model DISABLED, heuristic scoring only (report: state/ml_validation.json)")
                return
            
            # STAGE-15f: challenger passed - promote to champion, reset fail streak
            _meta = self._champion_meta()
            _meta['consec_fails'] = 0
            _meta['champion_ts'] = report['ts']
            self._save_champion_meta(_meta)
            
            xgb_reg = XGBRegressor(
                n_estimators=100, max_depth=3, learning_rate=0.03,
                subsample=0.8, colsample_bytree=0.8, min_child_weight=5,
                reg_lambda=2.0
            )
            xgb_reg.fit(Xs_tr, y_tr_p)
            
            self.xgb_reg, self.xgb_cls = xgb_reg, xgb_cls
            self._scaler = (mu, sd)
            self.trained = True
            
            # --- optional LGBM ensemble partner, same gate ---
            if LGBM_OK:
                lgbm_cls = LGBMClassifier(
                    n_estimators=100, max_depth=3, learning_rate=0.03,
                    subsample=0.8, colsample_bytree=0.8, min_child_samples=20,
                    reg_lambda=2.0, verbose=-1
                )
                lgbm_cls.fit(Xs_tr, y_tr_d)
                lgbm_test_acc = _acc(y_te_d, lgbm_cls.predict(Xs_te))
                if lgbm_test_acc >= max(base_acc, 0.5) + 0.05:
                    lgbm_reg = LGBMRegressor(
                        n_estimators=100, max_depth=3, learning_rate=0.03,
                        subsample=0.8, colsample_bytree=0.8, min_child_samples=20,
                        reg_lambda=2.0, verbose=-1
                    )
                    lgbm_reg.fit(Xs_tr, y_tr_p)
                    self.lgbm_reg, self.lgbm_cls = lgbm_reg, lgbm_cls
                else:
                    self.lgbm_reg = self.lgbm_cls = None
                    LOG.info(f"[ML] LGBM failed the gate (holdout={lgbm_test_acc:.3f}) - XGB only")
            
            os.makedirs(os.path.dirname(CFG["ml_regressor_path"]), exist_ok=True)
            
            with open(CFG["ml_regressor_path"], 'wb') as f:
                pickle.dump({'model': self.xgb_reg, 'scaler': self._scaler, 'report': report}, f)
            
            with open(CFG["ml_classifier_path"], 'wb') as f:
                pickle.dump({'model': self.xgb_cls, 'scaler': self._scaler, 'report': report}, f)
            
            if LGBM_OK and self.lgbm_reg and self.lgbm_cls:
                with open(CFG["lgbm_regressor_path"], 'wb') as f:
                    pickle.dump({'model': self.lgbm_reg, 'scaler': self._scaler, 'report': report}, f)
                
                with open(CFG["lgbm_classifier_path"], 'wb') as f:
                    pickle.dump({'model': self.lgbm_cls, 'scaler': self._scaler, 'report': report}, f)
            
            LOG.info(f"[ML] Walk-forward gate PASSED: val={val_acc:.3f} holdout={test_acc:.3f} baseline={base_acc:.3f} - model ENABLED (report: state/ml_validation.json)")
        except Exception as e:
            LOG.warning(f"[ML] Training failed: {e}")
    
    def predict(self, sig):
        if not self.trained:
            return {
                'enabled': False,
                'pred_price': 0,
                'conf': 0.5,
                'dir_prob': 0.5
            }
        
        try:
            features = sig.get('features', {})
            X = np.array([[
                safe_float(features.get('ema9', 0)),
                safe_float(features.get('rsi', 50)),
                safe_float(features.get('macd', 0)),
                safe_float(features.get('atr', 1)),
                safe_float(features.get('bb_width', 0.02)),
                safe_float(features.get('vwap', sig.get('entry', 2000)))
            ]])
            # STAGE-15: apply the training-window standardization
            if self._scaler is not None:
                _mu, _sd = self._scaler
                X = (X - _mu) / _sd
            
            xgb_delta = self.xgb_reg.predict(X)[0]
            xgb_prob = self.xgb_cls.predict_proba(X)[0][1]
            
            if self.lgbm_reg and self.lgbm_cls:
                lgbm_delta = self.lgbm_reg.predict(X)[0]
                lgbm_prob = self.lgbm_cls.predict_proba(X)[0][1]
                
                pred_delta = xgb_delta * 0.6 + lgbm_delta * 0.4
                dir_prob = xgb_prob * 0.6 + lgbm_prob * 0.4
            else:
                pred_delta = xgb_delta
                dir_prob = xgb_prob
            
            return {
                'enabled': True,
                'pred_price': sig['entry'] + pred_delta,
                'pred_delta': pred_delta,
                'dir_prob': dir_prob,
                'conf': max(dir_prob, 1 - dir_prob)
            }
        except Exception:
            return {
                'enabled': False,
                'pred_price': 0,
                'conf': 0.5,
                'dir_prob': 0.5
            }

ML = PredictiveML()

class RiskManager:
    def __init__(self):
        self.last_size_adjustment = 0.0
        self.portfolio_correlations = {}  # FIX 5: Track position correlations
    
    def calculate_portfolio_heat(self, open_positions, correlation_matrix=None):
        """FIX 5: Calculate total portfolio heat (risk exposure) with correlation adjustments.
        
        Args:
            open_positions: List of open trade dicts
            correlation_matrix: Optional correlation matrix between positions
        
        Returns: {'total_heat': float, 'heat_pct': float, 'by_position': dict}
        """
        try:
            if not open_positions:
                return {'total_heat': 0.0, 'heat_pct': 0.0, 'by_position': {}}
            
            account_info = MT5.get_account_info()
            balance = account_info.get('balance', 1)
            
            total_heat = 0.0
            position_heats = {}
            
            for pos in open_positions:
                try:
                    entry = pos.get('entry', 0)
                    size = pos.get('size', 0)
                    sl = pos.get('sl', 0)
                    ticket = pos.get('ticket', 0)
                    
                    if entry <= 0 or size <= 0:
                        continue
                    
                    sl_dist = abs(entry - sl) if sl > 0 else entry * 0.02
                    risk_amt = size * sl_dist * EXNESS['point_value'] * EXNESS['contract_size']
                    heat = risk_amt / max(1, balance) if balance > 0 else 0
                    
                    position_heats[ticket] = heat
                    total_heat += heat
                    
                except Exception as e:
                    LOG.debug(f"[HEAT] Error calculating position heat: {e}")
                    continue
            
            # FIX 5: Apply correlation adjustment if available
            if correlation_matrix is not None and len(position_heats) > 1:
                correlation_factor = 1.0 - (0.2 * abs(np.mean(correlation_matrix)))
                correlation_factor = max(0.5, min(1.0, correlation_factor))
                total_heat = total_heat * correlation_factor
                LOG.debug(f"[HEAT] Correlation adjustment: {correlation_factor:.2f}")
            
            heat_pct = (total_heat / 1.0) * 100  # Heat as % (1.0 = 100% risk)
            
            result = {
                'total_heat': float(total_heat),
                'heat_pct': float(heat_pct),
                'by_position': position_heats,
                'safe': heat_pct < CFG.get('portfolio_heat_limit', 30)
            }
            
            if not result['safe']:
                LOG.warning(f"[HEAT] Portfolio heat {heat_pct:.1f}% exceeds limit {CFG.get('portfolio_heat_limit', 30)}%")
            
            return result
            
        except Exception as e:
            LOG.error(f"[HEAT] Calculation failed: {e}")
            return {'total_heat': 0.0, 'heat_pct': 0.0, 'by_position': {}, 'error': str(e)}
    
    def get_time_mult(self):
        hour = utc_now().hour
        day = utc_now().weekday()
        
        if 0 <= hour < 2:
            return 0.5
        elif 7 <= hour < 9:
            return 1.0
        elif 13 <= hour < 15:
            return 1.2
        elif day == 4 and hour >= 20:
            return 0.6
        elif day == 6 and hour < 2:
            return 0.5
        else:
            return 1.0
    
    def get_vol_mult(self):
        """Get volatility multiplier based on recent market conditions"""
        try:
            # STAGE-13: `dfs` was never in scope here (it is a _cycle local), so
            # this always returned 1.0. Use the shared LAST_DFS instead.
            df = (LAST_DFS or {}).get(CFG["timeframes"][0])
            if df is None or df.empty or 'atr' not in df.columns:
                return 1.0
            
            atr_pct = (df['atr'].iloc[-1] / df['close'].iloc[-1] * 100) if df['close'].iloc[-1] > 0 else 0.5
            
            # Low volatility = 1.0, High volatility = 0.7 (reduce size in high vol)
            if atr_pct < 0.3:
                return 1.1  # Low vol boost
            elif atr_pct > 1.0:
                return 0.7  # High vol reduction
            else:
                return 1.0
        except Exception:
            return 1.0

    def calculate_confluence_multiplier(self, signal_data, ml_result, correlation_value, mtf_score):
        score = signal_data.get('score', 7.0) if signal_data else 7.0
        score_norm = max(0.0, min(1.0, (score - 7.0) / 8.0))
        base_mult = 1.0 + (0.7 * score_norm)

        mtf_norm = max(0.0, min(1.0, mtf_score if mtf_score is not None else 0.0))
        mtf_mult = 1.0 + (0.3 * mtf_norm)

        ml_conf = ml_result.get('conf', 0.5) if ml_result else 0.5
        ml_boost = 0.2 if ml_conf > 0.8 else (0.1 if ml_conf > 0.65 else 0.0)

        corr_boost = 0.0
        if signal_data and correlation_value is not None:
            if signal_data.get('dir') == 'BUY' and correlation_value < -0.75:
                corr_boost = 0.15
            elif signal_data.get('dir') == 'SELL' and correlation_value > 0.75:
                corr_boost = 0.15

        mult = base_mult * mtf_mult + ml_boost + corr_boost
        mult = min(mult, CFG["max_confluence_multiplier"])

        log_json(
            "confluence_calc",
            score=score,
            base_mult=round(base_mult, 3),
            mtf_mult=round(mtf_mult, 3),
            ml_boost=round(ml_boost, 3),
            corr_boost=round(corr_boost, 3),
            final_mult=round(mult, 3)
        )
        return mult

    def calc_size(self, entry, sl, ml_conf, score, confluence_multiplier=None,
                  signal_data=None, ml_result=None, correlation_value=None, mtf_score=None,
                  df_for_risk=None):
        """Calculate position size based on current dynamic balance"""
        # Get REAL MT5 balance, not config
        current_balance = MT5.get_current_balance()
        if current_balance <= 0:
            current_balance = CFG["account_balance"]

        win_rate = STORE.get_win_rate()
        kelly_raw = win_rate - (1 - win_rate)
        kelly = max(0.05, min(kelly_raw * 0.5, 0.35))

        # Enhanced Kelly with account growth scaling
        equity_slope = STORE.get_equity_slope()
        kelly_boost = 1.2 if equity_slope > 0.02 else (1.1 if equity_slope > 0.01 else (0.7 if equity_slope < -0.01 else 1.0))
        kelly = kelly * kelly_boost
        kelly = max(0.05, min(kelly, 0.35))
        
        # Scale with account growth (ratio of current to initial balance)
        balance_growth = (current_balance / max(1, CFG["account_balance"])) if CFG["account_balance"] > 0 else 1.0
        equity_mult = min(1.5, balance_growth * 1.2)

        time_mult = self.get_time_mult()

        if confluence_multiplier is None:
            confluence_multiplier = self.calculate_confluence_multiplier(
                signal_data or {'score': score},
                ml_result or {'conf': ml_conf},
                correlation_value,
                mtf_score or 0.0
            )

        vol_mult = self.get_vol_mult()

        dynamic_risk_pct = ADAPTIVE_SIZER.get_dynamic_risk_pct(df_for_risk, ml_conf) if ADAPTIVE_SIZER else CFG.get("risk_pct", 0.01)
        risk_amt = current_balance * dynamic_risk_pct * kelly * equity_mult * time_mult * confluence_multiplier * vol_mult
        sl_dist = abs(entry - sl)

        if sl_dist <= 0:
            return EXNESS['min_lot']

        raw_lots = risk_amt / (sl_dist * EXNESS['point_value'] * EXNESS['contract_size'])
        adjusted_lots = round(raw_lots / EXNESS['step']) * EXNESS['step']
        
        # Hard cap position size before any checks (safety bound)
        adjusted_lots = min(max(EXNESS['min_lot'], adjusted_lots), 5.0)

        self.last_size_adjustment = {
            'balance': current_balance,
            'risk_pct': dynamic_risk_pct,
            'kelly': kelly,
            'equity_mult': equity_mult,
            'time_mult': time_mult,
            'confluence_mult': confluence_multiplier,
            'vol_mult': vol_mult,
            'calculated_lots': adjusted_lots
        }

        # FIX 1: Check margin availability
        margin_check = MT5.check_available_margin(adjusted_lots, entry)
        if not margin_check.get('available', False):
            LOG.warning(f"[RISK] Margin failed. Req: ${margin_check.get('margin_required', 0):.2f}")
            return EXNESS['min_lot']
        
        # FIX 5: Check portfolio heat before accepting position
        open_trades = STORE.open_trades() if STORE else []
        heat_info = self.calculate_portfolio_heat(open_trades)
        if not heat_info.get('safe', True):
            LOG.warning(f"[RISK] Portfolio heat {heat_info.get('heat_pct', 0):.1f}% too high, reducing size")
            adjusted_lots = adjusted_lots * 0.7  # Reduce by 30%

        self.last_size_adjustment['margin_level'] = margin_check.get('margin_level', 0)
        self.last_size_adjustment['portfolio_heat_pct'] = heat_info.get('heat_pct', 0)
        final_lots = min(max(EXNESS['min_lot'], adjusted_lots), 10.0)
        # STAGE-10: min-lot risk warning - if even the SMALLEST lot risks an
        # outsized fraction of the account on a single stop-out, warn (don't
        # block): e.g. $30 account / 0.01 XAU lot can be >50% of equity.
        try:
            min_lot_risk = sl_dist * EXNESS['point_value'] * EXNESS['contract_size'] * EXNESS['min_lot']
            min_lot_risk_pct = (min_lot_risk / current_balance) if current_balance > 0 else 0.0
            if final_lots <= EXNESS['min_lot'] * 1.001 and min_lot_risk_pct > 0.25:
                LOG.warning(f"[RISK] MIN-LOT RISK: {EXNESS['min_lot']} lot stop-out ~ ${min_lot_risk:.2f} = {min_lot_risk_pct*100:.0f}% of ${current_balance:.0f} account - account too small for 1% risk sizing")
        except Exception:
            pass
        LOG.info(f"[RISK] Bal:${current_balance:.2f} Lots:{final_lots:.2f} Marg:{margin_check.get('margin_level', 0):.0f}% Heat:{heat_info.get('heat_pct', 0):.1f}%")
        return final_lots

class AdaptivePositionSizer:
    """Dynamic risk sizing based on volatility, regime, time, streaks, and ML confidence."""
    def __init__(self):
        self.cache = TTLCache(maxsize=8, ttl_sec=60)

    def _volatility_factor(self, df):
        if not CFG.get("volatility_adjustment", True):
            return 1.0
        if df is None or df.empty or 'atr' not in df.columns:
            return 1.0
        atr_series = df['atr'].dropna()
        if len(atr_series) < 20:
            return 1.0
        current_atr = atr_series.iloc[-1]
        pct = np.percentile(atr_series, 80)
        if current_atr >= pct:
            return 0.7
        pct_low = np.percentile(atr_series, 20)
        if current_atr <= pct_low:
            return 1.2
        return 1.0

    def _regime_factor(self, df):
        if not CFG.get("regime_adjustment", True):
            return 1.0
        try:
            regime = REGIME.detect(df)
        except Exception:
            return 1.0
        return {
            "TRENDING": 1.3,
            "RANGING": 0.8,
            "VOLATILE": 0.5,
            "TRANSITIONAL": 1.0
        }.get(regime, 1.0)

    def _time_factor(self):
        if not CFG.get("time_adjustment", True):
            return 1.0
        hour = utc_now().hour
        if 12 <= hour < 16:
            return 1.4
        if 0 <= hour < 6:
            return 0.7
        return 1.0

    def _streak_factor(self):
        if not CFG.get("streak_adjustment", True):
            return 1.0
        pnls = STORE.get_recent_pnls(limit=5)
        if len(pnls) < 3:
            return 1.0
        streak = 0
        for p in pnls:
            if p > 0:
                streak = streak + 1 if streak >= 0 else 1
            elif p < 0:
                streak = streak - 1 if streak <= 0 else -1
            else:
                break
        if streak >= 3:
            return 1.2
        if streak <= -3:
            return 0.8
        return 1.0

    def _ml_factor(self, ml_conf):
        """Scale risk based on ML confidence - boost high conf, don't over-penalize low
        
        High confidence (>0.8) → 1.15x boost
        Mid confidence (0.6-0.8) → 1.0x neutral
        Low confidence (<0.6) → 0.95x slight reduction (not harsh)
        """
        if ml_conf > 0.8:
            return 1.15
        if ml_conf < 0.6:
            return 0.95
        return 1.0

    def get_dynamic_risk_pct(self, df, ml_conf):
        cache_key = f"risk:{utc_now().strftime('%Y%m%d%H')}"
        cached = self.cache.get(cache_key)
        if cached:
            return cached

        base = CFG.get("min_risk_pct", 0.01)
        
        # Use weighted additive approach instead of multiplicative cascade
        vol_factor = self._volatility_factor(df)
        regime_factor = self._regime_factor(df)
        time_factor = self._time_factor()
        streak_factor = self._streak_factor()
        ml_factor = self._ml_factor(ml_conf)
        session_factor = SESSION_DETECTOR.session_multiplier() if 'SESSION_DETECTOR' in globals() else 1.0
        
        # Weighted average: prevents cascading reductions
        # Vol & Regime have high impact (0.3 weight each), others lower (0.1 each)
        combined_mult = (vol_factor * 0.3 + regime_factor * 0.3 + 
                        time_factor * 0.15 + streak_factor * 0.15 + 
                        ml_factor * 0.07)
        
        # Session factor applied separately (light touch)
        dynamic = base * combined_mult * (0.95 + session_factor * 0.05)
        
        # Enforce sensible bounds: 0.2% (scalping) to 5% (aggressive)
        dynamic = max(0.002, min(dynamic, 0.05))
        
        # Fix floating-point precision artifacts
        dynamic = round(dynamic, 10)
        
        self.cache.set(cache_key, dynamic)

        log_json(
            "dynamic_risk",
            base=base,
            vol_factor=round(vol_factor, 3),
            regime_factor=round(regime_factor, 3),
            time_factor=round(time_factor, 3),
            streak_factor=round(streak_factor, 3),
            ml_factor=round(ml_factor, 3),
            session_factor=round(session_factor, 3),
            combined_mult=round(combined_mult, 3),
            dynamic_risk=round(dynamic, 6)
        )
        return dynamic
    
    
    def get_vol_mult(self):
        """Get volatility multiplier for risk reduction"""
        # Simple ATR-based approach for volatility measurement
        try:
            df = MT5.fetch(CFG["symbol"], 'H1', 100)
            if df is not None and len(df) > 20:
                d = add_indicators(df)
                current_atr = d['atr'].iloc[-1]
                avg_atr = d['atr'].rolling(50).mean().iloc[-1]
                
                if avg_atr > 0:
                    atr_ratio = current_atr / avg_atr
                    if atr_ratio > 2.0:
                        return 0.5
                    elif atr_ratio > 1.5:
                        return 0.75
        except Exception as e:
            LOG.warning(f"[RISK] Volatility calculation error: {e}")
        return 1.0

RISK = RiskManager()
ADAPTIVE_SIZER = AdaptivePositionSizer()
FEATURE_FACTORY = FeatureFactory(MT5, STORE) if CFG.get("feature_factory_enabled", False) else None
DRL_COPILOT = DRLCoPilot() if CFG.get("drl_enabled", False) else None
