QUANTUM_CONTEXT = {'regime': None, 'session': None}

class TradeManager:
    def _tf_minutes(self, tf):
        return {
            'M1': 1,
            'M5': 5,
            'M15': 15,
            'H1': 60,
            'H4': 240,
            'D1': 1440,
            'W1': 10080,
            'MN1': 43200
        }.get(tf, 15)

    def _bars_since_entry(self, entry_ts, tf):
        try:
            entry_time = datetime.fromisoformat(entry_ts)
        except Exception:
            return 0
        mins = (utc_now() - entry_time).total_seconds() / 60
        return int(mins / self._tf_minutes(tf))

    def _get_min_lot_profit_lock(self, direction, entry, sl, tp, price, risk, atr):
        """Return a profit-lock SL level for 0.01-lot trades once they hit a meaningful milestone."""
        if risk <= 0:
            return None

        lock_rr = CFG.get("min_lot_profit_lock_rr", 1.0)
        lock_progress = CFG.get("min_lot_profit_lock_progress", 0.50)
        lock_fraction = CFG.get("min_lot_profit_lock_fraction_of_risk", 0.50)
        atr_mult = CFG.get("min_lot_profit_lock_atr_mult", 0.75)

        target_distance = abs(tp - entry) if tp and tp != 0 else (risk * 2.0)
        current_rr = abs(price - entry) / max(risk, 1e-6)
        progress = abs(price - entry) / max(target_distance, 1e-6)

        if current_rr < lock_rr and progress < lock_progress:
            return None

        base_lock_distance = risk * lock_fraction
        atr_lock_distance = atr * atr_mult if atr and atr > 0 else 0.0
        lock_distance = max(base_lock_distance, atr_lock_distance)

        if direction == 'BUY':
            return entry + lock_distance
        return entry - lock_distance

    def _close_conflicting_trade(self, trade, price, reason):
        ticket = trade.get('ticket')
        direction = trade.get('dir')
        vol = float(trade.get('vol', 0.0))
        if not ticket or vol <= 0:
            return False

        if not MT5.partial_close(ticket, vol, direction):
            return False

        entry = float(trade.get('entry', 0.0))
        pnl = (price - entry) * vol * 100 if direction == 'BUY' else (entry - price) * vol * 100
        risk = abs(entry - float(trade.get('sl', entry)))
        r = pnl / max(1e-6, risk)

        STORE.close_trade(trade.get('id'), price, pnl, r)
        TG.notify_trade_update({
            'dir': direction,
            'action': reason,
            'pnl': pnl,
            'rr': r
        })
        OUTCOMES.record(
            trade.get('id'),
            pnl,
            r,
            strategy=trade.get('strategy'),
            regime=QUANTUM_CONTEXT.get('regime'),
            session=QUANTUM_CONTEXT.get('session'),
            reason=reason
        )
        if CFG.get("feature_store_enabled", True):
            STORE.update_feature_label(trade.get('id'), 1 if pnl > 0 else 0, meta={'pnl': pnl, 'reason': reason})
        LOG.info(f"[CONFLICT] Closed opposing trade {trade.get('id')} ({direction}) due to {reason}")
        return True

    def _update_chandelier(self, t, df, atr):
        if df is None or df.empty or atr <= 0:
            return None

        entry_ts = t.get('ts')
        if not entry_ts:
            return None

        try:
            entry_time = datetime.fromisoformat(entry_ts)
        except Exception:
            return None

        df_since = df[df.index >= entry_time]
        if df_since.empty:
            return None

        if t['dir'] == 'BUY':
            high_close = df_since['close'].max()
            trail_level = high_close - (CFG["trail_atr_multiplier"] * atr)
            return high_close, None, trail_level

        low_close = df_since['close'].min()
        trail_level = low_close + (CFG["trail_atr_multiplier"] * atr)
        return None, low_close, trail_level

    async def manage(self):
        # v13.0 Integration: Check portfolio heat (safely check if BATTLE exists)
        battle_inst = globals().get('BATTLE')
        if battle_inst and hasattr(battle_inst, 'v13_components_ready') and battle_inst.v13_components_ready:
            if battle_inst.risk_manager_v13 and (battle_inst.cycle_count % CFG.get("heat_check_frequency", 5) == 0):
                try:
                    heat_result = battle_inst.risk_manager_v13.portfolio_heat_monitor()
                    if heat_result and heat_result.get('status') == 'CRITICAL':
                        LOG.warning(f"[V13] Portfolio heat CRITICAL: {heat_result.get('total_heat_pct'):.1f}%")
                        if CFG.get("alert_on_heat_critical", True):
                            TG.notify(f"⚠️ v13 ALERT: Portfolio heat CRITICAL at {heat_result.get('total_heat_pct'):.1f}%")
                except Exception as e:
                    LOG.debug(f"[V13] Heat monitoring error: {e}")
        
        if CFG["mode"] == 'live':
            await MT5.sync_positions(STORE)
        trades = STORE.open_trades()
        if not trades:
            return
        
        tick = MT5.get_fresh_tick()
        if not tick:
            return
        
        price = tick['mid']

        if CFG.get("opposite_conflict_cleanup_enabled", True):
            buys = [t for t in trades if t.get('dir') == 'BUY']
            sells = [t for t in trades if t.get('dir') == 'SELL']
            if buys and sells:
                buy_pnl = sum((price - float(t.get('entry', 0.0))) * float(t.get('vol', 0.0)) * 100 for t in buys)
                sell_pnl = sum((float(t.get('entry', 0.0)) - price) * float(t.get('vol', 0.0)) * 100 for t in sells)
                threshold = CFG.get("opposite_trade_conflict_close_threshold", 1.0)

                if buy_pnl >= threshold and sell_pnl < 0:
                    closed_any = False
                    for t in sells:
                        if (float(t.get('entry', 0.0)) - price) * float(t.get('vol', 0.0)) * 100 <= 0:
                            if self._close_conflicting_trade(t, price, 'opposite_cleanup'):
                                closed_any = True
                    if closed_any:
                        trades = STORE.open_trades()
                        if not trades:
                            return

                elif sell_pnl >= threshold and buy_pnl < 0:
                    closed_any = False
                    for t in buys:
                        if (price - float(t.get('entry', 0.0))) * float(t.get('vol', 0.0)) * 100 <= 0:
                            if self._close_conflicting_trade(t, price, 'opposite_cleanup'):
                                closed_any = True
                    if closed_any:
                        trades = STORE.open_trades()
                        if not trades:
                            return

        def _trail_multiplier(regime_label):
            label = (regime_label or '').upper()
            if "SQUEEZE" in label or "VCP" in label or "COMPRESSION" in label:
                return 1.5
            if "TREND" in label:
                return 3.5
            return 2.5
        
        for t in trades:
            tid = t['id']
            ticket = t['ticket']
            entry = t['entry']
            sl = t['sl']
            tp = t['tp']
            vol = t['vol']
            direction = t['dir']
            
            risk = abs(entry - sl)
            base_risk = risk
            profit = (price - entry) if direction == 'BUY' else (entry - price)
            rr = profit / risk if risk > 0 else 0

            entry_tf = t.get('entry_tf') or CFG["timeframes"][0]
            trade_df = MT5.fetch(CFG["symbol"], entry_tf, 200)
            atr = None
            if trade_df is not None and not trade_df.empty:
                d = add_indicators(trade_df)
                if d is not None and not d.empty:
                    atr = float(d['atr'].iloc[-1])
            
            lot_step = EXNESS.get('step', 0.01)
            min_lot = EXNESS.get('min_lot', 0.01)
            init_vol = safe_float(t.get('init_vol'), vol)
            if init_vol <= 0:
                init_vol = vol
            if t.get('init_vol') is None:
                STORE.update_trade(tid, init_vol=init_vol)

            pip_value = EXNESS.get('point_value', 0.01)
            tier_1_pips = 10 * pip_value

            is_multi = init_vol >= 0.03 - 1e-9
            is_mid = abs(init_vol - 0.02) <= 1e-9
            is_min = abs(init_vol - 0.01) <= 1e-9

            if is_multi:
                tier1_vol = round(init_vol * 0.50, 2)
                tier2_vol = round(init_vol * 0.25, 2)

                if rr >= 1.0 and not t['partial_1']:
                    pvol = min(tier1_vol, max(0.0, vol - min_lot))
                    pvol = round(pvol, 2)
                    if pvol >= min_lot:
                        if MT5.partial_close(ticket, pvol, direction):
                            vol = round(vol - pvol, 2)
                            STORE.update_trade(tid, partial_1=1, vol=vol)
                            sl_tier1 = entry + tier_1_pips if direction == 'BUY' else entry - tier_1_pips
                            if MT5.modify(ticket, sl=sl_tier1):
                                STORE.update_trade(tid, sl=sl_tier1)
                            TG.notify_trade_update({
                                'dir': direction,
                                'action': 'partial',
                                'rr': rr
                            })

                if rr >= 2.0 and not t['partial_2']:
                    pvol = min(tier2_vol, max(0.0, vol - min_lot))
                    pvol = round(pvol, 2)
                    if pvol >= min_lot:
                        if MT5.partial_close(ticket, pvol, direction):
                            vol = round(vol - pvol, 2)
                            STORE.update_trade(tid, partial_2=1, vol=vol)
                            sl_tier2 = entry + base_risk if direction == 'BUY' else entry - base_risk
                            if MT5.modify(ticket, sl=sl_tier2):
                                STORE.update_trade(tid, sl=sl_tier2)
                            TG.notify_trade_update({
                                'dir': direction,
                                'action': 'partial',
                                'rr': rr
                            })

                runner_active = t.get('partial_2', 0) == 1
            elif is_mid:
                runner_active = False
                if rr >= 1.5 and not t['partial_1']:
                    pvol = round(min(round(init_vol * 0.50, 2), max(0.0, vol - min_lot)), 2)
                    if pvol >= min_lot:
                        if MT5.partial_close(ticket, pvol, direction):
                            vol = round(vol - pvol, 2)
                            STORE.update_trade(tid, partial_1=1, vol=vol)
                            TG.notify_trade_update({
                                'dir': direction,
                                'action': 'partial',
                                'rr': rr
                            })
                            runner_active = True
                else:
                    runner_active = t.get('partial_1', 0) == 1
            else:
                runner_active = False
                profit_lock_level = self._get_min_lot_profit_lock(direction, entry, sl, tp, price, risk, atr)
                if profit_lock_level is not None and not t['be_moved']:
                    moved = MT5.modify(ticket, sl=profit_lock_level)
                    if moved:
                        STORE.update_trade(tid, sl=profit_lock_level, be_moved=1)
                        TG.notify_trade_update({
                            'dir': direction,
                            'action': 'profit_lock'
                        })
                    runner_active = moved
                elif rr >= 1.0 and not t['be_moved']:
                    moved = MT5.modify(ticket, sl=entry)
                    if moved:
                        STORE.update_trade(tid, sl=entry, be_moved=1)
                        TG.notify_trade_update({
                            'dir': direction,
                            'action': 'breakeven'
                        })
                    runner_active = moved
                else:
                    runner_active = t.get('be_moved', 0) == 1
            
            if runner_active:
                entry_tf = t.get('entry_tf') or CFG["timeframes"][0]
                df = MT5.fetch(CFG["symbol"], entry_tf, 200)
                if df is not None and not df.empty:
                    d = add_indicators(df)
                    if d is not None and not d.empty:
                        atr = d['atr'].iloc[-1]
                        regime_label = QUANTUM_CONTEXT.get('regime')
                        if not regime_label:
                            try:
                                regime_label = QUANTUM_REGIME.detect(d)
                            except Exception:
                                regime_label = None
                        trail_mult = _trail_multiplier(regime_label)
                        trail_state = TRAIL_ENGINE.update(t, d, atr, multiplier=trail_mult)
                        if trail_state and trail_state.get('trail_level') is not None:
                            trail_level = trail_state['trail_level']
                            if direction == 'BUY' and trail_level > sl:
                                if MT5.modify(ticket, sl=trail_level):
                                    STORE.update_trade(
                                        tid,
                                        sl=trail_level,
                                        trail_high=trail_state.get('trail_high'),
                                        trail_level=trail_level
                                    )
                                    log_json("trail_update", trade_id=tid, new_sl=trail_level, rr=rr)
                            elif direction == 'SELL' and trail_level < sl:
                                if MT5.modify(ticket, sl=trail_level):
                                    STORE.update_trade(
                                        tid,
                                        sl=trail_level,
                                        trail_low=trail_state.get('trail_low'),
                                        trail_level=trail_level
                                    )
                                    log_json("trail_update", trade_id=tid, new_sl=trail_level, rr=rr)

            max_bars = t.get('max_duration_bars')
            if max_bars:
                entry_tf = t.get('entry_tf') or CFG["timeframes"][0]
                bars_since = self._bars_since_entry(t.get('ts'), entry_tf)
                if bars_since >= max_bars:
                    pvol = round(vol, 2)
                    if MT5.partial_close(ticket, pvol, direction):
                        pnl = (price - entry) if direction == 'BUY' else (entry - price)
                        r = pnl / risk if risk > 0 else 0
                        STORE.close_trade(tid, price, pnl, r)
                        TG.notify_trade_update({
                            'dir': direction,
                            'action': 'time_exit',
                            'pnl': pnl,
                            'rr': r
                        })
                        OUTCOMES.record(
                            tid,
                            pnl,
                            r,
                            strategy=t.get('strategy'),
                            regime=QUANTUM_CONTEXT.get('regime'),
                            session=QUANTUM_CONTEXT.get('session'),
                            reason='time_exit'
                        )
                        if CFG.get("feature_store_enabled", True):
                            STORE.update_feature_label(tid, 1 if pnl > 0 else 0, meta={'pnl': pnl})
                        
                        # v13.0 Integration: Record outcome in tracker and ingest features
                        battle_inst = globals().get('BATTLE')
                        if battle_inst and hasattr(battle_inst, 'v13_components_ready') and battle_inst.v13_components_ready:
                            try:
                                if battle_inst.outcome_tracker_v13:
                                    battle_inst.outcome_tracker_v13.record_outcome(
                                        tid, pnl, r,
                                        strategy=t.get('strategy'),
                                        regime=QUANTUM_CONTEXT.get('regime'),
                                        session=QUANTUM_CONTEXT.get('session'),
                                        reason='time_exit'
                                    )
                                if battle_inst.feature_store_v13:
                                    battle_inst.feature_store_v13.ingest_features(
                                        tid,
                                        features=None,  # Let it extract from trade data
                                        label=1 if pnl > 0 else 0,
                                        metadata={'pnl': pnl, 'rr': r, 'strategy': t.get('strategy')}
                                    )
                            except Exception as e:
                                LOG.warning(f"[V13] Error recording outcome/features: {e}")
                        
                        continue
            
            valid_sl = sl and sl != 0.0
            valid_tp = tp and tp != 0.0

            if ((direction == 'BUY' and ((valid_sl and price <= sl) or (valid_tp and price >= tp))) or \
               (direction == 'SELL' and ((valid_sl and price >= sl) or (valid_tp and price <= tp)))):
                
                pnl = (price - entry) if direction == 'BUY' else (entry - price)
                r = pnl / risk if risk > 0 else 0
                
                STORE.close_trade(tid, price, pnl, r)
                TG.notify_trade_update({
                    'dir': direction,
                    'action': 'close',
                    'pnl': pnl,
                    'rr': r
                })
                OUTCOMES.record(
                    tid,
                    pnl,
                    r,
                    strategy=t.get('strategy'),
                    regime=QUANTUM_CONTEXT.get('regime'),
                    session=QUANTUM_CONTEXT.get('session'),
                    reason='close'
                )
                if CFG.get("feature_store_enabled", True):
                    STORE.update_feature_label(tid, 1 if pnl > 0 else 0, meta={'pnl': pnl})
                
                # v13.0 Integration: Record outcome in tracker and ingest features
                battle_inst = globals().get('BATTLE')
                if battle_inst and hasattr(battle_inst, 'v13_components_ready') and battle_inst.v13_components_ready:
                    try:
                        if battle_inst.outcome_tracker_v13:
                            battle_inst.outcome_tracker_v13.record_outcome(
                                tid, pnl, r,
                                strategy=t.get('strategy'),
                                regime=QUANTUM_CONTEXT.get('regime'),
                                session=QUANTUM_CONTEXT.get('session'),
                                reason='close'
                            )
                        if battle_inst.feature_store_v13:
                            battle_inst.feature_store_v13.ingest_features(
                                tid,
                                features=None,  # Let it extract from trade data
                                label=1 if pnl > 0 else 0,
                                metadata={'pnl': pnl, 'rr': r, 'strategy': t.get('strategy')}
                            )
                    except Exception as e:
                        LOG.warning(f"[V13] Error recording outcome/features: {e}")
                
                trade_outcome = {'pnl': pnl, 'drawdown': 0.0, 'time_penalty': 0.0}
                reward = DRL_TRAINER.calculate_reward(trade_outcome)
                state = FEATURE_FACTORY.build_state_vector(CFG["symbol"], CFG["timeframes"]) if FEATURE_FACTORY else None
                DRL_TRAINER.collect_experience(state, 0, reward, state, True)

TRADE_MGR = TradeManager()

class ChartGenerator:
    def generate(self, df, sig):
        os.makedirs(CFG["charts_dir"], exist_ok=True)
        
        if MT5.connected:
            img_mt5 = MT5.screenshot('M15')
            if img_mt5:
                return img_mt5
        
        if MPF_OK:
            try:
                chart_df = df.tail(200).copy()
                if 'volume' not in chart_df.columns:
                    chart_df['volume'] = 0
                if 'tick_volume' in chart_df.columns:
                    chart_df = chart_df.rename(columns={'tick_volume': 'volume'})
                chart_df.index.name = 'Date'
                d = add_indicators(chart_df)
                if d is None or d.empty:
                    return None
                
                entry = sig['entry']
                sl = sig['sl']
                tp = sig['tp']
                
                # Professional color scheme
                apds = [
                    mpf.make_addplot(d['ema9'], color='#4CC9F0', width=1.5),     # Bright cyan
                    mpf.make_addplot(d['ema21'], color='#F59E0B', width=1.5),    # Amber
                    mpf.make_addplot(d['ema50'], color='#EF4444', width=1.0),    # Red
                    mpf.make_addplot(d['bb_upper'], color='#9CA3AF', linestyle='--', width=0.7, alpha=0.6),
                    mpf.make_addplot(d['bb_lower'], color='#9CA3AF', linestyle='--', width=0.7, alpha=0.6)
                ]
                
                # Create custom dark style for cleaner look
                mc = mpf.make_marketcolors(up='#10B981', down='#EF4444', edge='inherit', wick='inherit', volume='inherit')
                s = mpf.make_mpf_style(marketcolors=mc, gridcolor='#374151', gridstyle=':', facecolor='#111827', edgecolor='#1F2937')
                
                fig, axes = mpf.plot(
                    d,
                    type='candle',
                    style=s,
                    addplot=apds,
                    volume=False,
                    figsize=(14, 7),
                    returnfig=True
                )
                
                ax = axes[0]
                ax.set_facecolor('#111827')
                
                # Professional line styling for levels
                ax.axhline(entry, color='#4CC9F0', linestyle='-', linewidth=2.0, alpha=0.8, label=f'Entry: {entry:.2f}')
                ax.axhline(sl, color='#EF4444', linestyle='--', linewidth=1.5, alpha=0.8, label=f'Stop Loss: {sl:.2f}')
                ax.axhline(tp, color='#10B981', linestyle='--', linewidth=1.5, alpha=0.8, label=f'Target: {tp:.2f}')
                
                # Professional legend
                ax.legend(loc='upper left', framealpha=0.95, fancybox=True, shadow=False, fontsize=9)
                
                # Clean header with timestamp
                timestamp = utc_now().strftime('%Y-%m-%d %H:%M UTC')
                ax.text(0.98, 0.98, f'XAUUSD | Sentinel v12.1\n{timestamp}', 
                       transform=ax.transAxes,
                       fontsize=9, 
                       verticalalignment='top',
                       horizontalalignment='right',
                       bbox=dict(boxstyle='round,pad=0.5', facecolor='#1F2937', edgecolor='#4CC9F0', linewidth=1, alpha=0.9),
                       color='#D1D5DB', family='monospace')
                
                # Clean grid
                ax.grid(True, linestyle=':', alpha=0.3, color='#4B5563')
                ax.set_axisbelow(True)
                
                # Style axis labels
                ax.tick_params(colors='#9CA3AF', labelsize=8)
                for spine in ax.spines.values():
                    spine.set_color('#374151')
                
                buf = io.BytesIO()
                fig.savefig(buf, format='png', dpi=150, bbox_inches='tight', facecolor='#111827', edgecolor='none')
                plt.close(fig)
                buf.seek(0)
                return buf.read()
                
            except Exception as e:
                LOG.warning(f"[CHART] Generation failed: {e}")
                pass
        
        return None

class AdvancedChartGenerator:
    def __init__(self, mode='dark'):
        self.mode = mode

    def _style(self, mode):
        if mode == 'light':
            return mpf.make_mpf_style(base_mpf_style='yahoo')
        return mpf.make_mpf_style(base_mpf_style='nightclouds')

    def _prepare_df(self, df):
        if df is None or df.empty:
            return None
        d = df.copy()
        if 'tick_volume' in d.columns and 'volume' not in d.columns:
            d = d.rename(columns={'tick_volume': 'volume'})
        if 'volume' not in d.columns:
            d['volume'] = 0
        if not isinstance(d.index, pd.DatetimeIndex):
            if 'time' in d.columns:
                d.index = pd.to_datetime(d['time'], unit='s', utc=True)
            else:
                d.index = pd.to_datetime(d.index, utc=True)
        d.index.name = 'Date'
        return d

    def _trend_mask(self, d):
        if d is None or len(d) < 30:
            return None
        ema_fast = d['close'].ewm(span=9, adjust=False).mean()
        ema_slow = d['close'].ewm(span=21, adjust=False).mean()
        return ema_fast > ema_slow

    def _support_resistance_levels(self, d, window=5, max_levels=6):
        if d is None or len(d) < window * 3:
            return []
        highs = d['high']
        lows = d['low']
        piv_high = highs[(highs.shift(window) < highs) & (highs.shift(-window) < highs)]
        piv_low = lows[(lows.shift(window) > lows) & (lows.shift(-window) > lows)]
        levels = []
        for price in pd.concat([piv_high, piv_low]).dropna():
            bucket = round(price * 2) / 2
            levels.append(bucket)
        strength = {}
        for lvl in levels:
            strength[lvl] = strength.get(lvl, 0) + 1
        ranked = sorted(strength.items(), key=lambda x: x[1], reverse=True)
        return ranked[:max_levels]

    def _volume_profile(self, d, bins=24, value_area=0.7):
        if d is None or d.empty:
            return None
        prices = d['close'].values
        volume = d['volume'].values if 'volume' in d.columns else np.ones_like(prices)
        hist, edges = np.histogram(prices, bins=bins, weights=volume)
        if hist.sum() == 0:
            return None
        centers = (edges[:-1] + edges[1:]) / 2
        poc_idx = int(np.argmax(hist))
        total = hist.sum()
        sorted_idx = np.argsort(hist)[::-1]
        cum = 0
        included = []
        for idx in sorted_idx:
            cum += hist[idx]
            included.append(idx)
            if cum >= total * value_area:
                break
        va_low = centers[min(included)]
        va_high = centers[max(included)]
        return {
            'hist': hist,
            'centers': centers,
            'poc': centers[poc_idx],
            'va_low': va_low,
            'va_high': va_high
        }

    def _fib_levels(self, d, lookback=120):
        if d is None or len(d) < lookback:
            return []
        recent = d.tail(lookback)
        high = recent['high'].max()
        low = recent['low'].min()
        if high == low:
            return []
        levels = [0.236, 0.382, 0.5, 0.618, 0.786]
        return [high - (high - low) * lvl for lvl in levels]

    def _annotate_patterns(self, ax, d):
        if d is None or d.empty:
            return
        patterns = CANDLESTICK.detect(d) if 'CANDLESTICK' in globals() else []
        harmonic = HARMONIC.detect(d) if 'HARMONIC' in globals() else None
        y = d['high'].iloc[-1]
        if harmonic:
            ax.text(0.01, 0.95, f"{harmonic['pattern']} {harmonic['type']}",
                    transform=ax.transAxes, fontsize=8, color='gold')
        if patterns:
            top = patterns[0]
            ax.text(0.01, 0.90, top['type'], transform=ax.transAxes, fontsize=8, color='cyan')

    def _strategy_overlays(self, d, strategy):
        overlays = []
        if d is None or d.empty:
            return overlays
        strat = (strategy or "").lower()
        if "mean" in strat:
            if 'bb_upper' in d.columns and 'bb_lower' in d.columns:
                overlays.append(mpf.make_addplot(d['bb_upper'], color='#9ca3af', linestyle='--', width=0.8))
                overlays.append(mpf.make_addplot(d['bb_lower'], color='#9ca3af', linestyle='--', width=0.8))
        elif "breakout" in strat:
            lookback = min(len(d), 20)
            high_level = d['high'].iloc[-lookback:].max()
            low_level = d['low'].iloc[-lookback:].min()
            overlays.append(mpf.make_addplot(pd.Series(high_level, index=d.index), color='#fbbf24', width=0.8))
            overlays.append(mpf.make_addplot(pd.Series(low_level, index=d.index), color='#fbbf24', width=0.8))
        else:
            if 'ema9' in d.columns and 'ema21' in d.columns:
                overlays.append(mpf.make_addplot(d['ema9'], color='#60a5fa', width=1.0))
                overlays.append(mpf.make_addplot(d['ema21'], color='#f59e0b', width=1.0))
        return overlays

    def generate(self, data, sig=None, mode=None):
        if not MPF_OK:
            return None

        try:
            if isinstance(data, pd.DataFrame):
                data = {CFG["timeframes"][0]: data}

            sig_tf = sig.get('tf') if sig else None
            tf = sig_tf or (CFG.get("zen_chart_tf", CFG["timeframes"][0]) if CFG.get("zen_chart_tf") in data else None) or next((tf for tf in CFG["timeframes"] if tf in data), None)
            if not tf:
                return None
            tfs = [tf]

            mode = mode or self.mode
            style = self._style(mode)

            show_vp = False
            fig = plt.figure(figsize=(10, 5.5))
            gs = fig.add_gridspec(nrows=1, ncols=1, hspace=0.15)

            sig_tf = sig.get('tf') if sig else None
            for idx, tf in enumerate(tfs):
                ax = fig.add_subplot(gs[idx, 0] if show_vp else gs[idx, 0])
                tf_df = self._prepare_df(data[tf])
                if tf_df is None or tf_df.empty:
                    continue

                d = add_indicators(tf_df)
                if d is None or d.empty:
                    continue
                apply_overlays = (sig_tf is None and idx == 0) or (sig_tf == tf)
                overlays = []
                if apply_overlays and CFG.get("chart_strategy_overlays", True):
                    overlays.extend(self._strategy_overlays(d, sig.get('strategy') if sig else None))

                # Plot candlesticks using matplotlib directly (more reliable than mpf.plot with ax)
                ax.set_facecolor('#111111' if mode == 'dark' else '#f2f2f2')
                
                # Draw candlesticks
                for i, (idx_val, row) in enumerate(d.iterrows()):
                    open_p, close_p = row['open'], row['close']
                    high_p, low_p = row['high'], row['low']
                    
                    color = '#2dd4bf' if close_p >= open_p else '#ef4444'
                    
                    # Draw wick
                    ax.plot([i, i], [low_p, high_p], color=color, linewidth=0.8)
                    
                    # Draw body
                    body_height = abs(close_p - open_p)
                    body_bottom = min(open_p, close_p)
                    ax.add_patch(plt.Rectangle((i - 0.3, body_bottom), 0.6, body_height, 
                                              facecolor=color, edgecolor=color, linewidth=1.0))
                
                # Add overlays (strategy lines like EMA)
                if overlays:
                    for overlay in overlays:
                        if isinstance(overlay, dict) and 'data' in overlay:
                            ax.plot(overlay['data'], color=overlay.get('color', '#60a5fa'), 
                                   linewidth=overlay.get('width', 1.0))
                
                # Trend shading
                trend = self._trend_mask(d) if CFG.get("chart_show_trend_shading", False) else None
                if trend is not None:
                    for i in range(1, len(d)):
                        if trend.iloc[i]:
                            ax.axvspan(i - 0.5, i + 0.5, color='#1b4332', alpha=0.08)
                        else:
                            ax.axvspan(i - 0.5, i + 0.5, color='#5a1a1a', alpha=0.06)

                # Support/Resistance levels
                if CFG.get("chart_show_sr", False):
                    sr_levels = self._support_resistance_levels(d)
                    for lvl, strength in sr_levels:
                        ax.axhline(lvl, color='white' if mode == 'dark' else 'black', 
                                  linewidth=0.6 + 0.2 * strength, alpha=0.5)

                # Fibonacci levels
                if apply_overlays and CFG.get("chart_show_fibs", False):
                    fibs = self._fib_levels(d)
                    for lvl in fibs:
                        ax.axhline(lvl, color='#b08968', linestyle='--', linewidth=0.8, alpha=0.8)

                # Signal levels (Entry, SL, TP)
                if apply_overlays and sig:
                    entry = sig.get('entry')
                    sl = sig.get('sl')
                    tp = sig.get('tp')
                    if entry and sl:
                        ax.axhspan(min(entry, sl), max(entry, sl), color='#991b1b', alpha=0.15)
                    if entry and tp:
                        ax.axhspan(min(entry, tp), max(entry, tp), color='#065f46', alpha=0.12)
                    if entry:
                        ax.axhline(entry, color='#4cc9f0', linewidth=1.2, label='Entry')
                    if sl:
                        ax.axhline(sl, color='#f94144', linestyle='--', linewidth=1.0, label='SL')
                    if tp:
                        ax.axhline(tp, color='#90be6d', linestyle='--', linewidth=1.0, label='TP')

                # Patterns
                if apply_overlays and CFG.get("chart_show_patterns", False):
                    try:
                        self._annotate_patterns(ax, d)
                    except:
                        pass

                ax.set_title(f"{CFG['symbol']} {tf}", fontsize=9)
                ax.set_xlim(0, len(d))
                ax.set_ylim(d['low'].min() * 0.99, d['high'].max() * 1.01)
                ax.grid(True, alpha=0.2)


            buf = io.BytesIO()
            fig.savefig(buf, format='png', dpi=150, bbox_inches='tight')
            plt.close(fig)
            buf.seek(0)
            return buf.read()
        
        except ValueError as e:
            LOG.debug(f"[CHART] Chart generation error: {e}")
            plt.close('all')
            return None
        except Exception as e:
            LOG.debug(f"[CHART] Generation failed: {type(e).__name__}: {e}")
            plt.close('all')
            return None

class ZenChartGenerator(AdvancedChartGenerator):
    """Minimal, signal-focused chart for Telegram."""
    def generate(self, data, sig=None, mode=None):
        if not MPF_OK:
            return None

        if isinstance(data, pd.DataFrame):
            data = {CFG["timeframes"][0]: data}

        tf = (sig.get('tf') if sig else None) or CFG.get("zen_chart_tf", CFG["timeframes"][0])
        df = data.get(tf)
        df = self._prepare_df(df)
        if df is None or df.empty:
            return None

        d = add_indicators(df.tail(200))
        if d is None or d.empty:
            return None

        entry = sig.get('entry') if sig else None
        sl = sig.get('sl') if sig else None
        tp = sig.get('tp') if sig else None
        trail = sig.get('trail_level') if sig else None

        style = mpf.make_mpf_style(
            base_mpf_style='nightclouds',
            marketcolors=mpf.make_marketcolors(up='#2dd4bf', down='#ef4444', inherit=True),
            facecolor='#0E1117',
            gridcolor='#1f2937',
            figcolor='#0E1117'
        )

        fig, axlist = mpf.plot(
            d,
            type='candle',
            style=style,
            volume=False,
            returnfig=True,
            figsize=(10, 5)
        )
        ax = axlist[0]

        if entry and sl:
            ax.axhspan(min(entry, sl), max(entry, sl), color='#991b1b', alpha=0.15)
        if entry and tp:
            ax.axhspan(min(entry, tp), max(entry, tp), color='#065f46', alpha=0.12)
        if entry:
            ax.axhline(entry, color='#60a5fa', linewidth=1.2)
        if sl:
            ax.axhline(sl, color='#f87171', linestyle='--', linewidth=1.0)
        if tp:
            ax.axhline(tp, color='#34d399', linestyle='--', linewidth=1.0)
        if trail:
            ax.axhline(trail, color='#f59e0b', linestyle='-', linewidth=1.0)

        info = []
        if sig:
            if sig.get('final_confluence_score') is not None:
                info.append(f"Confluence: {sig['final_confluence_score']:.2f}")
            if sig.get('drl_confidence') is not None:
                info.append(f"DRL: {sig['drl_confidence']:.2f}")
            if sig.get('vol') is not None:
                info.append(f"Lots: {sig['vol']:.2f}")
            if sig.get('rr') is not None:
                info.append(f"RR: {sig['rr']:.2f}")

        if info:
            ax.text(
                0.01, 0.98, "\n".join(info),
                transform=ax.transAxes,
                fontsize=8,
                verticalalignment='top',
                bbox=dict(boxstyle='round', facecolor='#111827', alpha=0.6, edgecolor='#1f2937')
            )

        buf = io.BytesIO()
        fig.savefig(buf, format='png', dpi=150, bbox_inches='tight')
        plt.close(fig)
        buf.seek(0)
        return buf.read()

CHART = ZenChartGenerator() if CFG.get("use_zen_charts", False) else AdvancedChartGenerator()

class OfflineRecovery:
    def __init__(self):
        self.protect_mode = False
        self.protect_until = None
    
    def check_and_recover(self):
        state = STATE.load()
        if not state or 'ts' not in state:
            return True
        
        offline_mins = (utc_now() - datetime.fromisoformat(state['ts'])).total_seconds() / 60
        
        if offline_mins < 5:
            return True
        
        LOG.warning(f"[RECOVERY] Offline {offline_mins:.1f}m")
        TG.notify_status(f"Offline: {offline_mins:.1f}m")
        
        if offline_mins < 30:
            df = MT5.fetch(CFG["symbol"], 'M15', 100)
            if df is None or df.empty:
                self.protect_mode = True
                self.protect_until = utc_now() + timedelta(minutes=30)
            return True
        
        elif offline_mins < 360:
            start_time = datetime.fromisoformat(state['ts'])
            df = MT5.fetch_range(CFG["symbol"], 'M15', start_time, utc_now())
            if df is None or df.empty:
                self.protect_mode = True
                self.protect_until = utc_now() + timedelta(minutes=60)
            return True
        
        else:
            LOG.info("[RECOVERY] Full recovery")
            self.protect_mode = True
            self.protect_until = utc_now() + timedelta(minutes=240)
            return False
    
    def is_protected(self):
        if self.protect_mode and self.protect_until:
            return utc_now() < self.protect_until
        return False

RECOVERY = OfflineRecovery()

class AbsoluteRecoveryEngine:
    def __init__(self, store, mt5_conn, strategy):
        self.store = store
        self.mt5 = mt5_conn
        self.strategy = strategy
        self.last_recovery_ts = None

    def _timeframe_map(self):
        return {
            'M1': mt5.TIMEFRAME_M1,
            'M5': mt5.TIMEFRAME_M5,
            'M15': mt5.TIMEFRAME_M15,
            'H1': mt5.TIMEFRAME_H1,
            'H4': mt5.TIMEFRAME_H4,
            'D1': mt5.TIMEFRAME_D1,
            'W1': mt5.TIMEFRAME_W1,
            'MN1': mt5.TIMEFRAME_MN1
        }

    def _get_last_timestamp(self):
        state = STATE.load() or {}
        ts_state = state.get('ts')
        if ts_state:
            try:
                return datetime.fromisoformat(ts_state)
            except Exception:
                pass
        return self.store.get_latest_event_ts()

    def _fetch_range_direct(self, symbol, tf, start, end):
        if not self.mt5.ensure_connection():
            return None
        tf_map = self._timeframe_map()
        if tf not in tf_map:
            return None
        try:
            rates = mt5.copy_rates_range(symbol, tf_map[tf], start, end)
            if rates is None or (isinstance(rates, np.ndarray) and rates.size == 0):
                return None
            df = pd.DataFrame(rates)
            df.index = pd.to_datetime(df['time'], unit='s', utc=True)
            if 'tick_volume' in df.columns and 'volume' not in df.columns:
                df = df.rename(columns={'tick_volume': 'volume'})
            if 'volume' not in df.columns:
                df['volume'] = 0
            return df[['open', 'high', 'low', 'close', 'volume', 'spread']]
        except Exception as e:
            LOG.error(f"[RECOVERY] Fetch range error {tf}: {e}")
            return None

    def _fetch_tf_chunks(self, tf, start, end):
        chunk_minutes = CFG.get("recovery_chunk_minutes", {}).get(tf, 360)
        chunks = []
        cur = start
        while cur < end:
            chunk_end = min(cur + timedelta(minutes=chunk_minutes), end)
            df = self._fetch_range_direct(CFG["symbol"], tf, cur, chunk_end)
            if df is not None and not df.empty:
                chunks.append(df)
            cur = chunk_end
        if not chunks:
            return None
        merged = pd.concat(chunks).drop_duplicates()
        if len(merged) > CFG.get("recovery_max_bars", 5000):
            merged = merged.tail(CFG["recovery_max_bars"])
        return merged

    def _bulk_sync(self, start, end):
        dfs = {}
        bars_processed = 0
        with ThreadPoolExecutor(max_workers=min(4, len(CFG["timeframes"]))) as ex:
            futures = {
                tf: ex.submit(self._fetch_tf_chunks, tf, start, end)
                for tf in CFG["timeframes"]
            }
            for tf, fut in futures.items():
                df = fut.result()
                if df is not None and not df.empty:
                    dfs[tf] = df
                    bars_processed += len(df)
        return dfs, bars_processed

    def _catch_up_analysis(self, dfs):
        if not dfs:
            return 0
        bars = 0
        dfs_with_indicators = {}
        for tf, df in dfs.items():
            d = add_indicators(df)
            if d is not None and not d.empty:
                bars += len(d)
                dfs_with_indicators[tf] = d
        try:
            # Use dataframes WITH indicators, not raw dfs
            if dfs_with_indicators:
                tail = {tf: df.tail(300) for tf, df in dfs_with_indicators.items()}
                if tail and CFG["timeframes"][0] in tail:
                    self.strategy.analyze(tail, REGIME.detect(tail[CFG["timeframes"][0]]))
        except Exception as e:
            LOG.warning(f"[RECOVERY] Catch-up analyze failed: {e}")
        return bars

    def _reconcile_trades(self):
        if not self.mt5.ensure_connection():
            return 0, 0
        recovered = 0
        closed = 0
        try:
            positions = mt5.positions_get(symbol=CFG["symbol"]) or []
            if not positions:
                LOG.debug(f"[RECOVERY] No symbol positions returned for {CFG['symbol']}; checking all account positions")
                positions = [p for p in (mt5.positions_get() or []) if getattr(p, 'symbol', None) == CFG['symbol']]
            pos_map = {p.ticket: p for p in positions}
            db_open = self.store.open_trades()
            db_tickets = {t.get('ticket') for t in db_open}

            for trade in db_open:
                ticket = trade.get('ticket')
                if ticket not in pos_map:
                    # Try direct lookup in case symbol filtering missed the position
                    direct_pos = self.mt5.get_position_by_ticket(ticket)
                    if direct_pos is not None:
                        LOG.debug(f"[RECOVERY] Position {ticket} found by direct lookup despite symbol filter; continuing")
                        continue

                    all_positions = mt5.positions_get() or []
                    all_positions_for_symbol = [p for p in all_positions if getattr(p, 'symbol', None) == CFG['symbol']]

                    matching_pos = None
                    trade_dir = 'BUY' if trade['dir'] == 'BUY' else 'SELL'
                    trade_vol = abs(trade.get('vol', trade.get('init_vol', 0.0)))
                    trade_entry = float(trade.get('entry', 0.0))
                    for pos in all_positions_for_symbol:
                        if pos.ticket in db_tickets:
                            continue
                        pos_type = 'BUY' if pos.type == mt5.ORDER_TYPE_BUY else 'SELL'
                        if pos_type != trade_dir:
                            continue
                        vol_diff_pct = abs(pos.volume - trade_vol) / max(trade_vol, 1e-6) * 100
                        price_diff = abs(pos.price_open - trade_entry)
                        price_threshold = max(0.01, abs(trade_entry) * 0.002)
                        if vol_diff_pct < 5 and price_diff <= price_threshold:
                            matching_pos = pos
                            LOG.debug(f"[RECOVERY] Found matching position for ticket {ticket}: new_ticket={pos.ticket}, vol_diff={vol_diff_pct:.1f}%, price_diff={price_diff:.4f}")
                            break

                    if matching_pos:
                        self.store.update_trade(trade['id'], ticket=matching_pos.ticket)
                        recovered += 1
                        continue

                    valid_sl = trade.get('sl', 0.0) and trade.get('sl', 0.0) != 0.0
                    valid_tp = trade.get('tp', 0.0) and trade.get('tp', 0.0) != 0.0
                    if not valid_sl and not valid_tp:
                        LOG.warning(f"[RECOVERY] Skipping close for trade {trade['id']} with missing SL/TP and unknown MT5 ticket {ticket}")
                        continue

                    current = self.mt5.current_price()
                    if current:
                        pnl = (current - trade['entry']) if trade['dir'] == 'BUY' else (trade['entry'] - current)
                        r = pnl / max(1e-6, abs(trade['entry'] - trade['sl']))
                        self.store.close_trade(trade['id'], current, pnl, r)
                        closed += 1
                else:
                    pos = pos_map[ticket]
                    if abs(pos.volume - trade['vol']) > 1e-6:
                        self.store.update_trade(trade['id'], vol=pos.volume)
                        recovered += 1
                    if hasattr(pos, 'sl') and pos.sl:
                        self.store.update_trade(trade['id'], sl=pos.sl)
                    if hasattr(pos, 'tp') and pos.tp:
                        self.store.update_trade(trade['id'], tp=pos.tp)

            for pos in positions:
                if pos.ticket not in db_tickets:
                    trade_data = {
                        'id': f"REC{uuid.uuid4().hex[:8]}",
                        'sig_id': "RECOVERY",
                        'ts': utc_now().isoformat(),
                        'dir': 'BUY' if pos.type == mt5.ORDER_TYPE_BUY else 'SELL',
                        'entry': pos.price_open,
                        'sl': pos.sl or 0.0,
                        'tp': pos.tp or 0.0,
                        'vol': pos.volume,
                        'init_vol': pos.volume,
                        'status': 'open',
                        'ticket': pos.ticket,
                        'correlation_used': 0
                    }
                    self.store.insert_trade(trade_data)
                    recovered += 1
        except Exception as e:
            LOG.error(f"[RECOVERY] Trade reconcile failed: {e}")
        return recovered, closed

    def _validate(self):
        if not self.mt5.ensure_connection():
            return False
        try:
            positions = mt5.positions_get(symbol=CFG["symbol"]) or []
            db_open = self.store.open_trades()
            return len(positions) == len(db_open)
        except Exception:
            return False

    def check_and_recover(self):
        if not CFG.get("use_hedge_grade_recovery", False):
            return True

        start_time = time.time()
        last_ts = self._get_last_timestamp()
        if not last_ts:
            return True

        offline_mins = (utc_now() - last_ts).total_seconds() / 60
        if offline_mins < 5:
            return True

        log_json("recovery_start", offline_minutes=offline_mins)
        end_ts = utc_now()
        dfs, bars_processed = self._bulk_sync(last_ts, end_ts)
        analyzed = self._catch_up_analysis(dfs)
        recovered, closed = self._reconcile_trades()
        valid = self._validate()

        elapsed = time.time() - start_time
        log_json(
            "recovery_complete",
            duration_sec=round(elapsed, 2),
            bars_processed=bars_processed,
            bars_analyzed=analyzed,
            trades_recovered=recovered,
            trades_closed=closed,
            validation_ok=valid
        )

        if elapsed > CFG.get("recovery_timeout_sec", 1800):
            LOG.warning("[RECOVERY] Timeout threshold exceeded")

        return valid

class Backtester:
    """Complete backtesting engine with historical data simulation"""
    def __init__(self):
        self.trades = []
        self.equity_curve = []
        self.balance = CFG.get("account_balance", 100000)
        self.initial_balance = self.balance
        self.max_balance = self.balance
        self.min_balance = self.balance
        
    def run(self):
        LOG.info("[BACKTEST] Starting backtest")
        TG.notify_status("Starting backtest mode")
        
        try:
            # Parse date range from config
            from_date = CFG.get("backtest_from", "2024-01-01")
            to_date = CFG.get("backtest_to", "2024-12-31")
            symbol = CFG["symbol"]
            
            LOG.info(f"[BACKTEST] Fetching data from {from_date} to {to_date}")
            TG.notify_status(f"Backtesting {symbol} from {from_date} to {to_date}")
            
            # Fetch historical data for all timeframes
            dfs = {}
            for tf in CFG["timeframes"]:
                try:
                    df = self._fetch_backtest_data(symbol, tf, from_date, to_date)
                    if df is not None and not df.empty:
                        dfs[tf] = df
                        LOG.info(f"[BACKTEST] Loaded {len(df)} bars for {tf}")
                except Exception as e:
                    LOG.warning(f"[BACKTEST] Failed to load {tf}: {e}")
            
            if not dfs:
                LOG.error("[BACKTEST] No data available for backtest")
                TG.notify_error("Backtest failed: No data available")
                return
            
            # Run backtest on all data
            results = self._simulate_trading(dfs)
            
            # Calculate performance metrics
            metrics = self._calculate_metrics(results)
            
            # Log results
            self._log_results(metrics)
            
            LOG.info("[BACKTEST] Backtest completed successfully")
            TG.notify_status(f"✅ Backtest complete. Return: {metrics['total_return']:.2%}, Sharpe: {metrics['sharpe']:.2f}")
            
        except Exception as e:
            LOG.error(f"[BACKTEST] Error: {e}", exc_info=True)
            TG.notify_error(f"Backtest failed: {str(e)[:100]}")
    
    def _fetch_backtest_data(self, symbol, tf, from_date, to_date):
        """Fetch historical data from MT5 or cache"""
        try:
            # Try to fetch from MT5
            import datetime
            from_dt = datetime.datetime.fromisoformat(from_date)
            to_dt = datetime.datetime.fromisoformat(to_date)
            
            # Map timeframe strings to MT5 constants
            tf_map = {'M1': mt5.TIMEFRAME_M1, 'M5': mt5.TIMEFRAME_M5, 'M15': mt5.TIMEFRAME_M15,
                     'H1': mt5.TIMEFRAME_H1, 'H4': mt5.TIMEFRAME_H4, 'D1': mt5.TIMEFRAME_D1, 'W1': mt5.TIMEFRAME_W1, 'MN1': mt5.TIMEFRAME_MN1}
            
            if tf not in tf_map:
                return None
            
            # Calculate number of bars needed
            tf_minutes = {'M1': 1, 'M5': 5, 'M15': 15, 'H1': 60, 'H4': 240, 'D1': 1440, 'W1': 10080, 'MN1': 43200}
            days_diff = (to_dt - from_dt).days
            bars_needed = int((days_diff * 24 * 60) / tf_minutes.get(tf, 60)) + 100
            
            # Fetch from MT5
            rates = mt5.copy_rates_range(symbol, tf_map[tf], from_dt, to_dt)
            
            if rates is None or len(rates) == 0:
                return None
            
            # Convert to DataFrame
            df = pd.DataFrame(rates)
            df['time'] = pd.to_datetime(df['time'], unit='s')
            df = df.rename(columns={'open': 'open', 'high': 'high', 'low': 'low', 'close': 'close', 'tick_volume': 'volume'})
            df.set_index('time', inplace=True)
            df = df[['open', 'high', 'low', 'close', 'volume']]
            
            return df
            
        except Exception as e:
            LOG.warning(f"[BACKTEST] MT5 fetch failed: {e}")
            return None
    
    def _simulate_trading(self, dfs):
        """Simulate trading on historical data"""
        results = {'signals_generated': 0, 'trades_executed': 0, 'trades': [], 'equity': []}
        
        # Get the main timeframe data
        main_tf = CFG["timeframes"][0]
        main_df = dfs.get(main_tf)
        
        if main_df is None or main_df.empty:
            return results
        
        # Add indicators
        main_df = add_indicators(main_df, tf=main_tf, use_cache=True)
        
        # Iterate through each bar
        for idx in range(100, len(main_df)):
            try:
                current_df = main_df.iloc[:idx+1]
                
                # Generate signals
                signals = STRATEGY.analyze(dfs if idx < 500 else {main_tf: current_df}, 
                                          REGIME.detect(current_df.iloc[-1:]))
                
                if signals:
                    results['signals_generated'] += len(signals)
                    
                    # Find best signal
                    best = max(signals, key=lambda x: x.get('score', 0))
                    
                    # Apply filters
                    if best['score'] >= CFG.get("min_score", 5.5):
                        # Execute trade
                        trade = self._execute_backtest_trade(best, current_df.iloc[-1], results)
                        if trade:
                            results['trades_executed'] += 1
                            results['trades'].append(trade)
                
                # Record equity
                self.balance = self._update_balance_from_trades(results['trades'])
                self.equity_curve.append({'time': current_df.index[-1], 'equity': self.balance})
                results['equity'].append(self.balance)
                
            except Exception as e:
                LOG.debug(f"[BACKTEST] Bar error: {e}")
                continue
        
        return results
    
    def _execute_backtest_trade(self, signal, bar, results):
        """Simulate trade execution"""
        try:
            spread = CFG.get("backtest_spread_min", 0.2)
            direction = signal['dir']
            entry = bar['close']
            
            # Apply spread
            if direction == 1:  # BUY
                entry += (spread / 2)
            else:  # SELL
                entry -= (spread / 2)
            
            # Calculate position size
            risk_amount = self.balance * (CFG.get("risk_per_trade", 0.02))
            stop_distance = abs(entry - signal.get('sl', entry - 50))
            size = risk_amount / stop_distance if stop_distance > 0 else 0.01
            size = max(0.01, min(size, self.balance * 0.1))  # Limit to 10% of balance
            
            trade = {
                'direction': 'BUY' if direction == 1 else 'SELL',
                'entry': entry,
                'entry_time': bar.name,
                'size': size,
                'sl': signal.get('sl', entry - 50),
                'tp': signal.get('tp', entry + 100),
                'pnl': 0,
                'status': 'open'
            }
            
            return trade
            
        except Exception as e:
            LOG.debug(f"[BACKTEST] Trade execution error: {e}")
            return None
    
    def _update_balance_from_trades(self, trades):
        """Calculate current balance from open trades"""
        balance = self.initial_balance
        for trade in trades:
            if trade['status'] == 'closed':
                balance += trade['pnl']
        return balance
    
    def _calculate_metrics(self, results):
        """Calculate performance metrics"""
        try:
            equity = np.array(results.get('equity', [self.initial_balance]))
            trades = results.get('trades', [])
            
            # Basic metrics
            total_trades = len(trades)
            winning_trades = sum(1 for t in trades if t.get('pnl', 0) > 0)
            losing_trades = sum(1 for t in trades if t.get('pnl', 0) < 0)
            win_rate = winning_trades / total_trades if total_trades > 0 else 0
            
            # Drawdown
            cummax = np.maximum.accumulate(equity)
            drawdown = (equity - cummax) / cummax
            max_dd = np.min(drawdown) if len(drawdown) > 0 else 0
            
            # Returns
            returns = np.diff(equity) / equity[:-1] if len(equity) > 1 else np.array([])
            total_return = (equity[-1] - equity[0]) / equity[0] if len(equity) > 0 else 0
            avg_return = np.mean(returns) if len(returns) > 0 else 0
            std_return = np.std(returns) if len(returns) > 1 else 0
            
            # Sharpe ratio
            sharpe = (avg_return * 252) / (std_return * np.sqrt(252)) if std_return > 0 else 0
            
            # Profit factor
            total_profit = sum(max(t.get('pnl', 0), 0) for t in trades)
            total_loss = sum(max(-t.get('pnl', 0), 0) for t in trades)
            profit_factor = total_profit / total_loss if total_loss > 0 else 0
            
            metrics = {
                'total_trades': total_trades,
                'winning_trades': winning_trades,
                'losing_trades': losing_trades,
                'win_rate': win_rate,
                'total_return': total_return,
                'max_drawdown': max_dd,
                'sharpe': sharpe,
                'profit_factor': profit_factor,
                'avg_trade_pnl': np.mean([t.get('pnl', 0) for t in trades]) if trades else 0,
                'final_balance': equity[-1] if len(equity) > 0 else self.initial_balance
            }
            
            return metrics
            
        except Exception as e:
            LOG.error(f"[BACKTEST] Metric calculation error: {e}")
            return {}
    
    def _log_results(self, metrics):
        """Log backtest results"""
        try:
            LOG.info("[BACKTEST] ===== BACKTEST RESULTS =====")
            LOG.info(f"  Total Trades: {metrics.get('total_trades', 0)}")
            LOG.info(f"  Win Rate: {metrics.get('win_rate', 0):.1%}")
            LOG.info(f"  Total Return: {metrics.get('total_return', 0):.2%}")
            LOG.info(f"  Max Drawdown: {metrics.get('max_drawdown', 0):.2%}")
            LOG.info(f"  Sharpe Ratio: {metrics.get('sharpe', 0):.2f}")
            LOG.info(f"  Profit Factor: {metrics.get('profit_factor', 0):.2f}")
            LOG.info(f"  Final Balance: ${metrics.get('final_balance', 0):.2f}")
            LOG.info("[BACKTEST] =============================")
            
            # Save to file
            with open('state/backtest_results.json', 'w') as f:
                json.dump(metrics, f, indent=2, default=str)
                
        except Exception as e:
            LOG.error(f"[BACKTEST] Logging error: {e}")


