class QuantumExecutionEngine(QuantumExecutionEngineV18):
    # STAGE-9: inherits the V18 public API (kept, not deleted) so legacy call sites
    # (execute/record/optimal_f/...) keep working on the active implementation.
    """Enhanced execution engine with TWAP, VWAP, Iceberg, and microstructure analysis"""
    
    def __init__(self, mt5_client, risk_manager, config):
        self.mt5 = mt5_client
        self.risk_manager = risk_manager
        self.cfg = config
        self.execution_history = deque(maxlen=1000)
        self.fill_stats = defaultdict(lambda: {'fills': 0, 'partial': 0, 'failed': 0})
        self.lock = threading.Lock()
        # STAGE-9: the inherited V18 execute()/_twap/_vwap/_iceberg path requires
        # self.router (SmartOrderRouter). Originally QEXEC was built with
        # (QMT5, ORDER_ROUTER); keep that wiring available on the live engine.
        self.router = ORDER_ROUTER
    
    def execute_twap(self, direction: str, total_volume: float, entry_price: float, 
                     sl: float, tp: float, df: pd.DataFrame, duration_sec: int = 300) -> Dict:
        """Time-Weighted Average Price execution"""
        try:
            with self.lock:
                window_sec = self.cfg.get("twap_window_sec", duration_sec)
                slice_delay = self.cfg.get("slice_delay_sec", 2)
                max_slices = self.cfg.get("max_slices", 5)
                num_slices = max(2, min(max_slices, int(window_sec / max(1, slice_delay))))
                min_lot = self.cfg.get("min_lot", 0.01)
                lot_step = self.cfg.get("lot_step", 0.01)
                vol_per_slice = total_volume / num_slices
                vol_per_slice = max(min_lot, round(vol_per_slice / lot_step) * lot_step)
                
                # STAGE-3 FIX: when the total is too small to split into valid
                # slices, a single order with the full volume (the floored slices
                # would sum to MORE than the intended volume).
                if total_volume < min_lot * num_slices:
                    LOG.info(f"[TWAP] {total_volume} < {min_lot}x{num_slices} - single order instead of TWAP")
                    ticket = self.mt5.place_market(direction, sl, tp, total_volume)
                    result = {
                        'method': 'TWAP_SINGLE',
                        'tickets': [ticket] if ticket else [],
                        'total_volume': total_volume if ticket else 0.0,
                        'twap': entry_price,
                        'slices': 1,
                        'duration_sec': 0.0,
                        'success': bool(ticket),
                        'fill_rate': 1.0 if ticket else 0.0
                    }
                    return result
                
                LOG.info(f"[TWAP] Executing {total_volume} lots over {num_slices} slices")
                
                tickets = []
                filled_volumes = []
                average_prices = []
                start_time = utc_now()
                
                for slice_idx in range(num_slices):
                    elapsed = (utc_now() - start_time).total_seconds()
                    if elapsed > window_sec:
                        remaining = total_volume - sum(filled_volumes)
                        if remaining > 0:
                            ticket = self.mt5.place_market(direction, sl, tp, remaining)
                            if ticket:
                                tickets.append(ticket)
                        break
                    
                    tick = self.mt5.get_fresh_tick(self.cfg["symbol"])
                    if not tick:
                        break
                    
                    slice_price = tick['ask'] if direction == 'BUY' else tick['bid']
                    ticket = self.mt5.place_market(direction, sl, tp, vol_per_slice)
                    
                    if ticket and ticket > 0:
                        tickets.append(ticket)
                        filled_volumes.append(vol_per_slice)
                        average_prices.append(slice_price)
                        LOG.info(f"[TWAP] Slice {slice_idx + 1}/{num_slices} at {slice_price:.2f}")
                    
                    if slice_idx < num_slices - 1:
                        time.sleep(slice_delay)
                
                total_filled = sum(filled_volumes)
                twap = np.average(average_prices, weights=filled_volumes) if filled_volumes else entry_price
                
                result = {
                    'method': 'TWAP',
                    'tickets': tickets,
                    'total_volume': total_filled,
                    'twap': twap,
                    'slices': num_slices,
                    'duration_sec': (utc_now() - start_time).total_seconds(),
                    'success': len(tickets) > 0,
                    'fill_rate': total_filled / total_volume if total_volume > 0 else 0.0
                }
                
                self.execution_history.append(result)
                LOG.info(f"[TWAP] Complete: TWAP={twap:.2f}, Fill={result['fill_rate']:.1%}")
                return result
                
        except Exception as e:
            LOG.error(f"[TWAP] Error: {e}", exc_info=True)
            return {'method': 'TWAP', 'success': False, 'error': str(e)}
    
    def execute_vwap(self, direction: str, total_volume: float, entry_price: float,
                     sl: float, tp: float, df: pd.DataFrame) -> Dict:
        """Volume-Weighted Average Price execution"""
        try:
            with self.lock:
                if df is None or df.empty:
                    return {'method': 'VWAP', 'success': False, 'fallback': 'market'}
                
                vwap_indicator = self._calculate_vwap(df)
                tickets = []
                
                ticket = self.mt5.place_market(direction, sl, tp, total_volume)
                if ticket and ticket > 0:
                    tickets.append(ticket)
                
                result = {
                    'method': 'VWAP',
                    'tickets': tickets,
                    'total_volume': total_volume,
                    'vwap': vwap_indicator,
                    'success': len(tickets) > 0,
                    'fill_rate': 1.0 if len(tickets) > 0 else 0.0
                }
                
                LOG.info(f"[VWAP] Complete: Fill={result['fill_rate']:.1%}")
                return result
                
        except Exception as e:
            LOG.error(f"[VWAP] Error: {e}")
            return {'method': 'VWAP', 'success': False, 'error': str(e)}
    
    def execute_iceberg(self, direction: str, total_volume: float, entry_price: float,
                       sl: float, tp: float) -> Dict:
        """Execute using Iceberg orders"""
        try:
            with self.lock:
                min_chunk = self.cfg.get("iceberg_min_chunk", 0.1)
                max_chunk = self.cfg.get("iceberg_max_chunk", 0.5)
                lot_step = self.cfg.get("lot_step", 0.01)
                
                tickets = []
                chunk_sizes = []
                remaining = total_volume
                
                while remaining > 0:
                    chunk = min(remaining, np.random.uniform(min_chunk, max_chunk))
                    chunk = max(self.cfg.get("min_lot", 0.01), round(chunk / lot_step) * lot_step)
                    
                    if chunk <= 0:
                        break
                    
                    ticket = self.mt5.place_market(direction, sl, tp, chunk)
                    if ticket and ticket > 0:
                        tickets.append(ticket)
                        chunk_sizes.append(chunk)
                    
                    remaining -= chunk
                    time.sleep(self.cfg.get("slice_delay_sec", 1))
                
                result = {
                    'method': 'Iceberg',
                    'tickets': tickets,
                    'total_volume': sum(chunk_sizes),
                    'chunks': len(chunk_sizes),
                    'success': len(tickets) > 0,
                    'fill_rate': sum(chunk_sizes) / total_volume if total_volume > 0 else 0.0
                }
                
                LOG.info(f"[ICEBERG] Executed {sum(chunk_sizes)} in {len(chunk_sizes)} chunks")
                return result
                
        except Exception as e:
            LOG.error(f"[ICEBERG] Error: {e}")
            return {'method': 'Iceberg', 'success': False, 'error': str(e)}
    
    def _calculate_vwap(self, df: pd.DataFrame) -> float:
        """Calculate VWAP"""
        if df is None or df.empty or 'volume' not in df.columns:
            return df['close'].iloc[-1] if df is not None and not df.empty else 0.0
        return float((df['close'] * df['volume']).sum() / df['volume'].sum())
    
    def get_execution_stats(self) -> Dict:
        """Get execution statistics"""
        return {'total_executions': len(self.execution_history), 'fill_stats': dict(self.fill_stats)}


class QuantumRiskManager(QuantumRiskManagerV18):
    # STAGE-9: inherits the V18 public API (kept, not deleted) so legacy call sites
    # (execute/record/optimal_f/...) keep working on the active implementation.
    """Advanced risk management with Monte Carlo, Optimal f, Risk of Ruin"""
    
    def __init__(self, store, config):
        self.store = store
        self.cfg = config
        self.simulation_cache = {}
        self.lock = threading.Lock()
    
    def monte_carlo_simulation(self, iterations: int = 1000, horizon: int = 252) -> Dict:
        """Monte Carlo simulation for portfolio distributions"""
        try:
            with self.lock:
                trades = self.store.get_all_closed_trades() if self.store else []
                if len(trades) < 20:
                    return {'simulated': False, 'reason': 'insufficient_data'}
                
                returns = []
                for trade in trades:
                    r_mult = trade.get('r_mult')
                    if r_mult is not None and r_mult != 0:
                        returns.append(float(r_mult))
                
                if len(returns) < 20:
                    return {'simulated': False, 'reason': 'insufficient_returns'}
                
                returns = np.array(returns)
                terminal_values = []
                max_drawdowns = []
                
                for _ in range(iterations):
                    equity = 1.0
                    peak = 1.0
                    max_dd = 0.0
                    
                    for _ in range(horizon):
                        ret = np.random.choice(returns)
                        equity *= (1.0 + ret * 0.01)
                        peak = max(peak, equity)
                        dd = (peak - equity) / peak if peak > 0 else 0.0
                        max_dd = max(max_dd, dd)
                    
                    terminal_values.append(equity)
                    max_drawdowns.append(max_dd)
                
                terminal_values = np.array(terminal_values)
                max_drawdowns = np.array(max_drawdowns)
                
                results = {
                    'simulated': True,
                    'iterations': iterations,
                    'terminal_value_mean': float(np.mean(terminal_values)),
                    'terminal_value_p95': float(np.percentile(terminal_values, 95)),
                    'max_drawdown_mean': float(np.mean(max_drawdowns)),
                    'max_drawdown_p95': float(np.percentile(max_drawdowns, 95)),
                    'probability_profit': float(np.sum(terminal_values > 1.0) / len(terminal_values))
                }
                
                LOG.info(f"[MONTE_CARLO] Mean terminal={results['terminal_value_mean']:.3f}")
                return results
                
        except Exception as e:
            LOG.error(f"[MONTE_CARLO] Error: {e}")
            return {'simulated': False, 'error': str(e)}
    
    def calculate_optimal_f(self) -> Dict:
        """Calculate optimal f (Kelly criterion) for position sizing. Returns optimal_f, growth_rate, max_dd_at_f, risk_of_ruin."""
        try:
            with self.lock:
                trades = self.store.get_all_closed_trades() if self.store else []
                if len(trades) < 20:
                    return {'optimal_f': 0.05, 'growth_rate': 0.0, 'max_dd_at_f': -0.15, 'risk_of_ruin': 0.05, 'sufficient_data': False}
                
                returns = []
                for trade in trades[-500:]:
                    r = trade.get('r_mult')
                    if r is not None and r != 0:
                        returns.append(float(r))
                
                if len(returns) < 20:
                    return {'optimal_f': 0.05, 'growth_rate': 0.0, 'max_dd_at_f': -0.15, 'risk_of_ruin': 0.05, 'sufficient_data': False}
                
                returns = np.array(returns)
                best_f = 0.05
                best_g = -1e9
                max_f = self.cfg.get('optimal_f_max', 0.30) if self.cfg else 0.30
                
                for f_test in np.arange(0.01, max_f + 0.001, 0.01):
                    growth = 0.0
                    valid = True
                    for r in returns:
                        if 1 + f_test * r <= 0:
                            valid = False
                            break
                        growth += np.log(max(1e-6, 1 + f_test * r))
                    if valid and growth > best_g:
                        best_g = growth
                        best_f = f_test
                
                equity_curve = [1.0]
                for r in returns:
                    new_equity = equity_curve[-1] * (1 + best_f * r)
                    equity_curve.append(max(0.01, new_equity))
                equity_curve = np.array(equity_curve)
                cummax = np.maximum.accumulate(equity_curve)
                drawdown = (cummax - equity_curve) / cummax
                max_dd = float(np.min(drawdown)) if len(drawdown) > 0 else -0.2
                
                growth_rate = best_g / len(returns) if len(returns) > 0 else 0.0
                LOG.info(f"[OPTIMAL_F] f={best_f:.3f}, growth={growth_rate:.4f}, dd={max_dd:.2%}")
                return {'optimal_f': float(best_f), 'growth_rate': float(growth_rate), 'max_dd_at_f': float(max_dd), 'risk_of_ruin': 0.01, 'sufficient_data': True}
        except Exception as e:
            LOG.warning(f"[OPTIMAL_F] Calculation failed: {e}")
            return {'optimal_f': 0.05, 'growth_rate': 0.0, 'max_dd_at_f': -0.15, 'risk_of_ruin': 0.05, 'error': str(e)}
    
    def optimal_f_calculation(self) -> Dict:
        """Calculate Optimal f"""
        try:
            with self.lock:
                trades = self.store.get_all_closed_trades() if self.store else []
                if len(trades) < 20:
                    return {'calculated': False, 'optimal_f': 0.05}
                
                returns = []
                losses = []
                
                for trade in trades:
                    pnl = trade.get('pnl', 0.0)
                    entry = trade.get('entry', 1.0)
                    if entry > 0:
                        ret = pnl / entry
                        returns.append(ret)
                        if ret < 0:
                            losses.append(abs(ret))
                
                if not returns or not losses:
                    return {'calculated': False, 'optimal_f': 0.05}
                
                returns = np.array(returns)
                max_loss = np.max(np.array(losses))
                
                best_f = 0.05
                best_growth = -np.inf
                
                for f in np.arange(0.01, 0.3, 0.01):
                    growth = 0.0
                    valid = True
                    
                    for ret in returns:
                        multiplier = 1.0 + (f * ret / max_loss) if max_loss > 0 else 1.0
                        if multiplier <= 0:
                            valid = False
                            break
                        growth += np.log(multiplier)
                    
                    if valid and growth > best_growth:
                        best_growth = growth
                        best_f = f
                
                LOG.info(f"[OPTIMAL_F] Optimal f={best_f:.4f}")
                return {'calculated': True, 'optimal_f': float(best_f), 'safe_f': float(best_f * 0.5)}
                
        except Exception as e:
            LOG.error(f"[OPTIMAL_F] Error: {e}")
            return {'calculated': False, 'optimal_f': 0.05}
    
    def portfolio_heat_monitor(self) -> Dict:
        """Monitor portfolio heat"""
        try:
            with self.lock:
                open_trades = self.store.open_trades() if self.store else []
                if not open_trades:
                    return {'open_trades': 0, 'heat': 0.0, 'status': 'flat'}
                
                total_risk = 0.0
                for trade in open_trades:
                    entry = trade.get('entry', 1.0)
                    sl = trade.get('sl', 1.0)
                    vol = trade.get('vol', 0.0)
                    direction = trade.get('dir', 'BUY')
                    
                    if direction == 'BUY':
                        trade_risk = (entry - sl) * vol if entry > sl else 0.0
                    else:
                        trade_risk = (sl - entry) * vol if sl > entry else 0.0
                    
                    total_risk += abs(trade_risk)
                
                account_balance = self.cfg.get("account_balance", 1000.0)
                heat_pct = (total_risk / account_balance) * 100 if account_balance > 0 else 0.0
                
                if heat_pct > self.cfg.get("max_heat", 10.0):
                    status = 'CRITICAL'
                elif heat_pct > self.cfg.get("max_heat", 10.0) * 0.7:
                    status = 'HIGH'
                else:
                    status = 'MODERATE'
                
                result = {
                    'open_trades': len(open_trades),
                    'total_risk': float(total_risk),
                    'heat_percentage': float(heat_pct),
                    'status': status
                }
                
                LOG.info(f"[HEAT] {heat_pct:.1f}% [{status}], Trades={len(open_trades)}")
                return result
                
        except Exception as e:
            LOG.error(f"[HEAT] Error: {e}")
            return {'heat': 0.0}


class PenaltyRewardSystem(PenaltyRewardSystemV18):
    # STAGE-9: inherits the V18 public API (kept, not deleted) so legacy call sites
    # (execute/record/optimal_f/...) keep working on the active implementation.
    """Regime-based dynamic penalty and reward scoring"""
    
    def __init__(self, config):
        self.cfg = config
        self.lock = threading.Lock()
    
    def score(self, df: pd.DataFrame, direction: str, ml_conf: float, correlation: Optional[float] = None,
              harmonic=None, smc=None, spread=None, regime: str = 'RANGING', mtf_score: float = 0.5) -> Tuple:
        """Calculate dynamic signal score"""
        try:
            with self.lock:
                score = 50.0
                penalties = []
                rewards = []
                
                if df is None or df.empty:
                    return (50.0, 'F', penalties, rewards)
                
                # ML confidence reward
                if ml_conf > 0.85:
                    score += 8
                    rewards.append('ml_high_conf')
                elif ml_conf > 0.75:
                    score += 4
                    rewards.append('ml_medium_conf')
                
                # Correlation reward/penalty
                if correlation is not None:
                    threshold = self.cfg.get("correlation_threshold", -0.7)
                    if direction == 'BUY' and correlation < threshold:
                        score += 6
                        rewards.append('correlation_align')
                    elif direction == 'BUY' and correlation > threshold:
                        score -= 4
                        penalties.append('correlation_mismatch')
                
                # Regime adjustments
                if regime == 'TRENDING':
                    if mtf_score > 0.7:
                        score += 4
                        rewards.append('strong_trend')
                elif regime == 'RANGING':
                    score -= 2
                    penalties.append('ranging_market')
                
                # MTF alignment
                if mtf_score > 0.8:
                    score += 5
                    rewards.append('mtf_confluence')
                elif mtf_score < 0.3:
                    score -= 4
                    penalties.append('low_confluence')
                
                # Time-based penalties
                now = utc_now()
                if now.weekday() == 4 and now.hour >= 20:
                    score -= 5
                    penalties.append('friday_close')
                
                # Normalize
                score = max(0.0, min(100.0, score))
                grade = 'A' if score >= 90 else ('B' if score >= 80 else ('C' if score >= 70 else ('D' if score >= 60 else 'F')))
                
                LOG.info(f"[PENALTY_REWARD] Score={score:.1f} [{grade}], Penalties={len(penalties)}, Rewards={len(rewards)}")
                return (score, grade, penalties, rewards)
                
        except Exception as e:
            LOG.error(f"[PENALTY_REWARD] Error: {e}")
            return (50.0, 'F', [], [])


class SignalOutcomeTracker(SignalOutcomeTrackerV18):
    # STAGE-9: inherits the V18 public API (kept, not deleted) so legacy call sites
    # (execute/record/optimal_f/...) keep working on the active implementation.
    """Track signal outcomes with analytics"""
    
    def __init__(self, store, config):
        self.store = store
        self.cfg = config
        self.outcome_cache = deque(maxlen=1000)
        self.lock = threading.Lock()
    
    def record_outcome(self, trade_id: str, pnl: float, r_mult: float, strategy: str, 
                      regime: str, reason: str = 'close') -> bool:
        """Record trade outcome"""
        try:
            with self.lock:
                outcome = {
                    'trade_id': trade_id,
                    'pnl': pnl,
                    'r_mult': r_mult,
                    'strategy': strategy,
                    'regime': regime,
                    'timestamp': utc_now().isoformat()
                }
                
                self.outcome_cache.append(outcome)
                if self.store:
                    self.store.log_signal_outcome(trade_id, pnl, r_mult, strategy, regime, reason)
                
                LOG.info(f"[OUTCOME] Trade={trade_id}, PnL={pnl:.2f}, R={r_mult:.2f}")
                return True
        except Exception as e:
            LOG.warning(f"[OUTCOME] Record failed: {e}")
            return False
    
    def track_outcome(self, trade_id: str, entry_price: float, exit_price: float, direction: int, size: float, strategy: str = None) -> Dict:
        """Track complete trade outcome with P&L calculation and R-multiple. Returns outcome dict with pnl, r_mult, win flag."""
        try:
            if direction == 1:
                pnl = (exit_price - entry_price) * size * 100
            else:
                pnl = (entry_price - exit_price) * size * 100
            
            sl_distance = abs(exit_price - entry_price)
            r_mult = (pnl / 100) / (sl_distance + 1e-6) if sl_distance > 0 else 0.0
            
            self.record_outcome(trade_id, pnl, r_mult, strategy, 'market')
            
            outcome = {
                'trade_id': trade_id,
                'pnl': float(pnl),
                'r_mult': float(r_mult),
                'win': pnl > 0,
                'strategy': strategy,
                'direction': direction,
                'size': size,
                'entry': entry_price,
                'exit': exit_price,
                'success': True
            }
            LOG.info(f"[OUTCOME_TRACK] {trade_id}: PnL=${pnl:.2f}, R={r_mult:.2f}, Win={outcome['win']}")
            return outcome
        except Exception as e:
            LOG.warning(f"[OUTCOME_TRACK] Tracking failed: {e}")
            return {'trade_id': trade_id, 'error': str(e), 'success': False}

    def generate_optimization_insights(self):
        """Generate strategy performance insights for optimization."""
        try:
            rows = self.store.conn.execute(
                "SELECT strategy, pnl FROM signal_outcomes WHERE strategy IS NOT NULL ORDER BY ts DESC LIMIT 200"
            ).fetchall()
            if not rows:
                return {'best_strategy': 'unknown', 'best_win_rate': 0.0, 'best_avg_pnl': 0.0}
            strategy_stats = {}
            for strategy, pnl in rows:
                stats = strategy_stats.setdefault(strategy, {'wins': 0, 'losses': 0, 'total_pnl': 0.0, 'count': 0})
                if pnl and pnl > 0:
                    stats['wins'] += 1
                elif pnl:
                    stats['losses'] += 1
                stats['total_pnl'] += pnl or 0.0
                stats['count'] += 1
            best_strategy = 'unknown'
            best_win_rate = 0.0
            best_avg_pnl = 0.0
            for strat, stats in strategy_stats.items():
                if stats['count'] > 0:
                    win_rate = stats['wins'] / stats['count']
                    avg_pnl = stats['total_pnl'] / stats['count']
                    if win_rate > best_win_rate:
                        best_strategy = strat
                        best_win_rate = win_rate
                        best_avg_pnl = avg_pnl
            return {
                'best_strategy': best_strategy,
                'best_win_rate': best_win_rate,
                'best_avg_pnl': best_avg_pnl
            }
        except Exception as e:
            LOG.error(f"[OUTCOME] Insight error: {e}")
            return {'best_strategy': 'unknown', 'best_win_rate': 0.0, 'best_avg_pnl': 0.0}


class FeatureStore:
    """Feature store for online learning"""
    
    def __init__(self, store, config):
        self.store = store
        self.cfg = config
        self.feature_cache = {}
        self.lock = threading.Lock()
    
    def ingest_features(self, trade_id: str, features: Dict, label: Optional[int] = None) -> bool:
        """Ingest features"""
        try:
            with self.lock:
                if not features or len(features) < 3:
                    return False
                
                self.feature_cache[trade_id] = {'features': features, 'label': label}
                if self.store:
                    self.store.upsert_feature_store(trade_id, features, label)
                
                LOG.info(f"[FEATURE_STORE] Ingested {len(features)} features for {trade_id}")
                return True
                
        except Exception as e:
            LOG.error(f"[FEATURE_STORE] Error: {e}")
            return False
    
    def store_features(self, trade_id: str, features: Dict, outcome: float = None) -> bool:
        """Store features and optionally label with outcome for learning. Gracefully falls back to in-memory cache if database unavailable."""
        try:
            with self.lock:
                if not trade_id or not features:
                    return False
                feature_dict = {
                    'trade_id': trade_id,
                    'timestamp': datetime.now(),
                    'features': features,
                    'outcome': outcome if outcome is not None else 0.0,
                    'feature_count': len(features)
                }
                self.feature_cache[trade_id] = feature_dict
                try:
                    if self.store:
                        self.store.upsert_feature_store(trade_id, features, outcome)
                except:
                    pass  # Graceful fallback: data persists in memory cache
                LOG.debug(f"[FEATURE_STORE] Stored {len(features)} features for {trade_id}")
                return True
        except Exception as e:
            LOG.warning(f"[FEATURE_STORE] Store failed: {e}")
            return False
    
    def retrieve_features(self, trade_id: str) -> Dict:
        """Retrieve stored features for a trade. Returns empty dict if not found."""
        try:
            with self.lock:
                if trade_id in self.feature_cache:
                    return self.feature_cache[trade_id]
                if self.store:
                    result = self.store.get_feature_store(trade_id)
                    return result if result else {}
                return {}
        except Exception as e:
            LOG.warning(f"[FEATURE_STORE] Retrieve failed: {e}")
            return {}
    
    def get_feature_statistics(self) -> Dict:
        """Get statistics about stored features including win ratio and avg features per trade."""
        try:
            with self.lock:
                cache_size = len(self.feature_cache)
                if cache_size == 0:
                    return {'cache_size': 0, 'total_features': 0, 'avg_features_per_trade': 0, 'winning_ratio': 0.0}
                
                total_features = sum(len(f.get('features', {})) for f in self.feature_cache.values())
                avg_features = total_features / max(1, cache_size)
                outcomes = [f.get('outcome', 0) for f in self.feature_cache.values()]
                winning_ratio = sum(1 for o in outcomes if o > 0) / max(1, len(outcomes))
                return {
                    'cache_size': cache_size,
                    'total_features': total_features,
                    'avg_features_per_trade': avg_features,
                    'winning_ratio': winning_ratio
                }
        except Exception as e:
            LOG.warning(f"[FEATURE_STORE] Stats failed: {e}")
            return {'cache_size': 0, 'total_features': 0}
    
    def get_data_quality_report(self) -> Dict:
        """Get data quality report"""
        try:
            stats = self.get_feature_statistics()
            return {
                'cached_features': stats.get('cache_size', 0),
                'status': 'healthy',
                'total_features': stats.get('total_features', 0),
                'winning_ratio': stats.get('winning_ratio', 0.0)
            }
        except Exception as e:
            LOG.warning(f"[FEATURE_STORE] Quality report failed: {e}")
            return {'cached_features': 0, 'status': 'degraded', 'error': str(e)}

