class MeanReversionStrategy:
    """Trade mean reversion in sideways markets using Bollinger Bands + Z-score"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.trades = deque(maxlen=100)
        self.lock = threading.Lock()
        self.name = 'MEAN_REVERSION'
    
    def generate_signal(self, df: pd.DataFrame) -> Dict:
        """Generate mean reversion signal"""
        try:
            if df is None or df.empty or len(df) < 20:
                return {'signal': 'NEUTRAL', 'confidence': 0}
            
            # Calculate Bollinger Bands
            sma = df['close'].rolling(20).mean()
            std = df['close'].rolling(20).std()
            upper_bb = sma + (std * 2)
            lower_bb = sma - (std * 2)
            
            current_price = df['close'].iloc[-1]
            current_sma = sma.iloc[-1]
            current_std = std.iloc[-1]
            
            # Z-score
            z_score = (current_price - current_sma) / (current_std + 1e-6)
            
            signal = 'NEUTRAL'
            confidence = 0.5
            
            # Signal generation
            if current_price > upper_bb.iloc[-1] and z_score > 2:
                signal = 'SELL'  # Overbought
                confidence = min(0.85, 0.5 + abs(z_score) * 0.1)
            elif current_price < lower_bb.iloc[-1] and z_score < -2:
                signal = 'BUY'  # Oversold
                confidence = min(0.85, 0.5 + abs(z_score) * 0.1)
            
            return {
                'signal': signal,
                'confidence': float(confidence),
                'strategy': self.name,
                'z_score': float(z_score),
                'bb_position': float((current_price - lower_bb.iloc[-1]) / (upper_bb.iloc[-1] - lower_bb.iloc[-1]))
            }
        except Exception as e:
            LOG.warning(f"[{self.name}] Signal failed: {e}")
            return {'signal': 'NEUTRAL', 'confidence': 0}


class BreakoutMomentumStrategy:
    """Trade breakouts with momentum confirmation"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.trades = deque(maxlen=100)
        self.lock = threading.Lock()
        self.name = 'BREAKOUT'
    
    def generate_signal(self, df: pd.DataFrame) -> Dict:
        """Generate breakout signal"""
        try:
            if df is None or df.empty or len(df) < 20:
                return {'signal': 'NEUTRAL', 'confidence': 0}
            
            d = add_indicators(df)
            if d is None or d.empty:
                return {'signal': 'NEUTRAL', 'confidence': 0}

            # Donchian Channel (20-period)
            high_20 = d['high'].rolling(20).max()
            low_20 = d['low'].rolling(20).min()
            
            current_price = d['close'].iloc[-1]
            prev_price = d['close'].iloc[-2]
            last = d.iloc[-1]
            prev = d.iloc[-2]
            atr = float(last.get('atr', 1.0))
            adx = float(calc_adx(d).iloc[-1]) if len(d) > 30 else 20.0
            vol_surge, momentum_strength, vol_ok, _, _ = _adaptive_volume_filter(last, prev, d, atr, adx)
            
            signal = 'NEUTRAL'
            confidence = 0.5
            
            # Breakout detection
            if current_price > high_20.iloc[-1] and vol_ok:
                if _detect_false_breakout(d, 'BUY', float(high_20.iloc[-1]), atr):
                    return {'signal': 'NEUTRAL', 'confidence': 0, 'strategy': self.name, 'reason': 'false_breakout'}
                signal = 'BUY'
                confidence = min(0.90, 0.6 + vol_surge * 0.1 + (0.03 if momentum_strength >= 1.0 else 0.0))
            elif current_price < low_20.iloc[-1] and vol_ok:
                if _detect_false_breakout(d, 'SELL', float(low_20.iloc[-1]), atr):
                    return {'signal': 'NEUTRAL', 'confidence': 0, 'strategy': self.name, 'reason': 'false_breakout'}
                signal = 'SELL'
                confidence = min(0.90, 0.6 + vol_surge * 0.1 + (0.03 if momentum_strength >= 1.0 else 0.0))
            
            return {
                'signal': signal,
                'confidence': float(confidence),
                'strategy': self.name,
                'donchian_high': float(high_20.iloc[-1]),
                'donchian_low': float(low_20.iloc[-1]),
                'volume_surge': float(vol_surge),
                'momentum_strength': float(momentum_strength)
            }
        except Exception as e:
            LOG.warning(f"[{self.name}] Signal failed: {e}")
            return {'signal': 'NEUTRAL', 'confidence': 0}


class DivergenceStrategy:
    """Trade price/indicator divergences for reversals"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.lock = threading.Lock()
        self.name = 'DIVERGENCE'
    
    def generate_signal(self, df: pd.DataFrame) -> Dict:
        """Generate divergence signal"""
        try:
            if df is None or df.empty or len(df) < 20:
                return {'signal': 'NEUTRAL', 'confidence': 0}
            
            # Calculate RSI for divergence
            delta = df['close'].diff()
            gain = (delta.where(delta > 0, 0)).rolling(window=14).mean()
            loss = (-delta.where(delta < 0, 0)).rolling(window=14).mean()
            rs = gain / loss
            rsi = 100 - (100 / (1 + rs))
            
            # Look for divergence (last 2 peaks/troughs)
            signal = 'NEUTRAL'
            confidence = 0.5
            
            try:
                recent_rsi = rsi.iloc[-10:].values
                recent_price = df['close'].iloc[-10:].values
                
                # Bullish divergence: price lower low, RSI higher low
                if recent_price[-1] < recent_price[-5] and recent_rsi[-1] > recent_rsi[-5]:
                    signal = 'BUY'
                    confidence = 0.75
                
                # Bearish divergence: price higher high, RSI lower high
                elif recent_price[-1] > recent_price[-5] and recent_rsi[-1] < recent_rsi[-5]:
                    signal = 'SELL'
                    confidence = 0.75
            except:
                pass
            
            return {
                'signal': signal,
                'confidence': float(confidence),
                'strategy': self.name,
                'rsi': float(rsi.iloc[-1]) if len(rsi) > 0 else 50
            }
        except Exception as e:
            LOG.warning(f"[{self.name}] Signal failed: {e}")
            return {'signal': 'NEUTRAL', 'confidence': 0}


class ScalpingStrategy:
    """High-frequency scalping using tick velocity and micro S/R"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.tick_buffer = deque(maxlen=50)
        self.lock = threading.Lock()
        self.name = 'SCALPING'
    
    def generate_signal(self, df: pd.DataFrame, latest_tick: Dict = None) -> Dict:
        """Generate scalping signal"""
        try:
            if df is None or df.empty or len(df) < 5:
                return {'signal': 'NEUTRAL', 'confidence': 0}
            
            # Tick velocity (price changes per period)
            if latest_tick:
                with self.lock:
                    self.tick_buffer.append(latest_tick)
            
            # Micro support/resistance (last 5 candles)
            micro_high = df['high'].iloc[-5:].max()
            micro_low = df['low'].iloc[-5:].min()
            current_price = df['close'].iloc[-1]
            
            # Momentum on 1-minute scale
            velocity = df['close'].diff().rolling(3).mean()
            
            signal = 'NEUTRAL'
            confidence = 0.5
            
            # Bounce off micro levels
            if current_price < micro_low * 1.001 and velocity.iloc[-1] > 0:
                signal = 'BUY'
                confidence = 0.70
            elif current_price > micro_high * 0.999 and velocity.iloc[-1] < 0:
                signal = 'SELL'
                confidence = 0.70
            
            return {
                'signal': signal,
                'confidence': float(confidence),
                'strategy': self.name,
                'micro_support': float(micro_low),
                'micro_resistance': float(micro_high),
                'velocity': float(velocity.iloc[-1]) if len(velocity) > 0 else 0
            }
        except Exception as e:
            LOG.warning(f"[{self.name}] Signal failed: {e}")
            return {'signal': 'NEUTRAL', 'confidence': 0}


