class PerformanceDashboard:
    """Real-time performance monitoring dashboard"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.metrics_history = deque(maxlen=1000)
        self.lock = threading.Lock()
    
    def update_metrics(self, equity: float, drawdown: float, win_rate: float, 
                      sharpe: float, trades_count: int) -> Dict:
        """Update performance metrics"""
        try:
            with self.lock:
                metrics = {
                    'timestamp': datetime.now(),
                    'equity': float(equity),
                    'drawdown': float(drawdown),
                    'win_rate': float(win_rate),
                    'sharpe': float(sharpe),
                    'trades': int(trades_count)
                }
                self.metrics_history.append(metrics)
                
                return metrics
        except Exception as e:
            LOG.warning(f"[DASHBOARD] Update failed: {e}")
            return {}
    
    def get_current_dashboard(self) -> Dict:
        """Get current dashboard state"""
        try:
            with self.lock:
                if not self.metrics_history:
                    return {}
                
                latest = self.metrics_history[-1]
                
                # Calculate trends
                if len(self.metrics_history) > 10:
                    recent = list(self.metrics_history)[-10:]
                    equity_trend = 'UP' if recent[-1]['equity'] > recent[0]['equity'] else 'DOWN'
                    wr_trend = 'UP' if recent[-1]['win_rate'] > recent[0]['win_rate'] else 'DOWN'
                else:
                    equity_trend = 'FLAT'
                    wr_trend = 'FLAT'
                
                return {
                    'current_metrics': latest,
                    'equity_trend': equity_trend,
                    'win_rate_trend': wr_trend,
                    'history_size': len(self.metrics_history)
                }
        except Exception as e:
            LOG.warning(f"[DASHBOARD] Get failed: {e}")
            return {}


class StrategyAnalytics:
    """Detailed strategy performance analytics"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.strategy_stats = defaultdict(lambda: {
            'trades': 0, 'wins': 0, 'losses': 0, 'avg_win': 0, 'avg_loss': 0,
            'profit_factor': 0, 'win_rate': 0, 'total_pnl': 0
        })
        self.lock = threading.Lock()
    
    def record_trade(self, strategy: str, pnl: float, win: bool) -> None:
        """Record trade result for strategy"""
        try:
            with self.lock:
                stats = self.strategy_stats[strategy]
                stats['trades'] += 1
                stats['total_pnl'] += pnl
                
                if win:
                    stats['wins'] += 1
                    stats['avg_win'] = (stats['avg_win'] * (stats['wins'] - 1) + pnl) / stats['wins']
                else:
                    stats['losses'] += 1
                    stats['avg_loss'] = (stats['avg_loss'] * (stats['losses'] - 1) + abs(pnl)) / stats['losses']
                
                # Recalculate metrics
                if stats['trades'] > 0:
                    stats['win_rate'] = stats['wins'] / stats['trades']
                
                if stats['avg_loss'] > 0:
                    stats['profit_factor'] = (stats['avg_win'] * stats['wins']) / (stats['avg_loss'] * stats['losses'])
        except Exception as e:
            LOG.warning(f"[STRATEGY_ANALYTICS] Record failed: {e}")
    
    def get_strategy_report(self, strategy: str = None) -> Dict:
        """Get strategy performance report"""
        try:
            with self.lock:
                if strategy:
                    return dict(self.strategy_stats.get(strategy, {}))
                else:
                    return dict(self.strategy_stats)
        except Exception as e:
            LOG.warning(f"[STRATEGY_ANALYTICS] Report failed: {e}")
            return {}


class ModelExplainability:
    """ML model decision explanation using SHAP-like approach"""
    
    def __init__(self, config: Dict = None):
        self.cfg = config or {}
        self.explanations = deque(maxlen=500)
        self.lock = threading.Lock()
    
    def explain_decision(self, decision: Dict, features: Dict, 
                        feature_importance: Dict = None) -> Dict:
        """Explain ML model decision"""
        try:
            with self.lock:
                explanation = {
                    'timestamp': datetime.now(),
                    'decision': decision,
                    'contributing_features': [],
                    'feature_values': features
                }
                
                # Calculate feature contribution (simplified SHAP-like)
                if feature_importance:
                    for feature, importance in sorted(feature_importance.items(), 
                                                     key=lambda x: x[1], reverse=True)[:5]:
                        explanation['contributing_features'].append({
                            'feature': feature,
                            'importance': float(importance),
                            'value': features.get(feature, 0)
                        })
                
                self.explanations.append(explanation)
                
                return explanation
        except Exception as e:
            LOG.warning(f"[EXPLAINABILITY] Explanation failed: {e}")
            return {}


