#   STRATEGY.analyze / STRATEGY.multi_tf_alignment / REGIME.detect /
#   CIRCUIT.check_protocol (5/10/15/20% ladder) / RISK_ENGINE (SL + lots) /
#   consecutive-loss pause / max-daily-DD halt.
#
# Execution model (conservative, no lookahead):
#   - decision on bar j's CLOSE, fill at bar j+1's OPEN (+/- half spread)
#   - SL = 2.0*ATR (real risk-engine formula), TP = 2R, 50% partial at 1R
#   - intrabar SL/TP resolution; SL assumed first if both hit in one bar
#   - one position at a time; time-stop at 48 bars; gap through SL fills at open
#
# NOT simulated (disclosed in every report): M5/M15 intrabar granularity
# (decision TF = H1), news filter, DXY correlation, trailing/BE,
# v19/orchestrator/neural/order-flow layers, commission/swap (spread included).
# yfinance GC=F is a COMEX futures proxy for spot XAUUSD.
RISK_ENGINE = RiskEngine()  # PHASE A: backtest uses the SAME risk engine as the bot

# ============================================================================
# PHASE B (STAGE-18): GOLD LAYERS
# ============================================================================
# AsianRangeEngine - research-based session engine:
#   build the Asian range (00:00-07:00 UTC), trade the London/NY breakout
#   with WICK-PROOF entry (the candle must CLOSE beyond the range, a wick
#   does not count), target 1.5-2x the range width, stop at the opposite
#   end of the range. One entry per side per day.
class AsianRangeEngine:
    def __init__(self, symbol=None, persist=True):
        self.day = None
        self.asian_high = None
        self.asian_low = None
        self.entries = {}
        self._symbol = symbol
        self._persist = persist
        if persist:
            self._load()

    def _state_path(self):
        _d = os.path.dirname(CFG.get('state_file', 'state/bot_state.json')) or '.'
        _sym = self._symbol or CFG.get('symbol', 'XAUUSDm')
        return os.path.join(_d, f"asian_range_{_sym}.json")

    def _load(self):
        try:
            p = self._state_path()
            if os.path.exists(p):
                s = json.load(open(p))
                if s.get('day') == utc_now().date().isoformat():
                    self.day = s['day']
                    self.asian_high = s.get('asian_high')
                    self.asian_low = s.get('asian_low')
                    self.entries = s.get('entries', {})
        except Exception:
            pass

    def _save(self):
        if not self._persist:
            return
        try:
            with open(self._state_path(), 'w') as f:
                json.dump({'day': self.day, 'asian_high': self.asian_high,
                           'asian_low': self.asian_low, 'entries': self.entries}, f)
        except Exception:
            pass

    def reset_if_new_day(self, ts):
        d = str(ts.date())
        if self.day != d:
            self.day = d
            self.asian_high = None
            self.asian_low = None
            self.entries = {}
            self._save()

    def on_bar(self, ts, high, low, close, atr, tf_trend=None, trinity_bias='neutral'):
        """Feed one CLOSED bar (UTC). Returns a breakout signal dict or None."""
        end_h = CFG.get('asian_range_end_hour', 7)
        self.reset_if_new_day(ts)
        hr = ts.hour
        if hr < end_h:  # build the Asian range
            changed = False
            if self.asian_high is None or high > self.asian_high:
                self.asian_high = high; changed = True
            if self.asian_low is None or low < self.asian_low:
                self.asian_low = low; changed = True
            if changed:
                self._save()
            return None
        if hr >= 20:  # outside the London/NY breakout window
            return None
        if self.asian_high is None or self.asian_low is None:
            return None
        rng = self.asian_high - self.asian_low
        min_rng = max(CFG.get('asian_range_min_width', 2.0), 0.25 * (atr or 0))
        if rng < min_rng:
            return None
        max_per_side = CFG.get('asian_range_max_entries_per_side', 1)
        direction = None
        if close > self.asian_high:      # wick-proof: CLOSE beyond the range
            if self.entries.get('BUY', 0) < max_per_side:
                direction = 'BUY'
        elif close < self.asian_low:
            if self.entries.get('SELL', 0) < max_per_side:
                direction = 'SELL'
        if direction is None:
            return None
        self.entries[direction] = self.entries.get(direction, 0) + 1
        self._save()
        tp_mult = CFG.get('asian_range_tp_mult', 1.75)
        if direction == 'BUY':
            sl, tp = self.asian_low, close + tp_mult * rng
        else:
            sl, tp = self.asian_high, close - tp_mult * rng
        score = 7.5
        reasons = [f"AsianRange {direction} (range {self.asian_low:.1f}-{self.asian_high:.1f}, w={rng:.1f}, wick-proof close)"]
        if tf_trend == direction:
            score += 1.0
            reasons.append("H4 trend confluence")
        if (direction == 'BUY' and trinity_bias == 'bullish') or (direction == 'SELL' and trinity_bias == 'bearish'):
            score += 1.0
            reasons.append(f"Trinity confluence ({trinity_bias})")
        return {
            'tf': 'ASIAN', 'dir': direction, 'score': score, 'raw_score': score,
            'entry': close, 'sl': sl, 'tp': tp, 'atr': atr or 0,
            'signal_type': 'breakout', 'strategy': 'asian_breakout',
            'reasons': reasons,
            'features': {'range_high': self.asian_high, 'range_low': self.asian_low,
                         'range_width': rng, 'atr': atr or 0, 'close': close}
        }

    @staticmethod
    def h4_trend(df):
        try:
            d = add_indicators(df)
            l = d.iloc[-1]
            if l['ema9'] > l['ema21'] > l['ema50']:
                return 'BUY'
            if l['ema9'] < l['ema21'] < l['ema50']:
                return 'SELL'
        except Exception:
            pass
        return None


# TrinitySentinel - the gold "holy trinity": DXY + US10Y yields + XAU.
# Deterministic bias from 20d daily trends + rolling 50d XAU/DXY correlation
# (decoupling flag per the research: |corr| < 0.3 = the classic negative
# relationship is weakening). Background refresh only - the cycle never blocks.
class TrinitySentinel:
    def __init__(self):
        self.cache = None
        self._lock = threading.Lock()
        self._thread = None

    def get(self, max_age_hours=24.0):
        c = self.cache
        if c and (utc_now() - c['ts']).total_seconds() < max_age_hours * 3600:
            return c
        return None

    def refresh_async(self):
        with self._lock:
            if self.cache and (utc_now() - self.cache['ts']).total_seconds() < CFG.get('trinity_refresh_minutes', 15) * 60:
                return
            if self._thread and self._thread.is_alive():
                return
            self._thread = threading.Thread(target=self._fetch, daemon=True)
            self._thread.start()

    @staticmethod
    def compute_bias(xau_closes, dxy_closes, tny_closes):
        """Deterministic bias from 20d trends + 50d rolling correlation."""
        if len(xau_closes) < 25 or len(dxy_closes) < 25 or len(tny_closes) < 25:
            return None
        dxy20 = (dxy_closes[-1] / dxy_closes[-21] - 1.0) * 100.0
        tny20 = tny_closes[-1] - tny_closes[-21]  # in yield points
        xr = pd.Series(xau_closes[-55:]).pct_change().dropna()
        dr = pd.Series(dxy_closes[-55:]).pct_change().dropna()
        corr = float(xr.corr(dr)) if len(xr) >= 30 and len(dr) >= 30 else 0.0
        decoupled = abs(corr) < 0.3
        if dxy20 < -0.2 and tny20 < -0.03:
            bias = 'bullish'
        elif dxy20 > 0.2 and tny20 > 0.03:
            bias = 'bearish'
        else:
            bias = 'neutral'
        reasons = [f"DXY 20d {dxy20:+.2f}%, US10Y 20d {tny20:+.2f}pts, corr50 {corr:+.2f}"]
        if decoupled:
            reasons.append("XAU/DXY decoupling - classic negative link weakening")
        return {'dxy_trend': dxy20, 'y10y_trend': tny20, 'corr': corr,
                'decoupled': decoupled, 'bias': bias, 'reasons': reasons}

    def _fetch(self):
        try:
            import yfinance as yf
            x = yf.download('GC=F', period='120d', interval='1d', progress=False)
            d = yf.download('DX-Y.NYB', period='120d', interval='1d', progress=False)
            t = yf.download('^TNX', period='120d', interval='1d', progress=False)
            if x is None or d is None or t is None or x.empty or d.empty or t.empty:
                return
            for f in (x, d, t):
                if isinstance(f.columns, pd.MultiIndex):
                    f.columns = f.columns.get_level_values(0)
            xc = x.rename(columns=str.lower)['close'].dropna().tolist()
            dc = d.rename(columns=str.lower)['close'].dropna().tolist()
            tc = t.rename(columns=str.lower)['close'].dropna().tolist()
            n = min(len(xc), len(dc), len(tc))
            bias = self.compute_bias(xc[-n:], dc[-n:], tc[-n:])
            if bias:
                bias['ts'] = utc_now()
                with self._lock:
                    self.cache = bias
                try:
                    os.makedirs('state', exist_ok=True)
                    with open('state/trinity_cache.json', 'w') as f:
                        json.dump({'ts': bias['ts'].isoformat(), **{k: v for k, v in bias.items() if k != 'ts'}}, f, indent=1)
                except Exception:
                    pass
        except Exception:
            pass

    @staticmethod
    def adjust(sig_dir, cache):
        """Score delta + reasons for a signal direction given the trinity cache."""
        if not cache or cache.get('bias') == 'neutral':
            return 0.0, []
        agree = (sig_dir == 'BUY') == (cache['bias'] == 'bullish')
        d = 1.5 if agree else -1.5
        r = [f"Trinity {cache['bias']} ({'; '.join(cache.get('reasons', [])[:2])})"]
        return d, r


# ============================================================================
# PHASE C (STAGE-19): BTC MICROSTRUCTURE (public data, no API key)
# ============================================================================
# BinanceSentiment - funding rate, open interest, taker ratio, Fear & Greed.
# Research-based flags:
#   crowded_long : high positive funding + rising OI + stalling price -> reversal
#   squeeze_long : deep negative funding + OI building -> squeeze setup
#   funding_div  : price up + funding down = hidden strength (and vice versa)
#   stress       : |funding| > 0.1%/8h
class BinanceSentiment:
    BASE = "https://fapi.binance.com"

    def __init__(self):
        self.cache = None
        self._lock = threading.Lock()
        self._thread = None

    def get(self, max_age_hours=24.0):
        c = self.cache
        if c and (utc_now() - c['ts']).total_seconds() < max_age_hours * 3600:
            return c
        return None

    def refresh_async(self):
        with self._lock:
            if self.cache and (utc_now() - self.cache['ts']).total_seconds() < CFG.get('btc_sentiment_refresh_hours', 4) * 3600:
                return
            if self._thread and self._thread.is_alive():
                return
            self._thread = threading.Thread(target=self._fetch, daemon=True)
            self._thread.start()

    @staticmethod
    def _get(url, timeout=8):
        import urllib.request
        req = urllib.request.Request(url, headers={'User-Agent': 'sentinel-backtest/1.0'})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return json.loads(r.read().decode())

    @classmethod
    def compute(cls, prem, oi, oi_hist, taker_hist, klines, fng=None):
        try:
            funding = float(prem.get('lastFundingRate', 0) or 0)
            oi_now = float(oi.get('openInterest', 0) or 0)
            oi_5d = oi_30d = 0.0
            if oi_hist and len(oi_hist) >= 6:
                oi_5d = oi_now / max(1e-9, float(oi_hist[-6].get('sumOpenInterest', 0))) - 1.0
            if oi_hist and len(oi_hist) >= 30:
                oi_30d = oi_now / max(1e-9, float(oi_hist[-30].get('sumOpenInterest', 0))) - 1.0
            taker = float(taker_hist[-1].get('buySellRatio', 1.0)) if taker_hist else 1.0
            chg24 = float(klines[-1][4]) / max(1e-9, float(klines[0][4])) - 1.0 if klines and len(klines) > 1 else 0.0
            fng_val = None
            if fng and isinstance(fng, list) and fng:
                try:
                    fng_val = int(fng[0].get('value'))
                except Exception:
                    pass
            snap = cls.flags_from(funding, oi_5d, chg24, fng_val, taker)
            snap['oi_change_30d'] = oi_30d
            return snap
        except Exception:
            return None

    @staticmethod
    def flags_from(funding, oi_5d=0.0, chg24=0.0, fng=None, taker=1.0):
        """Pure flag/bias logic - shared by the live snapshot and backtest history."""
        flags = []
        if funding > 0.0005 and oi_5d > 0.05 and abs(chg24) < 0.005:
            flags.append('crowded_long')
        if funding < -0.0003 and oi_5d > 0.02:
            flags.append('squeeze_long')
        if chg24 > 0.005 and funding < 0:
            flags.append('div_bull')
        if chg24 < -0.005 and funding > 0.0003:
            flags.append('div_bear')
        if abs(funding) > 0.001:
            flags.append('stress')
        if 'crowded_long' in flags:
            bias = 'bearish'
        elif 'squeeze_long' in flags or 'div_bull' in flags:
            bias = 'bullish'
        elif 'div_bear' in flags:
            bias = 'bearish'
        else:
            bias = 'neutral'
        return {
            'funding': funding, 'funding_ann': funding * 3 * 365,
            'oi_change_5d': oi_5d,
            'taker_ratio_24h': taker, 'chg_24h': chg24, 'fng': fng,
            'flags': flags, 'bias': bias
        }

    def fetch_history(self, start_ts, end_ts, max_pages=8):
        """PHASE C backtest support: historical funding (paged, full depth),
        daily OI + taker (90d max), daily F&G (~365d max). Returns a dict of
        pd.Series, or None if the API is unreachable from this network."""
        try:
            sym = 'BTCUSDT'
            out = {'funding': None, 'oi': None, 'taker': None, 'fng': None}
            start_ms = int(start_ts.timestamp() * 1000)
            end_ms = int(end_ts.timestamp() * 1000)
            cur_end = end_ms
            rows = []
            for _ in range(max_pages):
                try:
                    chunk = self._get(f"{self.BASE}/fapi/v1/fundingRate?symbol={sym}&startTime={start_ms}&endTime={cur_end}&limit=1000")
                except Exception:
                    return None  # API unreachable from this network
                if not chunk:
                    break
                rows = chunk + rows
                if len(chunk) < 1000:
                    break
                cur_end = int(chunk[0].get('fundingTime', 0)) - 1
            if rows:
                out['funding'] = pd.Series(
                    {pd.to_datetime(int(r['fundingTime']), unit='ms'): float(r['fundingRate']) for r in rows})
            try:
                oi_hist = self._get(f"{self.BASE}/futures/data/openInterestHist?symbol={sym}&period=1d&limit=90")
                out['oi'] = pd.Series({pd.to_datetime(int(r['timestamp']), unit='ms'): float(r['sumOpenInterest']) for r in oi_hist})
                tk_hist = self._get(f"{self.BASE}/futures/data/takerlongshortRatio?symbol={sym}&period=1d&limit=90")
                out['taker'] = pd.Series({pd.to_datetime(int(r['timestamp']), unit='ms'): float(r['buySellRatio']) for r in tk_hist})
                fng = self._get('https://api.alternative.me/fng/?limit=365')
                out['fng'] = pd.Series({pd.to_datetime(int(r['timestamp']) * 1000, unit='ms'): int(r['value']) for r in fng.get('data', [])})
            except Exception:
                pass
            return out if out['funding'] is not None else None
        except Exception:
            return None

    def _fetch(self):
        sym = 'BTCUSDT'
        try:
            prem = self._get(f"{self.BASE}/fapi/v1/premiumIndex?symbol={sym}")
            oi = self._get(f"{self.BASE}/fapi/v1/openInterest?symbol={sym}")
            oi_hist = self._get(f"{self.BASE}/futures/data/openInterestHist?symbol={sym}&period=1d&limit=31")
            taker_hist = self._get(f"{self.BASE}/futures/data/takerlongshortRatio?symbol={sym}&period=1h&limit=24")
            klines = self._get(f"{self.BASE}/fapi/v1/klines?symbol={sym}&interval=1h&limit=25")
            try:
                fng = self._get("https://api.alternative.me/fng/?limit=1")
            except Exception:
                fng = None
            snap = self.compute(prem, oi, oi_hist, taker_hist, klines, fng)
            if snap:
                snap['ts'] = utc_now()
                with self._lock:
                    self.cache = snap
                try:
                    os.makedirs('state', exist_ok=True)
                    with open('state/btc_sentiment.json', 'w') as f:
                        json.dump({'ts': snap['ts'].isoformat(), **{k: v for k, v in snap.items() if k != 'ts'}}, f, indent=1)
                except Exception:
                    pass
        except Exception as e:
            LOG.debug(f"[BTC-SENT] fetch failed: {e}")

    @staticmethod
    def adjust(sig_dir, snap):
        """Score delta + reasons for a signal direction given the sentiment snapshot."""
        if not snap:
            return 0.0, []
        d, r = 0.0, []
        if snap.get('bias') in ('bullish', 'bearish'):
            agree = (sig_dir == 'BUY') == (snap['bias'] == 'bullish')
            d += 1.5 if agree else -1.5
            r.append(f"Funding/OI {snap['bias']} (funding {snap['funding']*100:.3f}%/8h, OI5d {snap['oi_change_5d']*100:+.1f}%, F&G {snap.get('fng')})")
        if 'crowded_long' in snap.get('flags', []) and sig_dir == 'BUY':
            d -= 2.0
            r.append("Crowded-long warning: high funding + rising OI + stalling price")
        if 'stress' in snap.get('flags', []):
            d -= 0.5
            r.append("Funding stress |f|>0.1%")
        return d, r


# ============================================================================
# PHASE D (STAGE-20): NARRATIVE SENTINEL
# ============================================================================
# Deterministic market narrative built from LIVE state (state -> chosen words).
# No LLM required; optional Gemini polish when enabled and available.
class NarrativeSentinel:
    def build(self, bot=None):
        """Assemble the narrative from live (or CLI-synthesized) state."""
        L = []
        sym = CFG.get('symbol', 'XAUUSDm')
        is_xau = sym.upper().startswith('XAU')
        now = utc_now()
        session = 'Asia' if now.hour < 7 else ('London' if now.hour < 13 else ('New York' if now.hour < 20 else 'Overnight'))
        L.append(f"{sym} — {session} session, {now.strftime('%Y-%m-%d %H:%M UTC')}.")
        # trend + regime from the bot's live frames (or CLI fallback data)
        trend_txt, regime_txt = 'trend state unknown (no market data in this process)', 'regime unknown'
        try:
            dfs = getattr(bot, 'dfs', None) or {}
            h4 = dfs.get('H4')
            if h4 is not None and len(h4) >= 30:
                d = add_indicators(h4)
                l = d.iloc[-1]
                if l['ema9'] > l['ema21'] > l['ema50']:
                    trend_txt = "H4 structure is bullish (EMA9>21>50)"
                elif l['ema9'] < l['ema21'] < l['ema50']:
                    trend_txt = "H4 structure is bearish (EMA9<21<50)"
                else:
                    trend_txt = "H4 structure is mixed/rotating"
            r = getattr(bot, 'current_regime', None)
            if r:
                regime_txt = f"market regime reads as {r}"
        except Exception:
            pass
        L.append(f"{trend_txt}; {regime_txt}.")
        # macro layer
        if is_xau:
            tri = TRINITY.get()
            if tri:
                if tri['bias'] == 'bullish':
                    L.append(f"Macro trinity leans BULLISH: DXY 20d {tri['dxy_trend']:+.2f}%, US10Y {tri['y10y_trend']:+.2f}pts, XAU/DXY corr50 {tri['corr']:+.2f}." + (" Warning: the classic DXY inverse link is decoupling." if tri['decoupled'] else ""))
                elif tri['bias'] == 'bearish':
                    L.append(f"Macro trinity leans BEARISH: DXY 20d {tri['dxy_trend']:+.2f}%, US10Y {tri['y10y_trend']:+.2f}pts, XAU/DXY corr50 {tri['corr']:+.2f}.")
                else:
                    L.append(f"Macro trinity is mixed/neutral (DXY 20d {tri['dxy_trend']:+.2f}%, US10Y {tri['y10y_trend']:+.2f}pts, corr50 {tri['corr']:+.2f}).")
            else:
                L.append("Macro trinity data not fresh (DXY/US10Y unavailable).")
        else:
            sent = BINANCE_SENT.get()
            if sent:
                parts = [f"funding {sent['funding']*100:.3f}%/8h ({sent['funding_ann']*100:+.1f}% ann.)",
                         f"OI 5d {sent['oi_change_5d']*100:+.1f}%", f"24h {sent['chg_24h']*100:+.1f}%"]
                if sent.get('fng') is not None:
                    parts.append(f"Fear&Greed {sent['fng']}")
                flags = ", ".join(sent.get('flags', [])) or "no stress flags"
                L.append(f"Derivatives: {'; '.join(parts)}. Microstructure: {flags}; bias {sent['bias']}.")
            else:
                L.append("Derivatives data not fresh (funding/OI unavailable).")
        # risk state
        try:
            if bot is not None and hasattr(bot, 'max_balance'):
                bal = float(CFG.get('account_balance', 0) or 0)
                dd = (bot.max_balance - bal) / bot.max_balance if bot.max_balance > 0 else 0.0
                lvl = CIRCUIT.triggered_level or 'normal'
                pause = ' - loss pause ACTIVE' if getattr(bot, 'paused_losses', False) else ''
                L.append(f"Risk: balance ${bal:,.0f}, drawdown {dd*100:.1f}% from high ${bot.max_balance:,.0f}, ladder level {lvl}{pause}.")
        except Exception:
            pass
        # ML champion
        try:
            if ML.trained:
                L.append("ML champion is active and voting.")
            else:
                L.append("ML has no passing champion - strategy engine scores alone.")
            if os.path.exists('state/ml_validation.json'):
                v = json.load(open('state/ml_validation.json'))
                L.append(f"Last walk-forward gate: holdout {v.get('test_acc',0)*100:.1f}% vs baseline {v.get('baseline_acc',0)*100:.1f}% -> {'PASSED' if v.get('passed') else 'REJECTED'}.")
        except Exception:
            pass
        # recent performance
        try:
            closed = STORE.get_all_closed_trades()[-20:]
            if closed:
                pnls = [float(t.get('pnl') or 0) for t in closed]
                wins = sum(1 for p in pnls if p > 0)
                L.append(f"Last {len(closed)} closed trades: {wins}W/{len(closed)-wins}L, net ${sum(pnls):+,.2f}.")
        except Exception:
            pass
        text = " ".join(L)
        # optional Gemini polish
        if CFG.get('narrative_use_gemini', False) and GEMINI_OK:
            try:
                text = self._gemini_polish(text) or text
            except Exception:
                pass
        return {'ts': now.isoformat(), 'symbol': sym, 'narrative': text, 'components': L}

    def _gemini_polish(self, text):
        try:
            import google.genai as genai
            client = genai.Client(api_key=CFG.get('macro_llm_api_key') or os.environ.get('GEMINI_API_KEY', ''))
            out = client.models.generate_content(
                model='gemini-2.0-flash',
                contents=("Rewrite this trading market note in 3-5 crisp sentences, keeping every "
                          "number and flag exactly as given. No new facts. Output text only:\n\n" + text))
            t = getattr(out, 'text', None)
            return t.strip() if t else None
        except Exception:
            return None

    def deliver(self, bot=None, force=False):
        """Build + save + (optionally) Telegram-notify the narrative."""
        n = self.build(bot)
        try:
            os.makedirs('logs/narratives', exist_ok=True)
            p = f"logs/narratives/{utc_now().strftime('%Y-%m-%d')}_{utc_now().strftime('%H%M')}.md"
            with open(p, 'w') as f:
                f.write(f"# Narrative — {n['symbol']} — {n['ts']}\n\n{n['narrative']}\n")
        except Exception:
            pass
        try:
            TG.notify(f"📰 <b>Sentinel Narrative</b>\n{n['narrative']}")
        except Exception:
            pass
        return n


# singletons
ASIAN_RANGE = AsianRangeEngine()
TRINITY = TrinitySentinel()
BINANCE_SENT = BinanceSentiment()
NARRATIVE = NarrativeSentinel()


class BacktestHarness:
    SYMBOL_MAP = {
        'XAUUSDm': {'yf': 'GC=F',    'label': 'XAUUSD (GC=F futures proxy)', 'spread': 0.30, 'contract': 100.0},
        'XAUUSD':  {'yf': 'GC=F',    'label': 'XAUUSD (GC=F futures proxy)', 'spread': 0.30, 'contract': 100.0},
        'BTCUSDm': {'yf': 'BTC-USD', 'label': 'BTCUSD',                      'spread': 2.0,  'contract': 1.0},
        'BTCUSD':  {'yf': 'BTC-USD', 'label': 'BTCUSD',                      'spread': 2.0,  'contract': 1.0},
    }
    WARMUP = 2400  # H1 bars (~100 days) so D1 has 100+ completed bars
    WARMUP_15M = 400  # 15m bars (~4 days)

    def __init__(self, symbol=None, days=730, source='yfinance', csv_path=None, balance=None, tf='1h'):
        self.symbol = symbol or CFG.get('symbol', 'XAUUSDm')
        self.meta = self.SYMBOL_MAP.get(self.symbol, self.SYMBOL_MAP['XAUUSDm'])
        self.tf = tf  # base decision TF: '1h' (730d) or '15m' (60d, live entry TF)
        self.days = min(int(days), 730 if tf == '1h' else 60)
        self.base_label = 'H1' if tf == '1h' else 'M15'
        self.source = source
        self.csv_path = csv_path
        self.balance0 = float(balance) if balance else float(CFG.get('account_balance', 1000.0))
        self.df = None
        self.result = None

    # ---------------- data loading ----------------
    def _normalize(self, df):
        df = df.rename(columns=str.lower)
        need = ['open', 'high', 'low', 'close']
        for c in need:
            if c not in df.columns:
                raise ValueError(f"missing column '{c}' (have: {list(df.columns)})")
        if 'volume' not in df.columns:
            df['volume'] = 0.0
        df = df[need + ['volume']].copy()
        if not isinstance(df.index, pd.DatetimeIndex):
            for col in ('date', 'datetime', 'time', 'timestamp'):
                if col in df.columns:
                    df[col] = pd.to_datetime(df[col])
                    df = df.set_index(col)
                    break
        if getattr(df.index, 'tz', None) is not None:
            df.index = df.index.tz_convert('UTC').tz_localize(None)
        df = df.sort_index()
        df = df[~df.index.duplicated(keep='first')]
        return df.dropna()

    def load_data(self):
        if self.source == 'csv' and self.csv_path:
            df = pd.read_csv(self.csv_path)
            df = self._normalize(df)
            if df.index.tz is None and (df.index.max() - df.index.min()) > pd.Timedelta(days=3650):
                pass
            # resample whatever frequency to H1
            agg = {'open': 'first', 'high': 'max', 'low': 'min', 'close': 'last', 'volume': 'sum'}
            if df.index.to_series().dt.total_seconds().mode().iloc[0] > 3600 * 2 if len(df) > 2 else False:
                df = df.resample('1h').agg(agg).dropna()
            self.df = df
        elif self.source == 'synthetic':
            self.df = self._synthetic()
        else:
            import yfinance as yf
            print(f"[BT] Downloading {self.days} days of {self.tf} data for {self.meta['yf']} ...")
            raw = yf.download(self.meta['yf'], period=f'{self.days}d', interval=self.tf, progress=False)
            if raw is None or raw.empty:
                raise RuntimeError(f"yfinance returned no data for {self.meta['yf']} (try --source csv or --source synthetic)")
            if isinstance(raw.columns, pd.MultiIndex):
                raw.columns = raw.columns.get_level_values(0)
            self.df = self._normalize(raw)
        print(f"[BT] Loaded {len(self.df)} {self.base_label} bars: {self.df.index[0]} -> {self.df.index[-1]}")
        return self.df

    def _synthetic(self):
        # regime-switching GBM — PIPELINE TEST ONLY, not market evidence
        n = max(500, self.days * (24 if self.tf == '1h' else 96))
        rng = np.random.default_rng(7)
        price = 4400.0 if self.symbol.upper().startswith('XAU') else 60000.0
        rows = []
        mu, sigma = 0.0, 0.0012
        for i in range(n):
            if i % 720 == 0:
                mu = float(rng.choice([-0.0004, 0.0, 0.0004]))
                sigma = float(rng.choice([0.0008, 0.0015, 0.0030]))
            r = mu + sigma * float(rng.standard_normal())
            o = price
            c = price * math.exp(r)
            h = max(o, c) * (1 + abs(float(rng.standard_normal())) * sigma * 0.6)
            l = min(o, c) * (1 - abs(float(rng.standard_normal())) * sigma * 0.6)
            rows.append([o, h, l, c, abs(float(rng.standard_normal()) + 1) * 1000])
            price = c
        idx = pd.date_range('2024-01-01', periods=n, freq=('h' if self.tf == '1h' else '15min'))
        self.df = pd.DataFrame(rows, index=idx, columns=['open', 'high', 'low', 'close', 'volume'])
        return self.df

    # ---------------- PHASE B/C history loaders (best-effort, disclosed) ----------------
    def _trinity_daily_bias(self):
        """Daily XAU/DXY/US10Y bias series for the backtest window (Phase B).
        Maps calendar date -> 'bullish'/'bearish'/'neutral' using the SAME
        deterministic rule as the live TrinitySentinel."""
        try:
            import yfinance as yf
            x0 = str(self.df.index[0])[:10]
            x1 = str(self.df.index[-1])[:10]
            x = yf.download('GC=F', start=x0, end=x1, interval='1d', progress=False)
            d = yf.download('DX-Y.NYB', start=x0, end=x1, interval='1d', progress=False)
            t = yf.download('^TNX', start=x0, end=x1, interval='1d', progress=False)
            if x is None or x.empty or d is None or d.empty or t is None or t.empty:
                return None
            for f in (x, d, t):
                if isinstance(f.columns, pd.MultiIndex):
                    f.columns = f.columns.get_level_values(0)
            j = pd.concat([
                x.rename(columns=str.lower)['close'].dropna(),
                d.rename(columns=str.lower)['close'].dropna(),
                t.rename(columns=str.lower)['close'].dropna(),
            ], axis=1, keys=['x', 'd', 't']).dropna()
            if len(j) < 30:
                return None
            out = {}
            for i in range(25, len(j) + 1):
                b = TrinitySentinel.compute_bias(list(j['x'].iloc[:i]), list(j['d'].iloc[:i]), list(j['t'].iloc[:i]))
                if b:
                    out[j.index[i - 1].date()] = b['bias']
            return out or None
        except Exception:
            return None

    def _btc_sentiment_history(self):
        """Historical funding/OI/taker/F&G for the backtest window (Phase C).
        Returns BinanceSentiment.fetch_history() output or None when the API is
        unreachable from this network (layer then runs OFF and is disclosed)."""
        try:
            return BINANCE_SENT.fetch_history(self.df.index[0], self.df.index[-1])
        except Exception:
            return None

    # ---------------- multi-timeframe frames ----------------
    def _build_hf(self):
        def _agg(d, rule):
            return d.resample(rule).agg(
                {'open': 'first', 'high': 'max', 'low': 'min', 'close': 'last', 'volume': 'sum'}
            ).dropna()
        if self.tf == '1h':
            self.hf_list = [('H4', _agg(self.df, '4h'), pd.Timedelta(hours=3)),
                            ('D1', _agg(self.df, '1D'), pd.Timedelta(hours=23))]
        else:  # 15m base -> H1, H4, D1 (D1 added for ADR stop floor, Phase B)
            self.hf_list = [('H1', _agg(self.df, '1h'), pd.Timedelta(minutes=45)),
                            ('H4', _agg(self.df, '4h'), pd.Timedelta(hours=3, minutes=45)),
                            ('D1', _agg(self.df, '1D'), pd.Timedelta(hours=23))]

    # ---------------- main loop ----------------
    def run(self):
        h1 = self.df
        n = len(h1)
        warm_need = self.WARMUP if self.tf == '1h' else self.WARMUP_15M
        if n < warm_need + 50:
            raise RuntimeError(f"not enough data: {n} {self.base_label} bars (need ~{warm_need + 50}); use --days 730")
        self._build_hf()
        hf_list = self.hf_list
        hs = self.meta['spread'] / 2.0
        contract = self.meta['contract']
        is_xau = self.meta['contract'] > 1.0

        cash = self.balance0
        peak = cash
        last_peak_t = h1.index[0]  # STAGE-17: high-water-mark clock (set to warm below)
        day_start_eq = cash
        day = h1.index[0].date()
        pos = None
        trades = []
        eq_curve = []
        min_score = float(CFG.get('min_score', 7.0))
        dd_risk_mult = 1.0
        dd_in_pause_zone = False
        paused_until = None
        consec_losses = 0
        emergency = False
        warm = min(warm_need, n - 2)
        last_peak_t = h1.index[warm]  # STAGE-17: high-water-mark clock starts at first decision bar
        pause_events = []
        gate_stats = {'bars': 0, 'in_position': 0, 'paused': 0, 'regime_volatile': 0,
                      'no_signals': 0, 'score_reject': 0, 'atr_zero': 0, 'ml_reject': 0,
                      'accepted': 0, 'analyze_error': 0}

        # ---------------- PHASE B/C history precomputation (no lookahead) ----------------
        # XAU: daily macro trinity bias (as-of previous completed day) + ADR14 series
        self._tri_daily = {}
        self._adr_series = None
        self._sent_hist = None
        self._ar_engine = None
        if is_xau:
            if CFG.get('trinity_backtest', True):
                _tb = self._trinity_daily_bias()
                if _tb:
                    self._tri_daily = _tb
            if CFG.get('xau_adr_stop_enabled', True):
                _d1f = dict((lbl, df) for lbl, df, _ in hf_list).get('D1')
                if _d1f is not None and len(_d1f) >= 15:
                    self._adr_series = (_d1f['high'] - _d1f['low']).rolling(14).mean()
            if CFG.get('asian_range_enabled', True):
                self._ar_engine = AsianRangeEngine(symbol=self.symbol, persist=False)  # backtest-only instance
        else:
            if CFG.get('btc_sentiment_enabled', True):
                self._sent_hist = self._btc_sentiment_history()

        # H4 trend + last-known trinity bias lookups per bar
        _h4f = dict((lbl, df) for lbl, df, _ in hf_list).get('H4')
        _h4_close_arr = _h4f['close'].values if _h4f is not None else None
        _h4_idx = _h4f.index if _h4f is not None else None

        o_arr = h1['open'].values
        h_arr = h1['high'].values
        l_arr = h1['low'].values
        c_arr = h1['close'].values

        for j in range(warm, n):
            t = h1.index[j]
            o, h, l, c = o_arr[j], h_arr[j], l_arr[j], c_arr[j]
            if day != t.date():
                day = t.date()
                day_start_eq = cash

            # ---------- 1. manage open position on bar j ----------
            if pos is not None:
                if pos['fill'] is None:
                    pos['fill'] = o + (hs if pos['dir'] == 'BUY' else -hs)
                F = pos['fill']
                sl, tp1, tp2 = pos['sl'], pos['tp1'], pos['tp2']
                exit_price = None
                exit_reason = None
                if pos['dir'] == 'BUY':
                    if o <= sl:
                        exit_price, exit_reason = o, 'gap_sl'
                    elif l <= sl:
                        exit_price, exit_reason = sl, 'sl'
                    else:
                        if not pos['partial_done'] and h >= tp1:
                            _ppnl = (tp1 - F) * pos['units'] * 0.5
                            cash += _ppnl
                            pos['partial_pnl'] += _ppnl
                            pos['units'] *= 0.5
                            pos['partial_done'] = True
                        if h >= tp2:
                            exit_price, exit_reason = tp2, 'tp'
                        elif j - pos['entry_bar'] >= 48:
                            exit_price, exit_reason = c, 'time'
                else:
                    if o >= sl:
                        exit_price, exit_reason = o, 'gap_sl'
                    elif h >= sl:
                        exit_price, exit_reason = sl, 'sl'
                    else:
                        if not pos['partial_done'] and l <= tp1:
                            _ppnl = (F - tp1) * pos['units'] * 0.5
                            cash += _ppnl
                            pos['partial_pnl'] += _ppnl
                            pos['units'] *= 0.5
                            pos['partial_done'] = True
                        if l <= tp2:
                            exit_price, exit_reason = tp2, 'tp'
                        elif j - pos['entry_bar'] >= 48:
                            exit_price, exit_reason = c, 'time'
                if exit_price is not None:
                    dsign = 1 if pos['dir'] == 'BUY' else -1
                    pnl = dsign * (exit_price - F) * pos['units']
                    total_pnl = pnl + pos.get('partial_pnl', 0.0)
                    risk_amt = abs(F - sl) * (pos['units'] / 0.5)  # original units (pre-partial)
                    cash += pnl
                    trades.append({
                        'entry_ts': str(h1.index[pos['entry_bar']]), 'exit_ts': str(t),
                        'dir': pos['dir'], 'strategy': pos['strategy'], 'score': round(pos['score'], 2),
                        'fill': round(F, 5), 'exit': round(exit_price, 5),
                        'sl': round(sl, 5), 'tp': round(tp2, 5),
                        'pnl': round(total_pnl, 2), 'r_mult': round(total_pnl / risk_amt, 3) if risk_amt > 0 else 0.0,
                        'exit_reason': exit_reason, 'bars_held': j - pos['entry_bar'],
                        'session': self._session(t), 'reasons': pos.get('reasons', [])
                    })
                    consec_losses = consec_losses + 1 if total_pnl < 0 else 0
                    if consec_losses >= CFG.get('max_consecutive_losses', 3):
                        paused_until = t + pd.Timedelta(hours=CFG.get('consecutive_loss_pause_hours', 12))
                        consec_losses = 0
                        pause_events.append(('consec_loss', str(t), str(paused_until)))
                    pos = None

            unreal = 0.0
            if pos is not None and pos['fill'] is not None:
                dsign = 1 if pos['dir'] == 'BUY' else -1
                unreal = dsign * (c - pos['fill']) * pos['units']
            eq = cash + unreal

            # ---------- 2. risk overlay ----------
            # STAGE-16 FIX: the DD ladder + daily halt run on REALIZED balance,
            # exactly like the live bot (update_balance_tracking -> max_balance vs
            # balance), including the live bot's recovery: when the balance decays
            # to within 5% of the initial balance, max_balance follows down and
            # the drawdown clock resets. (Mark-to-market equity had set the peak
            # from unrealized profit spikes, which made every later normal loss
            # measure 15%+ "drawdown" and re-armed a 1h pause on every bar.)
            # STAGE-17: mirror the live bot's high-water-mark expiry (14 days
            # without a new high -> the peak resets to the current balance)
            if cash <= self.balance0 * 1.05 and peak > self.balance0 * 1.05:
                peak = cash
                last_peak_t = t
            elif cash > peak:
                peak = cash
                last_peak_t = t
            elif t - last_peak_t > pd.Timedelta(days=CFG.get('dd_peak_staleness_days', 14)):
                peak = cash
                last_peak_t = t
            dd_pct = max(0.0, (peak - cash) / peak) if peak > 0 else 0.0
            # max daily DD halt
            if day_start_eq > 0 and (day_start_eq - cash) / day_start_eq > CFG.get('max_daily_dd', 0.40):
                if paused_until is None or t + pd.Timedelta(hours=12) > paused_until:
                    paused_until = t.replace(hour=0, minute=0, second=0) + pd.Timedelta(days=1)
                    pause_events.append(('daily_dd', str(t), str(paused_until)))
            act = CIRCUIT.check_protocol(dd_pct)['action']
            # STAGE-16 FIX: the 15% cool-down is ONE-SHOT per drawdown excursion.
            # The original re-armed the pause on every bar while DD stayed above
            # the line, so the bot paused itself permanently and could never
            # recover by trading. (Same fix applied to the live bot's ladder
            # consumer - see STAGE-16 note in BattleBot._cycle.)
            if act == 'reduce_size':
                dd_risk_mult = 0.7
                dd_in_pause_zone = False
            elif act == 'increase_filters':
                min_score = 8.5
                dd_in_pause_zone = False
            elif act == 'pause_trading':
                dd_risk_mult = 0.7   # 5% mitigation stays active while >= 15%
                min_score = 8.5      # 10% mitigation stays active while >= 15%
                if not dd_in_pause_zone:
                    paused_until = t + pd.Timedelta(hours=1)
                    pause_events.append(('dd_ladder_15pct', str(t), str(paused_until)))
                dd_in_pause_zone = True
            elif act == 'emergency_stop':
                emergency = True
                if pos is not None:
                    dsign = 1 if pos['dir'] == 'BUY' else -1
                    pnl = dsign * (c - pos['fill']) * pos['units'] + pos.get('partial_pnl', 0.0)
                    cash += pnl
                    trades.append({'entry_ts': str(h1.index[pos['entry_bar']]), 'exit_ts': str(t),
                                   'dir': pos['dir'], 'strategy': pos['strategy'], 'score': round(pos['score'], 2),
                                   'fill': round(pos['fill'], 5), 'exit': round(c, 5), 'pnl': round(pnl, 2),
                                   'r_mult': 0.0, 'exit_reason': 'emergency_stop', 'bars_held': j - pos['entry_bar'],
                                   'session': self._session(t), 'reasons': []})
                    pos = None
                break
            else:
                dd_risk_mult = 1.0
                min_score = float(CFG.get('min_score', 7.0))
                dd_in_pause_zone = False
            if paused_until is not None and t >= paused_until:
                paused_until = None

            # ---------- 3. decision on close of bar j -> entry at open of j+1 ----------
            gate_stats['bars'] += 1
            if pos is not None:
                gate_stats['in_position'] += 1
            elif paused_until is not None:
                gate_stats['paused'] += 1
            elif j < n - 1:
                base_win = h1.iloc[max(0, j + 1 - 300):j + 1]
                try:
                    regime = REGIME.detect(base_win)
                except Exception:
                    regime = 'NEUTRAL'
                if regime == 'VOLATILE':
                    gate_stats['regime_volatile'] += 1
                else:
                    dfs = {self.base_label: base_win}
                    for _lbl, _series, _cut in hf_list:
                        _w = _series[_series.index <= t - _cut]
                        if len(_w) >= 100:
                            dfs[_lbl] = _w.tail(150)
                    # H4 trend (for Asian range / parity with live)
                    _h4_trend = 'neutral'
                    if _h4f is not None and _h4_idx is not None:
                        _w4 = _h4f[_h4f.index <= t - pd.Timedelta(hours=4)]  # only CLOSED H4 bars
                        if len(_w4) >= 50:
                            try:
                                _h4_trend = AsianRangeEngine.h4_trend(_w4)
                            except Exception:
                                pass
                    # XAU: macro trinity bias as of the last COMPLETED daily close
                    _tri_bias = 'neutral'
                    if is_xau and self._tri_daily:
                        _known = (t - pd.Timedelta(hours=12)).date()
                        for _back in range(0, 10):
                            _key = _known - pd.Timedelta(days=_back)
                            if _key in self._tri_daily:
                                _tri_bias = self._tri_daily[_key]
                                break
                    try:
                        signals = STRATEGY.analyze(dfs, regime)
                    except Exception:
                        signals = []
                        gate_stats['analyze_error'] += 1
                    # PHASE B: trinity vote (same +/-1.5 as live) + Asian Range candidate
                    if is_xau:
                        if _tri_bias in ('bullish', 'bearish') and signals:
                            for _s in signals:
                                _d = 1.5 if (_s['dir'] == 'BUY') == (_tri_bias == 'bullish') else -1.5
                                _s['score'] = round(_s['score'] + _d, 3)
                                _s.setdefault('reasons', []).append(f"Trinity {_tri_bias} (backtest)")
                        if self._ar_engine is not None:
                            _ar_atr = 0.0
                            if signals:
                                _ar_atr = float(max(signals, key=lambda s: s.get('score', 0.0)).get('atr', 0.0) or 0.0)
                            try:
                                _ar_sig = self._ar_engine.on_bar(t, h, l, c, _ar_atr, _h4_trend, _tri_bias)
                                if _ar_sig:
                                    signals.append(_ar_sig)
                            except Exception:
                                pass
                    # PHASE C: BTC funding/OI sentiment vote (history-driven, no lookahead)
                    if not is_xau and self._sent_hist is not None and signals:
                        try:
                            _sh = self._sent_hist
                            _f = _sh['funding'][_sh['funding'].index <= t]
                            _funding = float(_f.iloc[-1]) if len(_f) else 0.0
                            _oi_5d = 0.0
                            if _sh.get('oi') is not None:
                                _oi = _sh['oi'][_sh['oi'].index <= t]
                                if len(_oi) >= 6:
                                    _oi_5d = float(_oi.iloc[-1]) / max(1e-9, float(_oi.iloc[-6])) - 1.0
                            _tk = float(_sh['taker'].iloc[-1]) if (_sh.get('taker') is not None and len(_sh['taker'][_sh['taker'].index <= t])) else 1.0
                            _fng = int(_sh['fng'].iloc[-1]) if (_sh.get('fng') is not None and len(_sh['fng'][_sh['fng'].index <= t])) else None
                            _c24 = c_arr[max(0, j - 24)]
                            _chg24 = float(c) / max(1e-9, float(_c24)) - 1.0
                            _snap = BinanceSentiment.flags_from(_funding, _oi_5d, _chg24, _fng, _tk)
                            if _snap['bias'] in ('bullish', 'bearish'):
                                for _s in signals:
                                    _d = 1.5 if (_s['dir'] == 'BUY') == (_snap['bias'] == 'bullish') else -1.5
                                    _s['score'] = round(_s['score'] + _d, 3)
                                    _s.setdefault('reasons', []).append(f"BTC sentiment: {','.join(_snap['flags']) or _snap['bias']}")
                            if 'crowded_long' in _snap['flags']:
                                for _s in signals:
                                    if _s['dir'] == 'BUY':
                                        _s['score'] = round(_s['score'] - 2.0, 3)
                                        _s.setdefault('reasons', []).append('crowded-long fade')
                            if 'stress' in _snap['flags']:
                                for _s in signals:
                                    _s['score'] = round(_s['score'] - 0.5, 3)
                        except Exception:
                            pass
                    if not signals:
                        gate_stats['no_signals'] += 1
                    else:
                        best = max(signals, key=lambda s: s.get('score', 0.0))
                        try:
                            mtf = STRATEGY.multi_tf_alignment(dfs)
                        except Exception:
                            mtf = 0.0
                        score = best.get('score', 0.0) + mtf
                        ml_reject = False
                        if ML.trained:
                            try:
                                mp = ML.predict({'features': best.get('features', {}), 'entry': best.get('entry')})
                                if mp.get('enabled'):
                                    dp = float(mp.get('dir_prob', 0.5))
                                    ml_dir = 'BUY' if dp >= 0.5 else 'SELL'
                                    if ml_dir != best['dir']:
                                        ml_reject = True
                                    else:
                                        score += 1.0
                            except Exception:
                                pass
                        entry = float(best.get('entry', c))
                        atr = float(best.get('atr', 0.0) or 0.0)
                        if ml_reject:
                            gate_stats['ml_reject'] += 1
                        elif atr <= 0:
                            gate_stats['atr_zero'] += 1
                        elif score < min_score:
                            gate_stats['score_reject'] += 1
                        if not ml_reject and score >= min_score and atr > 0:
                            # Phase B/C parity: honor explicit sl/tp carried by the signal
                            # (Asian Range sets both); else ATR-based like the live bot.
                            sl = float(best['sl']) if best.get('sl') else None
                            if sl is None:
                                sl = RISK_ENGINE.calculate_sl_from_atr(entry, atr, best['dir'], 2.0)
                                # PHASE B: ADR14 stop floor (XAU) - widen SL to >= 0.5*ADR14
                                if is_xau and CFG.get('xau_adr_stop_enabled', True) and self._adr_series is not None:
                                    _ad = self._adr_series[self._adr_series.index <= t - pd.Timedelta(hours=23)]
                                    if len(_ad) >= 1:
                                        _adr14 = float(_ad.iloc[-1])
                                        _floor = CFG.get('xau_adr_mult', 0.5) * _adr14
                                        if best['dir'] == 'BUY' and (entry - sl) < _floor:
                                            sl = entry - _floor
                                        elif best['dir'] == 'SELL' and (sl - entry) < _floor:
                                            sl = entry + _floor
                            r_dist = abs(entry - sl)
                            if r_dist > 0:
                                _tp0 = float(best['tp']) if best.get('tp') else None
                                if _tp0 is not None:
                                    tp2 = _tp0  # signal's own TP (e.g. 1.75x Asian width)
                                else:
                                    tp2 = entry + 2.0 * r_dist if best['dir'] == 'BUY' else entry - 2.0 * r_dist
                                tp1 = entry + 1.0 * r_dist if best['dir'] == 'BUY' else entry - 1.0 * r_dist
                                risk_pct = 1.0 * dd_risk_mult
                                if is_xau:
                                    lots = RISK_ENGINE.calculate_lots(cash, entry, sl, risk_pct, atr)
                                    units = lots * contract
                                else:
                                    units = (cash * risk_pct / 100.0) / r_dist
                                if units > 0:
                                    pos = {
                                        'dir': best['dir'], 'sl': sl, 'tp1': tp1, 'tp2': tp2,
                                        'units': units, 'entry_bar': j + 1, 'fill': None,
                                        'partial_done': False, 'partial_pnl': 0.0,
                                        'score': score, 'strategy': best.get('strategy', 'rule'),
                                        'reasons': best.get('reasons', [])[:6]
                                    }
                                    gate_stats['accepted'] += 1
            eq_curve.append((t, eq))
            if (j - warm) % 500 == 0:
                print(f"[BT] {j - warm}/{n - warm} bars | equity ${eq:,.2f} | trades {len(trades)}")

        # close any open position at the last close (marked, not a real exit edge)
        if pos is not None and pos['fill'] is not None:
            dsign = 1 if pos['dir'] == 'BUY' else -1
            pnl = dsign * (c_arr[-1] - pos['fill']) * pos['units'] + pos.get('partial_pnl', 0.0)
            cash += pnl
            trades.append({'entry_ts': str(h1.index[pos['entry_bar']]), 'exit_ts': str(h1.index[-1]),
                           'dir': pos['dir'], 'strategy': pos['strategy'], 'score': round(pos['score'], 2),
                           'fill': round(pos['fill'], 5), 'exit': round(float(c_arr[-1]), 5), 'pnl': round(pnl, 2),
                           'r_mult': 0.0, 'exit_reason': 'end_of_data', 'bars_held': n - 1 - pos['entry_bar'],
                           'session': self._session(h1.index[-1]), 'reasons': []})

        self.result = {
            'symbol': self.symbol, 'label': self.meta['label'], 'source': self.source,
            'start': str(h1.index[warm]), 'end': str(h1.index[-1]),
            'bars': int(n - warm), 'balance_start': self.balance0, 'balance_end': round(cash, 2),
            'trades': trades,
            'equity_curve': [(str(t), round(v, 2)) for t, v in eq_curve],
            'emergency_stopped': emergency,
            'ml_was_trained': bool(ML.trained),
            'min_score_base': float(CFG.get('min_score', 7.0)),
            'gate_stats': gate_stats,
            'pause_events': pause_events,
            'layers': self._layer_status(),  # PHASE B/C: which layers actually ran (honesty)
        }
        return self.result

    def _layer_status(self):
        L = {}
        if self.meta['contract'] > 1.0:  # XAU
            L['trinity'] = (f"ON — {len(self._tri_daily)} daily bias points"
                            if self._tri_daily else "OFF — DXY/US10Y history unavailable (voted neutral)")
            L['adr_stop_floor'] = ("ON — ADR14(14d) widens ATR stops"
                                   if self._adr_series is not None else "OFF — D1 series short")
            L['asian_range'] = ("ON" if self._ar_engine is not None else "OFF")
        else:  # BTC
            if self._sent_hist is not None:
                L['binance_sentiment'] = (f"ON — funding history {len(self._sent_hist['funding'])} prints, "
                                          f"OI {'ON' if self._sent_hist.get('oi') is not None else 'OFF(>90d)'}, "
                                          f"F&G {'ON' if self._sent_hist.get('fng') is not None else 'OFF(>365d)'}")
            else:
                L['binance_sentiment'] = "OFF — Binance API unreachable from this network (voted neutral)"
        return L

    @staticmethod
    def _session(t):
        hr = t.hour
        if 0 <= hr < 7:
            return 'Asia'
        if 7 <= hr < 13:
            return 'London'
        if 13 <= hr < 20:
            return 'NewYork'
        return 'Overnight'

    # ---------------- reporting ----------------
    def report(self, out_json=None, out_html=None):
        r = self.result
        if r is None:
            self.run()
            r = self.result
        trades = r['trades']
        eq = [v for _, v in r['equity_curve']]
        n_tr = len(trades)
        wins = [t for t in trades if t['pnl'] > 0]
        losses = [t for t in trades if t['pnl'] <= 0]
        gross_win = sum(t['pnl'] for t in wins)
        gross_loss = -sum(t['pnl'] for t in losses)
        pf = (gross_win / gross_loss) if gross_loss > 0 else float('inf') if gross_win > 0 else 0.0
        peak = eq[0] if eq else r['balance_start']
        max_dd = 0.0
        for v in eq:
            peak = max(peak, v)
            if peak > 0:
                max_dd = max(max_dd, (peak - v) / peak)
        days = max(1, (pd.Timestamp(r['end']) - pd.Timestamp(r['start'])).days)
        total_ret = (r['balance_end'] / r['balance_start'] - 1.0)
        ann_ret = (r['balance_end'] / r['balance_start']) ** (365.0 / days) - 1.0 if r['balance_start'] > 0 and r['balance_end'] > 0 else float('nan')
        avg_r = (sum(t['r_mult'] for t in trades) / n_tr) if n_tr else 0.0

        def _bucket(key):
            out = {}
            for t in trades:
                k = t[key] if isinstance(t[key], str) else str(t[key])[:4]
                d = out.setdefault(k, {'n': 0, 'pnl': 0.0, 'wins': 0})
                d['n'] += 1
                d['pnl'] += t['pnl']
                d['wins'] += 1 if t['pnl'] > 0 else 0
            for k, d in out.items():
                d['pnl'] = round(d['pnl'], 2)
                d['win_rate'] = round(d['wins'] / d['n'], 3)
            return out

        by_strategy = _bucket('strategy')
        by_year = {}
        for t in trades:
            y = str(t['exit_ts'])[:4]
            if not y.startswith(('20', '19')):
                continue
            d = by_year.setdefault(y, {'n': 0, 'pnl': 0.0, 'wins': 0})
            d['n'] += 1
            d['pnl'] += t['pnl']
            d['wins'] += 1 if t['pnl'] > 0 else 0
        for d in by_year.values():
            d['pnl'] = round(d['pnl'], 2)
            d['win_rate'] = round(d['wins'] / d['n'], 3)
        by_session = _bucket('session')
        by_reason = _bucket('exit_reason')

        stats = {
            'total_return_pct': round(total_ret * 100, 2),
            'annualized_return_pct': round(ann_ret * 100, 2) if ann_ret == ann_ret else None,
            'max_drawdown_pct': round(max_dd * 100, 2),
            'trades': n_tr,
            'win_rate_pct': round(len(wins) / n_tr * 100, 1) if n_tr else 0.0,
            'profit_factor': round(pf, 2) if pf != float('inf') else 'inf',
            'avg_r': round(avg_r, 3),
            'avg_bars_held': round(sum(t['bars_held'] for t in trades) / n_tr, 1) if n_tr else 0.0,
            'by_strategy': by_strategy, 'by_year': by_year,
            'by_session': by_session, 'by_exit_reason': by_reason,
        }
        r['stats'] = stats

        # ---- console ----
        print()
        print("=" * 66)
        print(f" BACKTEST — {r['label']}  [{r['source']}]   {r['start'][:10]} -> {r['end'][:10]}")
        print("=" * 66)
        print(f" Start ${r['balance_start']:,.2f}  ->  End ${r['balance_end']:,.2f}   "
              f"Return {stats['total_return_pct']:+.2f}%   MaxDD {stats['max_drawdown_pct']:.2f}%")
        print(f" Trades {n_tr}   Win {stats['win_rate_pct']:.1f}%   PF {stats['profit_factor']}   "
              f"Avg R {stats['avg_r']:+.3f}   Avg hold {stats['avg_bars_held']:.0f} bars")
        if r.get('emergency_stopped'):
            print(" ** EMERGENCY STOP (20% DD) — backtest halted by the live ladder **")
        if not r.get('ml_was_trained'):
            print(" (ML vote OFF - no trained champion; strategy engine only)")
        _layers = r.get('layers') or {}
        for _k, _v in _layers.items():
            print(f" Layer: {_k:<18} {_v}")
        print("-" * 66)
        print(" By strategy:")
        for k, d in sorted(by_strategy.items(), key=lambda kv: -kv[1]['pnl']):
            print(f"   {k:<28} n={d['n']:<4} pnl ${d['pnl']:>10,.2f}   win {d['win_rate'] * 100:.0f}%")
        print(" By year:")
        for k, d in sorted(by_year.items()):
            print(f"   {k}  n={d['n']:<4} pnl ${d['pnl']:>10,.2f}   win {d['win_rate'] * 100:.0f}%")
        print(" By session:")
        for k, d in sorted(by_session.items(), key=lambda kv: -kv[1]['pnl']):
            print(f"   {k:<10} n={d['n']:<4} pnl ${d['pnl']:>10,.2f}   win {d['win_rate'] * 100:.0f}%")
        print(" Exits:")
        for k, d in sorted(by_reason.items(), key=lambda kv: -kv[1]['n']):
            print(f"   {k:<12} n={d['n']:<4} pnl ${d['pnl']:>10,.2f}")
        gs = r.get('gate_stats', {})
        if gs:
            print(" Gate activity (bars the bot spent in each state):")
            for k in ('in_position', 'accepted', 'paused', 'regime_volatile',
                      'no_signals', 'score_reject', 'ml_reject', 'atr_zero', 'analyze_error'):
                if gs.get(k):
                    print(f"   {k:<16} {gs[k]}")
            print(f"   (total decision bars: {gs.get('bars', 0)})")
        pe = r.get('pause_events', [])
        if pe:
            from collections import Counter
            pc = Counter(x[0] for x in pe)
            print(f" Pause events ({len(pe)} total): " + ", ".join(f"{k}={v}" for k, v in pc.most_common()))
            print(f"   first: {pe[0]}   last: {pe[-1]}")
        print("-" * 66)
        _tf_note = (f"{self.base_label}-decision backtest (missing lower-TF refinement)"
                   if self.tf == '1h' else
                   "M15-decision backtest (M5 layer not simulated; Yahoo 15m limit = 60 days)")
        print(f" HONESTY BOX: {_tf_note}, no news/DXY/trailing,")
        print(" spread modeled, SL-first on same-bar ambiguity. History != future.")

        # ---- JSON ----
        stamp = pd.Timestamp.utcnow().strftime('%Y%m%d_%H%M')
        out_json = out_json or f"state/backtest_{self.symbol}_{stamp}.json"
        try:
            os.makedirs(os.path.dirname(out_json) or '.', exist_ok=True)
            with open(out_json, 'w') as f:
                json.dump(r, f, indent=1, default=str)
            print(f" JSON  -> {out_json}")
        except Exception as e:
            print(f"[BT] JSON save failed: {e}")

        # ---- self-contained HTML equity chart (inline SVG, no CDN) ----
        out_html = out_html or f"charts/backtest_{self.symbol}.html"
        try:
            os.makedirs(os.path.dirname(out_html) or '.', exist_ok=True)
            with open(out_html, 'w') as f:
                f.write(self._equity_svg_html(r, stats))
            print(f" Chart -> {out_html}")
        except Exception as e:
            print(f"[BT] chart save failed: {e}")
        return stats

    def _equity_svg_html(self, r, stats):
        pts = r['equity_curve']
        if not pts:
            return "<html><body>no data</body></html>"
        W, H, PAD = 920, 300, 46
        ts = [pd.Timestamp(t) for t, _ in pts]
        vs = [v for _, v in pts]
        vmin, vmax = min(vs), max(vs)
        span = (vmax - vmin) or 1.0
        t0, t1 = ts[0], ts[-1]
        tspan = (t1 - t0).total_seconds() or 1.0

        def X(t):
            return PAD + (t - t0).total_seconds() / tspan * (W - 2 * PAD)

        def Y(v):
            return H - PAD - (v - vmin) / span * (H - 2 * PAD)

        line = " ".join(f"{X(t):.1f},{Y(v):.1f}" for t, v in zip(ts, vs))
        area = f"{PAD},{H - PAD} " + line + f" {W - PAD},{H - PAD}"
        # trade markers (cap at 400)
        tr = r['trades']
        idx = {str(pd.Timestamp(t)): i for i, (t, _) in enumerate(pts)}
        marks = []
        for t in tr[::max(1, len(tr) // 400)]:
            i = idx.get(t['exit_ts'])
            if i is None:
                continue
            x, y = X(ts[i]), Y(vs[i])
            up = t['pnl'] > 0
            ch = '^v' [0] if up else 'v'
            marks.append(f'<path d="M{x:.1f},{y:.1f} l{-4},7 l8,0 z" fill="{"#2ecc71" if up else "#e74c3c"}" opacity="0.75"/>')
        grid = []
        for k in range(5):
            v = vmin + span * k / 4
            y = Y(v)
            grid.append(f'<line x1="{PAD}" y1="{y:.1f}" x2="{W - PAD}" y2="{y:.1f}" stroke="#333" stroke-width="0.5"/>'
                        f'<text x="4" y="{y + 4:.1f}" fill="#aaa" font-size="11">${v:,.0f}</text>')
        xticks = []
        for k in range(5):
            t = t0 + (t1 - t0) * k / 4
            x = X(t)
            xticks.append(f'<text x="{x:.1f}" y="{H - 14}" fill="#aaa" font-size="11" text-anchor="middle">{t.strftime("%Y-%m")}</text>')
        svg = (f'<svg width="{W}" height="{H}" xmlns="http://www.w3.org/2000/svg" style="background:#111">'
               + "".join(grid) + "".join(xticks)
               + f'<polygon points="{area}" fill="#3498db" opacity="0.15"/>'
               + f'<polyline points="{line}" fill="none" stroke="#3498db" stroke-width="1.6"/>'
               + "".join(marks)
               + f'<text x="{PAD}" y="20" fill="#eee" font-size="14">Equity — {r["label"]} ({r["source"]}) '
                 f'{r["start"][:10]} → {r["end"][:10]}</text>'
               + f'<text x="{W - PAD}" y="20" fill="{"#2ecc71" if stats["total_return_pct"] >= 0 else "#e74c3c"}" '
                 f'font-size="14" text-anchor="end">{stats["total_return_pct"]:+.1f}% | MaxDD {stats["max_drawdown_pct"]:.1f}% | '
                 f'n={stats["trades"]} WR {stats["win_rate_pct"]:.0f}%</text></svg>')
        rows = ""
        for k, d in sorted(stats['by_strategy'].items(), key=lambda kv: -kv[1]['pnl']):
            rows += (f"<tr><td>{k}</td><td>{d['n']}</td>"
                     f"<td style='color:{'#2ecc71' if d['pnl'] >= 0 else '#e74c3c'}'>${d['pnl']:,.2f}</td>"
                     f"<td>{d['win_rate'] * 100:.0f}%</td></tr>")
        html = f"""<!DOCTYPE html><html><head><meta charset="utf-8"><title>Backtest {r['symbol']}</title>
<style>body{{background:#111;color:#ddd;font:14px/1.5 monospace;margin:24px}}
h1{{font-size:18px}}table{{border-collapse:collapse;margin:12px 0}}td,th{{border:1px solid #333;padding:4px 12px;text-align:right}}
td:first-child,th:first-child{{text-align:left}}.note{{color:#888;font-size:12px}}</style></head>
<body><h1>Backtest — {r['label']} ({r['source']})</h1>
<div>{svg}</div>
<table><tr><th>strategy</th><th>trades</th><th>pnl</th><th>win%</th></tr>{rows}</table>
<p class="note">H1-decision backtest (no M5/M15 refinement), no news/DXY/trailing, spread modeled, SL-first on
same-bar ambiguity. yfinance {r['label']}. History is not a promise of future results.</p>
</body></html>"""
        return html


